/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2023_SEED = {"dse/writing/part-b/2023/Q3":[{"front":"human stories behind","meaning":"背後的人情故事","examples":[{"en":"The article explores the human stories behind Anime Expo.","zh":"文章探討動漫展背後的人情故事。"},{"en":"“The human stories behind” means the personal experiences, feelings and efforts hidden behind a public event or activity.","zh":"「the human stories behind」表示一項公開活動背後隱藏的個人經歷、感受和努力。"},{"en":"A documentary explored the human stories behind the city’s old shops.","zh":"一套紀錄片探討城市老店背後的人情故事。"},{"en":"Looking beyond costumes can reveal the human stories behind the people who made them.","zh":"不只看服裝外表，可以發現製作者背後的人情故事。"},{"en":"Understanding the human stories behind an event makes it feel more personal and meaningful.","zh":"了解活動背後的人情故事，可以令整件事更有人情味和意義。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"Anime Expo","meaning":"動漫展","examples":[{"en":"Anime Expo was held at the Hong Kong Convention and Exhibition Centre.","zh":"動漫展在香港會議展覽中心舉行。"},{"en":"Anime Expo is an exhibition centred on anime, manga, games, cosplay and related popular culture.","zh":"動漫展是以動畫、漫畫、遊戲、角色扮演和相關流行文化為主的展覽。"},{"en":"Fans arrived early at Anime Expo to see costumes and merchandise.","zh":"粉絲一早到動漫展觀看服裝和周邊商品。"},{"en":"Anime Expo brought together visitors with many different interests.","zh":"動漫展把有不同興趣的訪客聚集在一起。"},{"en":"Events like Anime Expo can function as both entertainment and community gatherings.","zh":"動漫展這類活動既可以是娛樂，也可以是社群聚會。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"school reporter","meaning":"校園記者","examples":[{"en":"Chris Wong attended Anime Expo as a school reporter.","zh":"Chris Wong以校園記者身分出席動漫展。"},{"en":"A school reporter is a student who writes or reports on events for a school publication or media platform.","zh":"校園記者是為學校刊物或媒體平台採訪和報道活動的學生。"},{"en":"The school reporter interviewed students after the sports day.","zh":"校園記者在運動會後訪問學生。"},{"en":"A school reporter needs to observe carefully and ask useful questions.","zh":"校園記者需要仔細觀察並提出有用問題。"},{"en":"Reporting on real events gives students practical experience in writing and communication.","zh":"報道真實活動可以讓學生獲得寫作和溝通的實際經驗。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"Hong Kong Convention and Exhibition Centre","meaning":"香港會議展覽中心","examples":[{"en":"The Hong Kong Convention and Exhibition Centre was humming like a power station.","zh":"香港會議展覽中心像發電站一樣嗡嗡作響。"},{"en":"The Hong Kong Convention and Exhibition Centre is a major venue used for exhibitions, conferences and large public events.","zh":"香港會議展覽中心是一個用來舉辦展覽、會議和大型公眾活動的重要場地。"},{"en":"Thousands of visitors entered the Hong Kong Convention and Exhibition Centre that morning.","zh":"當天早上數千名訪客進入香港會議展覽中心。"},{"en":"Large events can make the Convention and Exhibition Centre extremely busy.","zh":"大型活動可以令香港會議展覽中心非常繁忙。"},{"en":"A major venue helps bring different communities together in one place.","zh":"大型場地可以把不同社群聚集在同一地方。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"humming like a power station","meaning":"像發電站一樣嗡嗡作響","examples":[{"en":"At nine o’clock, the exhibition centre was humming like a power station.","zh":"九時正，展覽中心像發電站一樣嗡嗡作響。"},{"en":"“Humming like a power station” means being filled with continuous activity, noise and energy.","zh":"「humming like a power station」表示充滿持續活動、聲音和能量。"},{"en":"Before the concert, the backstage area was humming like a power station.","zh":"演唱會開始前，後台像發電站一樣忙個不停。"},{"en":"The comparison suggests that people, machines and movement were everywhere.","zh":"這個比喻令人想像到人、機器和走動到處都是。"},{"en":"This image makes the exhibition centre feel energetic rather than merely crowded.","zh":"它令展覽中心顯得充滿活力，而不只是擁擠。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"cameras flashed","meaning":"相機閃光燈閃個不停","examples":[{"en":"Elevators opened and cameras flashed.","zh":"升降機門打開，相機閃光燈閃個不停。"},{"en":"“Cameras flashed” means people were taking many photographs using camera flashes.","zh":"「cameras flashed」表示很多人正在使用閃光燈拍照。"},{"en":"Cameras flashed as the performers entered the hall.","zh":"表演者進入大堂時，相機閃光燈不斷閃動。"},{"en":"Popular costumes attracted visitors, and cameras flashed around them.","zh":"受歡迎的服裝吸引訪客，周圍相機不停閃。"},{"en":"Repeated camera flashes can create a feeling of excitement and attention.","zh":"不斷出現的閃光燈可以營造興奮和受注目的感覺。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"fictional worlds","meaning":"虛構世界","examples":[{"en":"Fictional worlds seemed to have landed in Wan Chai.","zh":"虛構世界彷彿降臨灣仔。"},{"en":"Fictional worlds are imaginary settings, characters and realities created in stories, games or films.","zh":"虛構世界是故事、遊戲或電影中創造的想像背景、人物和現實。"},{"en":"Fantasy novels often build detailed fictional worlds with their own rules.","zh":"奇幻小說常建立有自己規則的詳細虛構世界。"},{"en":"Cosplayers brought several fictional worlds into the same exhibition hall.","zh":"角色扮演者把幾個不同虛構世界帶進同一展覽廳。"},{"en":"Seeing characters physically represented can make fictional worlds feel temporarily real.","zh":"當角色被真實呈現，虛構世界會短暫感覺像真的存在。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"seemed to have landed","meaning":"彷彿降臨","examples":[{"en":"Fictional worlds seemed to have landed in Wan Chai.","zh":"虛構世界彷彿降臨灣仔。"},{"en":"“Seemed to have landed” means appeared as if they had suddenly arrived and become physically present.","zh":"「seemed to have landed」表示看起來好像突然到達並真實出現在某地。"},{"en":"With all the costumes, the fantasy kingdom seemed to have landed in the shopping mall.","zh":"到處都是服裝時，那個奇幻王國好像降臨商場。"},{"en":"The phrase creates a playful image of imaginary worlds arriving in a real place.","zh":"這個片語創造出想像世界來到真實地方的有趣畫面。"},{"en":"It emphasises how completely the exhibition changed the atmosphere around it.","zh":"它強調展覽如何徹底改變周圍氣氛。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"Hong Kong’s biggest anime, manga and video game exhibition","meaning":"香港最大的動漫及電子遊戲展覽","examples":[{"en":"Anime Expo is described as Hong Kong’s biggest anime, manga and video game exhibition.","zh":"動漫展被形容為香港最大的動漫及電子遊戲展覽。"},{"en":"This phrase describes a large exhibition focusing on animation, comics and electronic games.","zh":"這個片語形容一個集中動畫、漫畫和電子遊戲的大型展覽。"},{"en":"A major exhibition can attract fans, creators, families and businesses at the same time.","zh":"大型展覽可以同時吸引粉絲、創作者、家庭和商戶。"},{"en":"Its size helps explain why the venue became so crowded and energetic.","zh":"展覽規模之大，可以解釋為甚麼場地如此擠迫和充滿活力。"},{"en":"Large pop-culture exhibitions can influence youth culture beyond the event itself.","zh":"大型流行文化展覽的影響可以超越活動本身。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"was held there","meaning":"在那裏舉行","examples":[{"en":"Anime Expo was held there last weekend.","zh":"動漫展上週末在那裏舉行。"},{"en":"“Was held there” means the event took place at the location just mentioned.","zh":"「was held there」表示活動在剛才提到的地點舉行。"},{"en":"The school concert was held there last Friday.","zh":"學校音樂會上星期五在那裏舉行。"},{"en":"Large events are often held at venues with enough space and transport links.","zh":"大型活動通常在有足夠空間和方便交通的場地舉行。"},{"en":"This phrase avoids repeating the place name when the location is already clear.","zh":"當地點已清楚時，這個片語可以避免重複地名。"}],"source":"2023 Q3.pdf","sourcePage":1},{"front":"drawing fans, families and passers-by","meaning":"吸引粉絲、家庭和路人","examples":[{"en":"The exhibition drew fans, families and passers-by into one colourful crowd.","zh":"展覽把粉絲、家庭和路人吸引成一群色彩繽紛的人潮。"},{"en":"“Drawing fans, families and passers-by” means attracting several different groups of people towards the event.","zh":"「drawing fans, families and passers-by」表示把幾種不同群體吸引到活動中。"},{"en":"The street performance drew tourists and local residents into the square.","zh":"街頭表演把遊客和本地居民吸引到廣場。"},{"en":"A colourful public event can attract both dedicated fans and curious people walking past.","zh":"色彩豐富的公眾活動既可以吸引忠實粉絲，也可以吸引好奇路人。"},{"en":"A successful exhibition often reaches beyond its core fan community.","zh":"成功展覽往往可以接觸核心粉絲群以外的人。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"one colourful crowd","meaning":"一群色彩繽紛的人潮","examples":[{"en":"Fans, families and passers-by became one colourful crowd.","zh":"粉絲、家庭和路人成為一群色彩繽紛的人潮。"},{"en":"“One colourful crowd” describes many different people gathered together, often wearing bright or unusual clothing.","zh":"「one colourful crowd」形容很多不同的人聚在一起，通常穿着鮮豔或不尋常的衣服。"},{"en":"Festival visitors formed one colourful crowd outside the stage.","zh":"節日訪客在舞台外形成一群色彩繽紛的人潮。"},{"en":"Cosplay costumes made the crowd visually more varied and lively.","zh":"角色扮演服裝令整個人群在視覺上更豐富和有活力。"},{"en":"The phrase also suggests that different groups temporarily became part of the same community.","zh":"這個說法也暗示不同群體暫時成為同一個社群。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"attended the event","meaning":"出席活動","examples":[{"en":"As a school reporter, I attended the event.","zh":"作為校園記者，我出席了這項活動。"},{"en":"To attend an event means to go to it and be present there.","zh":"出席活動表示親身前往並在活動現場。"},{"en":"Hundreds of students attended the school careers fair.","zh":"數百名學生出席學校職業博覽。"},{"en":"Attending an event allows a reporter to observe details directly.","zh":"親身出席活動讓記者直接觀察細節。"},{"en":"First-hand attendance can make writing more vivid than relying only on second-hand information.","zh":"親身參與可以令文章比只依靠二手資料更生動。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"interviewed several cosplayers","meaning":"訪問了幾位角色扮演者","examples":[{"en":"I attended the event and interviewed several cosplayers.","zh":"我出席活動並訪問了幾位角色扮演者。"},{"en":"To interview several cosplayers means to ask a number of costume participants questions about their experiences and ideas.","zh":"訪問幾位角色扮演者表示向多名參與者提問，了解他們的經驗和想法。"},{"en":"The reporter interviewed several athletes after the competition.","zh":"記者在比賽後訪問了幾名運動員。"},{"en":"Interviewing cosplayers reveals the preparation that visitors cannot see from photographs alone.","zh":"訪問角色扮演者可以揭示照片本身看不到的準備工作。"},{"en":"Personal interviews help turn an event report into a story about real people.","zh":"個人訪問幫助活動報道變成人與人的故事。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"reconsider cosplay not as…but as…","meaning":"不把角色扮演視為……而視為……","examples":[{"en":"We should reconsider cosplay not as childish play, but as craftsmanship and confidence.","zh":"我們應重新看待角色扮演，不把它視為幼稚玩意，而視為工藝和自信的展現。"},{"en":"“Reconsider A not as X, but as Y” means changing an old interpretation and viewing something in a different, more accurate way.","zh":"「reconsider A not as X, but as Y」表示改變舊理解，以另一個更準確角度看事情。"},{"en":"We should reconsider volunteering not as free labour, but as community participation.","zh":"我們應重新看待義工服務，不把它視為免費勞動，而視為社區參與。"},{"en":"Seeing the work behind costumes can change how people judge cosplay.","zh":"看見服裝背後的工作，可以改變人對角色扮演的評價。"},{"en":"This structure strongly contrasts an old stereotype with a new interpretation.","zh":"這個句式強烈對比舊有刻板印象和新的理解。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"childish play","meaning":"幼稚玩意","examples":[{"en":"Cosplay should not be dismissed as childish play.","zh":"角色扮演不應被貶低為幼稚玩意。"},{"en":"Childish play means an activity treated as immature, silly or suitable only for children.","zh":"幼稚玩意表示被視為不成熟、愚蠢或只適合兒童的活動。"},{"en":"Some adults wrongly describe video games as childish play.","zh":"有些成年人錯誤把電子遊戲形容成幼稚玩意。"},{"en":"A colourful hobby can involve serious skill even if outsiders see only childish play.","zh":"色彩繽紛的興趣活動可以涉及認真技巧，即使局外人只看見幼稚玩意。"},{"en":"Calling something childish may hide the effort and meaning that participants experience.","zh":"把某事叫作幼稚，可以掩蓋參與者投入的努力和意義。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"craftsmanship","meaning":"工藝技巧","examples":[{"en":"Cosplay involves serious craftsmanship.","zh":"角色扮演涉及認真的工藝技巧。"},{"en":"Craftsmanship is skill and care in making something well by hand or through practical technique.","zh":"工藝技巧是透過手作或實際技術，把東西製作得好的能力和用心。"},{"en":"The handmade wooden chair showed excellent craftsmanship.","zh":"那張手製木椅展現出優秀工藝技巧。"},{"en":"Sewing, painting and building costume parts all require craftsmanship.","zh":"縫紉、上色和製作服裝配件都需要工藝技巧。"},{"en":"Good craftsmanship is visible in details that look carefully made rather than rushed.","zh":"良好工藝會在細節中顯現，看起來仔細製作而不是趕工完成。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"confidence","meaning":"自信","examples":[{"en":"Cosplay can give participants confidence.","zh":"角色扮演可以給參與者自信。"},{"en":"Confidence is belief in your ability to act, speak or present yourself successfully.","zh":"自信是相信自己有能力成功行動、說話或展現自己。"},{"en":"Repeated practice helped her gain confidence before the presentation.","zh":"反覆練習令她在簡報前更有自信。"},{"en":"Wearing a character costume may help a shy student feel more comfortable approaching strangers.","zh":"穿上角色服裝可能令害羞學生更自在地接近陌生人。"},{"en":"Confidence can grow when people receive positive responses to something they created themselves.","zh":"當人因自己創作的東西得到正面回應，自信可以增加。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"cultural connection","meaning":"文化連繫","examples":[{"en":"Cosplay can create cultural connection.","zh":"角色扮演可以創造文化連繫。"},{"en":"Cultural connection is a sense of relationship formed through shared stories, traditions, media or interests from different cultures.","zh":"文化連繫是透過共同故事、傳統、媒體或跨文化興趣建立的關係感。"},{"en":"A film festival can create cultural connection between local and overseas audiences.","zh":"電影節可以在本地和海外觀眾之間建立文化連繫。"},{"en":"Fans may connect through characters even if they come from different countries.","zh":"即使來自不同國家，粉絲也可以透過角色建立連結。"},{"en":"Shared popular culture can create bridges across language and background.","zh":"共同流行文化可以跨越語言和背景建立橋樑。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"the first thing that struck me","meaning":"第一件令我印象深刻的事","examples":[{"en":"The first thing that struck me was the atmosphere.","zh":"第一件令我印象深刻的事是氣氛。"},{"en":"“The first thing that struck me” means the first detail that strongly caught my attention or made an impression.","zh":"「the first thing that struck me」表示第一個強烈吸引我注意或留下印象的細節。"},{"en":"The first thing that struck me about the village was how quiet it was.","zh":"那條村第一件令我印象深刻的事，是它非常安靜。"},{"en":"A reporter often begins by describing the strongest first impression.","zh":"記者常由最強烈的第一印象開始描述。"},{"en":"This phrase makes observation feel personal and immediate.","zh":"這個片語令觀察感覺更個人和即時。"}],"source":"2023 Q3.pdf","sourcePage":2},{"front":"atmosphere","meaning":"氣氛","examples":[{"en":"The atmosphere near the entrance was full of excitement.","zh":"入口附近的氣氛充滿興奮。"},{"en":"Atmosphere is the general feeling or mood created by a place, event or group of people.","zh":"氣氛是某個地方、活動或人群所營造的整體感覺或情緒。"},{"en":"The café had a calm atmosphere in the morning.","zh":"那間咖啡店早上的氣氛很平靜。"},{"en":"Costumes, music and excited conversations created a lively atmosphere.","zh":"服裝、音樂和興奮談話營造出熱鬧氣氛。"},{"en":"Atmosphere can strongly affect how visitors remember an event.","zh":"氣氛可以強烈影響訪客如何記住一項活動。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"near the entrance","meaning":"在入口附近","examples":[{"en":"Near the entrance, cosplayers were posing for a photo.","zh":"在入口附近，角色扮演者正在擺姿勢拍照。"},{"en":"“Near the entrance” means close to the place where people enter a building or event.","zh":"「near the entrance」表示接近人們進入建築物或活動的入口位置。"},{"en":"Staff checked tickets near the entrance.","zh":"工作人員在入口附近檢查門票。"},{"en":"Popular photo spots often develop near the entrance because many visitors pass there.","zh":"入口附近多人經過，所以常會形成受歡迎的拍照位置。"},{"en":"Describing location helps readers picture where an action is happening.","zh":"說明地點可以幫助讀者想像事情在哪裏發生。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"elaborate costumes","meaning":"精緻複雜的服裝","examples":[{"en":"A group of cosplayers wore elaborate costumes.","zh":"一群角色扮演者穿着精緻複雜的服裝。"},{"en":"Elaborate costumes are highly detailed outfits involving complex design, decoration or construction.","zh":"精緻複雜的服裝是設計、裝飾或製作都很仔細而複雜的服飾。"},{"en":"The theatre production used elaborate costumes covered with embroidery.","zh":"那齣舞台劇使用了滿是刺繡的精緻服裝。"},{"en":"Elaborate cosplay costumes may require weeks or months of work.","zh":"精緻的角色扮演服裝可能需要幾星期甚至幾個月製作。"},{"en":"Complexity in a costume can reveal both creativity and technical skill.","zh":"服裝的複雜程度可以反映創意和技術能力。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"posing for a photo","meaning":"擺姿勢拍照","examples":[{"en":"The cosplayers were posing for a photo near the entrance.","zh":"角色扮演者在入口附近擺姿勢拍照。"},{"en":"Posing for a photo means holding a deliberate position or expression while someone takes a picture.","zh":"擺姿勢拍照表示刻意保持某個姿勢或表情，讓別人拍照。"},{"en":"The family stood together, posing for a photo in front of the harbour.","zh":"那一家人在海港前站在一起擺姿勢拍照。"},{"en":"Cosplayers often pose in ways that match their characters.","zh":"角色扮演者常會用符合角色性格的姿勢拍照。"},{"en":"A good pose can help make a costume look more convincing.","zh":"合適姿勢可以令服裝看起來更有說服力。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"silver-armoured warrior","meaning":"銀甲戰士","examples":[{"en":"One cosplayer dressed as a silver-armoured warrior.","zh":"一名角色扮演者打扮成銀甲戰士。"},{"en":"A silver-armoured warrior is a fighter character wearing protective armour with a silver appearance.","zh":"銀甲戰士是穿着銀色外觀保護盔甲的戰鬥角色。"},{"en":"The silver-armoured warrior carried a shield across the hall.","zh":"那名銀甲戰士拿着盾牌走過展覽廳。"},{"en":"Metallic paint can make lightweight costume material look like real armour.","zh":"金屬色油漆可以令輕身服裝材料看起來像真盔甲。"},{"en":"Fantasy warrior designs often require careful work on both shape and surface detail.","zh":"奇幻戰士造型通常需要仔細處理形狀和表面細節。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"velvet-caped magician","meaning":"披着天鵝絨斗篷的魔法師","examples":[{"en":"Another cosplayer dressed as a velvet-caped magician.","zh":"另一名角色扮演者打扮成披着天鵝絨斗篷的魔法師。"},{"en":"A velvet-caped magician is a magical character wearing a cape made to look like velvet.","zh":"這是指穿着看似天鵝絨斗篷的魔法角色。"},{"en":"The velvet-caped magician raised a staff while posing for cameras.","zh":"披斗篷的魔法師舉起法杖讓相機拍照。"},{"en":"Fabric choice can change how rich or dramatic a costume appears.","zh":"布料選擇可以改變服裝看起來有多華麗或有戲劇感。"},{"en":"A long cape can help create movement and character presence.","zh":"長斗篷可以增加動態和角色氣勢。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"cheerful idol","meaning":"開朗的偶像角色","examples":[{"en":"A cheerful idol wore pastel pink.","zh":"一個開朗的偶像角色穿着柔和粉紅色服裝。"},{"en":"A cheerful idol is a bright, energetic performer character designed to appear friendly and positive.","zh":"開朗的偶像角色是看起來友善、正面而有活力的表演角色。"},{"en":"The cheerful idol smiled and waved at young visitors.","zh":"那個開朗偶像角色向年幼訪客微笑和揮手。"},{"en":"Colour, posture and expression can help communicate an idol character’s personality.","zh":"顏色、姿勢和表情可以幫助傳達偶像角色的性格。"},{"en":"A convincing costume includes behaviour as well as clothing.","zh":"有說服力的角色扮演除了服裝，也包括行為。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"pastel pink","meaning":"柔和粉紅色","examples":[{"en":"The idol character was dressed in pastel pink.","zh":"偶像角色穿着柔和粉紅色服裝。"},{"en":"Pastel pink is a soft, pale shade of pink rather than a strong or bright one.","zh":"柔和粉紅色是一種淺而柔和的粉紅，而不是鮮豔強烈的粉紅。"},{"en":"The room was decorated in pastel pink and light blue.","zh":"房間以柔和粉紅色和淺藍色裝飾。"},{"en":"Pastel colours often create a gentle or playful visual effect.","zh":"柔和色系常營造溫柔或可愛的視覺效果。"},{"en":"Colour choice can help communicate a character’s mood and style.","zh":"顏色選擇可以幫助傳達角色情緒和風格。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"masked game character","meaning":"戴面具的遊戲角色","examples":[{"en":"A masked game character carried an enormous foam sword.","zh":"一名戴面具的遊戲角色拿着巨大的泡沫劍。"},{"en":"A masked game character is a character from a video game whose face is partly or completely covered.","zh":"戴面具的遊戲角色是來自電子遊戲、臉部部分或完全被面具遮住的角色。"},{"en":"The masked game character stood silently beside the booth.","zh":"那個戴面具的遊戲角色安靜站在攤位旁。"},{"en":"Masks can help cosplayers recreate characters whose identities depend strongly on visual design.","zh":"面具可以幫助角色扮演者重現視覺造型很重要的角色。"},{"en":"Props and masks together can make a fictional character easier to recognise.","zh":"道具和面具一起使用，可以令虛構角色更容易辨認。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"enormous foam sword","meaning":"巨大的泡沫劍","examples":[{"en":"The masked game character carried an enormous foam sword.","zh":"戴面具的遊戲角色拿着巨大的泡沫劍。"},{"en":"An enormous foam sword is a very large lightweight costume weapon made from soft foam material.","zh":"巨大的泡沫劍是用柔軟輕身泡沫材料製作的大型服裝道具武器。"},{"en":"The cosplayer built an enormous foam sword that looked heavy but was easy to carry.","zh":"角色扮演者製作了一把看似沉重、實際容易拿的巨大泡沫劍。"},{"en":"Foam allows costume makers to create oversized props more safely.","zh":"泡沫材料令服裝製作者可以較安全地製作大型道具。"},{"en":"A dramatic prop can become one of the most noticeable parts of a costume.","zh":"有戲劇感的道具可以成為服裝最搶眼的部分之一。"}],"source":"2023 Q3.pdf","sourcePage":3},{"front":"so detailed that","meaning":"詳細得以致","examples":[{"en":"The costumes were so detailed that even the fake scratches told stories.","zh":"服裝詳細得連假刮痕都彷彿在訴說故事。"},{"en":"“So detailed that” means having such a high level of detail that a particular result becomes noticeable.","zh":"「so detailed that」表示細節多到某個結果變得明顯。"},{"en":"The model was so detailed that even the tiny windows could be opened.","zh":"那個模型詳細得連小窗也可以打開。"},{"en":"A costume can be so detailed that viewers notice damage, texture and history built into it.","zh":"服裝可以詳細得讓觀眾留意到磨損、質感和角色歷史。"},{"en":"The “so…that…” structure connects a strong quality with its result.","zh":"「so…that…」句式把強烈特質與其結果連接起來。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"fake scratches","meaning":"假刮痕","examples":[{"en":"Even the fake scratches on the costumes seemed to tell stories.","zh":"連服裝上的假刮痕都彷彿在訴說故事。"},{"en":"Fake scratches are deliberately added marks made to look like damage even though the object is not actually scratched.","zh":"假刮痕是刻意加上的痕跡，看起來像損壞，但物件其實沒有真正被刮傷。"},{"en":"The armour had fake scratches to suggest years of battle.","zh":"盔甲上加了假刮痕，好像經歷過多年戰鬥。"},{"en":"Small signs of damage can make a new costume look older and more realistic.","zh":"細小磨損效果可以令新服裝看起來更舊、更真實。"},{"en":"Decorative details can communicate a character’s imagined history.","zh":"裝飾細節可以傳達角色想像中的歷史。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"glowing accessories","meaning":"發光配飾","examples":[{"en":"The glowing accessories seemed to tell stories.","zh":"發光配飾彷彿也在訴說故事。"},{"en":"Glowing accessories are costume decorations or objects that produce or appear to produce light.","zh":"發光配飾是會發出或看似會發出光線的服裝裝飾或物件。"},{"en":"The performer wore glowing accessories around her wrists.","zh":"表演者手腕戴着發光配飾。"},{"en":"LED lights can make accessories appear magical or futuristic.","zh":"LED燈可以令配飾顯得有魔法感或未來感。"},{"en":"Lighting effects help costume makers turn drawings into convincing physical designs.","zh":"燈光效果幫助服裝製作者把圖畫轉化成有說服力的實體設計。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"tell stories","meaning":"訴說故事","examples":[{"en":"The fake scratches and glowing accessories seemed to tell stories.","zh":"假刮痕和發光配飾彷彿在訴說故事。"},{"en":"To tell stories here means to suggest history, personality or events without using spoken words.","zh":"這裏的「tell stories」表示不用說話，也能暗示歷史、性格或發生過的事情。"},{"en":"Old photographs can tell stories about how a neighbourhood has changed.","zh":"舊照片可以訴說一個社區如何改變。"},{"en":"Costume details tell stories by showing what a character may have experienced.","zh":"服裝細節可以透過展示角色可能經歷過甚麼來訴說故事。"},{"en":"Visual storytelling allows objects and images to communicate meaning silently.","zh":"視覺敘事讓物件和影像能安靜地傳達意思。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"waited politely","meaning":"有禮貌地等候","examples":[{"en":"Visitors waited politely before taking photos.","zh":"訪客拍照前有禮貌地等候。"},{"en":"To wait politely means to remain patient and respectful rather than pushing ahead or interrupting others.","zh":"有禮貌地等候表示保持耐性和尊重，而不是推撞或插隊。"},{"en":"Fans waited politely for their turn to speak to the performer.","zh":"粉絲有禮貌地等候輪到自己與表演者說話。"},{"en":"Respectful behaviour matters when many people want photographs with the same cosplayer.","zh":"當很多人都想和同一角色扮演者拍照，尊重行為尤其重要。"},{"en":"Good event culture depends not only on excitement but also on courtesy.","zh":"良好活動文化不只需要熱情，也需要禮貌。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"may I take a picture?","meaning":"我可以拍照嗎？","examples":[{"en":"Visitors asked, “May I take a picture?” before lifting their phones.","zh":"訪客舉起手機前會問：「我可以拍照嗎？」"},{"en":"“May I take a picture?” is a polite way to ask permission before photographing someone.","zh":"「May I take a picture?」是拍攝某人前有禮貌地詢問許可的方法。"},{"en":"She asked, “May I take a picture?” before photographing the artist’s work.","zh":"她拍攝藝術家的作品前先問：「我可以拍照嗎？」"},{"en":"Asking first respects another person’s comfort and privacy.","zh":"先詢問可以尊重別人的感受和私隱。"},{"en":"Permission is especially important when photographing strangers at public events.","zh":"在公眾活動拍攝陌生人時，得到同意尤其重要。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"lifting their phones","meaning":"舉起手機","examples":[{"en":"Visitors asked permission before lifting their phones.","zh":"訪客在舉起手機前先詢問許可。"},{"en":"“Lifting their phones” means raising their phones, usually to take a photograph or video.","zh":"「lifting their phones」表示把手機舉高，通常準備拍照或錄影。"},{"en":"The audience began lifting their phones when the singer appeared.","zh":"歌手出現時，觀眾開始舉起手機。"},{"en":"At the expo, visitors lifted their phones only after asking the cosplayer.","zh":"在展覽中，訪客得到角色扮演者同意後才舉起手機。"},{"en":"A small action such as raising a phone can become part of respectful social behaviour when permission is involved.","zh":"當涉及拍攝許可，舉起手機這個小動作也可以成為尊重社交行為的一部分。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"it would be easy to describe","meaning":"很容易把……形容為","examples":[{"en":"It would be easy to describe the scene as noisy or strange.","zh":"很容易把這個場面形容為嘈吵或奇怪。"},{"en":"“It would be easy to describe” means a quick or superficial observer could easily label something in that way.","zh":"「it would be easy to describe」表示一個快速或表面的觀察者很容易用某種方式標籤事情。"},{"en":"It would be easy to describe the crowded market as chaotic without noticing how organised it is.","zh":"很容易把擠迫市場形容為混亂，而忽略它其實很有秩序。"},{"en":"First impressions can produce simple descriptions that miss deeper meaning.","zh":"第一印象可以產生簡單描述，但錯過更深意義。"},{"en":"This phrase often introduces a stereotype that the writer will then challenge.","zh":"這個片語常用來帶出作者之後要挑戰的刻板看法。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"noisy or strange","meaning":"嘈雜或奇怪","examples":[{"en":"The scene could easily be described as noisy or strange.","zh":"這個場面很容易被形容為嘈雜或奇怪。"},{"en":"“Noisy or strange” means loud, unfamiliar or outside what an observer considers normal.","zh":"「noisy or strange」表示聲音很大、陌生或超出觀察者認為正常的範圍。"},{"en":"A festival may seem noisy or strange to someone attending for the first time.","zh":"第一次參加節日的人可能覺得活動很嘈雜或奇怪。"},{"en":"Unfamiliar clothing can look strange before people understand its cultural meaning.","zh":"在理解文化意義前，陌生服裝可能看起來很奇怪。"},{"en":"Something that appears strange from outside may feel welcoming and meaningful to participants.","zh":"從外面看似奇怪的活動，對參與者而言可能很溫暖和有意義。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"standing there","meaning":"站在那裏","examples":[{"en":"Standing there, I felt shared excitement.","zh":"站在那裏，我感受到共同的興奮。"},{"en":"“Standing there” means while physically present in that particular place.","zh":"「standing there」表示身體正處於那個特定地方。"},{"en":"Standing there beside the stage, I could feel the crowd’s energy.","zh":"站在舞台旁，我可以感受到人群的能量。"},{"en":"Being physically present allowed the reporter to experience the atmosphere directly.","zh":"親身在場讓記者直接感受氣氛。"},{"en":"This phrase places the writer inside the scene rather than describing it from a distance.","zh":"這個片語把作者放進場景，而不是從遠處描述。"}],"source":"2023 Q3.pdf","sourcePage":4},{"front":"shared excitement","meaning":"共同的興奮","examples":[{"en":"The writer felt shared excitement at Anime Expo.","zh":"作者在動漫展感受到共同的興奮。"},{"en":"Shared excitement is a feeling of enthusiasm experienced together by many people.","zh":"共同的興奮是很多人一起感受到的熱情和期待。"},{"en":"Fans felt shared excitement when the band appeared on stage.","zh":"樂隊上台時，粉絲感受到共同的興奮。"},{"en":"Shared excitement can make strangers feel temporarily connected.","zh":"共同的興奮可以令陌生人暫時產生連結。"},{"en":"Collective emotion is one reason live events feel different from enjoying a hobby alone.","zh":"共同情緒是現場活動與獨自享受興趣不同的原因之一。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"smiled at one another","meaning":"互相微笑","examples":[{"en":"Strangers smiled at one another.","zh":"陌生人互相微笑。"},{"en":"To smile at one another means for two or more people to exchange friendly smiles.","zh":"互相微笑表示兩個或以上的人彼此友善地笑。"},{"en":"The passengers smiled at one another after helping an elderly man.","zh":"乘客幫助長者後互相微笑。"},{"en":"Shared interests can make strangers smile at one another more easily.","zh":"共同興趣可以令陌生人更容易互相微笑。"},{"en":"Small friendly gestures can create a sense of community without conversation.","zh":"細小友善動作即使沒有談話，也可以建立社群感。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"walk past one another in silence","meaning":"默默擦身而過","examples":[{"en":"Students who might normally walk past one another in silence began conversations.","zh":"平時可能默默擦身而過的學生開始交談。"},{"en":"To walk past one another in silence means to pass each other without speaking or interacting.","zh":"「walk past one another in silence」表示彼此經過時沒有說話或互動。"},{"en":"Neighbours sometimes walk past one another in silence when they do not know each other.","zh":"不認識的鄰居有時會默默擦身而過。"},{"en":"Shared hobbies can turn silent strangers into people willing to talk.","zh":"共同興趣可以把沉默的陌生人變成願意交談的人。"},{"en":"An event can create social contact that ordinary daily life does not.","zh":"活動可以創造日常生活未必有的社交接觸。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"began conversations about","meaning":"開始談論","examples":[{"en":"Students began conversations about favourite characters.","zh":"學生開始談論最喜愛的角色。"},{"en":"To begin conversations about something means to start talking with others about that topic.","zh":"「begin conversations about」表示開始與其他人談某個主題。"},{"en":"The exhibition helped visitors begin conversations about local art.","zh":"展覽令訪客開始談論本地藝術。"},{"en":"A visible shared interest gives strangers an easy topic to talk about.","zh":"看得見的共同興趣給陌生人一個容易開始的話題。"},{"en":"Conversation often begins more naturally when people already know they share an interest.","zh":"當人們已知道彼此有共同興趣，對話通常更自然開始。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"favourite characters","meaning":"最喜愛的角色","examples":[{"en":"Students talked about their favourite characters.","zh":"學生談論自己最喜愛的角色。"},{"en":"Favourite characters are fictional people or figures someone especially likes.","zh":"最喜愛的角色是某人特別喜歡的虛構人物或形象。"},{"en":"Fans compared their favourite characters from different anime series.","zh":"粉絲比較不同動畫系列中自己最喜愛的角色。"},{"en":"A favourite character may be admired for personality, design or story.","zh":"一個角色可以因性格、造型或故事而成為某人的最愛。"},{"en":"Talking about favourite characters can help people discover shared interests.","zh":"談論最喜愛角色可以幫助人發現共同興趣。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"in a city where","meaning":"在一個……的城市裏","examples":[{"en":"In a city where everyone seems rushed, Anime Expo created a rare space.","zh":"在一個人人看起來都很匆忙的城市裏，動漫展創造了一個難得空間。"},{"en":"“In a city where” introduces a particular condition that characterises the city.","zh":"「in a city where」用來帶出某個城市具有的特定情況。"},{"en":"In a city where space is limited, public parks are especially valuable.","zh":"在一個空間有限的城市裏，公共公園尤其珍貴。"},{"en":"The phrase sets up a contrast between normal urban life and the event.","zh":"這個片語在一般城市生活與活動之間建立對比。"},{"en":"Context makes the exhibition’s relaxed social connection seem more unusual and meaningful.","zh":"背景令展覽中的輕鬆社交連結顯得更難得和有意義。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"seems rushed","meaning":"看起來匆忙","examples":[{"en":"Everyone often seems rushed in Hong Kong.","zh":"香港很多人常看起來很匆忙。"},{"en":"To seem rushed means to look as if you are always hurrying and have little time.","zh":"「seems rushed」表示看起來總在趕時間，幾乎沒有空閒。"},{"en":"Commuters seemed rushed as they moved through the station.","zh":"通勤者穿過車站時看起來很匆忙。"},{"en":"People who seem rushed may avoid conversation with strangers.","zh":"看起來匆忙的人可能會避免與陌生人交談。"},{"en":"A social event can feel especially refreshing in a place where daily life often feels hurried.","zh":"在日常生活節奏很急的地方，社交活動會顯得特別令人放鬆。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"created a rare space","meaning":"創造了一個難得的空間","examples":[{"en":"Anime Expo created a rare space for visible enthusiasm.","zh":"動漫展創造了一個讓熱情看得見的難得空間。"},{"en":"To create a rare space means to provide an unusual environment where something can happen more freely than usual.","zh":"創造一個難得空間，表示提供一個不尋常環境，讓某件事比平時更自由地發生。"},{"en":"The club created a rare space where shy students could speak openly.","zh":"學會創造了一個讓害羞學生可以公開發言的難得空間。"},{"en":"The exhibition allowed people to display interests they might normally keep private.","zh":"展覽讓人展示平時可能收起來的興趣。"},{"en":"Rare social spaces can help people feel accepted for parts of themselves that are usually hidden.","zh":"難得的社交空間可以令人在平時隱藏的自我部分得到接納。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"enthusiasm","meaning":"熱情","examples":[{"en":"Anime Expo allowed enthusiasm to be visible.","zh":"動漫展讓熱情變得看得見。"},{"en":"Enthusiasm is strong excitement, interest and energy towards something.","zh":"熱情是對某件事強烈的興奮、興趣和投入。"},{"en":"Her enthusiasm for drawing was obvious from how much time she spent practising.","zh":"她花很多時間練習畫畫，顯示她對繪畫很有熱情。"},{"en":"Fans showed enthusiasm through costumes, conversations and photography.","zh":"粉絲透過服裝、談話和拍照展示熱情。"},{"en":"Enthusiasm becomes socially powerful when people realise others share it too.","zh":"當人發現其他人也有相同興趣，熱情會產生更強的社交力量。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"visible","meaning":"看得見的","examples":[{"en":"At Anime Expo, enthusiasm could be visible.","zh":"在動漫展，熱情可以變得看得見。"},{"en":"Visible means able to be seen clearly rather than hidden.","zh":"「visible」表示可以清楚看見，而不是隱藏。"},{"en":"The improvement became visible after several weeks of practice.","zh":"練習幾星期後，進步開始變得看得見。"},{"en":"Costumes make personal interests visible to everyone around them.","zh":"服裝把個人興趣變成周圍每個人都看得見的東西。"},{"en":"When enthusiasm becomes visible, people with similar interests can find one another more easily.","zh":"當熱情變得看得見，有相同興趣的人更容易找到彼此。"}],"source":"2023 Q3.pdf","sourcePage":5},{"front":"behind that enthusiasm","meaning":"在那份熱情背後","examples":[{"en":"Behind that enthusiasm, however, was serious effort.","zh":"然而，在那份熱情背後是認真的努力。"},{"en":"“Behind that enthusiasm” means underneath the visible excitement there was another less obvious reality.","zh":"「behind that enthusiasm」表示在看得見的興奮之下，還有另一個較不明顯的現實。"},{"en":"Behind the team’s celebration were months of training.","zh":"球隊慶祝背後，是幾個月的訓練。"},{"en":"The colourful surface of cosplay hides preparation, mistakes and repeated practice.","zh":"角色扮演色彩繽紛的外表背後，有準備、錯誤和反覆練習。"},{"en":"Looking behind enthusiasm helps observers understand that enjoyment and effort can exist together.","zh":"看見熱情背後的東西，可以令人明白享受與努力可以並存。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"serious effort","meaning":"認真的努力","examples":[{"en":"Behind the enthusiasm was serious effort.","zh":"熱情背後是認真的努力。"},{"en":"Serious effort is sustained, focused work that requires time, patience and commitment.","zh":"認真的努力是需要時間、耐性和投入的持續專注工作。"},{"en":"Her excellent results came from serious effort throughout the year.","zh":"她優秀的成績來自整年的認真努力。"},{"en":"Building a complicated costume requires serious effort even if the final result looks playful.","zh":"製作複雜服裝需要認真努力，即使最後看起來只是玩樂。"},{"en":"Visible success often rests on effort that audiences never see.","zh":"看得見的成功往往建立在觀眾看不見的努力上。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"was dressed as","meaning":"打扮成","examples":[{"en":"Melody was dressed as a princess from a fantasy manga.","zh":"Melody打扮成一位奇幻漫畫公主。"},{"en":"“Was dressed as” means wore clothing and accessories to look like a particular character or person.","zh":"「was dressed as」表示穿上服裝和配飾，看起來像某個特定人物或角色。"},{"en":"He was dressed as a famous detective for the school event.","zh":"他在學校活動中打扮成一位著名偵探。"},{"en":"Cosplayers use clothing, makeup and props to be dressed as fictional characters.","zh":"角色扮演者利用服裝、化妝和道具打扮成虛構角色。"},{"en":"Dressing as someone involves creating a recognisable visual identity.","zh":"打扮成某人涉及建立一個容易辨認的視覺身份。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"fantasy manga","meaning":"奇幻漫畫","examples":[{"en":"Melody dressed as a princess from a fantasy manga.","zh":"Melody打扮成一位來自奇幻漫畫的公主。"},{"en":"Fantasy manga is Japanese-style comic storytelling involving magical, supernatural or imaginary worlds.","zh":"奇幻漫畫是涉及魔法、超自然或想像世界的日式漫畫故事。"},{"en":"The fantasy manga followed a girl travelling through a kingdom of dragons.","zh":"那套奇幻漫畫講述一名女孩穿越龍之王國。"},{"en":"Fantasy manga often inspires elaborate costumes because its designs can be highly imaginative.","zh":"奇幻漫畫設計很有想像力，因此常啟發複雜角色扮演服裝。"},{"en":"Fans may connect strongly with fictional characters from long-running manga stories.","zh":"粉絲可以與長篇漫畫中的虛構角色建立強烈連結。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"looked as light as whipped cream","meaning":"看起來像忌廉一樣輕盈","examples":[{"en":"Her gown looked as light as whipped cream.","zh":"她的長裙看起來像忌廉一樣輕盈。"},{"en":"“As light as whipped cream” compares the gown’s soft, airy appearance with whipped cream.","zh":"「as light as whipped cream」把裙子的柔軟輕盈外觀比作忌廉。"},{"en":"The clouds looked as light as cotton in the morning sky.","zh":"早上天空的雲看起來像棉花一樣輕。"},{"en":"Layers of pale fabric can make a large dress appear surprisingly light.","zh":"淺色多層布料可以令大型裙子看起來意外地輕盈。"},{"en":"The simile creates a soft and delicate visual image.","zh":"這個明喻創造柔軟而精緻的視覺畫面。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"whipped cream","meaning":"忌廉","examples":[{"en":"Her gown looked as light as whipped cream.","zh":"她的長裙看起來像忌廉一樣輕盈。"},{"en":"Whipped cream is cream beaten until it becomes soft, light and full of air.","zh":"忌廉是打發後變得柔軟、輕盈而充滿空氣的奶油。"},{"en":"The cake was decorated with whipped cream and fruit.","zh":"蛋糕以忌廉和水果裝飾。"},{"en":"Because whipped cream looks soft and airy, it can be used in comparisons describing lightness.","zh":"因為打發忌廉看起來柔軟而輕盈，所以可用來比喻輕盈感。"},{"en":"Food comparisons can make descriptions more vivid and easy to imagine.","zh":"用食物作比較，可以令描述更生動和容易想像。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"had taken two months to sew","meaning":"花了兩個月縫製","examples":[{"en":"The gown had taken two months to sew.","zh":"那條長裙花了兩個月縫製。"},{"en":"“Had taken two months to sew” means the sewing process required two full months of work before completion.","zh":"「had taken two months to sew」表示整個縫製過程需要完整兩個月才能完成。"},{"en":"The handmade jacket had taken several weeks to sew.","zh":"那件手製外套花了幾星期縫製。"},{"en":"A costume that takes months to make clearly involves planning and persistence.","zh":"一件需要幾個月製作的服裝明顯涉及規劃和堅持。"},{"en":"The phrase contrasts the effortless final appearance with the long work behind it.","zh":"這個片語把最後輕鬆美麗的外表與背後長時間工作作對比。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"just buy a costume and wear it","meaning":"只是買套服裝來穿","examples":[{"en":"Some people think cosplayers just buy a costume and wear it.","zh":"有些人以為角色扮演者只是買套服裝來穿。"},{"en":"“Just buy a costume and wear it” suggests there is little skill, preparation or creativity involved.","zh":"「just buy a costume and wear it」暗示當中沒有太多技巧、準備或創意。"},{"en":"Outsiders may think baking is simply buying ingredients and mixing them.","zh":"局外人可能以為烘焙只是買材料再混合起來。"},{"en":"Interviews with cosplayers show that many design, alter and build their own pieces.","zh":"訪問角色扮演者後會發現，很多人自己設計、修改和製作部件。"},{"en":"Simple assumptions often hide the work behind a hobby.","zh":"簡單假設往往會掩蓋一項興趣背後的工作。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"spent three weekends","meaning":"花了三個週末","examples":[{"en":"Melody spent three weekends fixing the sleeves alone.","zh":"Melody單是修改袖子就花了三個週末。"},{"en":"“Spent three weekends” means used the free time across three separate weekends to work on something.","zh":"「spent three weekends」表示用了三個不同週末的空閒時間完成某件事。"},{"en":"He spent three weekends building the school exhibition model.","zh":"他花了三個週末製作學校展覽模型。"},{"en":"Giving up several weekends shows how much time a hobby can require.","zh":"願意用上幾個週末，顯示一項興趣可以需要很多時間。"},{"en":"Time investment is one sign of commitment.","zh":"投入時間是承擔和投入的其中一個證明。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"fixing the sleeves","meaning":"修改袖子","examples":[{"en":"Melody spent three weekends fixing the sleeves.","zh":"Melody花了三個週末修改袖子。"},{"en":"Fixing the sleeves means altering, repairing or improving the sleeve parts of a garment.","zh":"修改袖子表示改動、修補或改善衣服的袖子部分。"},{"en":"The tailor spent an hour fixing the sleeves because they were too long.","zh":"裁縫花了一小時修改太長的袖子。"},{"en":"Small costume problems may require repeated adjustment before the final fit looks right.","zh":"細小服裝問題可能需要反覆調整，最後版型才正確。"},{"en":"Detailed sewing work shows that craftsmanship often involves patience with small parts.","zh":"仔細縫製工作顯示工藝常需要對細節有耐性。"}],"source":"2023 Q3.pdf","sourcePage":6},{"front":"another participant","meaning":"另一位參加者","examples":[{"en":"Another participant had built a robotic arm.","zh":"另一位參加者製作了一隻機械手臂。"},{"en":"Another participant means a different person who was also taking part in the event or activity.","zh":"另一位參加者表示同一活動中另一個不同的參與者。"},{"en":"One student made a poster, while another participant prepared a video.","zh":"一名學生製作海報，另一位參加者則準備影片。"},{"en":"Different participants may demonstrate completely different skills at the same event.","zh":"同一活動中的不同參加者可以展示完全不同的技能。"},{"en":"This phrase introduces a new example without repeating the earlier person’s name.","zh":"這個片語可以帶出新例子，而不用重複之前人物的名字。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"robotic arm","meaning":"機械手臂","examples":[{"en":"Jason had built a robotic arm from cardboard and recycled plastic.","zh":"Jason用紙板和回收塑膠製作了一隻機械手臂。"},{"en":"A robotic arm is a mechanical arm designed to look or work like a robot’s limb.","zh":"機械手臂是設計成像機械人手臂一樣的機械裝置或造型。"},{"en":"The students programmed a robotic arm to pick up small objects.","zh":"學生編程令機械手臂拿起小物件。"},{"en":"For cosplay, a robotic arm may be decorative rather than fully functional.","zh":"在角色扮演中，機械手臂可以主要是裝飾，而不一定真的運作。"},{"en":"Building one combines design, measurement and material problem-solving.","zh":"製作它結合設計、量度和材料解難。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"LED strips","meaning":"LED燈條","examples":[{"en":"The robotic arm was made with cardboard, LED strips and recycled plastic.","zh":"機械手臂使用紙板、LED燈條和回收塑膠製作。"},{"en":"LED strips are flexible lines of small electric lights used for decoration or lighting effects.","zh":"LED燈條是一排柔性的細小電燈，可用作裝飾或燈光效果。"},{"en":"She placed LED strips under the shelf to create soft light.","zh":"她在層架下安裝LED燈條，製造柔和光線。"},{"en":"Costume makers use LED strips to create glowing futuristic effects.","zh":"服裝製作者使用LED燈條營造發光和未來感效果。"},{"en":"Simple electronic parts can make handmade props look more advanced.","zh":"簡單電子零件可以令手製道具看起來更先進。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"recycled plastic","meaning":"回收塑膠","examples":[{"en":"Jason used recycled plastic to build the robotic arm.","zh":"Jason使用回收塑膠製作機械手臂。"},{"en":"Recycled plastic is plastic material that has been processed and reused instead of thrown away.","zh":"回收塑膠是經處理後重新使用，而不是被丟棄的塑膠材料。"},{"en":"The art class used recycled plastic to make sculptures.","zh":"美術課使用回收塑膠製作雕塑。"},{"en":"Using recycled material can lower cost and reduce waste.","zh":"使用回收材料可以降低成本並減少廢物。"},{"en":"Creative reuse shows that expensive materials are not always necessary for good design.","zh":"創意再用顯示良好設計不一定需要昂貴材料。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"watched tutorials","meaning":"觀看教學影片","examples":[{"en":"Jason watched tutorials to learn how to build the arm.","zh":"Jason觀看教學影片，學習如何製作手臂。"},{"en":"To watch tutorials means to view instructional videos or demonstrations showing how to do something.","zh":"觀看教學影片表示觀看教人如何做某件事的指導影片或示範。"},{"en":"She watched tutorials online before learning basic sewing.","zh":"她學習基本縫紉前先在網上觀看教學影片。"},{"en":"Tutorials allow hobbyists to learn specialised skills independently.","zh":"教學影片讓興趣愛好者可以自行學習專門技能。"},{"en":"Watching a tutorial is useful, but successful making still requires practice and problem-solving.","zh":"看教學很有用，但真正成功製作仍需要練習和解難。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"tested different materials","meaning":"測試不同材料","examples":[{"en":"He tested different materials for the costume.","zh":"他為服裝測試不同材料。"},{"en":"To test different materials means to try several substances to see which works best.","zh":"測試不同材料表示嘗試幾種物料，看看哪一種最合適。"},{"en":"The designer tested different materials before choosing waterproof fabric.","zh":"設計師選擇防水布料前測試了不同材料。"},{"en":"Foam, cardboard and plastic may behave differently when cut, painted or bent.","zh":"泡沫、紙板和塑膠在切割、上色或彎曲時表現可能不同。"},{"en":"Testing materials reduces mistakes by revealing problems before final construction.","zh":"測試材料可以在正式製作前發現問題，減少錯誤。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"repainted the armour","meaning":"重新上色盔甲","examples":[{"en":"Jason repainted the armour twice.","zh":"Jason把盔甲重新上色了兩次。"},{"en":"To repaint the armour means to apply paint again because the first colour or finish was unsatisfactory.","zh":"重新上色盔甲表示因第一次顏色或效果不理想，再次塗上油漆。"},{"en":"She repainted the wall after deciding the first shade was too dark.","zh":"她覺得第一個顏色太深，所以重新上色牆壁。"},{"en":"Repainting a prop shows willingness to correct work rather than accept a weak result.","zh":"重新為道具上色顯示製作者願意改正，而不是接受較差結果。"},{"en":"Craftsmanship often involves repeating a stage until the effect is right.","zh":"工藝製作常需要反覆某個步驟，直到效果正確。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"reminded me that","meaning":"令我想起","examples":[{"en":"Their stories reminded me that cosplay involves serious skills.","zh":"他們的故事令我想起角色扮演涉及認真技能。"},{"en":"“Reminded me that” means caused me to remember or recognise an important fact or idea.","zh":"「reminded me that」表示令我重新想起或意識到一個重要事實或想法。"},{"en":"The old photograph reminded me that the neighbourhood had changed greatly.","zh":"舊照片令我想起這個社區已經改變很多。"},{"en":"Hearing how long the costumes took reminded the writer that cosplay requires discipline.","zh":"聽到服裝花了多久製作，令作者想起角色扮演需要自律。"},{"en":"Personal stories can remind observers not to judge only by appearances.","zh":"個人故事可以提醒觀察者不要只從外表判斷。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"involves design","meaning":"涉及設計","examples":[{"en":"Cosplay involves design, problem-solving, budgeting and patience.","zh":"角色扮演涉及設計、解難、預算管理和耐性。"},{"en":"To involve design means to require planning how something should look, fit or function.","zh":"涉及設計表示需要規劃某樣東西應如何外觀、配合或運作。"},{"en":"Building a school website involves design as well as technical work.","zh":"製作學校網站既涉及設計，也涉及技術工作。"},{"en":"Cosplayers must make choices about colour, shape, proportion and materials.","zh":"角色扮演者要決定顏色、形狀、比例和材料。"},{"en":"Design connects imagination with practical decisions.","zh":"設計把想像與實際決定連接起來。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"problem-solving","meaning":"解難能力","examples":[{"en":"Cosplay involves problem-solving.","zh":"角色扮演涉及解難能力。"},{"en":"Problem-solving is the process of identifying difficulties and finding workable ways to overcome them.","zh":"解難是找出困難並尋找可行方法克服它們的過程。"},{"en":"Fixing a broken model required careful problem-solving.","zh":"修理損壞模型需要仔細解難。"},{"en":"A costume maker may need problem-solving when a material bends or breaks unexpectedly.","zh":"材料意外彎曲或破裂時，服裝製作者需要解難。"},{"en":"Practical projects build problem-solving because real materials do not always behave as planned.","zh":"實踐項目可以培養解難，因為真實材料不一定按計劃運作。"}],"source":"2023 Q3.pdf","sourcePage":7},{"front":"budgeting","meaning":"預算管理","examples":[{"en":"Cosplay involves budgeting and patience.","zh":"角色扮演涉及預算管理和耐性。"},{"en":"Budgeting is planning how much money can be spent and deciding how to use it.","zh":"預算管理是規劃可以花多少錢，以及如何分配這些金錢。"},{"en":"Students practised budgeting when planning the class party.","zh":"學生策劃班會時練習預算管理。"},{"en":"A cosplayer may need to decide which materials are worth paying more for.","zh":"角色扮演者可能需要決定哪些材料值得花更多錢。"},{"en":"Budgeting turns a creative idea into something financially realistic.","zh":"預算管理令創意想法變得在經濟上可行。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"patience","meaning":"耐性","examples":[{"en":"Cosplay requires patience.","zh":"角色扮演需要耐性。"},{"en":"Patience is the ability to continue calmly despite delay, difficulty or repeated mistakes.","zh":"耐性是在拖延、困難或反覆犯錯時仍能冷靜繼續的能力。"},{"en":"Learning to sew neatly requires patience.","zh":"學習整齊縫紉需要耐性。"},{"en":"Costume makers need patience when details must be corrected many times.","zh":"細節要反覆修正時，服裝製作者需要耐性。"},{"en":"Long creative projects often succeed through steady effort rather than speed.","zh":"長期創作項目常靠穩定努力，而不是速度取得成功。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"not merely dressing up","meaning":"不只是打扮","examples":[{"en":"Cosplay is not merely dressing up.","zh":"角色扮演不只是打扮。"},{"en":"“Not merely dressing up” means cosplay involves more than simply putting on unusual clothes.","zh":"「not merely dressing up」表示角色扮演不只是穿上不尋常服裝。"},{"en":"Theatre is not merely dressing up because actors also interpret characters and stories.","zh":"戲劇不只是打扮，因為演員也要理解角色和故事。"},{"en":"Cosplay may include research, making, performance and social interaction.","zh":"角色扮演可以包括資料搜集、製作、表演和社交互動。"},{"en":"This phrase challenges a shallow understanding of the hobby.","zh":"這個片語挑戰對這項興趣過於表面的理解。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"hands-on learning","meaning":"實踐式學習","examples":[{"en":"Cosplay is a form of hands-on learning.","zh":"角色扮演是一種實踐式學習。"},{"en":"Hands-on learning is learning through direct practical activity rather than only reading or listening.","zh":"實踐式學習是透過直接動手活動學習，而不只是閱讀或聆聽。"},{"en":"Building a model bridge is hands-on learning in engineering.","zh":"製作模型橋樑是工程方面的實踐式學習。"},{"en":"Cosplayers learn sewing and construction by actually making objects.","zh":"角色扮演者透過真正製作物件學習縫紉和建構。"},{"en":"Practical experience helps learners understand what works and what fails.","zh":"實際經驗幫助學習者理解甚麼有效、甚麼失敗。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"turning imagination into","meaning":"把想像變成","examples":[{"en":"Cosplay turns imagination into something people can see.","zh":"角色扮演把想像變成人們看得見的東西。"},{"en":"“Turning imagination into” means transforming an idea that exists in the mind into a real, visible form.","zh":"「turning imagination into」表示把存在腦海的想法轉化成真實、可見的形式。"},{"en":"Architecture turns imagination into buildings people can use.","zh":"建築把想像變成人們可以使用的建築物。"},{"en":"Costume making turns drawings and fictional designs into physical objects.","zh":"服裝製作把圖畫和虛構設計轉化成實體物件。"},{"en":"Creative work becomes especially satisfying when an imagined idea gains real form.","zh":"當想像中的概念真正成形，創作會特別有滿足感。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"see, touch and admire","meaning":"看見、觸摸和欣賞","examples":[{"en":"Cosplay turns imagination into something people can see, touch and admire.","zh":"角色扮演把想像變成大家可以看見、觸摸和欣賞的東西。"},{"en":"“See, touch and admire” emphasises that an idea has become physically present and worthy of appreciation.","zh":"「see, touch and admire」強調想法已變成真實存在而值得欣賞的東西。"},{"en":"The sculpture turned a sketch into something visitors could see, touch and admire.","zh":"雕塑把草圖變成訪客可以看見、觸摸和欣賞的作品。"},{"en":"Physical craftsmanship allows audiences to appreciate texture and detail directly.","zh":"實體工藝讓觀眾直接欣賞質感和細節。"},{"en":"Tangible creative work can create a different connection from seeing an image online.","zh":"可觸摸的創作與只在網上看圖片能建立不同連結。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, cosplay gave many participants a voice.","zh":"更重要的是，角色扮演讓很多參與者有發聲機會。"},{"en":"“More importantly” introduces a point considered more significant than what was just discussed.","zh":"「more importantly」用來帶出比剛才內容更加重要的一點。"},{"en":"The workshop taught skills and, more importantly, built confidence.","zh":"工作坊教授技能；更重要的是，也建立了自信。"},{"en":"Costume making is impressive; more importantly, participation can change how people see themselves.","zh":"服裝製作很令人印象深刻；更重要的是，參與可以改變人如何看自己。"},{"en":"This phrase helps rank arguments by importance.","zh":"這個片語幫助按重要程度排列論點。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"give someone a voice","meaning":"讓某人有發聲機會","examples":[{"en":"Cosplay gave many participants a voice.","zh":"角色扮演讓很多參與者有發聲機會。"},{"en":"To give someone a voice means to give them a way or confidence to express themselves and be noticed.","zh":"讓某人有發聲機會表示給予方法或信心去表達自己並被看見。"},{"en":"The school newspaper gives students a voice on issues that affect them.","zh":"校報讓學生可以就影響自己的議題發聲。"},{"en":"A costume can give a shy person a new way to communicate identity.","zh":"服裝可以給害羞的人一種表達身份的新方法。"},{"en":"Having a voice means more than speaking loudly; it means feeling that your expression matters.","zh":"有發聲機會不只是說得大聲，而是感覺自己的表達有價值。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"willing to","meaning":"願意","examples":[{"en":"Karen was willing to walk around in a dramatic costume.","zh":"Karen願意穿着戲劇感強烈的服裝四處走動。"},{"en":"To be willing to do something means to be ready or prepared to do it even if it may be difficult.","zh":"「be willing to」表示即使事情可能困難，也準備或願意去做。"},{"en":"She was willing to speak first when nobody else volunteered.","zh":"沒有人自願時，她願意第一個發言。"},{"en":"Confidence may grow when someone becomes willing to try an uncomfortable action.","zh":"當人開始願意嘗試不舒服的行動，自信可能增加。"},{"en":"Being willing does not mean having no fear; it means deciding to act despite it.","zh":"願意並不表示完全不怕，而是即使害怕仍決定行動。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"walk around","meaning":"四處走動","examples":[{"en":"Karen walked around in a dramatic red-and-black costume.","zh":"Karen穿着具戲劇感的紅黑服裝四處走動。"},{"en":"To walk around means to move on foot through an area without necessarily heading directly to one destination.","zh":"「walk around」表示在某個範圍內步行活動，不一定直接前往單一目的地。"},{"en":"Visitors walked around the exhibition for several hours.","zh":"訪客在展覽中四處走了幾小時。"},{"en":"Walking around in costume exposes a cosplayer to many strangers’ attention.","zh":"穿着服裝四處走動會令角色扮演者受到很多陌生人注意。"},{"en":"Public movement can feel challenging for someone who normally avoids being noticed.","zh":"對平時避免被注意的人來說，公開四處走動可以很有挑戰。"}],"source":"2023 Q3.pdf","sourcePage":8},{"front":"dramatic red-and-black costume","meaning":"具戲劇感的紅黑色服裝","examples":[{"en":"Karen wore a dramatic red-and-black costume.","zh":"Karen穿着具戲劇感的紅黑色服裝。"},{"en":"A dramatic red-and-black costume is a striking outfit using strong red and black colours to create a bold effect.","zh":"具戲劇感的紅黑色服裝是使用強烈紅黑色對比、營造大膽效果的服裝。"},{"en":"The stage performer wore a dramatic red-and-black costume under bright lights.","zh":"舞台表演者在強光下穿着具戲劇感的紅黑服裝。"},{"en":"Strong colour contrast can make a costume visually powerful.","zh":"強烈顏色對比可以令服裝在視覺上很有力量。"},{"en":"A dramatic outfit can help the wearer feel temporarily different from their everyday self.","zh":"戲劇感強的服裝可以令穿着者暫時感覺不同於日常的自己。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"in front of thousands of people","meaning":"在數千人面前","examples":[{"en":"Karen wore the costume in front of thousands of people.","zh":"Karen在數千人面前穿着那套服裝。"},{"en":"“In front of thousands of people” means publicly where a very large crowd could see her.","zh":"「in front of thousands of people」表示在非常龐大人群都能看見的公開場合。"},{"en":"The singer performed in front of thousands of people at the stadium.","zh":"歌手在體育館數千人面前表演。"},{"en":"Appearing before a large crowd can be intimidating for someone who lacks confidence.","zh":"對缺乏自信的人來說，在大量人面前出現可以令人害怕。"},{"en":"Cosplay gave Karen a reason to practise being visible in a very public setting.","zh":"角色扮演給Karen一個在非常公開環境練習被看見的理由。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"unexpectedly quiet","meaning":"出乎意料地平靜","examples":[{"en":"Karen’s answer was unexpectedly quiet.","zh":"Karen的回答出乎意料地平靜。"},{"en":"“Unexpectedly quiet” means softer or calmer than the listener had expected.","zh":"「unexpectedly quiet」表示比聽者原本預期更輕聲或平靜。"},{"en":"After her energetic performance, her interview voice was unexpectedly quiet.","zh":"她表演非常有活力，但接受訪問時聲音出乎意料地輕。"},{"en":"A dramatic appearance does not necessarily mean the person is naturally loud or confident.","zh":"外表很戲劇化，不代表本人天生很大聲或很有自信。"},{"en":"The contrast can reveal a more private side of someone’s personality.","zh":"這種對比可以揭示一個人較私人的一面。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"not very confident","meaning":"不太有自信","examples":[{"en":"Karen said she was not very confident at school.","zh":"Karen說自己在學校不太有自信。"},{"en":"“Not very confident” means lacking strong belief in your ability or comfort in expressing yourself.","zh":"「not very confident」表示對自己的能力或表達自己缺乏強烈信心。"},{"en":"He was not very confident about speaking English in front of the class.","zh":"他不太有自信在全班面前說英語。"},{"en":"Someone may appear confident in one setting but not very confident in another.","zh":"一個人可以在某個場合看起來有自信，在另一個場合卻不太有自信。"},{"en":"Confidence can depend strongly on context and identity.","zh":"自信可以很受情境和身份影響。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"become this character","meaning":"成為這個角色","examples":[{"en":"When Karen becomes this character, she can stand straighter.","zh":"當Karen成為這個角色時，她可以站得更挺直。"},{"en":"To become this character means to take on the role, appearance and behaviour of the fictional person being portrayed.","zh":"成為這個角色表示採用所扮演虛構人物的身分、外觀和行為。"},{"en":"On stage, the shy actor seemed to become the confident character completely.","zh":"在舞台上，那個害羞演員好像完全成為自信角色。"},{"en":"A fictional role can give someone temporary permission to behave differently.","zh":"虛構角色可以暫時給人許可，用不同方式表現自己。"},{"en":"Trying out another identity can reveal abilities that everyday habits usually hide.","zh":"嘗試另一種身份，可以揭示日常習慣通常隱藏的能力。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"stand straighter","meaning":"站得更挺直","examples":[{"en":"Cosplay helps Karen stand straighter.","zh":"角色扮演幫助Karen站得更挺直。"},{"en":"To stand straighter means to hold your body more upright, often suggesting greater confidence.","zh":"站得更挺直表示身體姿勢更直，常帶有更有自信的感覺。"},{"en":"She stood straighter after hearing the audience applaud.","zh":"聽到觀眾掌聲後，她站得更挺直。"},{"en":"Clothing and role can influence how someone physically carries themselves.","zh":"服裝和角色可以影響一個人的身體姿態。"},{"en":"Standing straighter can symbolise a change in confidence as well as posture.","zh":"站得更挺直既可以表示姿勢改變，也可以象徵自信提升。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"stayed with me","meaning":"留在我心裏","examples":[{"en":"That sentence stayed with me.","zh":"那句話一直留在我心裏。"},{"en":"If something stays with you, you continue remembering or thinking about it after the moment has passed.","zh":"如果某件事「stays with you」，表示事情過後你仍然記得或反覆思考。"},{"en":"The teacher’s final advice stayed with me for years.","zh":"老師最後的忠告多年來一直留在我心裏。"},{"en":"Karen’s quiet comment stayed with the reporter because it revealed a deeper meaning of cosplay.","zh":"Karen平靜的說話一直留在記者心裏，因為它揭示角色扮演更深層的意義。"},{"en":"Powerful ideas often stay with us when they connect with something emotionally important.","zh":"當一個想法連結到重要情感，它往往會長久留在心中。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"an escape from reality","meaning":"逃避現實","examples":[{"en":"For some teenagers, cosplay is not an escape from reality.","zh":"對一些青少年來說，角色扮演不是逃避現實。"},{"en":"An escape from reality is an activity used mainly to avoid thinking about ordinary problems or responsibilities.","zh":"逃避現實是主要用來不去想日常問題或責任的活動。"},{"en":"Watching films can sometimes feel like an escape from reality after a stressful day.","zh":"壓力大的一天後，看電影有時像是一種逃避現實。"},{"en":"Cosplay may look like escape, but participants can also develop real-world skills through it.","zh":"角色扮演看似逃避，但參與者也可以從中發展真實世界技能。"},{"en":"An imaginative hobby can connect with reality rather than simply avoid it.","zh":"有想像力的興趣可以與現實連結，而不只是逃避它。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"a rehearsal for courage","meaning":"勇氣的預演","examples":[{"en":"For some teenagers, cosplay is a rehearsal for courage.","zh":"對一些青少年來說，角色扮演是勇氣的預演。"},{"en":"“A rehearsal for courage” is a metaphor meaning a safe opportunity to practise brave behaviour before using it in everyday life.","zh":"「a rehearsal for courage」是一個比喻，表示在日常生活真正使用勇氣前，先在安全情況練習勇敢行為。"},{"en":"A classroom presentation can become a rehearsal for courage for a shy student.","zh":"對害羞學生來說，課堂簡報可以成為勇氣的預演。"},{"en":"Speaking to strangers in costume may help someone practise being more confident.","zh":"穿服裝與陌生人交談，可以幫助人練習更有自信。"},{"en":"Courage often grows through repeated small acts rather than one dramatic moment.","zh":"勇氣往往透過反覆的小行動建立，而不是單一戲劇化時刻。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"shy student","meaning":"害羞的學生","examples":[{"en":"A shy student can practise speaking to strangers through cosplay.","zh":"害羞的學生可以透過角色扮演練習與陌生人說話。"},{"en":"A shy student is a learner who feels uncomfortable or nervous in social situations.","zh":"害羞的學生是在社交情況中容易感到不自在或緊張的學習者。"},{"en":"The shy student rarely volunteered to answer questions aloud.","zh":"那個害羞學生很少主動大聲回答問題。"},{"en":"A structured hobby can give a shy student a clear reason to start conversations.","zh":"有結構的興趣活動可以給害羞學生一個清楚理由開始對話。"},{"en":"Shyness does not mean a person lacks ideas or creativity.","zh":"害羞並不代表一個人缺乏想法或創意。"}],"source":"2023 Q3.pdf","sourcePage":9},{"front":"practise speaking to strangers","meaning":"練習與陌生人說話","examples":[{"en":"Cosplay allows shy students to practise speaking to strangers.","zh":"角色扮演讓害羞學生練習與陌生人說話。"},{"en":"To practise speaking to strangers means to build confidence by talking with people you do not already know.","zh":"練習與陌生人說話表示透過與不認識的人交談建立自信。"},{"en":"Volunteering at an information booth helped her practise speaking to strangers.","zh":"在資訊攤位做義工幫助她練習與陌生人說話。"},{"en":"Asking for photos gives cosplayers many short, manageable conversations.","zh":"拍照交流給角色扮演者很多短而容易處理的對話。"},{"en":"Repeated low-pressure conversations can make social situations feel less frightening.","zh":"反覆進行低壓對話，可以令社交情況沒有那麼可怕。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"anxious fan","meaning":"焦慮的粉絲","examples":[{"en":"An anxious fan can find others who understand the same fictional universe.","zh":"焦慮的粉絲可以找到理解同一虛構世界觀的人。"},{"en":"An anxious fan is a person who enjoys a work but may feel nervous or uncomfortable socially.","zh":"焦慮的粉絲是喜歡某項作品，但在社交上可能感到緊張或不自在的人。"},{"en":"The anxious fan stayed near the edge of the crowd at first.","zh":"那個焦慮的粉絲起初留在人群邊緣。"},{"en":"Finding people with the same interest can make an anxious fan feel safer.","zh":"找到有相同興趣的人，可以令焦慮粉絲感覺更安全。"},{"en":"Shared hobbies can reduce the pressure of having to invent a conversation topic.","zh":"共同興趣可以減少需要自己想話題的壓力。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"fictional universe","meaning":"虛構世界觀","examples":[{"en":"Fans can meet others who understand the same fictional universe.","zh":"粉絲可以遇到理解同一虛構世界觀的人。"},{"en":"A fictional universe is the complete imaginary world, characters, history and rules created for a story or series.","zh":"虛構世界觀是為故事或系列建立的完整想像世界、人物、歷史和規則。"},{"en":"The game’s fictional universe includes several planets and different species.","zh":"那個遊戲的虛構世界觀包括幾個星球和不同物種。"},{"en":"Fans may spend years learning details about a favourite fictional universe.","zh":"粉絲可能花多年了解自己喜愛虛構世界的細節。"},{"en":"Shared knowledge of a fictional universe can create instant social connection.","zh":"共同了解一個虛構世界，可以立即建立社交連結。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"young artist","meaning":"年輕藝術創作者","examples":[{"en":"A young artist can receive praise for creativity.","zh":"年輕藝術創作者可以因創意獲得讚賞。"},{"en":"A young artist is a young person who creates visual, performance or other artistic work.","zh":"年輕藝術創作者是創作視覺、表演或其他藝術作品的年輕人。"},{"en":"The young artist displayed handmade illustrations at the community fair.","zh":"那位年輕藝術創作者在社區市集展示手繪插圖。"},{"en":"Cosplay can give a young artist an audience outside school examinations.","zh":"角色扮演可以給年輕藝術創作者一個學校考試以外的觀眾群。"},{"en":"Recognition for creative work can strengthen an artist’s confidence and motivation.","zh":"創作得到認可可以提升藝術創作者的自信和動力。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"receive praise","meaning":"獲得讚賞","examples":[{"en":"A young artist can receive praise for creativity.","zh":"年輕藝術創作者可以因創意獲得讚賞。"},{"en":"To receive praise means to be given positive comments or recognition for something done well.","zh":"獲得讚賞表示因做得好而得到正面評論或認可。"},{"en":"She received praise from her teacher for improving the project.","zh":"她因改善專題而得到老師讚賞。"},{"en":"Positive feedback can encourage creators to continue practising.","zh":"正面回饋可以鼓勵創作者繼續練習。"},{"en":"Praise can be especially meaningful when it recognises a strength that formal tests rarely measure.","zh":"當讚賞認可的是正式考試很少量度的長處，它會特別有意義。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"exam marks","meaning":"考試分數","examples":[{"en":"A young artist can receive praise not for exam marks, but for creativity.","zh":"年輕藝術創作者可以不是因考試分數，而是因創意獲得讚賞。"},{"en":"Exam marks are numerical scores or grades showing performance in tests or examinations.","zh":"考試分數是顯示測驗或考試表現的數字成績或等級。"},{"en":"Some students place too much pressure on themselves because of exam marks.","zh":"有些學生因考試分數而給自己太大壓力。"},{"en":"Creative events can recognise abilities that exam marks do not measure well.","zh":"創意活動可以認可考試分數不容易量度的能力。"},{"en":"Education becomes broader when young people are valued for more than academic scores.","zh":"當年輕人得到學業分數以外的肯定，教育會變得更全面。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"creativity","meaning":"創意","examples":[{"en":"Cosplay allows young artists to be praised for creativity.","zh":"角色扮演讓年輕藝術創作者因創意獲得讚賞。"},{"en":"Creativity is the ability to produce original ideas, designs or solutions.","zh":"創意是產生原創想法、設計或解決方法的能力。"},{"en":"The project encouraged creativity by allowing students to choose their own format.","zh":"專題讓學生自行選擇形式，鼓勵創意。"},{"en":"Cosplay requires creativity when participants adapt fictional designs to real materials.","zh":"角色扮演者把虛構設計改成真實材料時需要創意。"},{"en":"Creativity combines imagination with practical decision-making.","zh":"創意把想像與實際決策結合起來。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"excessive to outsiders","meaning":"對局外人來說過分誇張","examples":[{"en":"Some costumes may look excessive to outsiders.","zh":"有些服裝對局外人來說可能過分誇張。"},{"en":"“Excessive to outsiders” means appearing too dramatic, large or unusual to people who do not belong to the community.","zh":"「excessive to outsiders」表示對不屬於該社群的人來說，顯得太戲劇化、太大或太不尋常。"},{"en":"Festival decorations may look excessive to outsiders who do not understand the tradition.","zh":"不理解傳統的局外人可能覺得節日裝飾過分誇張。"},{"en":"What seems excessive from outside may feel completely appropriate within the event.","zh":"從外面看似誇張的東西，在活動內可能完全合適。"},{"en":"Judgments about excess depend partly on cultural context and expectations.","zh":"對「過分」的判斷部分取決於文化背景和期望。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"even so","meaning":"即使如此","examples":[{"en":"Even so, dismissing the whole culture as weird would be unfair.","zh":"即使如此，把整個文化貶低為古怪仍然不公平。"},{"en":"“Even so” means despite the point just acknowledged, the following statement is still true.","zh":"「even so」表示即使承認剛才那一點，之後的說法仍然成立。"},{"en":"The task was difficult; even so, most students completed it.","zh":"任務很困難；即使如此，大部分學生仍完成了。"},{"en":"Some costumes may seem excessive; even so, that does not justify dismissing the whole culture.","zh":"有些服裝可能顯得誇張；即使如此，也不能因此否定整個文化。"},{"en":"This phrase helps writers recognise a criticism while maintaining their main argument.","zh":"這個片語幫助作者承認批評，同時保持主要立場。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"dismiss the whole culture as","meaning":"把整個文化貶低為","examples":[{"en":"It would be unfair to dismiss the whole culture as weird.","zh":"把整個文化貶低為古怪是不公平的。"},{"en":"To dismiss a whole culture as something means to reject or belittle it using one simple negative label.","zh":"把整個文化貶低為某事，表示用一個簡單負面標籤否定整體。"},{"en":"We should not dismiss an unfamiliar tradition as pointless before understanding it.","zh":"我們不應在理解前，就把陌生傳統貶低為沒有意義。"},{"en":"One unusual costume cannot justify judging every participant negatively.","zh":"一件不尋常服裝不能合理化對所有參與者的負面判斷。"},{"en":"Broad dismissal prevents people from seeing complexity and individual differences.","zh":"一概否定會令人看不到複雜性和個人差異。"}],"source":"2023 Q3.pdf","sourcePage":10},{"front":"weird","meaning":"古怪","examples":[{"en":"Some outsiders may wrongly dismiss cosplay as weird.","zh":"有些局外人可能錯誤地把角色扮演貶低為古怪。"},{"en":"Weird means very unusual, unfamiliar or difficult to understand according to someone’s expectations.","zh":"「weird」表示按照某人的期望看來非常不尋常、陌生或難理解。"},{"en":"The food looked weird to him only because he had never seen it before.","zh":"那種食物對他看起來很古怪，只因他從未見過。"},{"en":"What one culture finds weird may be ordinary in another community.","zh":"一種文化覺得古怪的事情，在另一個社群可能很普通。"},{"en":"Calling something weird can reveal unfamiliarity more than any real problem with the thing itself.","zh":"把某事叫做古怪，有時更多反映陌生，而不是事情本身真的有問題。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"what matters is not whether…but whether…","meaning":"重要的不是是否……而是是否……","examples":[{"en":"What matters is not whether we recognise every character, but whether we recognise the effort.","zh":"重要的不是我們是否認出每個角色，而是是否看見背後的努力。"},{"en":"This structure means the first question is less important than the second one.","zh":"這個句式表示第一個問題沒有第二個問題重要。"},{"en":"What matters is not whether the answer is fast, but whether it is accurate.","zh":"重要的不是答案是否快，而是是否準確。"},{"en":"Outsiders do not need to understand every fictional reference to appreciate the work involved.","zh":"局外人不用明白每一個虛構細節，也能欣賞當中的工作。"},{"en":"The pattern redirects attention from a surface issue to the deeper point.","zh":"這個句式把注意力由表面問題轉到更深層重點。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"recognise every character","meaning":"認出每個角色","examples":[{"en":"We may not recognise every character at Anime Expo.","zh":"我們未必能認出動漫展的每個角色。"},{"en":"To recognise every character means to know the identity of all the fictional figures being represented.","zh":"認出每個角色表示知道所有被扮演虛構人物的身分。"},{"en":"I recognised some heroes but not every character in the parade.","zh":"我認出遊行中的一些英雄，但不是每個角色。"},{"en":"Visitors can appreciate costume quality even when they do not recognise the character.","zh":"即使不認識角色，訪客仍可以欣賞服裝質素。"},{"en":"Cultural appreciation does not require complete specialist knowledge.","zh":"欣賞文化不需要擁有完整專門知識。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"effort behind the costume","meaning":"服裝背後的努力","examples":[{"en":"We should recognise the effort behind the costume.","zh":"我們應看見服裝背後的努力。"},{"en":"“The effort behind the costume” means the time, skill, planning and repeated work required to create it.","zh":"「the effort behind the costume」表示製作服裝所需要的時間、技巧、規劃和反覆工作。"},{"en":"Photographs rarely show the effort behind a handmade performance outfit.","zh":"照片很少能展示手製表演服裝背後的努力。"},{"en":"Sewing, painting and rebuilding are all part of the effort behind cosplay.","zh":"縫紉、上色和重做都是角色扮演背後努力的一部分。"},{"en":"Looking beyond appearance helps people value process as well as result.","zh":"不只看外表，可以令人同時重視過程和成果。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"youth culture","meaning":"青年文化","examples":[{"en":"The exhibition showed how youth culture connects Hong Kong with the wider world.","zh":"展覽展示青年文化如何把香港與更廣闊的世界連繫起來。"},{"en":"Youth culture is the shared interests, styles, media, language and activities associated with young people.","zh":"青年文化是與年輕人相關的共同興趣、風格、媒體、語言和活動。"},{"en":"Music, fashion and online communities are important parts of youth culture.","zh":"音樂、時尚和網上社群都是青年文化重要部分。"},{"en":"Anime and gaming can connect local youth culture with international trends.","zh":"動畫和遊戲可以把本地青年文化與國際潮流連接。"},{"en":"Youth culture often spreads quickly because young people communicate across digital platforms.","zh":"年輕人透過數碼平台交流，因此青年文化常傳播得很快。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"connects Hong Kong with","meaning":"把香港與……連繫起來","examples":[{"en":"Youth culture connects Hong Kong with the wider world.","zh":"青年文化把香港與更廣闊的世界連繫起來。"},{"en":"To connect Hong Kong with something means to create links between the city and other places, communities or ideas.","zh":"把香港與某事連繫起來，表示在城市與其他地方、社群或想法之間建立聯繫。"},{"en":"International education connects Hong Kong with universities around the world.","zh":"國際教育把香港與世界各地大學連繫起來。"},{"en":"Shared entertainment allows local fans to participate in global conversations.","zh":"共同娛樂讓本地粉絲參與全球話題。"},{"en":"Cultural connection can happen through hobbies as well as business or travel.","zh":"文化連繫既可以透過興趣建立，也可以透過商業或旅行建立。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"the wider world","meaning":"更廣闊的世界","examples":[{"en":"Anime Expo connects Hong Kong with the wider world.","zh":"動漫展把香港與更廣闊的世界連繫起來。"},{"en":"“The wider world” refers to people, places and cultures beyond one’s immediate local environment.","zh":"「the wider world」指自己本地生活範圍以外的人、地方和文化。"},{"en":"Exchange programmes help students learn about the wider world.","zh":"交流計劃幫助學生認識更廣闊的世界。"},{"en":"International pop culture gives young people contact with the wider world without leaving home.","zh":"國際流行文化令年輕人不用離家也能接觸更廣闊世界。"},{"en":"Local identity can remain strong while people participate in the wider world.","zh":"人可以保持本地身份，同時參與更廣闊的世界。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"booths sold","meaning":"攤位售賣","examples":[{"en":"Booths sold comics, game merchandise and handmade accessories.","zh":"攤位售賣漫畫、遊戲周邊商品和手製配飾。"},{"en":"“Booths sold” means small exhibition stalls offered particular products for visitors to buy.","zh":"「booths sold」表示展覽中的小攤位向訪客提供某些產品購買。"},{"en":"Festival booths sold food, crafts and souvenirs.","zh":"節日攤位售賣食物、手工藝和紀念品。"},{"en":"Different booths can represent commercial brands as well as independent creators.","zh":"不同攤位可以代表商業品牌，也可以代表獨立創作者。"},{"en":"Shopping is one part of an exhibition, but it may exist alongside community and cultural activity.","zh":"購物只是展覽一部分，也可以與社群和文化活動並存。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"comics","meaning":"漫畫","examples":[{"en":"Booths sold comics and game merchandise.","zh":"攤位售賣漫畫和遊戲周邊商品。"},{"en":"Comics are stories told through sequences of drawings, usually combined with written dialogue or narration.","zh":"漫畫是透過一連串圖畫講故事，通常配合文字對白或旁白。"},{"en":"She bought a comic from an independent artist.","zh":"她向一名獨立藝術家買了一本漫畫。"},{"en":"Comics can inspire films, animation, games and cosplay.","zh":"漫畫可以啟發電影、動畫、遊戲和角色扮演。"},{"en":"Visual storytelling allows readers to understand character and action through both words and images.","zh":"視覺敘事讓讀者同時透過文字和圖像理解人物和行動。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"game merchandise","meaning":"遊戲周邊商品","examples":[{"en":"Game merchandise was sold at the exhibition.","zh":"展覽有售遊戲周邊商品。"},{"en":"Game merchandise means products connected with video games, such as figures, clothing, posters or accessories.","zh":"遊戲周邊商品是與電子遊戲相關的產品，例如模型、服裝、海報或配飾。"},{"en":"Fans bought game merchandise featuring their favourite characters.","zh":"粉絲購買印有最喜愛角色的遊戲周邊商品。"},{"en":"Merchandise allows people to express their interests outside the game itself.","zh":"周邊商品讓人在遊戲本身以外表達自己的興趣。"},{"en":"Popular fictional worlds can support large markets of related products.","zh":"受歡迎虛構世界可以形成龐大的相關產品市場。"}],"source":"2023 Q3.pdf","sourcePage":11},{"front":"handmade accessories","meaning":"手製配飾","examples":[{"en":"Some booths sold handmade accessories.","zh":"一些攤位售賣手製配飾。"},{"en":"Handmade accessories are small decorative or useful items made by hand rather than mass-produced.","zh":"手製配飾是由人手製作，而不是大量生產的小型裝飾或實用品。"},{"en":"The market sold handmade accessories such as bracelets and hair clips.","zh":"市集售賣手製手鏈和髮夾等配飾。"},{"en":"Handmade items can show the individual style of local creators.","zh":"手製物品可以展示本地創作者的個人風格。"},{"en":"Buying handmade accessories can directly support independent artists.","zh":"購買手製配飾可以直接支持獨立藝術家。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"within minutes","meaning":"在幾分鐘內","examples":[{"en":"I heard several languages within minutes.","zh":"我在幾分鐘內便聽到幾種語言。"},{"en":"“Within minutes” means in only a few minutes or before much time had passed.","zh":"「within minutes」表示只在幾分鐘之內，沒有經過很長時間。"},{"en":"Within minutes, the rain had filled the street with water.","zh":"幾分鐘內，大雨已令街道積滿水。"},{"en":"Hearing several languages quickly showed how international the crowd was.","zh":"很快聽到幾種語言，顯示人群有多國際化。"},{"en":"The phrase emphasises how rapidly an impression formed.","zh":"這個片語強調某個印象形成得很快。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"famous studios","meaning":"著名工作室","examples":[{"en":"Some visitors came for famous studios.","zh":"一些訪客為著名工作室而來。"},{"en":"Famous studios are well-known companies or creative teams that produce animation, games, films or related works.","zh":"著名工作室是製作動畫、遊戲、電影或相關作品的知名公司或創作團隊。"},{"en":"Fans queued to see artwork from famous studios.","zh":"粉絲排隊觀看著名工作室的作品。"},{"en":"Major studios can attract large crowds because visitors already recognise their brands.","zh":"大型工作室因品牌已被認識，可以吸引大量人群。"},{"en":"Large exhibitions can place famous companies beside small independent creators.","zh":"大型展覽可以讓著名公司與小型獨立創作者同場出現。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"local creators","meaning":"本地創作者","examples":[{"en":"Other visitors supported local creators.","zh":"其他訪客支持本地創作者。"},{"en":"Local creators are artists, designers, writers or makers who produce work within the local community or region.","zh":"本地創作者是在本地社區或地區製作作品的藝術家、設計師、作家或製作者。"},{"en":"The market gave local creators space to sell original artwork.","zh":"市集給本地創作者空間售賣原創作品。"},{"en":"Supporting local creators helps money and attention remain within the creative community.","zh":"支持本地創作者可以令金錢和關注留在創意社群之中。"},{"en":"Local creators can bring familiar places and experiences into popular culture.","zh":"本地創作者可以把熟悉地方和經驗帶進流行文化。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"in this sense","meaning":"從這個意義上說","examples":[{"en":"In this sense, Anime Expo was more than a shopping event.","zh":"從這個意義上說，動漫展不只是一個購物活動。"},{"en":"“In this sense” means when considered from the particular viewpoint just explained.","zh":"「in this sense」表示從剛才解釋的特定角度考慮。"},{"en":"Volunteering builds confidence; in this sense, it is also a form of education.","zh":"義工服務可以建立自信；從這個意義上說，它也是一種教育。"},{"en":"Because the exhibition connected people and cultures, it had value beyond shopping.","zh":"因為展覽連結人和文化，所以價值超越購物。"},{"en":"This phrase helps a writer draw a broader conclusion from earlier examples.","zh":"這個片語幫助作者由之前例子得出更廣泛結論。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"more than a shopping event","meaning":"不只是一個購物活動","examples":[{"en":"Anime Expo was more than a shopping event.","zh":"動漫展不只是一個購物活動。"},{"en":"“More than a shopping event” means its value extended beyond buying and selling products.","zh":"「more than a shopping event」表示它的價值超越買賣產品。"},{"en":"The weekend market became more than a shopping event because neighbours met and performed there.","zh":"週末市集因鄰居在那裏見面和表演，而不只是一個購物活動。"},{"en":"Anime Expo also involved creativity, community and cultural exchange.","zh":"動漫展也涉及創意、社群和文化交流。"},{"en":"An event can have social meaning even when commercial activity is clearly present.","zh":"即使明顯有商業活動，一項活動仍可以具有社會意義。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"cultural bridge","meaning":"文化橋樑","examples":[{"en":"Anime Expo was a cultural bridge.","zh":"動漫展是一座文化橋樑。"},{"en":"A cultural bridge is something that connects people, ideas or communities from different cultural backgrounds.","zh":"文化橋樑是連接不同文化背景的人、想法或社群的事物。"},{"en":"Translation can act as a cultural bridge between readers from different countries.","zh":"翻譯可以成為不同國家讀者之間的文化橋樑。"},{"en":"Anime events connect Japanese-inspired media with local fans and creators.","zh":"動漫活動把日本文化啟發的媒體與本地粉絲和創作者連接起來。"},{"en":"A cultural bridge reduces distance by creating shared experiences.","zh":"文化橋樑透過共同經驗縮短彼此距離。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"linking entertainment with art","meaning":"把娛樂與藝術連繫起來","examples":[{"en":"The exhibition linked entertainment with art.","zh":"展覽把娛樂與藝術連繫起來。"},{"en":"“Linking entertainment with art” means connecting enjoyable popular activities with creative artistic expression.","zh":"「linking entertainment with art」表示把令人享受的流行活動與藝術創作連接。"},{"en":"A film festival links entertainment with art through screenings and exhibitions.","zh":"電影節透過放映和展覽把娛樂與藝術連繫起來。"},{"en":"Cosplay is entertaining to watch but also involves design and craftsmanship.","zh":"角色扮演看起來有娛樂性，同時也涉及設計和工藝。"},{"en":"The boundary between entertainment and art can become less clear in creative communities.","zh":"在創意社群中，娛樂與藝術之間的界線可以變得模糊。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"technology with storytelling","meaning":"把科技與故事創作連繫起來","examples":[{"en":"The exhibition linked technology with storytelling.","zh":"展覽把科技與故事創作連繫起來。"},{"en":"“Technology with storytelling” means using technical tools or devices to help create and communicate stories.","zh":"「technology with storytelling」表示利用技術工具或裝置幫助創作和傳達故事。"},{"en":"Video games link technology with storytelling through interactive worlds.","zh":"電子遊戲透過互動世界把科技與故事創作連繫起來。"},{"en":"LED costume effects can make fictional characters feel more convincing.","zh":"LED服裝效果可以令虛構角色更有說服力。"},{"en":"Technology becomes more meaningful when it supports a story rather than existing only as a technical display.","zh":"當科技支援故事，而不只是展示技術，它會更有意義。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"hobbies with community","meaning":"把興趣與社群連繫起來","examples":[{"en":"Anime Expo linked hobbies with community.","zh":"動漫展把興趣與社群連繫起來。"},{"en":"“Linking hobbies with community” means turning individual interests into shared social relationships and group identity.","zh":"把興趣與社群連繫起來，表示把個人愛好變成共同社交關係和群體身份。"},{"en":"A running club links a personal hobby with community.","zh":"跑步會把個人興趣與社群連繫起來。"},{"en":"Fans who usually enjoy anime alone can meet others at an exhibition.","zh":"平時獨自欣賞動畫的粉絲可以在展覽中認識其他人。"},{"en":"Shared hobbies often become stronger when people can enjoy them together.","zh":"當人能一起享受，共同興趣通常會變得更有力量。"}],"source":"2023 Q3.pdf","sourcePage":12},{"front":"globally aware","meaning":"具全球意識的","examples":[{"en":"Schools want students to become creative and globally aware.","zh":"學校希望學生變得有創意和具全球意識。"},{"en":"Globally aware means understanding that people, cultures and issues are connected across countries.","zh":"具全球意識表示理解不同國家的人、文化和議題彼此連繫。"},{"en":"Reading international news can help students become more globally aware.","zh":"閱讀國際新聞可以幫助學生更具全球意識。"},{"en":"Events involving different languages and cultures can broaden young people’s perspectives.","zh":"涉及不同語言和文化的活動可以擴闊年輕人視野。"},{"en":"Being globally aware means understanding differences without losing awareness of local identity.","zh":"具全球意識表示理解差異，同時不失去對本地身份的認識。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"expressive","meaning":"善於表達的","examples":[{"en":"Cosplay can help students become more expressive.","zh":"角色扮演可以幫助學生變得更善於表達。"},{"en":"Expressive means able to communicate thoughts, emotions or personality clearly and creatively.","zh":"「expressive」表示能清楚而有創意地表達思想、情感或個性。"},{"en":"The actor was highly expressive through voice and body movement.","zh":"那位演員透過聲音和身體動作非常善於表達。"},{"en":"Costume, pose and conversation give participants several ways to be expressive.","zh":"服裝、姿勢和談話給參與者幾種表達方法。"},{"en":"A person can become more expressive when they feel safe from judgment.","zh":"當人感覺不受批判，就可能變得更善於表達。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"ignore the places where","meaning":"忽視……出現的地方","examples":[{"en":"Schools should not ignore the places where creativity appears naturally.","zh":"學校不應忽視創意自然出現的地方。"},{"en":"To ignore the places where something appears means to fail to notice or value environments in which it already exists.","zh":"忽視某事出現的地方，表示沒有留意或重視它已經存在的環境。"},{"en":"Businesses should not ignore the places where young customers actually spend time.","zh":"企業不應忽視年輕顧客真正花時間的地方。"},{"en":"Creativity may develop outside classrooms in clubs, events and online communities.","zh":"創意可以在課室以外的學會、活動和網上社群發展。"},{"en":"Education can learn from spaces where young people already show motivation voluntarily.","zh":"教育可以向年輕人自願展示動力的空間學習。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"appear naturally","meaning":"自然出現","examples":[{"en":"Creativity and expression already appear naturally at events like Anime Expo.","zh":"創意和表達能力已經在動漫展這類活動中自然出現。"},{"en":"To appear naturally means to emerge without being forced or formally required.","zh":"「appear naturally」表示不用強迫或正式要求便自行出現。"},{"en":"Leadership sometimes appears naturally when a group faces a problem.","zh":"小組遇到問題時，領導能力有時會自然出現。"},{"en":"Fans create, perform and communicate because they genuinely want to participate.","zh":"粉絲創作、表演和交流，是因為他們真心想參與。"},{"en":"Skills shown voluntarily can reveal interests that formal lessons may not easily uncover.","zh":"自願展示的技能可以揭示正式課堂未必容易發現的興趣。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"by the time I left","meaning":"到我離開時","examples":[{"en":"By the time I left, the crowd was still moving through the halls.","zh":"到我離開時，人群仍在展覽廳中流動。"},{"en":"“By the time I left” means when I eventually departed after spending some time there.","zh":"「by the time I left」表示我在那裏逗留一段時間後終於離開的時候。"},{"en":"By the time I left the library, it was already dark outside.","zh":"到我離開圖書館時，外面已經天黑。"},{"en":"The crowd was still active even at the point when the reporter departed.","zh":"即使記者準備離開，人群仍然很活躍。"},{"en":"This phrase helps show how the atmosphere continued over time.","zh":"這個片語幫助顯示氣氛如何持續了一段時間。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"cape","meaning":"斗篷","examples":[{"en":"The magician’s cape was still sweeping the floor.","zh":"魔法師的斗篷仍在拂過地面。"},{"en":"A cape is a loose outer garment hanging from the shoulders, often worn by fantasy characters or superheroes.","zh":"斗篷是從肩膀垂下的鬆身外衣，奇幻角色或超級英雄常穿着。"},{"en":"The actor’s black cape moved behind him as he crossed the stage.","zh":"演員走過舞台時，黑色斗篷在身後飄動。"},{"en":"A long cape can make a costume appear more dramatic.","zh":"長斗篷可以令服裝看起來更有戲劇感。"},{"en":"Fabric movement can become an important part of visual character design.","zh":"布料的移動可以成為角色視覺設計的重要部分。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"sweeping the floor","meaning":"拂過地面","examples":[{"en":"The magician’s cape was still sweeping the floor.","zh":"魔法師的斗篷仍在拂過地面。"},{"en":"“Sweeping the floor” here means brushing lightly across the floor as the fabric moves.","zh":"這裏的「sweeping the floor」表示布料移動時輕輕掠過地面。"},{"en":"Her long wedding dress was sweeping the floor behind her.","zh":"她的長婚紗在身後拂過地面。"},{"en":"A long cape may sweep the floor and create graceful movement.","zh":"長斗篷可以拂過地面，營造優雅動態。"},{"en":"This description helps readers picture the costume continuing to move through the crowd.","zh":"這個描述幫助讀者想像服裝仍在人群中移動。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"moving like a bright river","meaning":"像明亮河流般移動","examples":[{"en":"The crowd was moving like a bright river through the halls.","zh":"人群像明亮河流般穿過展覽廳。"},{"en":"“Moving like a bright river” compares a colourful flowing crowd with water moving continuously.","zh":"「moving like a bright river」把色彩繽紛而流動的人群比作持續流動的河水。"},{"en":"Festival lanterns moved through the street like a river of light.","zh":"節日燈籠像一道光河般穿過街道。"},{"en":"Costumes and movement made the crowd appear colourful and flowing rather than static.","zh":"服裝和走動令整個人群看起來色彩豐富而流動，不是靜止。"},{"en":"The simile turns an ordinary crowd into a vivid visual image.","zh":"這個明喻把普通人群變成生動視覺畫面。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"through the halls","meaning":"穿過展覽廳","examples":[{"en":"The crowd moved through the halls.","zh":"人群穿過展覽廳。"},{"en":"“Through the halls” means moving inside and across the large interior spaces of the exhibition venue.","zh":"「through the halls」表示在展覽場地的大型室內空間中移動和穿行。"},{"en":"Visitors walked through the halls looking for different booths.","zh":"訪客穿過不同展覽廳尋找攤位。"},{"en":"The phrase suggests continuous movement across several parts of the venue.","zh":"這個片語帶有不斷穿梭場地不同部分的感覺。"},{"en":"Large exhibition halls allow thousands of people to circulate between activities.","zh":"大型展覽廳讓數千人可以在不同活動之間流動。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"arrived expecting","meaning":"到達時原本期待","examples":[{"en":"I had arrived expecting colourful costumes.","zh":"我到達時原本期待看見色彩繽紛的服裝。"},{"en":"“Arrived expecting” means came to a place with a particular idea about what you thought you would see or experience.","zh":"「arrived expecting」表示到達某地時，心中已對會看見或經歷甚麼有某種預期。"},{"en":"We arrived expecting a quiet meeting but found a lively celebration.","zh":"我們到達時原本期待一場安靜會議，卻發現是一場熱鬧慶祝。"},{"en":"The reporter expected visual spectacle rather than deeper personal stories.","zh":"記者原本期待的是視覺奇觀，而不是更深層的人情故事。"},{"en":"Expectations become important when the actual experience turns out to be different.","zh":"當實際經歷與預期不同，原本期待便變得重要。"}],"source":"2023 Q3.pdf","sourcePage":13},{"front":"colourful costumes","meaning":"色彩繽紛的服裝","examples":[{"en":"I expected to see colourful costumes.","zh":"我原本期待看見色彩繽紛的服裝。"},{"en":"Colourful costumes are outfits using bright, varied or striking colours.","zh":"色彩繽紛的服裝是使用明亮、多樣或搶眼顏色的服飾。"},{"en":"The parade was filled with colourful costumes inspired by fantasy characters.","zh":"遊行充滿由奇幻角色啟發的色彩繽紛服裝。"},{"en":"Colourful costumes attract attention immediately at crowded events.","zh":"在擠迫活動中，色彩繽紛的服裝會立即吸引注意。"},{"en":"Their visual impact may be the first thing outsiders notice, but not the only thing worth understanding.","zh":"它們可能是局外人第一樣看到的東西，但不是唯一值得理解的部分。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"left having seen","meaning":"離開時已看見","examples":[{"en":"I left having seen commitment, courage and community.","zh":"我離開時已看見投入、勇氣和社群。"},{"en":"“Left having seen” means departed after gaining a new understanding or witnessing something important.","zh":"「left having seen」表示離開時已經得到新理解或見證了一些重要事情。"},{"en":"I entered the workshop curious and left having seen how much teamwork mattered.","zh":"我帶着好奇進入工作坊，離開時已看見合作有多重要。"},{"en":"The writer left with a broader view than the one they arrived with.","zh":"作者離開時的看法比到達時更加廣闊。"},{"en":"This structure highlights how an experience changed the observer’s perspective.","zh":"這個句式突出經歷如何改變觀察者的視角。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"commitment","meaning":"承擔；投入","examples":[{"en":"I saw commitment stitched into every seam.","zh":"我看見投入彷彿縫進每一道縫線裏。"},{"en":"Commitment is strong dedication to continuing an activity or responsibility over time.","zh":"投入是長時間持續對一項活動或責任保持高度奉獻。"},{"en":"Her commitment to the project was clear from the hours she spent improving it.","zh":"她花很多時間改善專題，顯示出對項目的投入。"},{"en":"Spending months on one costume shows commitment as well as enthusiasm.","zh":"花幾個月製作一套服裝，顯示的不只是熱情，也是投入。"},{"en":"Commitment becomes visible through repeated effort, especially when the work is difficult.","zh":"尤其工作困難時，反覆努力會令投入變得看得見。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"courage","meaning":"勇氣","examples":[{"en":"The event showed courage as well as creativity.","zh":"活動除了展示創意，也展示勇氣。"},{"en":"Courage is the ability to act despite fear, difficulty or possible judgment.","zh":"勇氣是在恐懼、困難或可能被批評時仍願意行動的能力。"},{"en":"It took courage for the shy student to present in front of the class.","zh":"那個害羞學生在全班面前匯報需要勇氣。"},{"en":"Wearing a dramatic costume publicly can require courage from someone who usually avoids attention.","zh":"對平時避免受注意的人來說，公開穿戲劇性服裝可能需要勇氣。"},{"en":"Courage often appears as a small decision to become visible rather than a dramatic heroic act.","zh":"勇氣常表現在願意讓自己被看見的小決定，而不一定是戲劇化英雄行為。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"community","meaning":"社群","examples":[{"en":"Anime Expo created a sense of community.","zh":"動漫展創造了社群感。"},{"en":"Community is a group of people connected by place, interest, experience or shared identity.","zh":"社群是一群因地點、興趣、經驗或共同身份而連結的人。"},{"en":"The local sports club created a strong community among members.","zh":"本地運動會在會員之間建立強烈社群。"},{"en":"Anime fans may feel part of a community when they meet others who understand the same interests.","zh":"動畫粉絲遇到明白同樣興趣的人時，可能會感覺自己屬於一個社群。"},{"en":"Community gives people social connection beyond the activity itself.","zh":"社群提供活動本身以外的人際連結。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"stitched into every seam","meaning":"縫進每一道縫線裏","examples":[{"en":"I saw commitment, courage and community stitched into every seam.","zh":"我看見投入、勇氣和社群彷彿縫進每一道縫線裏。"},{"en":"“Stitched into every seam” is a metaphor meaning these qualities seemed present in every part of the costumes.","zh":"「stitched into every seam」是一個比喻，表示這些特質好像存在於服裝每個部分。"},{"en":"Years of family history seemed stitched into every piece of the handmade quilt.","zh":"多年家庭歷史彷彿縫進手製被子的每一部分。"},{"en":"Each seam represented time, patience and care rather than fabric alone.","zh":"每一道縫線代表的不只是布料，也包括時間、耐性和用心。"},{"en":"The metaphor turns physical sewing into a symbol of emotional and social effort.","zh":"這個比喻把實際縫紉轉化成情感和社會努力的象徵。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"last only one weekend","meaning":"只維持一個週末","examples":[{"en":"Anime Expo may last only one weekend.","zh":"動漫展可能只維持一個週末。"},{"en":"“Last only one weekend” means continue for just a short two- or three-day period.","zh":"「last only one weekend」表示只持續兩三天左右的短時間。"},{"en":"The festival lasts only one weekend each year.","zh":"那個節日每年只維持一個週末。"},{"en":"A short event can still have effects that continue long after it ends.","zh":"短暫活動結束後，其影響仍可以長時間持續。"},{"en":"Duration does not determine how meaningful an experience can be.","zh":"經歷是否有意義，不取決於持續時間長短。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"confidence it inspires","meaning":"它激發的自信","examples":[{"en":"The confidence Anime Expo inspires can last much longer.","zh":"動漫展所激發的自信可以持續更久。"},{"en":"“The confidence it inspires” means the stronger self-belief the event encourages in participants.","zh":"「the confidence it inspires」表示活動在參與者身上鼓勵出來的更強自我信心。"},{"en":"A supportive performance experience can inspire confidence in a shy student.","zh":"有支持性的表演經驗可以在害羞學生身上激發自信。"},{"en":"Positive attention for creativity may continue influencing someone after the exhibition ends.","zh":"因創意得到正面關注，可以在展覽結束後繼續影響一個人。"},{"en":"An event becomes important when it changes what participants believe they can do.","zh":"當活動改變參與者對自己能力的看法，它便變得重要。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"last much longer","meaning":"持續更久","examples":[{"en":"The confidence it inspires can last much longer.","zh":"它激發的自信可以持續更久。"},{"en":"“Last much longer” means continue for a significantly greater period of time.","zh":"「last much longer」表示持續的時間明顯比另一件事更長。"},{"en":"The meeting lasted one hour, but its consequences lasted much longer.","zh":"會議只持續一小時，但後果持續更久。"},{"en":"A weekend event may end quickly while the friendships formed there last much longer.","zh":"一個週末活動很快完結，但建立的友誼可能持續更久。"},{"en":"Emotional effects can outlive the activity that created them.","zh":"情感影響可以比創造它的活動本身存在更長時間。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"the next time","meaning":"下一次","examples":[{"en":"The next time we see a cosplayer, we should look again.","zh":"下一次我們看見角色扮演者時，應再看清楚。"},{"en":"“The next time” means on the next future occasion when the same kind of situation happens.","zh":"「the next time」表示未來下一次同類情況再次出現時。"},{"en":"The next time you visit the library, look at the new exhibition.","zh":"下一次你去圖書館時，可以看看新展覽。"},{"en":"A new understanding should influence how we respond the next time we meet the same situation.","zh":"新的理解應影響我們下一次遇到相同情況時的反應。"},{"en":"This phrase turns reflection into a future action.","zh":"這個片語把反思轉化成未來行動。"}],"source":"2023 Q3.pdf","sourcePage":14},{"front":"look again","meaning":"再看清楚","examples":[{"en":"We should look again when we see a cosplayer.","zh":"我們看見角色扮演者時應再看清楚。"},{"en":"To look again means to reconsider your first impression and observe more carefully.","zh":"「look again」表示重新考慮第一印象並更仔細觀察。"},{"en":"The painting seemed simple at first, but looking again revealed many details.","zh":"那幅畫第一眼看似簡單，但再看便發現很多細節。"},{"en":"Looking again may reveal effort, confidence and creativity behind an unusual appearance.","zh":"再看清楚可以發現不尋常外表背後的努力、自信和創意。"},{"en":"The phrase encourages curiosity instead of quick judgment.","zh":"這個片語鼓勵好奇，而不是快速判斷。"}],"source":"2023 Q3.pdf","sourcePage":15},{"front":"behind the mask","meaning":"面具背後","examples":[{"en":"Behind the mask, there may be an artist or storyteller.","zh":"面具背後可能是一位藝術家或說故事的人。"},{"en":"“Behind the mask” can literally mean the person wearing it and figuratively mean the real identity hidden behind an appearance.","zh":"「behind the mask」字面可以指戴面具的人，比喻則指外表背後真正的身份。"},{"en":"Behind the superhero mask was a nervous secondary school student.","zh":"超級英雄面具背後是一名緊張的中學生。"},{"en":"A dramatic costume can hide an ordinary person with real skills and feelings.","zh":"戲劇化服裝可以藏着一個有真實技能和感受的普通人。"},{"en":"Looking behind the mask means seeing the human being rather than only the character.","zh":"看面具背後，表示看見真正的人，而不只看角色。"}],"source":"2023 Q3.pdf","sourcePage":15},{"front":"an engineer","meaning":"工程師","examples":[{"en":"Behind the mask, there may be an engineer.","zh":"面具背後可能是一位工程師。"},{"en":"An engineer is someone who applies scientific and technical knowledge to design, build or solve practical problems.","zh":"工程師是運用科學和技術知識去設計、建造或解決實際問題的人。"},{"en":"The engineer designed a lightweight support for the robotic arm.","zh":"工程師為機械手臂設計輕身支架。"},{"en":"Costume construction can involve engineering ideas such as structure, balance and materials.","zh":"服裝建構可以涉及結構、平衡和材料等工程概念。"},{"en":"Hobbies can reveal technical ability that is not obvious from ordinary schoolwork.","zh":"興趣活動可以展示普通課業中不容易看見的技術能力。"}],"source":"2023 Q3.pdf","sourcePage":15},{"front":"a storyteller","meaning":"說故事的人","examples":[{"en":"Behind the mask, there may be a storyteller.","zh":"面具背後可能是一位說故事的人。"},{"en":"A storyteller is someone who communicates narratives through words, images, performance or other creative forms.","zh":"說故事的人是透過文字、影像、表演或其他創意形式傳達故事的人。"},{"en":"The filmmaker is a storyteller who uses images instead of only written words.","zh":"電影製作者是用影像而不只是文字說故事的人。"},{"en":"Cosplayers can tell stories through costume details, poses and character behaviour.","zh":"角色扮演者可以透過服裝細節、姿勢和角色行為說故事。"},{"en":"Storytelling does not require a book; many creative forms can carry a narrative.","zh":"說故事不一定需要一本書，很多創作形式都能承載敘事。"}],"source":"2023 Q3.pdf","sourcePage":15},{"front":"brave enough to become visible","meaning":"有足夠勇氣讓自己被看見","examples":[{"en":"There may simply be a student brave enough to become visible.","zh":"面具背後可能只是一個有足夠勇氣讓自己被看見的學生。"},{"en":"“Brave enough to become visible” means having enough courage to let other people notice, judge and see the real or creative self.","zh":"「brave enough to become visible」表示有足夠勇氣讓別人注意、評價和看見真正或有創意的自己。"},{"en":"The shy student was brave enough to display her artwork publicly.","zh":"那個害羞學生有足夠勇氣公開展示自己的藝術作品。"},{"en":"For someone used to hiding, wearing a costume before thousands can be an act of courage.","zh":"對習慣隱藏自己的人來說，在數千人面前穿角色服裝可以是一種勇氣。"},{"en":"Becoming visible can be a meaningful step towards confidence because it means no longer keeping every part of yourself hidden.","zh":"讓自己被看見可以成為建立自信的重要一步，因為它代表不再把自己的每一部分都藏起來。"}],"source":"2023 Q3.pdf","sourcePage":15}],"dse/writing/part-b/2023/Q4":[{"front":"watching work","meaning":"監察工作","examples":[{"en":"The essay discusses the promise and price of watching work through employee monitoring.","zh":"這篇文章討論透過員工監察來監察工作的好處與代價。"},{"en":"Watching work means observing how employees use time, tools, and workplace systems.","zh":"watching work 意思是觀察員工如何使用時間、工具和職場系統。"},{"en":"Managers may think watching work helps them understand productivity.","zh":"經理可能認為監察工作有助了解生產力。"},{"en":"If watching work becomes too intense, employees may feel distrusted.","zh":"如果監察工作變得過度，員工可能感到不被信任。"},{"en":"This phrase introduces the central issue of monitoring in modern workplaces.","zh":"這個片語引出現代職場監察的核心問題。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"the promise and price of","meaning":"……的好處與代價","examples":[{"en":"The essay examines the promise and price of employee monitoring.","zh":"這篇文章探討員工監察的好處與代價。"},{"en":"The promise and price of something means both its possible benefits and its possible costs.","zh":"the promise and price of 某事，意思是某事可能帶來的好處和成本。"},{"en":"The promise and price of online learning include flexibility and loneliness.","zh":"網上學習的好處與代價包括彈性和孤獨感。"},{"en":"Employee monitoring promises efficiency, but its price may be weaker trust.","zh":"員工監察帶來效率的好處，但代價可能是信任削弱。"},{"en":"This phrase helps the writer present a balanced discussion.","zh":"這個片語幫助作者作出平衡討論。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"employee monitoring","meaning":"員工監察","examples":[{"en":"Employee monitoring can improve efficiency but damage trust.","zh":"員工監察可以提高效率，但也會損害信任。"},{"en":"Employee monitoring means using tools or systems to observe workers’ behaviour or performance.","zh":"employee monitoring 指使用工具或系統觀察員工行為或表現。"},{"en":"A company may use employee monitoring to check computer activity or attendance.","zh":"公司可能使用員工監察來檢查電腦活動或出勤情況。"},{"en":"Monitoring can be useful when it is transparent and limited.","zh":"當監察透明而有限度時，可以有用。"},{"en":"This phrase refers to a workplace practice that can help or harm depending on how it is used.","zh":"這個片語指一種職場做法，其影響視乎如何使用。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"in many workplaces","meaning":"在很多職場中","examples":[{"en":"In many workplaces, supervisors have been replaced by cameras and software.","zh":"在很多職場中，主管已被攝影機和軟件取代。"},{"en":"In many workplaces means in a large number of offices, shops, factories, or organisations.","zh":"in many workplaces 意思是在大量辦公室、商店、工廠或機構中。"},{"en":"In many workplaces, staff now use digital systems every day.","zh":"在很多職場中，員工現在每天使用數碼系統。"},{"en":"Monitoring has become common in many workplaces because work is increasingly online.","zh":"由於工作越來越網上化，監察在很多職場中變得常見。"},{"en":"This phrase gives the issue a broad and modern setting.","zh":"這個片語為議題提供廣泛而現代的背景。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"walking between desks","meaning":"在辦公桌之間巡視","examples":[{"en":"The old supervisor walking between desks has been replaced by quieter watchers.","zh":"舊式在辦公桌之間巡視的主管已被較隱形的監察者取代。"},{"en":"Walking between desks means moving around the office to observe workers directly.","zh":"walking between desks 意思是在辦公室內走動，直接觀察員工。"},{"en":"A supervisor walking between desks can see whether staff need help.","zh":"在辦公桌之間巡視的主管可以看見員工是否需要幫助。"},{"en":"Today, software may replace the old habit of walking between desks.","zh":"今天，軟件可能取代舊式在辦公桌之間巡視的習慣。"},{"en":"This phrase contrasts visible supervision with invisible digital monitoring.","zh":"這個片語把可見監督與隱形數碼監察作對比。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"be replaced by","meaning":"被……取代","examples":[{"en":"The old supervisor has been replaced by cameras and software.","zh":"舊式主管已被攝影機和軟件取代。"},{"en":"Be replaced by means be removed and have something else take its place.","zh":"be replaced by 意思是被移除，並由另一事物代替。"},{"en":"Paper attendance sheets may be replaced by digital check-in systems.","zh":"紙本出勤表可能被數碼簽到系統取代。"},{"en":"Human supervision can be replaced by software if managers want constant data.","zh":"如果經理想取得持續數據，人手監督可能被軟件取代。"},{"en":"This phrase shows a change from one system to another.","zh":"這個片語顯示由一種制度轉向另一種制度。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"quieter watchers","meaning":"較隱形的監察者","examples":[{"en":"Modern workplaces may use quieter watchers such as cameras and software.","zh":"現代職場可能使用攝影機和軟件等較隱形的監察者。"},{"en":"Quieter watchers are monitoring tools that observe people without obvious human presence.","zh":"quieter watchers 指沒有明顯人為存在卻能觀察人的監察工具。"},{"en":"A camera in the ceiling can be a quieter watcher than a manager standing nearby.","zh":"天花板上的攝影機可以比站在旁邊的經理更隱形。"},{"en":"Quieter watchers may feel less visible, but they can still affect behaviour.","zh":"較隱形的監察者可能看起來不明顯，但仍會影響行為。"},{"en":"This phrase suggests silent and indirect forms of supervision.","zh":"這個片語暗示安靜而間接的監督形式。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"cameras in the ceiling","meaning":"天花板上的閉路電視","examples":[{"en":"Cameras in the ceiling can monitor workers quietly.","zh":"天花板上的閉路電視可以安靜地監察員工。"},{"en":"Cameras in the ceiling are surveillance cameras fixed above the workplace.","zh":"cameras in the ceiling 指固定在職場上方的監察攝影機。"},{"en":"Cameras in the ceiling may record movement in a warehouse or office.","zh":"天花板上的閉路電視可能記錄倉庫或辦公室內的活動。"},{"en":"Such cameras can improve security but also make staff feel watched.","zh":"這類攝影機可以提升保安，但也可能令員工感到被監視。"},{"en":"This phrase gives a physical example of workplace monitoring.","zh":"這個片語提供職場監察的實體例子。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"software inside company computers","meaning":"公司電腦內的軟件","examples":[{"en":"Software inside company computers can track employee activity.","zh":"公司電腦內的軟件可以追蹤員工活動。"},{"en":"Software inside company computers means programs installed on workplace devices to record usage or performance.","zh":"software inside company computers 指安裝在工作設備上、用來記錄使用情況或表現的程式。"},{"en":"Such software may record log-in times, websites visited, or files opened.","zh":"這類軟件可能記錄登入時間、瀏覽網站或開啟檔案。"},{"en":"If employees are not informed, this software can damage trust.","zh":"如果員工沒有被告知，這些軟件可能損害信任。"},{"en":"This phrase shows how monitoring can happen digitally and quietly.","zh":"這個片語顯示監察可以數碼化而安靜地進行。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"deadlines tightening","meaning":"截止日期越來越緊迫","examples":[{"en":"With deadlines tightening, some employers consider monitoring staff.","zh":"隨着截止日期越來越緊迫，有些僱主考慮監察員工。"},{"en":"Deadlines tightening means time limits are becoming stricter or closer.","zh":"deadlines tightening 意思是限期變得更嚴格或更接近。"},{"en":"When deadlines are tightening, managers may worry about delays.","zh":"當截止日期越來越緊迫時，經理可能擔心延誤。"},{"en":"Tight deadlines can make employers look for stronger oversight.","zh":"緊迫的截止日期可能令僱主尋求更強監督。"},{"en":"This phrase explains one reason companies may turn to monitoring.","zh":"這個片語解釋公司轉向監察的其中一個原因。"}],"source":"2023 Q4.pdf","sourcePage":1},{"front":"hybrid work becoming common","meaning":"混合工作模式變得普遍","examples":[{"en":"With hybrid work becoming common, employers may want clearer oversight.","zh":"隨着混合工作模式變得普遍，僱主可能想要更清晰的監督。"},{"en":"Hybrid work becoming common means more employees split work between home and the office.","zh":"hybrid work becoming common 意思是更多員工在家和辦公室之間分配工作。"},{"en":"When hybrid work becomes common, managers may find it harder to see daily work directly.","zh":"當混合工作模式變得普遍，經理可能較難直接看見日常工作。"},{"en":"Monitoring may increase because employers want proof of work outside the office.","zh":"由於僱主想證明辦公室以外的工作，監察可能增加。"},{"en":"This phrase connects workplace change with new management concerns.","zh":"這個片語把職場變化與新的管理憂慮連接起來。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"consider monitoring staff","meaning":"考慮監察員工","examples":[{"en":"Some employers consider monitoring staff to prevent misconduct.","zh":"有些僱主考慮監察員工，以防止不當行為。"},{"en":"To consider monitoring staff means to think about observing employees through tools or systems.","zh":"consider monitoring staff 意思是考慮透過工具或系統觀察員工。"},{"en":"A company may consider monitoring staff after repeated delays or data problems.","zh":"公司在多次延誤或資料問題後，可能考慮監察員工。"},{"en":"Considering monitoring staff should involve questions about privacy and trust.","zh":"考慮監察員工時，應包括私隱和信任問題。"},{"en":"This phrase shows a management decision before action is taken.","zh":"這個片語顯示採取行動前的管理決定。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"prevent misconduct","meaning":"防止不當行為","examples":[{"en":"Monitoring may be used to prevent misconduct.","zh":"監察可能被用來防止不當行為。"},{"en":"To prevent misconduct means to stop improper, dishonest, or unsafe behaviour before it happens.","zh":"prevent misconduct 意思是在不當、不誠實或不安全行為發生前阻止它。"},{"en":"Cameras may help prevent misconduct in a warehouse.","zh":"攝影機可能有助防止倉庫中的不當行為。"},{"en":"Clear rules can prevent misconduct without watching employees every second.","zh":"清晰規則可以防止不當行為，而不必每秒監視員工。"},{"en":"This phrase presents one possible reason for monitoring.","zh":"這個片語提出監察的一個可能理由。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"measure performance","meaning":"衡量表現","examples":[{"en":"Employers may use monitoring to measure performance.","zh":"僱主可能使用監察來衡量表現。"},{"en":"To measure performance means to assess how well someone is doing their work.","zh":"measure performance 意思是評估某人工作做得如何。"},{"en":"Managers may measure performance by looking at accuracy, speed, and customer feedback.","zh":"經理可能透過準確度、速度和顧客回饋來衡量表現。"},{"en":"Monitoring can measure some performance, but not creativity or judgement fully.","zh":"監察可以衡量部分表現，但不能完全衡量創意或判斷力。"},{"en":"This phrase shows the link between data and evaluation.","zh":"這個片語顯示數據與評估之間的關係。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"ensure that","meaning":"確保","examples":[{"en":"Monitoring can ensure that paid working hours are used responsibly.","zh":"監察可以確保受薪工作時間被負責任地使用。"},{"en":"Ensure that means make certain that something happens.","zh":"ensure that 意思是確保某事發生。"},{"en":"Clear guidelines help ensure that employees understand expectations.","zh":"清晰指引有助確保員工明白期望。"},{"en":"Monitoring may ensure that office computers are used for work tasks.","zh":"監察可能確保公司電腦用於工作任務。"},{"en":"This phrase introduces the purpose of a rule or system.","zh":"這個片語引出規則或制度的目的。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"paid working hours","meaning":"受薪工作時間","examples":[{"en":"Employers want paid working hours to be used responsibly.","zh":"僱主希望受薪工作時間被負責任地使用。"},{"en":"Paid working hours are the hours for which employees receive salary or wages.","zh":"paid working hours 指員工獲得薪金或工資的工作時段。"},{"en":"During paid working hours, staff are expected to focus on work duties.","zh":"在受薪工作時間內，員工被期望專注於工作職責。"},{"en":"Employers monitor paid working hours because they are paying for that time.","zh":"僱主監察受薪工作時間，因為他們正在為那些時間付費。"},{"en":"This phrase explains why time use becomes a workplace concern.","zh":"這個片語解釋為何時間使用成為職場關注。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"used responsibly","meaning":"被負責任地使用","examples":[{"en":"Paid working hours should be used responsibly.","zh":"受薪工作時間應被負責任地使用。"},{"en":"Used responsibly means used in a sensible, honest, and appropriate way.","zh":"used responsibly 意思是以合理、誠實和適當方式使用。"},{"en":"Company computers should be used responsibly during office hours.","zh":"公司電腦應在辦公時間被負責任地使用。"},{"en":"If workers use time responsibly, employers may feel less need to monitor them.","zh":"如果員工負責任地使用時間，僱主可能較少需要監察他們。"},{"en":"This phrase connects freedom with duty.","zh":"這個片語把自由與責任連接起來。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"the aim is understandable","meaning":"這個目標可以理解","examples":[{"en":"The aim is understandable: higher productivity and fewer mistakes.","zh":"這個目標可以理解：更高生產力和較少錯誤。"},{"en":"The aim is understandable means the purpose is reasonable and easy to sympathise with.","zh":"the aim is understandable 意思是目的合理，容易令人理解。"},{"en":"The aim is understandable when managers want to protect customers and deadlines.","zh":"當經理想保護顧客和截止日期時，這個目標可以理解。"},{"en":"Understanding the aim does not mean accepting every method.","zh":"理解目標不代表接受所有方法。"},{"en":"This phrase allows the writer to be fair before criticism.","zh":"這個片語讓作者在批評前保持公平。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"higher productivity","meaning":"更高生產力","examples":[{"en":"Employers hope monitoring will lead to higher productivity.","zh":"僱主希望監察會帶來更高生產力。"},{"en":"Higher productivity means producing more or better work in the same amount of time.","zh":"higher productivity 意思是在同樣時間內完成更多或更好的工作。"},{"en":"Clear priorities can lead to higher productivity without constant surveillance.","zh":"清晰優先次序可以在沒有持續監控下帶來更高生產力。"},{"en":"Monitoring may raise productivity if it helps workers avoid distractions.","zh":"如果監察幫助員工避免分心，可能提高生產力。"},{"en":"This phrase names one expected benefit of employee monitoring.","zh":"這個片語指出員工監察的一個預期好處。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"fewer mistakes","meaning":"較少錯誤","examples":[{"en":"Monitoring may help create fewer mistakes.","zh":"監察可能有助造成較少錯誤。"},{"en":"Fewer mistakes means a smaller number of errors or problems.","zh":"fewer mistakes 意思是錯誤或問題數量較少。"},{"en":"A checklist can help workers make fewer mistakes when handling orders.","zh":"清單可以幫助員工在處理訂單時犯較少錯誤。"},{"en":"Monitoring may reduce mistakes if it identifies weak points early.","zh":"如果監察及早找出弱點，可能減少錯誤。"},{"en":"This phrase describes a practical goal of workplace supervision.","zh":"這個片語描述職場監督的一個實際目標。"}],"source":"2023 Q4.pdf","sourcePage":2},{"front":"the real question is not simply whether…, but whether…","meaning":"真正問題不只是……而是……","examples":[{"en":"The real question is not simply whether monitoring works, but whether it improves work without damaging workers.","zh":"真正問題不只是監察是否有效，而是它是否能改善工作而不傷害員工。"},{"en":"This structure shows that the deeper issue is more complex than a simple yes-or-no question.","zh":"這個句式顯示更深層問題比簡單的是或否更複雜。"},{"en":"The real question is not simply whether a rule is efficient, but whether it is fair.","zh":"真正問題不只是規則是否有效率，而是它是否公平。"},{"en":"It shifts attention from results alone to human consequences.","zh":"它把注意力由結果本身轉向人的後果。"},{"en":"This phrase is useful for building a balanced argument.","zh":"這個片語適合用來建立平衡論點。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"improve work without damaging workers","meaning":"改善工作而不傷害員工","examples":[{"en":"Monitoring should improve work without damaging workers.","zh":"監察應改善工作而不傷害員工。"},{"en":"To improve work without damaging workers means to make performance better while protecting employees’ wellbeing.","zh":"improve work without damaging workers 意思是在改善表現的同時保護員工身心健康。"},{"en":"A good system improves work without creating fear or humiliation.","zh":"好制度會改善工作，而不製造恐懼或羞辱。"},{"en":"Monitoring fails if it raises output but destroys trust.","zh":"如果監察提高產出卻摧毀信任，就是失敗。"},{"en":"This phrase captures the balance employers should seek.","zh":"這個片語概括僱主應追求的平衡。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"examine both sides","meaning":"探討正反兩面","examples":[{"en":"This essay will examine both sides of employee monitoring.","zh":"這篇文章將探討員工監察的正反兩面。"},{"en":"To examine both sides means to consider advantages and disadvantages fairly.","zh":"examine both sides 意思是公平考慮好處和壞處。"},{"en":"A balanced essay should examine both sides before reaching a conclusion.","zh":"平衡文章應在下結論前探討正反兩面。"},{"en":"Examining both sides helps readers trust the argument.","zh":"探討正反兩面幫助讀者信任論點。"},{"en":"This phrase signals that the discussion will not be one-sided.","zh":"這個片語表示討論不會是片面的。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"arguing that","meaning":"主張；論證","examples":[{"en":"The essay argues that monitoring can raise efficiency when it is limited.","zh":"這篇文章主張，當監察有限度時，它可以提高效率。"},{"en":"Arguing that means presenting reasons to support a particular view.","zh":"arguing that 意思是提出理由支持某一觀點。"},{"en":"The writer is arguing that rules are better than total surveillance.","zh":"作者主張規則比全面監控更好。"},{"en":"An essay may argue that monitoring should be transparent and fair.","zh":"文章可能論證監察應透明而公平。"},{"en":"This phrase introduces the main position of a piece of writing.","zh":"這個片語引出文章的主要立場。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"raise efficiency and safety","meaning":"提高效率和安全","examples":[{"en":"Monitoring can raise efficiency and safety when it is limited and transparent.","zh":"當監察有限度而透明時，它可以提高效率和安全。"},{"en":"To raise efficiency and safety means to make work faster, smoother, and less risky.","zh":"raise efficiency and safety 意思是令工作更快、更順暢並減少風險。"},{"en":"Cameras can raise safety in a warehouse by discouraging unsafe behaviour.","zh":"攝影機可透過阻嚇不安全行為來提高倉庫安全。"},{"en":"Monitoring may raise efficiency if it helps managers find repeated delays.","zh":"如果監察幫助經理找出重複延誤，可能提高效率。"},{"en":"This phrase explains the positive case for careful monitoring.","zh":"這個片語解釋謹慎監察的正面理據。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"limited and transparent","meaning":"有限度而透明","examples":[{"en":"Monitoring should be limited and transparent.","zh":"監察應有限度而透明。"},{"en":"Limited and transparent means restricted in scope and clearly explained to employees.","zh":"limited and transparent 意思是範圍受限制，並向員工清楚解釋。"},{"en":"Monitoring is more acceptable when it is limited to work systems and openly disclosed.","zh":"當監察限於工作系統並公開披露時，較容易被接受。"},{"en":"If workers know what is monitored and why, trust may suffer less.","zh":"如果員工知道監察甚麼和原因，信任可能較少受損。"},{"en":"This phrase describes the conditions for fair monitoring.","zh":"這個片語描述公平監察的條件。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"reduce job satisfaction","meaning":"降低工作滿意度","examples":[{"en":"Monitoring may reduce job satisfaction when it becomes excessive.","zh":"當監察變得過度時，可能降低工作滿意度。"},{"en":"To reduce job satisfaction means to make employees feel less happy or fulfilled at work.","zh":"reduce job satisfaction 意思是令員工在工作中較不快樂或較少滿足感。"},{"en":"Constant surveillance may reduce job satisfaction by creating stress.","zh":"持續監控可能透過製造壓力來降低工作滿意度。"},{"en":"If workers feel distrusted, their job satisfaction may fall.","zh":"如果員工感到不被信任，工作滿意度可能下降。"},{"en":"This phrase identifies one emotional cost of monitoring.","zh":"這個片語指出監察的一項情感代價。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"become excessive","meaning":"變得過度","examples":[{"en":"Monitoring becomes harmful when it becomes excessive.","zh":"當監察變得過度時，它會變得有害。"},{"en":"Become excessive means become too much or go beyond a reasonable limit.","zh":"become excessive 意思是變得太多或超出合理限度。"},{"en":"Helpful supervision can become excessive if every click is tracked.","zh":"如果每一下點擊都被追蹤，有用的監督可能變得過度。"},{"en":"When monitoring becomes excessive, workers may protect themselves instead of contributing freely.","zh":"當監察變得過度，員工可能保護自己，而不是自由地作出貢獻。"},{"en":"This phrase marks the point where a useful tool turns harmful.","zh":"這個片語指出有用工具變成有害的界線。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"on the positive side","meaning":"從正面來看","examples":[{"en":"On the positive side, monitoring can help employees stay focused.","zh":"從正面來看，監察可以幫助員工保持專注。"},{"en":"On the positive side means looking at the advantages of the issue.","zh":"on the positive side 意思是從議題的好處方面看。"},{"en":"On the positive side, clear records can protect honest workers.","zh":"從正面來看，清晰記錄可以保護誠實員工。"},{"en":"This phrase introduces the benefits before discussing disadvantages.","zh":"這個片語在討論缺點前引出好處。"},{"en":"It helps organise a balanced essay.","zh":"它幫助組織平衡文章。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"stay focused","meaning":"保持專注","examples":[{"en":"Monitoring can help employees stay focused.","zh":"監察可以幫助員工保持專注。"},{"en":"To stay focused means to keep attention on the task instead of being distracted.","zh":"stay focused 意思是把注意力放在任務上，而不是分心。"},{"en":"A quiet workplace helps employees stay focused on detailed work.","zh":"安靜的職場幫助員工保持專注於細緻工作。"},{"en":"Monitoring may help some staff stay focused during paid working hours.","zh":"監察可能幫助部分員工在受薪工作時間保持專注。"},{"en":"This phrase describes one possible productivity benefit.","zh":"這個片語描述一項可能的生產力好處。"}],"source":"2023 Q4.pdf","sourcePage":3},{"front":"identify problems early","meaning":"及早找出問題","examples":[{"en":"Monitoring can help managers identify problems early.","zh":"監察可以幫助經理及早找出問題。"},{"en":"To identify problems early means to notice difficulties before they become serious.","zh":"identify problems early 意思是在困難變嚴重前留意到它們。"},{"en":"Call records can help managers identify weak customer service habits early.","zh":"通話記錄可以幫助經理及早找出薄弱的客戶服務習慣。"},{"en":"If problems are identified early, training can be offered sooner.","zh":"如果問題及早被找出，便可以更早提供培訓。"},{"en":"This phrase shows how monitoring can be used for improvement rather than punishment.","zh":"這個片語顯示監察可用於改善，而不只是懲罰。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"in any organisation","meaning":"在任何機構中","examples":[{"en":"In any organisation, some tasks depend on concentration and punctuality.","zh":"在任何機構中，有些任務取決於專注力和守時。"},{"en":"In any organisation means in every type of company, school, office, or institution.","zh":"in any organisation 意思是在每一類公司、學校、辦公室或機構中。"},{"en":"In any organisation, clear expectations help people work together.","zh":"在任何機構中，清晰期望有助人們合作。"},{"en":"Monitoring may seem useful in any organisation where timing and accuracy matter.","zh":"在任何重視時間和準確度的機構中，監察都可能看似有用。"},{"en":"This phrase makes the point general and widely applicable.","zh":"這個片語令重點更普遍和廣泛適用。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"depend on","meaning":"取決於；依賴","examples":[{"en":"Some tasks depend on concentration, punctuality, and consistent standards.","zh":"有些任務取決於專注力、守時和一致的標準。"},{"en":"Depend on means require something in order to succeed or work properly.","zh":"depend on 意思是需要某事才能成功或正常運作。"},{"en":"Customer service depends on polite answers and quick follow-up.","zh":"客戶服務取決於有禮回答和快速跟進。"},{"en":"Safe warehouse work depends on careful behaviour.","zh":"安全的倉庫工作依賴謹慎行為。"},{"en":"This phrase shows what good performance needs.","zh":"這個片語顯示良好表現需要甚麼。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"concentration","meaning":"專注力","examples":[{"en":"Some tasks depend on concentration.","zh":"有些任務取決於專注力。"},{"en":"Concentration means the ability to give full attention to one thing.","zh":"concentration 指把全部注意力集中在一件事上的能力。"},{"en":"Data entry requires concentration because small errors can create problems.","zh":"資料輸入需要專注力，因為小錯誤也會造成問題。"},{"en":"Too many distractions can weaken concentration at work.","zh":"太多干擾會削弱工作中的專注力。"},{"en":"This phrase explains why some employers value focused work.","zh":"這個片語解釋為何有些僱主重視專注工作。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"punctuality","meaning":"守時","examples":[{"en":"Some tasks depend on punctuality.","zh":"有些任務取決於守時。"},{"en":"Punctuality means being on time and meeting agreed schedules.","zh":"punctuality 指準時和遵守既定時間安排。"},{"en":"A customer-service centre needs punctuality so calls are answered on time.","zh":"客戶服務中心需要守時，讓電話能準時被接聽。"},{"en":"Poor punctuality can delay projects and frustrate colleagues.","zh":"守時不足會延誤項目並令同事挫敗。"},{"en":"This phrase refers to a basic workplace standard.","zh":"這個片語指基本職場標準。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"consistent standards","meaning":"一致的標準","examples":[{"en":"Good work often requires consistent standards.","zh":"良好工作往往需要一致的標準。"},{"en":"Consistent standards are stable levels of quality that do not change randomly.","zh":"consistent standards 指不會隨意改變的穩定質素水平。"},{"en":"A company needs consistent standards when handling customer complaints.","zh":"公司處理顧客投訴時需要一致的標準。"},{"en":"Monitoring may help check whether standards are being followed.","zh":"監察可能幫助檢查標準是否被遵守。"},{"en":"This phrase shows why fairness and quality control matter.","zh":"這個片語顯示公平和質素控制為何重要。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"serious delays","meaning":"嚴重延誤","examples":[{"en":"Workers know that serious delays may be recorded.","zh":"員工知道嚴重延誤可能被記錄。"},{"en":"Serious delays are long or important delays that affect work results.","zh":"serious delays 指長時間或重要的延誤，會影響工作結果。"},{"en":"A serious delay in replying to customers may lead to complaints.","zh":"回覆顧客出現嚴重延誤可能導致投訴。"},{"en":"Recording serious delays can help managers identify training needs.","zh":"記錄嚴重延誤可以幫助經理找出培訓需要。"},{"en":"This phrase shows one type of problem monitoring may detect.","zh":"這個片語顯示監察可能發現的一類問題。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"improper use of office computers","meaning":"不當使用公司電腦","examples":[{"en":"Improper use of office computers may be recorded.","zh":"不當使用公司電腦可能被記錄。"},{"en":"Improper use of office computers means using company devices in unsuitable or unauthorised ways.","zh":"improper use of office computers 意思是以不合適或未獲授權的方式使用公司設備。"},{"en":"Watching unrelated videos during work hours may be improper use of office computers.","zh":"工作時間觀看無關影片可能是不當使用公司電腦。"},{"en":"Monitoring may discourage improper use if rules are clear.","zh":"如果規則清晰，監察可能阻止不當使用。"},{"en":"This phrase focuses on responsible use of workplace technology.","zh":"這個片語著重負責任地使用職場科技。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"may be recorded","meaning":"可能被記錄","examples":[{"en":"Serious delays or improper computer use may be recorded.","zh":"嚴重延誤或不當使用電腦可能被記錄。"},{"en":"May be recorded means may be saved as data, video, audio, or written evidence.","zh":"may be recorded 意思是可能以數據、錄像、錄音或文字證據形式保存。"},{"en":"Calls may be recorded for training and quality control.","zh":"通話可能被記錄作培訓和質素控制用途。"},{"en":"If workers know actions may be recorded, they may behave more carefully.","zh":"如果員工知道行動可能被記錄，可能會更謹慎。"},{"en":"This phrase shows the possibility of creating evidence.","zh":"這個片語顯示產生證據的可能性。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"be less likely to","meaning":"較不可能","examples":[{"en":"Workers are less likely to waste time if serious misuse may be recorded.","zh":"如果嚴重濫用可能被記錄，員工較不可能浪費時間。"},{"en":"Be less likely to means have a lower chance of doing something.","zh":"be less likely to 意思是做某事的可能性較低。"},{"en":"Employees are less likely to misuse computers when rules are clear.","zh":"當規則清晰時，員工較不可能濫用電腦。"},{"en":"People may be less likely to ignore safety steps if cameras are present.","zh":"如果有攝影機，人們較不可能忽視安全步驟。"},{"en":"This phrase describes how monitoring may change behaviour.","zh":"這個片語描述監察如何可能改變行為。"}],"source":"2023 Q4.pdf","sourcePage":4},{"front":"spend long periods on","meaning":"花很長時間在……上","examples":[{"en":"Employees may spend long periods on online shopping or private messaging.","zh":"員工可能花很長時間在網上購物或私人訊息上。"},{"en":"To spend long periods on something means to use a lot of time doing it.","zh":"spend long periods on 某事，意思是用大量時間做某事。"},{"en":"A worker may spend long periods on social media if no boundaries are set.","zh":"如果沒有界線，員工可能花很長時間在社交媒體上。"},{"en":"Monitoring may reduce the time spent on non-work activities.","zh":"監察可能減少花在非工作活動上的時間。"},{"en":"This phrase highlights a concern about time use.","zh":"這個片語突顯對時間使用的關注。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"online shopping","meaning":"網上購物","examples":[{"en":"Monitoring may discourage workers from online shopping during work hours.","zh":"監察可能阻止員工在工作時間網上購物。"},{"en":"Online shopping means buying goods or services through the internet.","zh":"online shopping 意思是透過互聯網購買商品或服務。"},{"en":"Online shopping during work hours can distract employees from urgent tasks.","zh":"在工作時間網上購物會令員工從緊急任務中分心。"},{"en":"Clear rules may reduce online shopping on company computers.","zh":"清晰規則可能減少在公司電腦上網上購物。"},{"en":"This phrase gives a common example of non-work computer use.","zh":"這個片語提供非工作電腦使用的常見例子。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"private messaging","meaning":"私人訊息","examples":[{"en":"Monitoring may reduce private messaging during work hours.","zh":"監察可能減少工作時間內的私人訊息。"},{"en":"Private messaging means sending personal messages that are not related to work.","zh":"private messaging 指發送與工作無關的個人訊息。"},{"en":"Some private messaging is harmless, but long conversations can affect productivity.","zh":"有些私人訊息無傷大雅，但長時間對話可能影響生產力。"},{"en":"Workers may reduce private messaging if company rules are clear.","zh":"如果公司規則清楚，員工可能減少私人訊息。"},{"en":"This phrase shows the boundary between personal life and paid work time.","zh":"這個片語顯示個人生活與受薪工作時間的界線。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"unrelated videos","meaning":"無關影片","examples":[{"en":"Workers may avoid unrelated videos if monitoring is clear.","zh":"如果監察清晰，員工可能避免觀看無關影片。"},{"en":"Unrelated videos are videos that have nothing to do with work tasks.","zh":"unrelated videos 指與工作任務沒有關係的影片。"},{"en":"Watching unrelated videos for a long time may delay important work.","zh":"長時間觀看無關影片可能延誤重要工作。"},{"en":"Monitoring may discourage unrelated videos on company computers.","zh":"監察可能阻止員工在公司電腦上觀看無關影片。"},{"en":"This phrase gives another example of workplace distraction.","zh":"這個片語提供另一個職場分心例子。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"clear oversight","meaning":"清晰監督","examples":[{"en":"Clear oversight can remove temptation.","zh":"清晰監督可以消除誘惑。"},{"en":"Clear oversight means open and understandable supervision.","zh":"clear oversight 指公開且容易理解的監督。"},{"en":"Clear oversight helps employees know what is expected and checked.","zh":"清晰監督幫助員工知道期望和檢查內容。"},{"en":"If oversight is clear, workers may feel less unfairly targeted.","zh":"如果監督清晰，員工可能較少覺得被不公平針對。"},{"en":"This phrase suggests supervision that is structured rather than hidden.","zh":"這個片語表示有結構而不是隱藏的監督。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"remove temptation","meaning":"消除誘惑","examples":[{"en":"Clear oversight can remove temptation at work.","zh":"清晰監督可以消除工作中的誘惑。"},{"en":"To remove temptation means to reduce the urge to do something wrong or distracting.","zh":"remove temptation 意思是減少做錯事或分心事情的衝動。"},{"en":"Blocking non-work websites may remove temptation for some employees.","zh":"封鎖非工作網站可能為一些員工消除誘惑。"},{"en":"Clear monitoring can remove temptation to misuse paid working hours.","zh":"清晰監察可以消除濫用受薪工作時間的誘惑。"},{"en":"This phrase describes how rules can prevent problems before they happen.","zh":"這個片語描述規則如何在問題發生前預防問題。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"create a fairer environment","meaning":"建立更公平的環境","examples":[{"en":"Monitoring can create a fairer environment for responsible colleagues.","zh":"監察可以為負責任的同事建立更公平的環境。"},{"en":"To create a fairer environment means to make conditions more just for everyone.","zh":"create a fairer environment 意思是令環境對所有人更公正。"},{"en":"Monitoring can create a fairer environment if it stops some workers from hiding poor performance.","zh":"如果監察阻止部分員工隱藏差劣表現，便可以建立更公平的環境。"},{"en":"Responsible employees may feel protected when unfair behaviour is recorded.","zh":"當不公平行為被記錄，負責任員工可能感到受保護。"},{"en":"This phrase presents fairness as one possible benefit of monitoring.","zh":"這個片語把公平呈現為監察的一項可能好處。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"responsible colleagues","meaning":"負責任的同事","examples":[{"en":"Clear oversight can protect responsible colleagues.","zh":"清晰監督可以保護負責任的同事。"},{"en":"Responsible colleagues are workers who do their duties honestly and carefully.","zh":"responsible colleagues 指誠實而謹慎履行職責的員工。"},{"en":"Responsible colleagues may feel frustrated if others waste time without consequence.","zh":"如果其他人浪費時間卻沒有後果，負責任的同事可能感到不滿。"},{"en":"Fair monitoring can protect responsible colleagues from carrying extra work.","zh":"公平監察可以保護負責任同事，避免他們承擔額外工作。"},{"en":"This phrase reminds readers that monitoring may protect good workers too.","zh":"這個片語提醒讀者，監察也可能保護好員工。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"customer-service centre","meaning":"客戶服務中心","examples":[{"en":"Call-recording software may be useful in a customer-service centre.","zh":"通話錄音軟件在客戶服務中心可能有用。"},{"en":"A customer-service centre is a workplace where staff answer customer questions and complaints.","zh":"customer-service centre 是職員回答顧客問題和投訴的工作場所。"},{"en":"A customer-service centre often handles phone calls, emails, and live chats.","zh":"客戶服務中心通常處理電話、電郵和即時聊天。"},{"en":"Monitoring may help such a centre improve training and service quality.","zh":"監察可能幫助這類中心改善培訓和服務質素。"},{"en":"This phrase gives a concrete workplace example.","zh":"這個片語提供具體職場例子。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"call-recording software","meaning":"通話錄音軟件","examples":[{"en":"Call-recording software may show whether staff answer enquiries politely.","zh":"通話錄音軟件可能顯示職員是否有禮貌地回答查詢。"},{"en":"Call-recording software is a system that records phone conversations for review.","zh":"call-recording software 是記錄電話對話以供檢視的系統。"},{"en":"Managers may use call-recording software to check service tone and accuracy.","zh":"經理可能使用通話錄音軟件檢查服務語氣和準確度。"},{"en":"Such software can support training if used fairly.","zh":"如果公平使用，這類軟件可以支援培訓。"},{"en":"This phrase names a common tool in customer-service monitoring.","zh":"這個片語指出客戶服務監察中的常見工具。"}],"source":"2023 Q4.pdf","sourcePage":5},{"front":"answer enquiries politely","meaning":"有禮貌地回答查詢","examples":[{"en":"Staff should answer enquiries politely.","zh":"職員應有禮貌地回答查詢。"},{"en":"To answer enquiries politely means to respond to questions with respect and patience.","zh":"answer enquiries politely 意思是以尊重和耐性回應問題。"},{"en":"A customer-service worker should answer enquiries politely even when customers are upset.","zh":"即使顧客不滿，客戶服務員工也應有禮貌地回答查詢。"},{"en":"Call records can show whether staff answer enquiries politely.","zh":"通話記錄可以顯示職員是否有禮貌地回答查詢。"},{"en":"This phrase describes an important standard in customer service.","zh":"這個片語描述客戶服務中的重要標準。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"leave customers waiting","meaning":"讓顧客久等","examples":[{"en":"Call records may show whether staff leave customers waiting.","zh":"通話記錄可能顯示職員是否讓顧客久等。"},{"en":"To leave customers waiting means to make customers wait without timely help.","zh":"leave customers waiting 意思是讓顧客在沒有及時幫助下等待。"},{"en":"A hotline that leaves customers waiting too long may receive complaints.","zh":"讓顧客久等太久的熱線可能收到投訴。"},{"en":"Monitoring can reveal whether delays are occasional or repeated.","zh":"監察可以揭示延誤是偶然還是重複發生。"},{"en":"This phrase describes a service problem that affects customer trust.","zh":"這個片語描述影響顧客信任的服務問題。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"offer training","meaning":"提供培訓","examples":[{"en":"Managers can offer training before small weaknesses become complaints.","zh":"經理可以在小弱點變成投訴前提供培訓。"},{"en":"To offer training means to provide teaching or practice to improve skills.","zh":"offer training 意思是提供教學或練習以改善技能。"},{"en":"A manager may offer training after noticing weak customer responses.","zh":"經理在留意到薄弱顧客回應後，可能提供培訓。"},{"en":"Monitoring is more helpful when it leads to training instead of blame only.","zh":"當監察帶來培訓而不只是責備時，會更有幫助。"},{"en":"This phrase shows a constructive use of workplace data.","zh":"這個片語顯示職場數據的建設性用途。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"small weaknesses","meaning":"小弱點","examples":[{"en":"Small weaknesses can become costly complaints.","zh":"小弱點可以變成代價高昂的投訴。"},{"en":"Small weaknesses are minor problems or skill gaps that may grow if ignored.","zh":"small weaknesses 指細小問題或技能不足，如被忽視可能擴大。"},{"en":"A small weakness in tone may upset customers over time.","zh":"語氣上的小弱點久而久之可能令顧客不滿。"},{"en":"Monitoring can identify small weaknesses before they become serious.","zh":"監察可以在小弱點變嚴重前找出它們。"},{"en":"This phrase shows why early support matters.","zh":"這個片語顯示早期支援為何重要。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"costly complaints","meaning":"代價高昂的投訴","examples":[{"en":"Managers should act before weaknesses become costly complaints.","zh":"經理應在弱點變成代價高昂的投訴前採取行動。"},{"en":"Costly complaints are complaints that create financial, reputational, or time costs.","zh":"costly complaints 指帶來金錢、聲譽或時間成本的投訴。"},{"en":"A mishandled customer call can turn into a costly complaint.","zh":"處理不當的顧客電話可以變成代價高昂的投訴。"},{"en":"Training can prevent small mistakes from becoming costly complaints.","zh":"培訓可以防止小錯誤變成代價高昂的投訴。"},{"en":"This phrase explains why companies want to detect problems early.","zh":"這個片語解釋公司為何想及早發現問題。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"used wisely","meaning":"運用得宜","examples":[{"en":"Used wisely, monitoring is also a diagnostic tool.","zh":"運用得宜時，監察也是一種診斷工具。"},{"en":"Used wisely means applied carefully, fairly, and for a proper purpose.","zh":"used wisely 意思是謹慎、公平並為正當目的使用。"},{"en":"Used wisely, workplace data can help employees improve.","zh":"運用得宜時，職場數據可以幫助員工改善。"},{"en":"Monitoring used wisely focuses on patterns, not small human pauses.","zh":"運用得宜的監察會著重模式，而不是人的短暫停頓。"},{"en":"This phrase separates responsible monitoring from excessive surveillance.","zh":"這個片語把負責任監察與過度監控分開。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"not only a whip","meaning":"不只是鞭子","examples":[{"en":"Used wisely, monitoring is not only a whip.","zh":"運用得宜時，監察不只是鞭子。"},{"en":"Not only a whip means not merely a tool for punishment or pressure.","zh":"not only a whip 意思是不只是懲罰或施壓的工具。"},{"en":"Monitoring can be not only a whip but also a way to find training needs.","zh":"監察不只可以是鞭子，也可以是找出培訓需要的方法。"},{"en":"If data is used only to punish, workers may fear it.","zh":"如果數據只用於懲罰，員工可能會害怕它。"},{"en":"This phrase argues for a more constructive use of monitoring.","zh":"這個片語主張以更建設性的方式使用監察。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"diagnostic tool","meaning":"診斷工具","examples":[{"en":"Monitoring can be a diagnostic tool for managers.","zh":"監察可以成為經理的診斷工具。"},{"en":"A diagnostic tool helps identify problems, causes, and possible improvements.","zh":"diagnostic tool 幫助找出問題、原因和可能改善方法。"},{"en":"Call records can be a diagnostic tool for improving customer service.","zh":"通話記錄可以成為改善客戶服務的診斷工具。"},{"en":"Monitoring becomes useful when it shows what support employees need.","zh":"當監察顯示員工需要甚麼支援時，它便變得有用。"},{"en":"This phrase presents monitoring as a way to understand, not only control.","zh":"這個片語把監察呈現為理解的方法，而不只是控制。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"another advantage","meaning":"另一個好處","examples":[{"en":"Another advantage is that monitoring may protect employers and employees.","zh":"另一個好處是監察可能保障僱主和僱員。"},{"en":"Another advantage means one more benefit in addition to the previous point.","zh":"another advantage 意思是在前一點以外的另一項好處。"},{"en":"Another advantage of clear records is that disputes can be checked fairly.","zh":"清晰記錄的另一個好處是爭議可以被公平查核。"},{"en":"This phrase helps the writer add a second positive argument.","zh":"這個片語幫助作者加入第二個正面論點。"},{"en":"It signals that the discussion is moving to a new benefit.","zh":"它表示討論正轉向新的好處。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"protect both employers and employees","meaning":"同時保障僱主和僱員","examples":[{"en":"Monitoring may protect both employers and employees.","zh":"監察可能同時保障僱主和僱員。"},{"en":"To protect both employers and employees means to safeguard the interests and safety of both sides.","zh":"protect both employers and employees 意思是保障雙方的利益和安全。"},{"en":"Records can protect employers from false claims and employees from unfair blame.","zh":"記錄可以保護僱主免受虛假指控，也保護員工免受不公平責備。"},{"en":"Monitoring protects both sides only when it is fair and accurate.","zh":"只有在公平準確時，監察才會同時保障雙方。"},{"en":"This phrase shows that monitoring need not benefit only management.","zh":"這個片語顯示監察不一定只對管理層有利。"}],"source":"2023 Q4.pdf","sourcePage":6},{"front":"sensitive workplaces","meaning":"敏感工作場所","examples":[{"en":"Monitoring may be necessary in sensitive workplaces.","zh":"在敏感工作場所，監察可能有必要。"},{"en":"Sensitive workplaces are places where safety, money, private data, or vulnerable people are involved.","zh":"sensitive workplaces 指涉及安全、金錢、私人資料或弱勢人士的地方。"},{"en":"Banks, hospitals, and warehouses can be sensitive workplaces.","zh":"銀行、醫院和倉庫都可以是敏感工作場所。"},{"en":"In sensitive workplaces, reliable records may protect people from serious harm.","zh":"在敏感工作場所，可靠記錄可能保護人們免受嚴重傷害。"},{"en":"This phrase explains where monitoring may be more justified.","zh":"這個片語解釋哪些地方較能支持監察。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"discourage theft","meaning":"阻嚇盜竊","examples":[{"en":"Cameras can discourage theft.","zh":"攝影機可以阻嚇盜竊。"},{"en":"To discourage theft means to make stealing less likely.","zh":"discourage theft 意思是令偷竊較不可能發生。"},{"en":"Cameras in a stockroom may discourage theft by making evidence possible.","zh":"倉庫中的攝影機可能透過留下證據來阻嚇盜竊。"},{"en":"Discouraging theft protects the company and honest workers.","zh":"阻嚇盜竊保護公司和誠實員工。"},{"en":"This phrase gives a security reason for monitoring.","zh":"這個片語提供監察的保安理由。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"bullying","meaning":"欺凌","examples":[{"en":"Cameras can discourage bullying and harassment.","zh":"攝影機可以阻嚇欺凌和騷擾。"},{"en":"Bullying means repeated cruel or unfair treatment of someone with less power.","zh":"bullying 指反覆殘酷或不公平地對待較弱勢的人。"},{"en":"Workplace bullying may include insults, exclusion, or intimidation.","zh":"職場欺凌可能包括侮辱、排斥或恐嚇。"},{"en":"Monitoring may help reveal bullying if victims are afraid to report it.","zh":"如果受害者害怕舉報，監察可能幫助揭示欺凌。"},{"en":"This phrase identifies one harmful workplace behaviour.","zh":"這個片語指出一種有害職場行為。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"harassment","meaning":"騷擾","examples":[{"en":"Monitoring can discourage harassment in the workplace.","zh":"監察可以阻嚇職場騷擾。"},{"en":"Harassment means unwanted behaviour that offends, threatens, or humiliates someone.","zh":"harassment 指令人反感、受威脅或受羞辱的不受歡迎行為。"},{"en":"A clear complaint record can help investigate workplace harassment.","zh":"清晰投訴記錄可以幫助調查職場騷擾。"},{"en":"Monitoring should protect employees from harassment without invading privacy unnecessarily.","zh":"監察應保護員工免受騷擾，而不作不必要侵犯私隱。"},{"en":"This phrase names a serious issue that employers must prevent.","zh":"這個片語指出僱主必須防止的嚴重問題。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"unsafe behaviour","meaning":"不安全行為","examples":[{"en":"Cameras can discourage unsafe behaviour.","zh":"攝影機可以阻嚇不安全行為。"},{"en":"Unsafe behaviour means actions that may cause injury, damage, or danger.","zh":"unsafe behaviour 指可能造成受傷、損壞或危險的行動。"},{"en":"Running near heavy machinery is unsafe behaviour.","zh":"在重型機器附近奔跑是不安全行為。"},{"en":"Monitoring can discourage unsafe behaviour by reminding workers of safety rules.","zh":"監察可以透過提醒員工安全規則來阻嚇不安全行為。"},{"en":"This phrase shows the safety side of employee monitoring.","zh":"這個片語顯示員工監察中的安全面向。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"digital records","meaning":"數碼記錄","examples":[{"en":"Digital records can clarify what happened.","zh":"數碼記錄可以釐清發生了甚麼。"},{"en":"Digital records are electronic records such as logs, files, recordings, or system data.","zh":"digital records 指電子記錄，例如日誌、檔案、錄音或系統數據。"},{"en":"Digital records can show who accessed a file and when.","zh":"數碼記錄可以顯示誰在何時開啟了檔案。"},{"en":"In disputes, digital records may be more reliable than memory alone.","zh":"在爭議中，數碼記錄可能比單靠記憶更可靠。"},{"en":"This phrase explains how technology can provide evidence.","zh":"這個片語解釋科技如何提供證據。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"clarify what happened","meaning":"釐清發生了甚麼","examples":[{"en":"Digital records can clarify what happened when disputes arise.","zh":"當爭議出現時，數碼記錄可以釐清發生了甚麼。"},{"en":"To clarify what happened means to make the facts of an event clear.","zh":"clarify what happened 意思是令事件的事實變清楚。"},{"en":"Camera footage can clarify what happened during a workplace accident.","zh":"錄影片段可以釐清職場意外中發生了甚麼。"},{"en":"Clear records prevent people from relying only on rumours.","zh":"清晰記錄防止人們只依賴謠言。"},{"en":"This phrase shows the evidence-based value of monitoring.","zh":"這個片語顯示監察以證據為本的價值。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"when disputes arise","meaning":"當爭議出現時","examples":[{"en":"Records can clarify events when disputes arise.","zh":"當爭議出現時，記錄可以釐清事件。"},{"en":"When disputes arise means when disagreements or conflicts appear.","zh":"when disputes arise 意思是當分歧或衝突出現時。"},{"en":"When disputes arise between staff and managers, records may help both sides.","zh":"當員工和經理之間出現爭議時，記錄可能幫助雙方。"},{"en":"A clear system can reduce confusion when disputes arise.","zh":"當爭議出現時，清晰制度可以減少混亂。"},{"en":"This phrase refers to moments when evidence becomes important.","zh":"這個片語指證據變得重要的時刻。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"operate machinery","meaning":"操作機器","examples":[{"en":"Warehouse staff may operate machinery.","zh":"倉庫員工可能操作機器。"},{"en":"To operate machinery means to control or use machines for work.","zh":"operate machinery 意思是控制或使用機器工作。"},{"en":"Workers who operate machinery need training and attention.","zh":"操作機器的員工需要培訓和注意力。"},{"en":"Monitoring may improve safety where people operate machinery.","zh":"在有人操作機器的地方，監察可能改善安全。"},{"en":"This phrase shows why some workplaces have higher safety risks.","zh":"這個片語顯示為何某些職場有較高安全風險。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"handle confidential customer information","meaning":"處理機密客戶資料","examples":[{"en":"Bank employees handle confidential customer information.","zh":"銀行員工處理機密客戶資料。"},{"en":"To handle confidential customer information means to work with private client data carefully.","zh":"handle confidential customer information 意思是謹慎處理私人客戶資料。"},{"en":"Staff who handle confidential information must follow strict privacy rules.","zh":"處理機密資料的員工必須遵守嚴格私隱規則。"},{"en":"Monitoring may help detect improper access to customer data.","zh":"監察可能幫助偵測不當查閱客戶資料。"},{"en":"This phrase explains why data-heavy workplaces may need safeguards.","zh":"這個片語解釋為何資料密集的職場可能需要保障措施。"}],"source":"2023 Q4.pdf","sourcePage":7},{"front":"confidential customer information","meaning":"機密客戶資料","examples":[{"en":"Banks must protect confidential customer information.","zh":"銀行必須保護機密客戶資料。"},{"en":"Confidential customer information is private data about customers, such as accounts, addresses, or identity details.","zh":"confidential customer information 指關於顧客的私人資料，例如帳戶、地址或身份資料。"},{"en":"A data leak involving confidential customer information can seriously damage trust.","zh":"涉及機密客戶資料的資料外洩會嚴重損害信任。"},{"en":"Employees must access such information only for proper work reasons.","zh":"員工只應基於正當工作理由查閱這些資料。"},{"en":"This phrase refers to sensitive data that needs strong protection.","zh":"這個片語指需要強力保護的敏感資料。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"data leak","meaning":"資料外洩","examples":[{"en":"A data leak can seriously damage trust.","zh":"資料外洩可以嚴重損害信任。"},{"en":"A data leak is an incident where private or confidential information is exposed.","zh":"data leak 是私人或機密資料被洩露的事件。"},{"en":"A company may lose customers after a serious data leak.","zh":"公司在嚴重資料外洩後可能失去顧客。"},{"en":"Monitoring can help detect unusual access before a data leak occurs.","zh":"監察可以在資料外洩發生前幫助偵測異常存取。"},{"en":"This phrase shows one serious risk in digital workplaces.","zh":"這個片語顯示數碼職場中的一項嚴重風險。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"reliable records","meaning":"可靠記錄","examples":[{"en":"Reliable records can prevent rumours from replacing evidence.","zh":"可靠記錄可以防止謠言取代證據。"},{"en":"Reliable records are accurate and trustworthy pieces of information.","zh":"reliable records 指準確而可信的資料。"},{"en":"System logs can be reliable records if they are complete and secure.","zh":"如果系統記錄完整且安全，它們可以是可靠記錄。"},{"en":"Reliable records help both managers and employees understand what happened.","zh":"可靠記錄幫助經理和員工理解發生了甚麼。"},{"en":"This phrase shows why evidence matters in workplace disputes.","zh":"這個片語顯示證據在職場爭議中為何重要。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"prevent rumours from replacing evidence","meaning":"防止謠言取代證據","examples":[{"en":"Reliable records can prevent rumours from replacing evidence.","zh":"可靠記錄可以防止謠言取代證據。"},{"en":"To prevent rumours from replacing evidence means to stop gossip or guesses from being treated as facts.","zh":"prevent rumours from replacing evidence 意思是阻止閒話或猜測被當作事實。"},{"en":"Clear footage can prevent rumours from replacing evidence after an accident.","zh":"意外後，清晰錄影片段可以防止謠言取代證據。"},{"en":"Without records, people may rely on personal stories and assumptions.","zh":"沒有記錄，人們可能依賴個人說法和假設。"},{"en":"This phrase supports monitoring as a way to protect fairness.","zh":"這個片語支持把監察作為保護公平的方法。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"honest workers","meaning":"誠實員工","examples":[{"en":"Honest workers may feel safer when records are available.","zh":"當有記錄可查時，誠實員工可能感到更安全。"},{"en":"Honest workers are employees who act truthfully and responsibly.","zh":"honest workers 指誠實而負責任行事的員工。"},{"en":"Honest workers can be protected by records if false accusations arise.","zh":"如果出現虛假指控，記錄可以保護誠實員工。"},{"en":"Monitoring should not punish honest workers for normal pauses or human mistakes.","zh":"監察不應因正常停頓或人為錯誤而懲罰誠實員工。"},{"en":"This phrase reminds readers that fairness includes protecting the innocent.","zh":"這個片語提醒讀者，公平包括保護無辜者。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"false accusations","meaning":"虛假指控","examples":[{"en":"False accusations can be checked against footage or system logs.","zh":"虛假指控可以與錄影片段或系統記錄核對。"},{"en":"False accusations are claims that someone did something wrong when they did not.","zh":"false accusations 指聲稱某人做錯事，但事實並非如此。"},{"en":"An employee may face false accusations after a workplace dispute.","zh":"員工在職場爭議後可能面對虛假指控。"},{"en":"Records can help prove whether the accusation is fair or mistaken.","zh":"記錄可以幫助證明指控是否公平或錯誤。"},{"en":"This phrase shows one reason employees may also benefit from monitoring.","zh":"這個片語顯示員工也可能從監察中受惠的一個原因。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"be checked against","meaning":"與……核對","examples":[{"en":"False accusations can be checked against footage.","zh":"虛假指控可以與錄影片段核對。"},{"en":"Be checked against means be compared with another source to see if it is true.","zh":"be checked against 意思是與另一來源比較，以判斷是否屬實。"},{"en":"A worker’s claim can be checked against system logs.","zh":"員工的說法可以與系統記錄核對。"},{"en":"Checking claims against evidence reduces unfair judgement.","zh":"把說法與證據核對，可以減少不公平判斷。"},{"en":"This phrase describes a process of verification.","zh":"這個片語描述核實過程。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"footage","meaning":"錄影片段","examples":[{"en":"False accusations can be checked against footage.","zh":"虛假指控可以與錄影片段核對。"},{"en":"Footage means recorded video material.","zh":"footage 指錄下來的影片材料。"},{"en":"Security footage may show whether an employee was near the area.","zh":"保安錄影片段可能顯示員工是否在該區附近。"},{"en":"Footage can clarify events, but it should be used carefully and fairly.","zh":"錄影片段可以釐清事件，但應謹慎而公平地使用。"},{"en":"This phrase refers to visual evidence from cameras.","zh":"這個片語指來自攝影機的視覺證據。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"system logs","meaning":"系統記錄","examples":[{"en":"False accusations can be checked against system logs.","zh":"虛假指控可以與系統記錄核對。"},{"en":"System logs are digital records of actions taken in a computer system.","zh":"system logs 指電腦系統中行動的數碼記錄。"},{"en":"System logs may show when a file was opened or edited.","zh":"系統記錄可能顯示檔案何時被開啟或修改。"},{"en":"Managers can use system logs to investigate data access fairly.","zh":"經理可以使用系統記錄公平調查資料存取。"},{"en":"This phrase refers to technical evidence inside digital systems.","zh":"這個片語指數碼系統內的技術證據。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"performance evaluation","meaning":"表現評估","examples":[{"en":"Monitoring can make performance evaluation less dependent on personal impressions.","zh":"監察可以令表現評估較少依賴個人印象。"},{"en":"Performance evaluation means judging how well an employee does their job.","zh":"performance evaluation 指評價員工工作做得如何。"},{"en":"A fair performance evaluation should consider results, effort, quality, and teamwork.","zh":"公平的表現評估應考慮結果、努力、質素和團隊合作。"},{"en":"Monitoring data may support evaluation, but it should not replace human judgement completely.","zh":"監察數據可以支援評估，但不應完全取代人的判斷。"},{"en":"This phrase refers to how workers are assessed.","zh":"這個片語指員工如何被評核。"}],"source":"2023 Q4.pdf","sourcePage":8},{"front":"less dependent on","meaning":"較少依賴","examples":[{"en":"Performance evaluation may become less dependent on personal impressions.","zh":"表現評估可能變得較少依賴個人印象。"},{"en":"Less dependent on means relying less on something.","zh":"less dependent on 意思是較少依靠某事。"},{"en":"A fair system is less dependent on one manager’s personal opinion.","zh":"公平制度較少依賴一位經理的個人意見。"},{"en":"Data can make evaluation less dependent on memory or bias.","zh":"數據可以令評估較少依賴記憶或偏見。"},{"en":"This phrase shows a possible fairness benefit of records.","zh":"這個片語顯示記錄可能帶來的公平好處。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"personal impressions","meaning":"個人印象","examples":[{"en":"Performance evaluation should not depend only on personal impressions.","zh":"表現評估不應只依賴個人印象。"},{"en":"Personal impressions are opinions based on how someone seems rather than full evidence.","zh":"personal impressions 指根據某人看起來如何而非完整證據形成的意見。"},{"en":"A confident worker may create a good personal impression even if the work is careless.","zh":"自信的員工即使工作粗心，也可能留下良好個人印象。"},{"en":"A quiet worker may be undervalued if evaluation depends only on impressions.","zh":"如果評估只依賴印象，沉默寡言的員工可能被低估。"},{"en":"This phrase warns against judging people too subjectively.","zh":"這個片語提醒不要過分主觀地判斷人。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"quiet employee","meaning":"沉默寡言的員工","examples":[{"en":"A quiet employee who works accurately may receive recognition.","zh":"一位準確工作的沉默寡言員工可能獲得認可。"},{"en":"A quiet employee is a worker who does not speak much or draw attention to themselves.","zh":"quiet employee 指不常說話或不引人注意的員工。"},{"en":"A quiet employee may still complete difficult tasks carefully.","zh":"沉默寡言的員工仍可能仔細完成困難任務。"},{"en":"Data can help managers notice quiet employees who perform well.","zh":"數據可以幫助經理留意表現良好的沉默員工。"},{"en":"This phrase shows how monitoring may reveal hidden contribution.","zh":"這個片語顯示監察可能揭示隱藏貢獻。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"complete tasks accurately","meaning":"準確完成任務","examples":[{"en":"A quiet employee may complete tasks accurately.","zh":"沉默寡言的員工可能準確完成任務。"},{"en":"To complete tasks accurately means to finish work correctly and with few errors.","zh":"complete tasks accurately 意思是正確完成工作，並且錯誤很少。"},{"en":"Data entry staff must complete tasks accurately to protect customer records.","zh":"資料輸入員必須準確完成任務，以保護客戶紀錄。"},{"en":"Accurate work may be less visible than confident speech.","zh":"準確工作可能比自信說話更不顯眼。"},{"en":"This phrase highlights quality rather than appearance.","zh":"這個片語強調質素，而不是外表。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"receive recognition","meaning":"獲得認可","examples":[{"en":"A hardworking employee may finally receive recognition.","zh":"勤奮的員工可能終於獲得認可。"},{"en":"To receive recognition means to be noticed, valued, or praised for good work.","zh":"receive recognition 意思是因良好工作而被注意、重視或讚賞。"},{"en":"A quiet worker may receive recognition when data shows consistent accuracy.","zh":"當數據顯示持續準確時，沉默員工可能獲得認可。"},{"en":"Recognition can improve motivation and job satisfaction.","zh":"認可可以改善工作動力和工作滿意度。"},{"en":"This phrase describes a positive result of fair evaluation.","zh":"這個片語描述公平評估的正面結果。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"whereas","meaning":"然而；相比之下","examples":[{"en":"A quiet worker may receive recognition, whereas a careless worker may be exposed.","zh":"沉默員工可能獲得認可，然而粗心員工可能被揭露。"},{"en":"Whereas is used to compare two different situations.","zh":"whereas 用來比較兩種不同情況。"},{"en":"One employee may work carefully, whereas another may only appear confident.","zh":"一位員工可能仔細工作，相比之下，另一位可能只是看起來自信。"},{"en":"This word helps show contrast in a formal sentence.","zh":"這個字幫助在正式句子中顯示對比。"},{"en":"It is useful when comparing different effects of the same system.","zh":"當比較同一制度的不同影響時，它很有用。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"careless worker","meaning":"粗心大意的員工","examples":[{"en":"A careless worker may no longer hide behind confidence.","zh":"粗心大意的員工可能不再能躲在自信背後。"},{"en":"A careless worker is an employee who makes avoidable mistakes or ignores details.","zh":"careless worker 指犯可避免錯誤或忽視細節的員工。"},{"en":"A careless worker may sound confident but produce inaccurate work.","zh":"粗心大意的員工可能聽起來自信，但工作不準確。"},{"en":"Monitoring may expose careless work if errors are recorded.","zh":"如果錯誤被記錄，監察可能揭露粗心工作。"},{"en":"This phrase contrasts appearance with real performance.","zh":"這個片語把外表與真實表現作對比。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"hide behind confidence","meaning":"躲在自信背後","examples":[{"en":"A careless worker may no longer hide behind confidence.","zh":"粗心大意的員工可能不再能躲在自信背後。"},{"en":"To hide behind confidence means to use a confident manner to cover weak performance.","zh":"hide behind confidence 意思是用自信態度掩蓋薄弱表現。"},{"en":"A worker may speak loudly in meetings but still make careless errors.","zh":"員工可能在會議中說話響亮，但仍犯粗心錯誤。"},{"en":"Data can make it harder to hide behind confidence.","zh":"數據可以令人較難躲在自信背後。"},{"en":"This phrase criticises appearance without substance.","zh":"這個片語批評沒有實質內容的外表。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"limited monitoring","meaning":"有限度的監察","examples":[{"en":"Limited monitoring can support fairness, security, and accountability.","zh":"有限度的監察可以支持公平、安全和問責。"},{"en":"Limited monitoring means observation that is restricted to necessary areas and purposes.","zh":"limited monitoring 指限於必要範圍和目的的觀察。"},{"en":"Limited monitoring may check work systems without tracking private messages.","zh":"有限度的監察可能檢查工作系統，而不追蹤私人訊息。"},{"en":"It can protect safety while reducing damage to trust.","zh":"它可以保護安全，同時減少對信任的損害。"},{"en":"This phrase describes the type of monitoring the essay supports.","zh":"這個片語描述文章支持的監察類型。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"fairness, security and accountability","meaning":"公平、安全和問責","examples":[{"en":"Limited monitoring can support fairness, security, and accountability.","zh":"有限度的監察可以支持公平、安全和問責。"},{"en":"Fairness, security and accountability mean justice, protection, and responsibility for actions.","zh":"fairness, security and accountability 指公正、保障和對行動負責。"},{"en":"A good workplace needs fairness, security, and accountability for both managers and employees.","zh":"好職場對經理和員工都需要公平、安全和問責。"},{"en":"Monitoring may support these values when rules are clear and data is limited.","zh":"當規則清晰而數據有限時，監察可能支持這些價值。"},{"en":"This phrase summarises the strongest positive argument for monitoring.","zh":"這個片語總結支持監察的最強正面論點。"}],"source":"2023 Q4.pdf","sourcePage":9},{"front":"however","meaning":"然而","examples":[{"en":"However, the disadvantages are serious.","zh":"然而，缺點很嚴重。"},{"en":"However is used to introduce a contrast or opposite point.","zh":"however 用來引出對比或相反重點。"},{"en":"Monitoring may improve safety; however, it can also damage trust.","zh":"監察可能改善安全；然而，它也可能損害信任。"},{"en":"This word helps the essay move from advantages to disadvantages.","zh":"這個字幫助文章由好處轉向缺點。"},{"en":"It signals that the discussion is becoming more critical.","zh":"它表示討論變得較具批判性。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"the disadvantages are serious","meaning":"缺點很嚴重","examples":[{"en":"The disadvantages of monitoring are serious.","zh":"監察的缺點很嚴重。"},{"en":"The disadvantages are serious means the negative effects are important and should not be ignored.","zh":"the disadvantages are serious 意思是負面影響重要，不應被忽視。"},{"en":"The disadvantages are serious if monitoring makes employees anxious every day.","zh":"如果監察令員工每天焦慮，缺點便很嚴重。"},{"en":"A system with serious disadvantages needs limits and safeguards.","zh":"有嚴重缺點的制度需要限制和保障措施。"},{"en":"This phrase prepares the reader for a strong warning.","zh":"這個片語讓讀者準備閱讀強烈警告。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"the most obvious problem","meaning":"最明顯的問題","examples":[{"en":"The most obvious problem is the damage done to trust.","zh":"最明顯的問題是對信任造成的損害。"},{"en":"The most obvious problem means the easiest problem to notice.","zh":"the most obvious problem 意思是最容易察覺的問題。"},{"en":"The most obvious problem with constant cameras is that workers may feel watched all day.","zh":"持續攝影機最明顯的問題，是員工可能覺得整天被監視。"},{"en":"In employee monitoring, loss of trust is often the most visible harm.","zh":"在員工監察中，失去信任往往是最明顯的傷害。"},{"en":"This phrase introduces the main disadvantage clearly.","zh":"這個片語清楚引出主要缺點。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"damage done to trust","meaning":"對信任造成的損害","examples":[{"en":"The most obvious problem is the damage done to trust.","zh":"最明顯的問題是對信任造成的損害。"},{"en":"Damage done to trust means harm caused to the belief that people are honest and reliable.","zh":"damage done to trust 指對人們相信彼此誠實可靠所造成的傷害。"},{"en":"Secret monitoring can create serious damage to trust.","zh":"秘密監察可以對信任造成嚴重損害。"},{"en":"Once trust is damaged, employees may become defensive and less loyal.","zh":"一旦信任受損，員工可能變得防衛和較不忠誠。"},{"en":"This phrase explains why monitoring has emotional consequences.","zh":"這個片語解釋為何監察有情感後果。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"a workplace is not a prison","meaning":"職場不是監獄","examples":[{"en":"A workplace is not a prison.","zh":"職場不是監獄。"},{"en":"A workplace is not a prison means employees should not be treated like people under punishment or control.","zh":"a workplace is not a prison 意思是員工不應被當作受懲罰或受控制的人對待。"},{"en":"Workers need trust, dignity, and freedom to think.","zh":"員工需要信任、尊嚴和思考自由。"},{"en":"If cameras stare at staff all day, the office may feel like a prison.","zh":"如果攝影機整天盯着員工，辦公室可能像監獄。"},{"en":"This phrase strongly criticises excessive surveillance.","zh":"這個片語強烈批評過度監控。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"hired only to","meaning":"被聘請只為了……","examples":[{"en":"Employees are not machines hired only to produce measurable output.","zh":"員工不是被聘請只為了產生可量度產出的機器。"},{"en":"Hired only to means employed for just one narrow purpose.","zh":"hired only to 意思是被僱用只為了一個狹窄目的。"},{"en":"Workers are not hired only to press keys or fill forms.","zh":"員工不是被聘請只為按鍵或填表。"},{"en":"If employees feel hired only to produce numbers, they may lose motivation.","zh":"如果員工覺得自己被聘請只為製造數字，可能失去動力。"},{"en":"This phrase criticises a mechanical view of human work.","zh":"這個片語批評把人類工作機械化的看法。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"measurable output","meaning":"可量度的產出","examples":[{"en":"Employees are not machines hired only to produce measurable output.","zh":"員工不是被聘請只為產生可量度產出的機器。"},{"en":"Measurable output is work that can be counted, timed, or easily recorded.","zh":"measurable output 是可以被計算、計時或容易記錄的工作成果。"},{"en":"Number of calls answered is a form of measurable output.","zh":"接聽電話數量是一種可量度的產出。"},{"en":"Not all valuable work becomes measurable output, such as creativity or mentoring.","zh":"並非所有有價值工作都會變成可量度產出，例如創意或指導同事。"},{"en":"This phrase shows the limits of judging work only by numbers.","zh":"這個片語顯示只用數字判斷工作的限制。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"stare at staff all day","meaning":"整天盯着員工","examples":[{"en":"Cameras may stare at staff all day.","zh":"攝影機可能整天盯着員工。"},{"en":"To stare at staff all day means to watch employees constantly and intensely.","zh":"stare at staff all day 意思是持續而強烈地監視員工。"},{"en":"Workers may feel uncomfortable if cameras seem to stare at them all day.","zh":"如果攝影機像整天盯着員工，他們可能感到不自在。"},{"en":"Constant visual monitoring can make a workplace feel cold.","zh":"持續影像監察可以令職場感覺冷漠。"},{"en":"This phrase creates a strong image of excessive surveillance.","zh":"這個片語創造過度監控的強烈畫面。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"track every click","meaning":"追蹤每一下點擊","examples":[{"en":"Software may track every click, pause, and message.","zh":"軟件可能追蹤每一下點擊、停頓和訊息。"},{"en":"To track every click means to record each small computer action an employee makes.","zh":"track every click 意思是記錄員工在電腦上的每個細小行動。"},{"en":"Software that tracks every click can make workers feel constantly judged.","zh":"追蹤每一下點擊的軟件可以令員工感到持續被評判。"},{"en":"Tracking every click may measure activity but not real achievement.","zh":"追蹤每一下點擊可能衡量活動，但不能衡量真正成就。"},{"en":"This phrase shows how monitoring can become excessive.","zh":"這個片語顯示監察如何變得過度。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"feel as if","meaning":"感覺好像","examples":[{"en":"Workers may feel as if their employer assumes guilt.","zh":"員工可能感覺好像僱主假定他們有罪。"},{"en":"Feel as if means have the impression that something is true, even if it is not stated directly.","zh":"feel as if 意思是感覺某事是真的，即使沒有直接說出。"},{"en":"Employees may feel as if they are not trusted when every pause is recorded.","zh":"當每次停頓都被記錄時，員工可能感覺好像不被信任。"},{"en":"Feeling as if one is suspected can damage loyalty.","zh":"感覺好像被懷疑可以損害忠誠。"},{"en":"This phrase describes the emotional effect of monitoring.","zh":"這個片語描述監察的情緒影響。"}],"source":"2023 Q4.pdf","sourcePage":10},{"front":"assume guilt","meaning":"假定有罪","examples":[{"en":"Workers may feel that their employer assumes guilt before seeing effort.","zh":"員工可能覺得僱主在看見努力之前已假定有罪。"},{"en":"To assume guilt means to believe someone has done wrong before there is proof.","zh":"assume guilt 意思是在有證據前便相信某人做錯事。"},{"en":"Constant monitoring can make employees feel managers assume guilt first.","zh":"持續監察可以令員工覺得經理先假定有罪。"},{"en":"A fair employer should look at evidence before assuming guilt.","zh":"公平僱主應先看證據，而不是假定有罪。"},{"en":"This phrase explains why surveillance can feel insulting.","zh":"這個片語解釋為何監控會令人感到受冒犯。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"before seeing effort","meaning":"在看見努力之前","examples":[{"en":"Workers may feel judged before their effort is seen.","zh":"員工可能在自己的努力被看見之前已被評判。"},{"en":"Before seeing effort means before noticing how hard someone is trying.","zh":"before seeing effort 意思是在留意到某人有多努力之前。"},{"en":"A manager should understand an employee’s effort before judging one quiet afternoon.","zh":"經理應在評判某個安靜下午前，先理解員工的努力。"},{"en":"Monitoring may judge activity before seeing the thinking behind it.","zh":"監察可能在看見背後思考之前先評判活動量。"},{"en":"This phrase criticises hasty and surface-level judgement.","zh":"這個片語批評草率和表面化的判斷。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"feel distrusted","meaning":"感到不被信任","examples":[{"en":"People who feel distrusted are less likely to show loyalty.","zh":"感到不被信任的人較不可能表現忠誠。"},{"en":"Feel distrusted means feel that others do not believe you are honest or responsible.","zh":"feel distrusted 意思是覺得別人不相信你誠實或負責任。"},{"en":"Employees feel distrusted when every action is treated as suspicious.","zh":"當每個行動都被視為可疑時，員工會感到不被信任。"},{"en":"Feeling distrusted can reduce motivation and openness.","zh":"感到不被信任會降低動力和坦誠度。"},{"en":"This phrase explains how monitoring can damage workplace relationships.","zh":"這個片語解釋監察如何損害職場關係。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"show loyalty","meaning":"表現忠誠","examples":[{"en":"Distrusted workers are less likely to show loyalty.","zh":"不被信任的員工較不可能表現忠誠。"},{"en":"To show loyalty means to act with commitment and support towards an organisation or person.","zh":"show loyalty 意思是對機構或個人表現承擔和支持。"},{"en":"Employees show loyalty when they care about the company’s long-term success.","zh":"當員工關心公司長遠成功時，就是表現忠誠。"},{"en":"If workers feel watched rather than trusted, loyalty may weaken.","zh":"如果員工感到被監視而不是被信任，忠誠可能削弱。"},{"en":"This phrase connects trust with workplace commitment.","zh":"這個片語把信任與職場承擔連接起來。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"creativity","meaning":"創意","examples":[{"en":"Monitoring may reduce creativity.","zh":"監察可能降低創意。"},{"en":"Creativity means the ability to produce new, useful, or original ideas.","zh":"creativity 指產生新穎、有用或原創想法的能力。"},{"en":"Designers need creativity when solving problems or developing campaigns.","zh":"設計師在解難或開發宣傳活動時需要創意。"},{"en":"Constant monitoring may reduce creativity by making workers afraid to pause and think.","zh":"持續監察可能令員工害怕停下來思考，從而降低創意。"},{"en":"This phrase names a quality that is hard to measure with simple data.","zh":"這個片語指出一種難以用簡單數據衡量的質素。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"initiative","meaning":"主動性","examples":[{"en":"Distrusted workers are less likely to show initiative.","zh":"不被信任的員工較不可能表現主動性。"},{"en":"Initiative means the willingness to act, suggest ideas, or solve problems without being told.","zh":"initiative 指在未被要求下願意行動、提出想法或解決問題。"},{"en":"An employee shows initiative by improving a process before being asked.","zh":"員工在被要求前改善程序，就是表現主動性。"},{"en":"Excessive monitoring may reduce initiative because workers fear mistakes.","zh":"過度監察可能降低主動性，因為員工害怕犯錯。"},{"en":"This phrase describes independent and active contribution.","zh":"這個片語描述獨立而積極的貢獻。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"idle time","meaning":"空閒時間","examples":[{"en":"A designer may need idle time to think.","zh":"設計師可能需要空閒時間來思考。"},{"en":"Idle time is time that looks inactive but may be used for thinking or recovery.","zh":"idle time 指看似沒有活動，但可能用於思考或恢復的時間。"},{"en":"Creative workers may need idle time before producing strong ideas.","zh":"創意工作者在產生好想法前可能需要空閒時間。"},{"en":"Monitoring may wrongly treat idle time as laziness.","zh":"監察可能錯誤地把空閒時間視為懶惰。"},{"en":"This phrase shows that not all valuable work looks busy.","zh":"這個片語顯示並非所有有價值工作都看似忙碌。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"constantly recorded","meaning":"不斷被記錄","examples":[{"en":"Idle time may be constantly recorded by software.","zh":"空閒時間可能被軟件不斷記錄。"},{"en":"Constantly recorded means saved or tracked again and again without much pause.","zh":"constantly recorded 意思是反覆被保存或追蹤，幾乎沒有停頓。"},{"en":"If every pause is constantly recorded, workers may feel anxious.","zh":"如果每次停頓都不斷被記錄，員工可能感到焦慮。"},{"en":"Constantly recorded behaviour can make employees act for the system rather than the work.","zh":"不斷被記錄的行為可能令員工為系統而表演，而不是為工作而做事。"},{"en":"This phrase shows the pressure of continuous monitoring.","zh":"這個片語顯示持續監察帶來的壓力。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"avoid pausing to think","meaning":"避免停下來思考","examples":[{"en":"A designer may avoid pausing to think.","zh":"設計師可能避免停下來思考。"},{"en":"To avoid pausing to think means to stop taking quiet thinking time because it may look unproductive.","zh":"avoid pausing to think 意思是停止使用安靜思考時間，因為它可能看起來沒有生產力。"},{"en":"A monitored employee may avoid pausing even when reflection is needed.","zh":"被監察的員工即使需要反思，也可能避免停頓。"},{"en":"Avoiding pauses can weaken creativity and problem-solving.","zh":"避免停頓可能削弱創意和解難能力。"},{"en":"This phrase shows how monitoring can change useful work habits.","zh":"這個片語顯示監察如何改變有用的工作習慣。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"lead to better ideas","meaning":"帶來更好的想法","examples":[{"en":"Pauses may lead to better ideas.","zh":"停頓可能帶來更好的想法。"},{"en":"Lead to better ideas means result in stronger, more useful, or more creative thoughts.","zh":"lead to better ideas 意思是產生更有力、更有用或更有創意的想法。"},{"en":"A quiet walk may lead to better ideas for a design project.","zh":"一段安靜散步可能為設計項目帶來更好的想法。"},{"en":"If monitoring punishes pauses, it may reduce the chance of better ideas.","zh":"如果監察懲罰停頓，可能減少出現好想法的機會。"},{"en":"This phrase defends thinking time as productive.","zh":"這個片語為思考時間作出生產力辯護。"}],"source":"2023 Q4.pdf","sourcePage":11},{"front":"mistake silence for laziness","meaning":"把沉默誤當成懶惰","examples":[{"en":"Monitoring can mistake silence for laziness.","zh":"監察可以把沉默誤當成懶惰。"},{"en":"To mistake silence for laziness means to wrongly think quietness means lack of effort.","zh":"mistake silence for laziness 意思是錯誤地以為安靜代表缺乏努力。"},{"en":"A worker may be silent because she is solving a difficult problem.","zh":"員工沉默可能是因為正在解決困難問題。"},{"en":"Monitoring tools may misjudge silence if they only measure visible activity.","zh":"如果監察工具只量度可見活動，可能誤判沉默。"},{"en":"This phrase shows the danger of shallow measurement.","zh":"這個片語顯示表面衡量的危險。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"reflection for waste","meaning":"把反思誤當成浪費","examples":[{"en":"Monitoring can mistake reflection for waste.","zh":"監察可以把反思誤當成浪費。"},{"en":"To mistake reflection for waste means to wrongly treat thinking time as useless time.","zh":"mistake reflection for waste 意思是錯誤地把思考時間視為無用時間。"},{"en":"Reflection may help employees avoid careless decisions.","zh":"反思可能幫助員工避免草率決定。"},{"en":"A system that rewards only activity may see reflection as waste.","zh":"只獎勵活動量的系統可能把反思視為浪費。"},{"en":"This phrase criticises monitoring that cannot recognise thinking.","zh":"這個片語批評不能識別思考的監察。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"the result is","meaning":"結果是","examples":[{"en":"The result is a colder workplace.","zh":"結果是更冷漠的職場。"},{"en":"The result is means the consequence or outcome is.","zh":"the result is 意思是後果或結果是。"},{"en":"If every movement is tracked, the result may be fear rather than trust.","zh":"如果每個動作都被追蹤，結果可能是恐懼而不是信任。"},{"en":"This phrase clearly connects cause and effect.","zh":"這個片語清楚連接原因和結果。"},{"en":"It helps the writer show what excessive monitoring produces.","zh":"它幫助作者顯示過度監察會產生甚麼。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"a colder workplace","meaning":"更冷漠的職場","examples":[{"en":"Excessive monitoring can create a colder workplace.","zh":"過度監察可以造成更冷漠的職場。"},{"en":"A colder workplace is a work environment with less warmth, trust, and human connection.","zh":"colder workplace 指較少溫暖、信任和人際連繫的工作環境。"},{"en":"A colder workplace may make employees afraid to speak freely.","zh":"更冷漠的職場可能令員工害怕自由發言。"},{"en":"Constant surveillance can turn teamwork into self-protection.","zh":"持續監控可以把團隊合作變成自我保護。"},{"en":"This phrase describes the emotional atmosphere created by over-monitoring.","zh":"這個片語描述過度監察造成的情緒氣氛。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"protect themselves","meaning":"保護自己","examples":[{"en":"Employees may protect themselves instead of contributing freely.","zh":"員工可能保護自己，而不是自由地作出貢獻。"},{"en":"To protect themselves means to act defensively to avoid blame or risk.","zh":"protect themselves 意思是防衛性行事，以避免責備或風險。"},{"en":"Workers may protect themselves by avoiding new ideas that could fail.","zh":"員工可能透過避免可能失敗的新想法來保護自己。"},{"en":"Excessive monitoring encourages employees to protect themselves rather than experiment.","zh":"過度監察鼓勵員工保護自己，而不是嘗試。"},{"en":"This phrase shows how fear changes workplace behaviour.","zh":"這個片語顯示恐懼如何改變職場行為。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"contributing freely","meaning":"自由地作出貢獻","examples":[{"en":"Employees may stop contributing freely when they feel watched.","zh":"當員工感到被監視時，可能停止自由地作出貢獻。"},{"en":"Contributing freely means offering ideas, effort, and help without fear.","zh":"contributing freely 意思是在沒有恐懼下提供想法、努力和幫助。"},{"en":"A trusted employee is more likely to contribute freely in meetings.","zh":"被信任的員工較可能在會議中自由作出貢獻。"},{"en":"Constant surveillance can reduce free contribution by making workers cautious.","zh":"持續監控可能令員工變得謹慎，從而減少自由貢獻。"},{"en":"This phrase connects trust with creativity and teamwork.","zh":"這個片語把信任與創意和團隊合作連接起來。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"more worryingly","meaning":"更令人擔心的是","examples":[{"en":"More worryingly, excessive monitoring can create false productivity.","zh":"更令人擔心的是，過度監察可以造成虛假的生產力。"},{"en":"More worryingly means even more concerning than the previous point.","zh":"more worryingly 意思是比前一點更令人擔憂。"},{"en":"More worryingly, workers may learn to look busy rather than work meaningfully.","zh":"更令人擔心的是，員工可能學會看似忙碌，而不是做有意義的工作。"},{"en":"This phrase introduces a stronger or deeper problem.","zh":"這個片語引出更強或更深層的問題。"},{"en":"It warns readers that the issue is not only emotional but also practical.","zh":"它提醒讀者，問題不只是情緒上的，也是實際上的。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"excessive monitoring","meaning":"過度監察","examples":[{"en":"Excessive monitoring can create false productivity.","zh":"過度監察可以造成虛假的生產力。"},{"en":"Excessive monitoring means watching employees too much or beyond what is necessary.","zh":"excessive monitoring 意思是過多或超出必要地監察員工。"},{"en":"Tracking every pause and click may be excessive monitoring.","zh":"追蹤每次停頓和點擊可能是過度監察。"},{"en":"Excessive monitoring can make workers anxious and less creative.","zh":"過度監察可以令員工焦慮並降低創意。"},{"en":"This phrase names the harmful version of employee monitoring.","zh":"這個片語指出員工監察中有害的一種。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"false productivity","meaning":"虛假的生產力","examples":[{"en":"Excessive monitoring can create false productivity.","zh":"過度監察可以造成虛假的生產力。"},{"en":"False productivity means looking busy or productive without doing meaningful work.","zh":"false productivity 指看似忙碌或有生產力，但沒有完成有意義工作。"},{"en":"Keeping a screen active may create false productivity if no real task is completed.","zh":"如果沒有真正完成任務，讓螢幕保持運作可能造成虛假的生產力。"},{"en":"Monitoring can encourage false productivity when it rewards activity over results.","zh":"當監察獎勵活動量而不是成果時，可能鼓勵虛假的生產力。"},{"en":"This phrase criticises shallow measures of work.","zh":"這個片語批評表面化的工作衡量。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"the trouble with","meaning":"……的問題在於","examples":[{"en":"The trouble with measuring everything is that people perform for the measurement.","zh":"衡量一切的問題在於，人們會為指標而表演。"},{"en":"The trouble with something means the problem or weakness of it.","zh":"the trouble with 某事，意思是它的問題或弱點。"},{"en":"The trouble with tracking every minute is that workers may stop thinking freely.","zh":"追蹤每一分鐘的問題在於，員工可能停止自由思考。"},{"en":"This phrase introduces a criticism in a clear and conversational way.","zh":"這個片語以清楚而自然的方式引出批評。"},{"en":"It helps explain why a system that sounds logical may fail.","zh":"它幫助解釋看似合理的制度為何可能失敗。"}],"source":"2023 Q4.pdf","sourcePage":12},{"front":"measuring everything","meaning":"衡量一切","examples":[{"en":"The trouble with measuring everything is that people learn to game the system.","zh":"衡量一切的問題在於，人們會學會鑽制度空子。"},{"en":"Measuring everything means trying to turn every action into data or scores.","zh":"measuring everything 意思是嘗試把每個行動都變成數據或分數。"},{"en":"Measuring everything may miss important work such as mentoring or creativity.","zh":"衡量一切可能錯過重要工作，例如指導同事或創意。"},{"en":"If managers measure everything, employees may focus on numbers instead of quality.","zh":"如果經理衡量一切，員工可能專注於數字而不是質素。"},{"en":"This phrase criticises over-reliance on data.","zh":"這個片語批評過度依賴數據。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"perform for the measurement","meaning":"為指標而表演","examples":[{"en":"People may learn to perform for the measurement.","zh":"人們可能學會為指標而表演。"},{"en":"To perform for the measurement means to act in ways that make the data look good rather than improve real work.","zh":"perform for the measurement 意思是為令數據好看而行動，而不是改善真正工作。"},{"en":"A worker may keep typing to perform for the measurement.","zh":"員工可能不斷打字來為指標而表演。"},{"en":"Employees may perform for the measurement if they fear being judged by simple numbers.","zh":"如果員工害怕被簡單數字評判，可能會為指標而表演。"},{"en":"This phrase explains how monitoring can distort behaviour.","zh":"這個片語解釋監察如何扭曲行為。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"reward keystrokes","meaning":"獎勵按鍵次數","examples":[{"en":"Software may reward keystrokes instead of meaningful work.","zh":"軟件可能獎勵按鍵次數，而不是有意義的工作。"},{"en":"To reward keystrokes means to value the number of keyboard actions more than real results.","zh":"reward keystrokes 意思是重視鍵盤動作數量多於真正成果。"},{"en":"A system may reward keystrokes if it counts typing as productivity.","zh":"如果系統把打字量當作生產力，就可能獎勵按鍵次數。"},{"en":"Rewarding keystrokes encourages busy-looking behaviour.","zh":"獎勵按鍵次數會鼓勵看似忙碌的行為。"},{"en":"This phrase criticises measuring activity instead of achievement.","zh":"這個片語批評衡量活動量而非成就。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"type unnecessary notes","meaning":"打不必要的筆記","examples":[{"en":"Employees may type unnecessary notes to look productive.","zh":"員工可能打不必要的筆記，以看起來有生產力。"},{"en":"To type unnecessary notes means to write extra text that is not truly needed.","zh":"type unnecessary notes 意思是寫下並非真正需要的額外文字。"},{"en":"Workers may type unnecessary notes if the system rewards keyboard activity.","zh":"如果系統獎勵鍵盤活動，員工可能打不必要的筆記。"},{"en":"This behaviour wastes time while making productivity data look better.","zh":"這種行為浪費時間，卻令生產力數據看起來更好。"},{"en":"This phrase gives a concrete example of false productivity.","zh":"這個片語提供虛假生產力的具體例子。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"focus on","meaning":"專注於","examples":[{"en":"If managers focus on time spent online, workers may keep screens active.","zh":"如果經理專注於在線時間，員工可能讓螢幕保持運作。"},{"en":"Focus on means give special attention to something.","zh":"focus on 意思是特別注意某事。"},{"en":"Managers should focus on results, not only screen activity.","zh":"經理應專注於成果，而不只是螢幕活動。"},{"en":"If a company focuses on the wrong measure, workers may change behaviour in the wrong way.","zh":"如果公司專注於錯誤指標，員工可能以錯誤方式改變行為。"},{"en":"This phrase shows how attention shapes incentives.","zh":"這個片語顯示注意力如何塑造誘因。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"time spent online","meaning":"在線時間","examples":[{"en":"Managers may focus too much on time spent online.","zh":"經理可能過分專注於在線時間。"},{"en":"Time spent online means the amount of time someone appears active on the internet or computer system.","zh":"time spent online 指某人看似在互聯網或電腦系統上活躍的時間。"},{"en":"Time spent online does not always show whether meaningful work is done.","zh":"在線時間不一定顯示是否完成有意義的工作。"},{"en":"A worker may spend hours online while producing little real value.","zh":"員工可能在線數小時，卻產生很少真正價值。"},{"en":"This phrase shows a limited measure of productivity.","zh":"這個片語顯示一種有限的生產力衡量方式。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"keep screens active","meaning":"讓螢幕保持運作","examples":[{"en":"Workers may keep screens active without doing meaningful work.","zh":"員工可能讓螢幕保持運作，卻沒有做有意義的工作。"},{"en":"To keep screens active means to make the computer appear in use.","zh":"keep screens active 意思是令電腦看起來正在被使用。"},{"en":"An employee may move the mouse simply to keep the screen active.","zh":"員工可能只是移動滑鼠來讓螢幕保持運作。"},{"en":"Keeping screens active can create false productivity.","zh":"讓螢幕保持運作可以造成虛假的生產力。"},{"en":"This phrase shows how employees may game monitoring systems.","zh":"這個片語顯示員工如何鑽監察制度空子。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"meaningful work","meaning":"有意義的工作","examples":[{"en":"Active screens do not always mean meaningful work.","zh":"螢幕活躍不一定代表有意義的工作。"},{"en":"Meaningful work is work that has real value, purpose, or useful results.","zh":"meaningful work 指有真正價值、目的或有用結果的工作。"},{"en":"Solving a customer problem is meaningful work even if it takes quiet thinking.","zh":"解決顧客問題是有意義的工作，即使需要安靜思考。"},{"en":"Monitoring should measure meaningful work, not only visible activity.","zh":"監察應衡量有意義的工作，而不只是可見活動。"},{"en":"This phrase contrasts real contribution with surface busyness.","zh":"這個片語把真正貢獻與表面忙碌作對比。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"punish every short conversation","meaning":"懲罰每段短暫對話","examples":[{"en":"Cameras may punish every short conversation.","zh":"攝影機可能懲罰每段短暫對話。"},{"en":"To punish every short conversation means to treat even brief human interaction as wasted time.","zh":"punish every short conversation 意思是把即使短暫的人際交流也視為浪費時間。"},{"en":"A short conversation may help colleagues solve a problem quickly.","zh":"一段短暫對話可能幫助同事快速解決問題。"},{"en":"Monitoring that punishes every chat may damage teamwork.","zh":"懲罰每段聊天的監察可能損害團隊合作。"},{"en":"This phrase warns against interpreting all conversation as laziness.","zh":"這個片語提醒不要把所有對話都理解為懶惰。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"sharing useful information","meaning":"分享有用資料","examples":[{"en":"Colleagues may stop sharing useful information face to face.","zh":"同事可能停止面對面分享有用資料。"},{"en":"Sharing useful information means giving others helpful facts, updates, or advice.","zh":"sharing useful information 意思是向他人提供有幫助的事實、最新情況或建議。"},{"en":"Workers share useful information when they warn colleagues about a customer issue.","zh":"員工提醒同事某個顧客問題時，就是分享有用資料。"},{"en":"Excessive monitoring may stop useful sharing if people fear being judged.","zh":"如果人們害怕被評判，過度監察可能阻止有用分享。"},{"en":"This phrase shows how surveillance can weaken informal cooperation.","zh":"這個片語顯示監控如何削弱非正式合作。"}],"source":"2023 Q4.pdf","sourcePage":13},{"front":"face to face","meaning":"面對面","examples":[{"en":"Colleagues may stop sharing useful information face to face.","zh":"同事可能停止面對面分享有用資料。"},{"en":"Face to face means directly in person, not through a screen or message.","zh":"face to face 意思是親身直接地，而不是透過螢幕或訊息。"},{"en":"Face-to-face conversations can solve small problems quickly.","zh":"面對面對話可以快速解決小問題。"},{"en":"Monitoring may reduce face-to-face exchange if workers fear being seen as idle.","zh":"如果員工害怕被視為閒散，監察可能減少面對面交流。"},{"en":"This phrase highlights the human side of teamwork.","zh":"這個片語突顯團隊合作的人性一面。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"in the short term","meaning":"短期而言","examples":[{"en":"In the short term, the office may look busy.","zh":"短期而言，辦公室可能看似忙碌。"},{"en":"In the short term means during the near future or for a limited immediate period.","zh":"in the short term 意思是在接近未來或有限的即時期間內。"},{"en":"In the short term, strict monitoring may increase visible activity.","zh":"短期而言，嚴格監察可能增加可見活動。"},{"en":"However, long-term trust may decline if workers feel watched all the time.","zh":"然而，如果員工一直感到被監察，長期信任可能下降。"},{"en":"This phrase contrasts immediate appearance with later effects.","zh":"這個片語把即時外觀與後來影響作對比。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"look busy","meaning":"看似忙碌","examples":[{"en":"The office may look busy without doing meaningful work.","zh":"辦公室可能看似忙碌，卻沒有做有意義的工作。"},{"en":"Look busy means appear active or occupied, even if little useful work is done.","zh":"look busy 意思是看起來活躍或有事做，即使實際上完成很少有用工作。"},{"en":"Employees may look busy by typing unnecessary notes.","zh":"員工可能透過打不必要的筆記來看似忙碌。"},{"en":"A workplace can look busy while creativity and cooperation decline.","zh":"職場可以看似忙碌，同時創意和合作卻下降。"},{"en":"This phrase criticises appearance without real productivity.","zh":"這個片語批評沒有真正生產力的外表。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"in reality","meaning":"事實上","examples":[{"en":"In reality, motivation and cooperation may decline.","zh":"事實上，工作動力和合作可能下降。"},{"en":"In reality means in the actual situation, not just in appearance.","zh":"in reality 意思是在實際情況中，而不只是外表上。"},{"en":"A monitored office may look efficient, but in reality workers may feel anxious.","zh":"被監察的辦公室可能看似有效率，但事實上員工可能感到焦慮。"},{"en":"This phrase contrasts surface appearance with truth.","zh":"這個片語把表面外觀與真相作對比。"},{"en":"It helps the writer expose a hidden problem.","zh":"它幫助作者揭示隱藏問題。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"motivation","meaning":"工作動力","examples":[{"en":"Motivation may decline under constant surveillance.","zh":"在持續監控下，工作動力可能下降。"},{"en":"Motivation means the desire and energy to do work well.","zh":"motivation 指做好工作的意願和能量。"},{"en":"Employees have stronger motivation when they feel trusted and valued.","zh":"當員工感到被信任和被重視時，工作動力較強。"},{"en":"Constant surveillance can reduce motivation by making work feel controlled.","zh":"持續監控可能令工作感覺受控制，從而降低動力。"},{"en":"This phrase names a key part of job satisfaction.","zh":"這個片語指出工作滿意度的一個重要部分。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"cooperation","meaning":"合作","examples":[{"en":"Cooperation may decline when workers feel watched all the time.","zh":"當員工感到無時無刻被監察時，合作可能下降。"},{"en":"Cooperation means working together and helping one another.","zh":"cooperation 意思是一起工作並互相幫助。"},{"en":"Employees need cooperation to solve complex customer or technical problems.","zh":"員工需要合作來解決複雜顧客或技術問題。"},{"en":"If every conversation is monitored, cooperation may become weaker.","zh":"如果每段對話都被監察，合作可能變弱。"},{"en":"This phrase shows that work is social, not only individual.","zh":"這個片語顯示工作是社交性的，不只是個人的。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"problem-solving","meaning":"解難能力","examples":[{"en":"Problem-solving may decline in an over-monitored workplace.","zh":"在過度監察的職場中，解難能力可能下降。"},{"en":"Problem-solving means finding ways to deal with difficulties or improve situations.","zh":"problem-solving 指尋找方法處理困難或改善情況。"},{"en":"Good problem-solving often requires discussion, reflection, and creativity.","zh":"良好解難能力通常需要討論、反思和創意。"},{"en":"Over-monitoring may reduce problem-solving if workers fear trying new ideas.","zh":"如果員工害怕嘗試新想法，過度監察可能降低解難能力。"},{"en":"This phrase shows another cost of excessive surveillance.","zh":"這個片語顯示過度監控的另一項代價。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"job satisfaction will suffer","meaning":"工作滿意度會受損","examples":[{"en":"Job satisfaction will suffer under constant surveillance.","zh":"在持續監控下，工作滿意度會受損。"},{"en":"Job satisfaction will suffer means workers will feel less happy, respected, or fulfilled at work.","zh":"job satisfaction will suffer 意思是員工在工作中會較不快樂、較不被尊重或較少滿足感。"},{"en":"Job satisfaction may suffer if employees feel treated like suspects.","zh":"如果員工覺得自己被當作嫌疑人，工作滿意度可能受損。"},{"en":"Lower satisfaction can lead to weaker loyalty and higher turnover.","zh":"滿意度下降可能導致忠誠減弱和離職率上升。"},{"en":"This phrase predicts a negative effect on employees’ feelings about work.","zh":"這個片語預測對員工工作感受的負面影響。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"constant surveillance","meaning":"持續監控","examples":[{"en":"Constant surveillance increases stress and reduces dignity.","zh":"持續監控增加壓力並降低尊嚴。"},{"en":"Constant surveillance means continuous watching or tracking.","zh":"constant surveillance 指持續不斷的監視或追蹤。"},{"en":"Constant surveillance can make employees feel they have no private breathing space.","zh":"持續監控可以令員工感到沒有私人喘息空間。"},{"en":"It may raise short-term activity but lower long-term trust.","zh":"它可能提高短期活動量，但降低長期信任。"},{"en":"This phrase describes the most extreme and harmful form of monitoring.","zh":"這個片語描述最極端和有害的監察形式。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"increase stress","meaning":"增加壓力","examples":[{"en":"Constant surveillance can increase stress.","zh":"持續監控可以增加壓力。"},{"en":"To increase stress means to make pressure, worry, or tension stronger.","zh":"increase stress 意思是令壓力、憂慮或緊張更強。"},{"en":"Monitoring every click may increase stress during already busy periods.","zh":"在已經繁忙的時期，監察每一下點擊可能增加壓力。"},{"en":"Higher stress can reduce concentration and job satisfaction.","zh":"較高壓力可以降低專注力和工作滿意度。"},{"en":"This phrase identifies one health-related cost of monitoring.","zh":"這個片語指出監察的一項健康相關代價。"}],"source":"2023 Q4.pdf","sourcePage":14},{"front":"reduce dignity","meaning":"降低尊嚴","examples":[{"en":"Constant surveillance can reduce dignity.","zh":"持續監控可以降低尊嚴。"},{"en":"To reduce dignity means to make people feel less respected or less human.","zh":"reduce dignity 意思是令人感到較不被尊重或較不像被當作人看待。"},{"en":"Workers may feel their dignity is reduced if every movement is watched.","zh":"如果每個動作都被監視，員工可能覺得尊嚴被降低。"},{"en":"A fair workplace should protect dignity while expecting accountability.","zh":"公平職場應在要求問責的同時保護尊嚴。"},{"en":"This phrase shows that employee monitoring is also an ethical issue.","zh":"這個片語顯示員工監察也是道德問題。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"at worst","meaning":"最壞情況下","examples":[{"en":"At worst, talented employees may leave for companies with more autonomy.","zh":"最壞情況下，有才能的員工可能離職轉到提供更大自主權的公司。"},{"en":"At worst means in the most serious or negative situation.","zh":"at worst 意思是在最嚴重或最負面的情況下。"},{"en":"At worst, excessive monitoring may drive good workers away.","zh":"最壞情況下，過度監察可能迫使好員工離開。"},{"en":"This phrase introduces the strongest possible consequence.","zh":"這個片語引出最嚴重的可能後果。"},{"en":"It warns employers that over-monitoring can damage the company itself.","zh":"它提醒僱主，過度監察可以損害公司本身。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"talented employees","meaning":"有才能的員工","examples":[{"en":"Talented employees may leave if monitoring becomes excessive.","zh":"如果監察變得過度，有才能的員工可能離開。"},{"en":"Talented employees are workers with strong skills, judgement, creativity, or experience.","zh":"talented employees 指擁有強技能、判斷力、創意或經驗的員工。"},{"en":"Talented employees often value trust and room to make decisions.","zh":"有才能的員工通常重視信任和決策空間。"},{"en":"If they feel controlled all the time, they may choose another company.","zh":"如果他們一直感到受控制，可能會選擇另一間公司。"},{"en":"This phrase shows that over-monitoring can make companies lose valuable people.","zh":"這個片語顯示過度監察可以令公司失去寶貴人才。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"leave for companies that","meaning":"離職轉到……的公司","examples":[{"en":"Talented employees may leave for companies that offer more autonomy.","zh":"有才能的員工可能離職轉到提供更大自主權的公司。"},{"en":"Leave for companies that means resign and move to organisations with certain qualities.","zh":"leave for companies that 意思是辭職並轉到具有某些特質的機構。"},{"en":"Workers may leave for companies that trust employees more.","zh":"員工可能離職轉到更信任員工的公司。"},{"en":"If monitoring becomes too strict, employees may leave for companies with better culture.","zh":"如果監察變得太嚴格，員工可能離職轉到文化更好的公司。"},{"en":"This phrase describes how workers respond to poor workplace conditions.","zh":"這個片語描述員工如何回應差劣職場條件。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"offer more autonomy","meaning":"提供更大自主權","examples":[{"en":"Some companies offer more autonomy to employees.","zh":"有些公司向員工提供更大自主權。"},{"en":"To offer more autonomy means to give workers more freedom to decide how to do their work.","zh":"offer more autonomy 意思是給員工更多自由決定如何工作。"},{"en":"A company may offer more autonomy by focusing on results rather than screen time.","zh":"公司可透過專注成果而不是螢幕時間來提供更大自主權。"},{"en":"Employees with autonomy may feel more trusted and motivated.","zh":"擁有自主權的員工可能感到更被信任和更有動力。"},{"en":"This phrase names one workplace quality that attracts talent.","zh":"這個片語指出吸引人才的一項職場質素。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"autonomy","meaning":"自主權","examples":[{"en":"Workers often value autonomy.","zh":"員工通常重視自主權。"},{"en":"Autonomy means freedom to make choices and manage one’s own work responsibly.","zh":"autonomy 指有自由作選擇並負責任地管理自己工作。"},{"en":"Autonomy allows employees to decide when to think, discuss, or focus deeply.","zh":"自主權讓員工決定何時思考、討論或深入專注。"},{"en":"Too much monitoring can reduce autonomy and dignity.","zh":"過多監察可以降低自主權和尊嚴。"},{"en":"This phrase is central to the argument against excessive surveillance.","zh":"這個片語是反對過度監控論點的核心。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"productivity theatre","meaning":"生產力劇場；假裝高效","examples":[{"en":"False busyness is not productivity; it is productivity theatre.","zh":"虛假的忙碌不是生產力；而是生產力劇場。"},{"en":"Productivity theatre means acting busy so that work appears productive without real achievement.","zh":"productivity theatre 指假裝忙碌，使工作看似有生產力，卻沒有真正成就。"},{"en":"Keeping screens active without completing tasks is productivity theatre.","zh":"讓螢幕保持運作但沒有完成任務，就是生產力劇場。"},{"en":"Monitoring may encourage productivity theatre when it rewards visible activity.","zh":"當監察獎勵可見活動時，可能鼓勵生產力劇場。"},{"en":"This phrase sharply criticises fake efficiency.","zh":"這個片語尖銳批評虛假效率。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"in conclusion","meaning":"總結而言","examples":[{"en":"In conclusion, employee monitoring is neither wholly good nor wholly bad.","zh":"總結而言，員工監察既非完全好，也非完全壞。"},{"en":"In conclusion introduces the final summary or judgement.","zh":"in conclusion 用來引出最後總結或判斷。"},{"en":"In conclusion, monitoring should be limited, transparent, and fair.","zh":"總結而言，監察應有限度、透明和公平。"},{"en":"This phrase helps readers know the essay is ending.","zh":"這個片語幫助讀者知道文章即將結束。"},{"en":"It is common in formal essays and speeches.","zh":"它常見於正式文章和演講。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"neither wholly good nor wholly bad","meaning":"既非完全好，也非完全壞","examples":[{"en":"Employee monitoring is neither wholly good nor wholly bad.","zh":"員工監察既非完全好，也非完全壞。"},{"en":"Neither wholly good nor wholly bad means not completely positive and not completely negative.","zh":"neither wholly good nor wholly bad 意思是不是完全正面，也不是完全負面。"},{"en":"Technology in schools is neither wholly good nor wholly bad.","zh":"學校科技既非完全好，也非完全壞。"},{"en":"Employee monitoring depends on purpose, limits, and fairness.","zh":"員工監察取決於目的、限制和公平性。"},{"en":"This phrase supports a balanced conclusion.","zh":"這個片語支持平衡結論。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"used with a clear purpose","meaning":"帶着清晰目的使用","examples":[{"en":"Used with a clear purpose, monitoring can support productivity and fairness.","zh":"帶着清晰目的使用時，監察可以支持生產力和公平。"},{"en":"Used with a clear purpose means applied for a specific, explained, and reasonable reason.","zh":"used with a clear purpose 意思是基於具體、已解釋和合理的原因使用。"},{"en":"Monitoring used with a clear purpose focuses on safety or training, not curiosity.","zh":"帶着清晰目的使用的監察會集中於安全或培訓，而不是好奇。"},{"en":"Employees may accept monitoring more easily when its purpose is clear.","zh":"當目的清晰時，員工可能較容易接受監察。"},{"en":"This phrase describes responsible use of workplace data.","zh":"這個片語描述負責任地使用職場數據。"}],"source":"2023 Q4.pdf","sourcePage":15},{"front":"preventing serious misconduct","meaning":"防止嚴重不當行為","examples":[{"en":"Monitoring can help prevent serious misconduct.","zh":"監察可以幫助防止嚴重不當行為。"},{"en":"Preventing serious misconduct means stopping major wrongdoing before it happens.","zh":"preventing serious misconduct 意思是在重大錯誤行為發生前阻止它。"},{"en":"Monitoring may help prevent serious misconduct such as theft or data misuse.","zh":"監察可能幫助防止盜竊或濫用資料等嚴重不當行為。"},{"en":"This purpose is stronger than simply tracking every small pause.","zh":"這個目的比單純追蹤每個小停頓更有力。"},{"en":"This phrase gives a legitimate reason for limited monitoring.","zh":"這個片語提供有限度監察的合理理由。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"improving training","meaning":"改善培訓","examples":[{"en":"Monitoring can support productivity by improving training.","zh":"監察可以透過改善培訓來支持生產力。"},{"en":"Improving training means making teaching or workplace instruction better.","zh":"improving training 意思是令教學或職場指導變得更好。"},{"en":"Call records can improve training by showing where staff need support.","zh":"通話記錄可以透過顯示職員需要甚麼支援來改善培訓。"},{"en":"Monitoring data should be used to improve training, not only punish mistakes.","zh":"監察數據應用於改善培訓，而不只是懲罰錯誤。"},{"en":"This phrase describes a constructive use of monitoring.","zh":"這個片語描述監察的建設性用途。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"support productivity and fairness","meaning":"支持生產力和公平","examples":[{"en":"Limited monitoring can support productivity and fairness.","zh":"有限度的監察可以支持生產力和公平。"},{"en":"To support productivity and fairness means to help work become effective and just.","zh":"support productivity and fairness 意思是幫助工作變得有效而公正。"},{"en":"Data can support productivity and fairness when it identifies delays without personal bias.","zh":"當數據在沒有個人偏見下找出延誤時，可以支持生產力和公平。"},{"en":"Monitoring should support fairness for both managers and employees.","zh":"監察應支持經理和員工雙方的公平。"},{"en":"This phrase summarises what good monitoring should achieve.","zh":"這個片語總結良好監察應達成甚麼。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"used excessively","meaning":"過度使用時","examples":[{"en":"Used excessively, monitoring weakens trust.","zh":"過度使用時，監察會削弱信任。"},{"en":"Used excessively means applied too much or beyond a reasonable limit.","zh":"used excessively 意思是使用太多或超出合理限度。"},{"en":"Monitoring used excessively can make workers feel like suspects.","zh":"過度使用的監察可以令員工覺得自己像嫌疑人。"},{"en":"Even useful tools become harmful when used excessively.","zh":"即使有用工具，在過度使用時也會變得有害。"},{"en":"This phrase marks the danger of going too far.","zh":"這個片語指出走得太遠的危險。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"weaken trust","meaning":"削弱信任","examples":[{"en":"Excessive monitoring weakens trust.","zh":"過度監察會削弱信任。"},{"en":"To weaken trust means to make people less confident in one another’s honesty or goodwill.","zh":"weaken trust 意思是令人較不相信彼此的誠實或善意。"},{"en":"Secret tracking can weaken trust between employees and managers.","zh":"秘密追蹤可以削弱員工與經理之間的信任。"},{"en":"Trust weakens when workers feel every action is treated with suspicion.","zh":"當員工覺得每個行動都被懷疑時，信任會削弱。"},{"en":"This phrase describes the central emotional harm of surveillance.","zh":"這個片語描述監控的核心情感傷害。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"lower job satisfaction","meaning":"降低工作滿意度","examples":[{"en":"Excessive monitoring lowers job satisfaction.","zh":"過度監察會降低工作滿意度。"},{"en":"To lower job satisfaction means to reduce how happy and fulfilled employees feel at work.","zh":"lower job satisfaction 意思是減少員工在工作中的快樂和滿足感。"},{"en":"Constant tracking may lower job satisfaction by reducing autonomy.","zh":"持續追蹤可能透過降低自主權來降低工作滿意度。"},{"en":"Lower job satisfaction can make talented workers leave.","zh":"工作滿意度降低可能令有才能的員工離開。"},{"en":"This phrase links monitoring with employee wellbeing.","zh":"這個片語把監察與員工福祉連接起來。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"shallow performance","meaning":"表面化表現","examples":[{"en":"Excessive monitoring encourages shallow performance.","zh":"過度監察鼓勵表面化表現。"},{"en":"Shallow performance means surface-level behaviour that looks good but lacks real value.","zh":"shallow performance 指看起來好但缺乏真正價值的表面行為。"},{"en":"Typing unnecessary notes can be shallow performance.","zh":"打不必要的筆記可以是表面化表現。"},{"en":"Monitoring encourages shallow performance when it rewards activity rather than achievement.","zh":"當監察獎勵活動量而不是成就時，便會鼓勵表面化表現。"},{"en":"This phrase criticises fake productivity.","zh":"這個片語批評虛假生產力。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"genuine achievement","meaning":"真正成就","examples":[{"en":"Employers should encourage genuine achievement rather than shallow performance.","zh":"僱主應鼓勵真正成就，而不是表面化表現。"},{"en":"Genuine achievement means real success or meaningful progress, not just appearance.","zh":"genuine achievement 指真正成功或有意義的進展，而不只是外表。"},{"en":"Solving a difficult customer issue is genuine achievement.","zh":"解決困難顧客問題是真正成就。"},{"en":"Genuine achievement may require quiet thinking, cooperation, and creativity.","zh":"真正成就可能需要安靜思考、合作和創意。"},{"en":"This phrase describes what workplaces should reward.","zh":"這個片語描述職場應獎勵甚麼。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"explain what is being monitored","meaning":"解釋正在監察甚麼","examples":[{"en":"Employers should explain what is being monitored and why.","zh":"僱主應解釋正在監察甚麼和原因。"},{"en":"To explain what is being monitored means to tell employees clearly what data or behaviour is being checked.","zh":"explain what is being monitored 意思是清楚告訴員工哪些數據或行為被檢查。"},{"en":"Employers should explain whether emails, websites, or call records are monitored.","zh":"僱主應解釋是否監察電郵、網站或通話記錄。"},{"en":"Clear explanation helps reduce fear and misunderstanding.","zh":"清晰解釋有助減少恐懼和誤解。"},{"en":"This phrase supports transparency in workplace monitoring.","zh":"這個片語支持職場監察中的透明度。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"collect only necessary data","meaning":"只收集必要數據","examples":[{"en":"Employers should collect only necessary data.","zh":"僱主應只收集必要數據。"},{"en":"To collect only necessary data means to gather only information that is truly needed for a fair purpose.","zh":"collect only necessary data 意思是只收集真正為公平目的所需的資料。"},{"en":"A company may need log-in records but not private personal messages.","zh":"公司可能需要登入記錄，但不需要私人個人訊息。"},{"en":"Collecting only necessary data protects privacy and trust.","zh":"只收集必要數據可以保護私隱和信任。"},{"en":"This phrase describes a key safeguard against excessive monitoring.","zh":"這個片語描述防止過度監察的重要保障措施。"}],"source":"2023 Q4.pdf","sourcePage":16},{"front":"challenge unfair conclusions","meaning":"挑戰不公平結論","examples":[{"en":"Employees should be allowed to challenge unfair conclusions.","zh":"員工應獲准挑戰不公平結論。"},{"en":"To challenge unfair conclusions means to question decisions or judgements that seem wrong or unjust.","zh":"challenge unfair conclusions 意思是質疑看似錯誤或不公正的決定或判斷。"},{"en":"A worker should be able to challenge a warning based on incomplete data.","zh":"員工應能挑戰基於不完整數據作出的警告。"},{"en":"Allowing challenges prevents monitoring from becoming one-sided.","zh":"容許挑戰可以防止監察變成單方面制度。"},{"en":"This phrase protects employees from mistaken interpretation.","zh":"這個片語保護員工免受錯誤解讀影響。"}],"source":"2023 Q4.pdf","sourcePage":17},{"front":"reasonable accountability","meaning":"合理問責","examples":[{"en":"Employees should accept reasonable accountability.","zh":"員工應接受合理問責。"},{"en":"Reasonable accountability means fair responsibility for one’s actions and work results.","zh":"reasonable accountability 指對自己的行動和工作結果承擔公平責任。"},{"en":"Workers can accept reasonable accountability when standards are clear.","zh":"當標準清晰時，員工可以接受合理問責。"},{"en":"Accountability is reasonable when it is based on evidence, not suspicion.","zh":"當問責基於證據而不是懷疑時，就是合理的。"},{"en":"This phrase balances employee dignity with workplace responsibility.","zh":"這個片語平衡員工尊嚴和職場責任。"}],"source":"2023 Q4.pdf","sourcePage":17},{"front":"defend their dignity","meaning":"捍衛自己的尊嚴","examples":[{"en":"Employees should defend their dignity while accepting accountability.","zh":"員工應在接受問責的同時捍衛自己的尊嚴。"},{"en":"To defend their dignity means to protect their right to be treated with respect.","zh":"defend their dignity 意思是保護自己被尊重對待的權利。"},{"en":"Workers can accept feedback while still defending their dignity.","zh":"員工可以接受回饋，同時仍捍衛自己的尊嚴。"},{"en":"Defending dignity means rejecting unfair or humiliating surveillance.","zh":"捍衛尊嚴意思是拒絕不公平或羞辱性的監控。"},{"en":"This phrase shows that accountability should not require self-disrespect.","zh":"這個片語顯示問責不應要求人不尊重自己。"}],"source":"2023 Q4.pdf","sourcePage":17},{"front":"the best workplace","meaning":"最理想的職場","examples":[{"en":"The best workplace balances trust and responsibility.","zh":"最理想的職場會平衡信任和責任。"},{"en":"The best workplace means the ideal working environment.","zh":"the best workplace 意思是理想的工作環境。"},{"en":"The best workplace gives employees freedom while keeping clear standards.","zh":"最理想的職場給員工自由，同時保持清晰標準。"},{"en":"A strong workplace trusts workers but also protects fairness and safety.","zh":"強大的職場信任員工，也保護公平和安全。"},{"en":"This phrase introduces the writer’s final ideal.","zh":"這個片語引出作者最後的理想。"}],"source":"2023 Q4.pdf","sourcePage":17},{"front":"not one where…, nor one where…","meaning":"不是……也不是……","examples":[{"en":"The best workplace is not one where nobody is watched, nor one where everyone is watched all the time.","zh":"最理想的職場不是沒有人被監察，也不是每個人都無時無刻被監察。"},{"en":"This structure rejects two extremes at the same time.","zh":"這個句式同時拒絕兩個極端。"},{"en":"A fair school is not one where there are no rules, nor one where students are controlled every second.","zh":"公平學校不是沒有規則，也不是學生每秒都被控制。"},{"en":"The phrase helps the writer argue for balance instead of extremes.","zh":"這個片語幫助作者主張平衡，而不是極端。"},{"en":"It is useful in conclusions that seek a middle position.","zh":"它適用於尋求中間立場的結論。"}],"source":"2023 Q4.pdf","sourcePage":17},{"front":"watched all the time","meaning":"無時無刻被監察","examples":[{"en":"Employees should not be watched all the time.","zh":"員工不應無時無刻被監察。"},{"en":"Watched all the time means monitored continuously without real breaks.","zh":"watched all the time 意思是持續被監察，沒有真正間斷。"},{"en":"Workers who are watched all the time may feel anxious and distrusted.","zh":"無時無刻被監察的員工可能感到焦慮和不被信任。"},{"en":"No one can do creative work well if they feel watched every second.","zh":"如果感覺每秒都被看着，沒有人能好好做創意工作。"},{"en":"This phrase describes excessive surveillance in simple words.","zh":"這個片語用簡單文字描述過度監控。"}],"source":"2023 Q4.pdf","sourcePage":17},{"front":"watch over each other","meaning":"互相守護","examples":[{"en":"Trust and responsibility should watch over each other.","zh":"信任和責任應互相守護。"},{"en":"To watch over each other means to balance, protect, and limit one another.","zh":"watch over each other 意思是彼此平衡、保護和限制。"},{"en":"Trust watches over responsibility by preventing harsh control.","zh":"信任透過防止嚴厲控制來守護責任。"},{"en":"Responsibility watches over trust by preventing careless misuse of freedom.","zh":"責任透過防止草率濫用自由來守護信任。"},{"en":"This phrase gives the essay a balanced and memorable ending.","zh":"這個片語為文章帶來平衡而令人記得的結尾。"}],"source":"2023 Q4.pdf","sourcePage":17}],"dse/writing/part-b/2023/Q5":[{"front":"the wisdom behind","meaning":"……背後的智慧","examples":[{"en":"The essay explores the wisdom behind “Once Upon a Time.”","zh":"這篇文章探討「從前」背後的智慧。"},{"en":"The wisdom behind something means the deeper lesson or meaning hidden inside it.","zh":"……背後的智慧，是指隱藏在某事之中的更深層教訓或意思。"},{"en":"A teacher may ask students to find the wisdom behind an old story.","zh":"老師可能要求學生找出一個古老故事背後的智慧。"},{"en":"Looking for the wisdom behind a tale helps readers understand why it still matters.","zh":"尋找故事背後的智慧，能幫助讀者明白它為何至今仍重要。"},{"en":"This phrase shows that simple words can carry serious lessons.","zh":"這個短語顯示簡單說話也可以承載深刻教訓。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"Once Upon a Time","meaning":"從前；很久很久以前","examples":[{"en":"“Once Upon a Time” reminds readers of fairy tales and fables.","zh":"「從前」令人想起童話和寓言。"},{"en":"Once Upon a Time is a traditional opening used to begin old stories or fairy tales.","zh":"「從前」是開始古老故事或童話時使用的傳統開場白。"},{"en":"Children often hear “Once Upon a Time” before a story about magic, danger, or kindness.","zh":"小朋友常在聽到關於魔法、危險或善意的故事前，聽見「從前」。"},{"en":"This phrase prepares readers to enter an imaginary world with real lessons.","zh":"這個短語讓讀者準備進入一個有真實教訓的想像世界。"},{"en":"It creates a feeling of memory, wonder, and storytelling.","zh":"它營造回憶、驚奇和講故事的感覺。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"illustration","meaning":"插圖","examples":[{"en":"The writer looks at the illustration of children and animals in a forest.","zh":"作者看着一幅小朋友和動物在森林裏的插圖。"},{"en":"An illustration is a picture used to explain, decorate, or support a story or idea.","zh":"插圖是用來解釋、裝飾或支援故事或想法的圖畫。"},{"en":"A storybook illustration may show a child walking through a dark forest.","zh":"故事書插圖可能展示孩子走過黑暗森林。"},{"en":"Illustrations help young readers imagine characters, places, and emotions more clearly.","zh":"插圖幫助年輕讀者更清楚想像角色、地方和情感。"},{"en":"This word connects visual art with reading and meaning.","zh":"這個詞把視覺藝術與閱讀和意思連接起來。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"children and animals","meaning":"小朋友和動物","examples":[{"en":"The illustration shows children and animals in a forest.","zh":"插圖顯示小朋友和動物在森林裏。"},{"en":"Children and animals often appear together in stories to suggest innocence, friendship, and wonder.","zh":"小朋友和動物常在故事中一起出現，象徵純真、友誼和驚奇。"},{"en":"A picture of children and animals can make a forest scene feel gentle and magical.","zh":"小朋友和動物的圖畫可以令森林場景感覺溫柔而有魔法。"},{"en":"These figures help readers enter a world where humans and nature communicate.","zh":"這些形象幫助讀者進入人類和自然能溝通的世界。"},{"en":"This phrase gives the scene warmth and imagination.","zh":"這個短語為場景帶來溫暖和想像力。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"in a forest","meaning":"在森林裏","examples":[{"en":"The illustration shows a magical scene in a forest.","zh":"插圖展示一個在森林裏的魔法場景。"},{"en":"In a forest means inside or among many trees in a natural place.","zh":"在森林裏是指在一個有很多樹木的自然地方之中。"},{"en":"Many fairy tales begin in a forest because it feels mysterious and unknown.","zh":"許多童話從森林開始，因為森林感覺神秘而未知。"},{"en":"A forest can make characters feel lost, tested, or protected by nature.","zh":"森林可以令角色感到迷失、受考驗，或被自然保護。"},{"en":"This phrase gives the story a setting full of danger and discovery.","zh":"這個短語給故事一個充滿危險和發現的背景。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"more than a scene","meaning":"不只是一個場景","examples":[{"en":"When the writer looks at the illustration, he sees more than a scene.","zh":"當作者看着插圖時，他看見的不只是一個場景。"},{"en":"More than a scene means something has deeper meaning beyond what is shown visually.","zh":"不只是一個場景，是指某物除了畫面所見之外，還有更深層意思。"},{"en":"A picture of a family dinner may be more than a scene if it shows love and tension.","zh":"一幅家庭晚餐圖如果顯示愛與緊張，就不只是一個場景。"},{"en":"Seeing more than a scene helps readers think about symbols and lessons.","zh":"看見不只是場景，能幫助讀者思考象徵和教訓。"},{"en":"This phrase suggests that images can carry hidden meaning.","zh":"這個短語表示圖像可以承載隱藏意思。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"a world where","meaning":"一個……的世界","examples":[{"en":"The writer sees a world where the weak are heard.","zh":"作者看見一個弱者被聽見的世界。"},{"en":"A world where introduces an imagined place or situation with a special quality.","zh":"一個……的世界，用來引出具有某種特質的想像地方或情況。"},{"en":"Children may dream of a world where everyone is treated kindly.","zh":"小朋友可能夢想一個人人都被善待的世界。"},{"en":"Writers use this phrase to describe the values of an imaginary setting.","zh":"作者使用這個短語來描述想像背景中的價值觀。"},{"en":"It helps readers understand what kind of society the story presents.","zh":"它幫助讀者理解故事呈現的是怎樣的社會。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"the weak are heard","meaning":"弱者被聽見","examples":[{"en":"In fairy tales, the weak are heard.","zh":"在童話中，弱者被聽見。"},{"en":"The weak are heard means people with little power are listened to and taken seriously.","zh":"弱者被聽見，是指權力較少的人得到聆聽和認真看待。"},{"en":"A quiet student is heard when classmates stop and ask what she thinks.","zh":"當同學停下來問安靜學生的想法時，她就是被聽見。"},{"en":"Stories where the weak are heard give hope to readers who feel small.","zh":"弱者被聽見的故事，給感到渺小的讀者希望。"},{"en":"This phrase shows fairness toward people who are usually ignored.","zh":"這個短語顯示對通常被忽視者的公平。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"the lonely are loved","meaning":"孤獨的人被愛","examples":[{"en":"The lonely are loved in the world of fairy tales.","zh":"在童話世界裏，孤獨的人被愛。"},{"en":"The lonely are loved means people who feel isolated still receive care and belonging.","zh":"孤獨的人被愛，是指感到孤立的人仍得到關懷和歸屬感。"},{"en":"A new student feels loved when classmates invite him to sit with them.","zh":"當同學邀請新同學一起坐時，他會感到被愛。"},{"en":"Fairy tales often comfort readers by showing that loneliness is not permanent.","zh":"童話常透過顯示孤獨不是永久的，來安慰讀者。"},{"en":"This phrase gives emotional hope to people who feel unseen.","zh":"這個短語給感到不被看見的人情感上的希望。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"the frightened learn to walk on","meaning":"受驚的人學會繼續前行","examples":[{"en":"The frightened learn to walk on.","zh":"受驚的人學會繼續前行。"},{"en":"The frightened learn to walk on means scared people learn to continue despite fear.","zh":"受驚的人學會繼續前行，是指害怕的人學會即使恐懼仍繼續走下去。"},{"en":"A child afraid of a new school learns to walk on by going in one day at a time.","zh":"害怕新學校的孩子透過一天一天地上學，學會繼續前行。"},{"en":"This phrase shows that courage can grow slowly through action.","zh":"這個短語顯示勇氣可以透過行動慢慢成長。"},{"en":"It suggests that fear does not have to stop the journey.","zh":"它表示恐懼不必阻止旅程。"}],"source":"2023 Q5.pdf","sourcePage":1},{"front":"in an age of","meaning":"在……的時代","examples":[{"en":"In an age of examinations and social comparison, fairy tales may seem childish.","zh":"在考試和社會比較的時代，童話可能看似幼稚。"},{"en":"In an age of means during a time strongly shaped by a particular condition or concern.","zh":"在……的時代，是指在一個深受某種情況或關注影響的時期。"},{"en":"In an age of smartphones, many students read stories on screens.","zh":"在智能電話的時代，許多學生在螢幕上閱讀故事。"},{"en":"This phrase connects an idea with the wider society around it.","zh":"這個短語把一個想法與周圍更大的社會連接起來。"},{"en":"It helps explain why old stories may be viewed differently today.","zh":"它幫助解釋為何古老故事今天可能被不同看待。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"examinations","meaning":"考試","examples":[{"en":"Students live in an age of examinations.","zh":"學生活在考試的時代。"},{"en":"Examinations are formal tests used to measure knowledge, skills, or progress.","zh":"考試是用來衡量知識、技能或進步的正式測驗。"},{"en":"Students may feel pressure when examinations affect school places or future choices.","zh":"當考試影響學位或未來選擇時，學生可能感到壓力。"},{"en":"Too much focus on examinations can make reading feel only useful for marks.","zh":"過度專注考試可能令閱讀只被視為為分數服務。"},{"en":"This word represents academic pressure in student life.","zh":"這個詞代表學生生活中的學業壓力。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"social comparison","meaning":"社會比較","examples":[{"en":"Social comparison can make young people feel pressured.","zh":"社會比較會令年輕人感到壓力。"},{"en":"Social comparison means judging oneself by comparing with other people’s success, appearance, or life.","zh":"社會比較是指透過與別人的成功、外貌或生活比較來評價自己。"},{"en":"A student may feel unhappy because social comparison makes classmates’ results seem more important than personal growth.","zh":"學生可能感到不快，因為社會比較令同學成績看似比個人成長更重要。"},{"en":"Social comparison becomes harmful when it turns life into a competition.","zh":"當社會比較把生活變成競賽時，它就會變得有害。"},{"en":"This phrase explains one reason young people may lose confidence.","zh":"這個短語解釋年輕人可能失去信心的其中一個原因。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"may seem childish","meaning":"可能看似幼稚","examples":[{"en":"Fairy tales and fables may seem childish.","zh":"童話和寓言可能看似幼稚。"},{"en":"May seem childish means may appear too simple, young, or immature at first.","zh":"可能看似幼稚，是指起初可能顯得太簡單、年幼或不成熟。"},{"en":"A picture book may seem childish, but it can teach adults about kindness.","zh":"圖畫書可能看似幼稚，但可以教成年人善良。"},{"en":"Stories that seem childish can still carry deep moral questions.","zh":"看似幼稚的故事仍可以承載深刻道德問題。"},{"en":"This phrase shows the difference between first impression and deeper value.","zh":"這個短語顯示第一印象與深層價值之間的差別。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"fairy tales and fables","meaning":"童話和寓言","examples":[{"en":"Fairy tales and fables have taught the writer important lessons.","zh":"童話和寓言教會作者重要道理。"},{"en":"Fairy tales and fables are traditional stories that often teach moral lessons through magic, animals, or simple plots.","zh":"童話和寓言是傳統故事，常透過魔法、動物或簡單情節教導道德課題。"},{"en":"Cinderella is a fairy tale, while The Tortoise and the Hare is a fable.","zh":"《灰姑娘》是童話，而《龜兔賽跑》是寓言。"},{"en":"These stories help readers understand love, courage, patience, and fairness.","zh":"這些故事幫助讀者理解愛、勇氣、耐性和公平。"},{"en":"This phrase refers to old stories that are simple in form but rich in meaning.","zh":"這個短語指形式簡單但意義豐富的古老故事。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"young readers","meaning":"年輕讀者","examples":[{"en":"These stories have guided young readers.","zh":"這些故事一直引導年輕讀者。"},{"en":"Young readers are children or teenagers who are reading and learning from texts.","zh":"年輕讀者是正在閱讀並從文本中學習的兒童或青少年。"},{"en":"Young readers may understand difficult emotions through simple stories.","zh":"年輕讀者可以透過簡單故事理解困難情感。"},{"en":"Stories guide young readers by giving them examples of courage and kindness.","zh":"故事透過提供勇氣和善良的例子來引導年輕讀者。"},{"en":"This phrase focuses on the people who are still developing values and judgement.","zh":"這個短語著重仍在發展價值觀和判斷力的人。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"not merely for entertainment","meaning":"不只是為了娛樂","examples":[{"en":"These stories make young readers read not merely for entertainment.","zh":"這些故事令年輕讀者閱讀不只是為了娛樂。"},{"en":"Not merely for entertainment means not only for fun or enjoyment.","zh":"不只是為了娛樂，是指不僅為了有趣或享受。"},{"en":"Students may read a fable not merely for entertainment but to learn patience.","zh":"學生讀寓言可能不只是為了娛樂，而是為了學習耐性。"},{"en":"A story becomes more valuable when it entertains and teaches at the same time.","zh":"當故事同時娛樂和教導人時，它會變得更有價值。"},{"en":"This phrase prepares readers for a deeper purpose beyond amusement.","zh":"這個短語為娛樂以外的更深目的作鋪墊。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"but for guidance","meaning":"而是為了得到指引","examples":[{"en":"Young readers read these stories for guidance.","zh":"年輕讀者閱讀這些故事，是為了得到指引。"},{"en":"But for guidance means instead for advice, direction, or moral help.","zh":"而是為了得到指引，是指相反地，是為了得到建議、方向或道德幫助。"},{"en":"A child may read a story for guidance when facing fear or jealousy.","zh":"孩子面對恐懼或嫉妒時，可能閱讀故事來得到指引。"},{"en":"Stories guide readers by showing what choices lead to kindness or harm.","zh":"故事透過展示哪些選擇帶來善意或傷害來引導讀者。"},{"en":"This phrase explains the serious purpose of seemingly simple tales.","zh":"這個短語解釋看似簡單故事的嚴肅目的。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"from my perspective","meaning":"從我的角度來看","examples":[{"en":"From my perspective, these stories teach love, forgiveness and happiness.","zh":"從我的角度來看，這些故事教導愛、寬恕和幸福。"},{"en":"From my perspective means from my point of view or according to how I understand it.","zh":"從我的角度來看，是指以我的看法或理解來說。"},{"en":"From my perspective, fairy tales are not childish because they teach moral courage.","zh":"從我的角度來看，童話並不幼稚，因為它們教導道德勇氣。"},{"en":"Writers use this phrase to introduce a personal opinion politely.","zh":"作者使用這個短語禮貌地引出個人意見。"},{"en":"It helps make the essay sound reflective rather than absolute.","zh":"它幫助文章聽起來有反思，而不是絕對武斷。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"taught me that","meaning":"教曉我","examples":[{"en":"These stories have taught me that love begins with understanding.","zh":"這些故事教曉我，愛始於理解。"},{"en":"Taught me that means helped me learn or realise a particular lesson.","zh":"教曉我是指幫助我學會或明白某個道理。"},{"en":"My grandmother’s stories taught me that patience can be stronger than anger.","zh":"祖母的故事教曉我，耐性可以比憤怒更有力量。"},{"en":"A story teaches us when its meaning changes how we think or act.","zh":"當故事的意思改變我們的思想或行動時，它就是在教導我們。"},{"en":"This phrase links reading with personal growth.","zh":"這個短語把閱讀與個人成長連接起來。"}],"source":"2023 Q5.pdf","sourcePage":2},{"front":"begins with understanding","meaning":"始於理解","examples":[{"en":"Love begins with understanding.","zh":"愛始於理解。"},{"en":"Begins with understanding means starts when people try to see another person’s feelings and reasons.","zh":"始於理解，是指當人們嘗試看見別人的感受和原因時，某事才開始。"},{"en":"Friendship begins with understanding when classmates listen before judging.","zh":"當同學先聆聽再判斷時，友誼就始於理解。"},{"en":"Without understanding, love can become selfish or shallow.","zh":"沒有理解，愛可能變得自私或膚淺。"},{"en":"This phrase suggests that care must start with attention to others.","zh":"這個短語表示關心必須由留意他人開始。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"conflict can be survived through forgiveness","meaning":"衝突可以透過寬恕渡過","examples":[{"en":"Conflict can be survived through forgiveness.","zh":"衝突可以透過寬恕渡過。"},{"en":"Conflict can be survived through forgiveness means relationships can continue when people choose not to hold onto anger forever.","zh":"衝突可以透過寬恕渡過，是指當人選擇不永遠抓住憤怒時，關係可以繼續。"},{"en":"Friends can survive an argument through forgiveness if both admit their mistakes.","zh":"如果朋友雙方都承認錯誤，他們可以透過寬恕渡過爭吵。"},{"en":"Forgiveness helps conflict become a lesson rather than a permanent wound.","zh":"寬恕幫助衝突變成教訓，而不是永久傷口。"},{"en":"This phrase shows that disagreement does not have to destroy love.","zh":"這個短語顯示分歧不一定會摧毀愛。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"real happiness","meaning":"真正的幸福","examples":[{"en":"Real happiness is built on character rather than luck.","zh":"真正的幸福建基於品格，而不是運氣。"},{"en":"Real happiness means deep and lasting joy, not only excitement or success.","zh":"真正的幸福是深層而持久的快樂，而不只是興奮或成功。"},{"en":"A person may find real happiness by living honestly and caring for others.","zh":"一個人可以透過誠實生活和關心別人找到真正幸福。"},{"en":"Real happiness lasts longer when it grows from kindness, courage, and gratitude.","zh":"當真正幸福來自善良、勇氣和感恩時，它會更持久。"},{"en":"This phrase separates true fulfilment from temporary pleasure.","zh":"這個短語把真正滿足與短暫快樂分開。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"built on character rather than luck","meaning":"建基於品格而非運氣","examples":[{"en":"Real happiness is built on character rather than luck.","zh":"真正的幸福建基於品格而非運氣。"},{"en":"Built on character rather than luck means based on moral qualities, not accidental good fortune.","zh":"建基於品格而非運氣，是指以道德品質為基礎，而不是偶然的好運。"},{"en":"A student’s success is stronger when it is built on discipline rather than luck.","zh":"當學生的成功建基於紀律而非運氣時，會更穩固。"},{"en":"Happiness based only on luck can disappear quickly when circumstances change.","zh":"只建基於運氣的幸福，可能在環境改變時很快消失。"},{"en":"This phrase teaches that who we are matters more than what happens to us.","zh":"這個短語教導我們，我們是怎樣的人比發生甚麼事更重要。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"glittering prize","meaning":"閃閃發光的獎品","examples":[{"en":"Love is not a glittering prize won by beauty.","zh":"愛不是靠美貌贏得的閃閃發光的獎品。"},{"en":"A glittering prize is something attractive that seems like a reward to be won.","zh":"閃閃發光的獎品是看起來吸引、像可被贏取的獎賞。"},{"en":"Some stories make wealth look like a glittering prize, but wisdom matters more.","zh":"有些故事令財富看似閃閃發光的獎品，但智慧更重要。"},{"en":"Calling love a glittering prize would make it seem shallow and competitive.","zh":"把愛稱為閃閃發光的獎品，會令愛看似膚淺而具競爭性。"},{"en":"This phrase criticises the idea that love is merely a reward for appearance.","zh":"這個短語批評把愛只看成外貌獎賞的想法。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"won by beauty, wealth or charm","meaning":"靠美貌、財富或魅力贏得","examples":[{"en":"Love is not won by beauty, wealth or charm.","zh":"愛不是靠美貌、財富或魅力贏得。"},{"en":"Won by beauty, wealth or charm means gained because of appearance, money, or pleasant personality alone.","zh":"靠美貌、財富或魅力贏得，是指只因外貌、金錢或討人喜歡的性格而得到。"},{"en":"True friendship is not won by beauty or wealth but by trust and care.","zh":"真正友誼不是靠美貌或財富贏得，而是靠信任和關懷。"},{"en":"If love is won only by charm, it may not survive hardship.","zh":"如果愛只靠魅力贏得，它未必能渡過困難。"},{"en":"This phrase rejects a shallow view of relationships.","zh":"這個短語否定對關係的膚淺看法。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"a form of patient attention","meaning":"一種耐心的關注","examples":[{"en":"Love is a form of patient attention.","zh":"愛是一種耐心的關注。"},{"en":"A form of patient attention means a kind of care that watches, listens, and understands slowly.","zh":"一種耐心的關注，是指一種慢慢觀察、聆聽和理解的關懷。"},{"en":"Parents show patient attention when they listen to a child’s worries without rushing.","zh":"父母不急着打斷，而是聆聽孩子的憂慮時，就是表現耐心關注。"},{"en":"Love grows when people notice another person’s hidden pain and needs.","zh":"當人們留意到別人隱藏的痛苦和需要時，愛會成長。"},{"en":"This phrase presents love as steady care, not dramatic excitement.","zh":"這個短語把愛呈現為穩定關懷，而不是戲劇化興奮。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"as a child","meaning":"小時候","examples":[{"en":"As a child, the writer thought fairy tales were about romance.","zh":"小時候，作者以為童話是關於愛情的。"},{"en":"As a child means when someone was young.","zh":"小時候是指某人年幼的時候。"},{"en":"As a child, I believed every story ended with a perfect happy ending.","zh":"小時候，我相信每個故事都以完美快樂結局作結。"},{"en":"Writers use this phrase to compare earlier understanding with later wisdom.","zh":"作者使用這個短語來比較早期理解與後來智慧。"},{"en":"It helps show growth from simple belief to deeper reflection.","zh":"它幫助顯示由簡單相信到深層反思的成長。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"princes and princesses","meaning":"王子和公主","examples":[{"en":"Stories about princes and princesses seemed to be about romance.","zh":"關於王子和公主的故事看似是關於愛情。"},{"en":"Princes and princesses are royal characters often found in fairy tales.","zh":"王子和公主是常出現在童話中的皇室角色。"},{"en":"Children may expect stories about princes and princesses to end with weddings.","zh":"小朋友可能期待王子和公主的故事以婚禮作結。"},{"en":"These characters can represent power, beauty, loneliness, or moral testing.","zh":"這些角色可以代表權力、美貌、孤獨或道德考驗。"},{"en":"This phrase points to the familiar surface of many fairy tales.","zh":"這個短語指向許多童話熟悉的表層內容。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"simply about romance","meaning":"只是關於愛情","examples":[{"en":"The writer thought these stories were simply about romance.","zh":"作者以為這些故事只是關於愛情。"},{"en":"Simply about romance means only concerned with love stories between characters.","zh":"只是關於愛情，是指只關心角色之間的戀愛故事。"},{"en":"A reader may think Cinderella is simply about romance if they ignore endurance and forgiveness.","zh":"如果讀者忽略忍耐和寬恕，可能會以為《灰姑娘》只是關於愛情。"},{"en":"Later reading can reveal that romance is only one layer of the story.","zh":"後來再讀，可能會發現愛情只是故事其中一層。"},{"en":"This phrase shows an early, narrower interpretation.","zh":"這個短語顯示早期較狹窄的理解。"}],"source":"2023 Q5.pdf","sourcePage":3},{"front":"only later did I notice","meaning":"直到後來我才注意到","examples":[{"en":"Only later did I notice the deeper question in these stories.","zh":"直到後來我才注意到這些故事中的更深層問題。"},{"en":"Only later did I notice means I understood something only after time had passed.","zh":"直到後來我才注意到，是指時間過去後我才明白某事。"},{"en":"Only later did I notice that the fable was not about speed but discipline.","zh":"直到後來我才注意到，那則寓言不是關於速度，而是關於紀律。"},{"en":"This structure emphasises delayed understanding and personal growth.","zh":"這個句式強調延遲出現的理解和個人成長。"},{"en":"It shows that stories can reveal new meanings as readers mature.","zh":"它顯示故事會隨讀者成熟而展現新意思。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"deeper question","meaning":"更深層的問題","examples":[{"en":"Fairy tales ask a deeper question about hidden worth.","zh":"童話提出一個關於隱藏價值的更深層問題。"},{"en":"A deeper question is a more serious issue beneath the surface of a story or situation.","zh":"更深層的問題，是故事或情況表面下更嚴肅的議題。"},{"en":"A story about a monster may ask a deeper question about loneliness and acceptance.","zh":"一個關於怪物的故事，可能提出關於孤獨和接納的更深層問題。"},{"en":"Deeper questions make simple tales meaningful for older readers too.","zh":"更深層問題令簡單故事對年長讀者也有意義。"},{"en":"This phrase invites readers to think beyond the plot.","zh":"這個短語邀請讀者思考情節以外的內容。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"willing to see","meaning":"願意看見","examples":[{"en":"The stories ask who is willing to see another person’s worth.","zh":"這些故事問誰願意看見另一個人的價值。"},{"en":"Willing to see means ready to notice and understand something that may not be obvious.","zh":"願意看見，是指準備注意和理解未必明顯的東西。"},{"en":"A good friend is willing to see effort behind a quiet classmate’s silence.","zh":"好朋友願意看見安靜同學沉默背後的努力。"},{"en":"Being willing to see others deeply can change how we treat them.","zh":"願意深入看見別人，可以改變我們對待他們的方式。"},{"en":"This phrase connects love with attention and openness.","zh":"這個短語把愛與關注和開放連接起來。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"hidden worth","meaning":"隱藏的價值","examples":[{"en":"Fairy tales often reveal the hidden worth of another person.","zh":"童話常揭示另一個人的隱藏價值。"},{"en":"Hidden worth means value or goodness that is not obvious at first.","zh":"隱藏的價值是指一開始不明顯的價值或美善。"},{"en":"A shy student may have hidden worth that appears when someone gives them time to speak.","zh":"害羞學生可能有隱藏的價值，當有人給他時間說話時才顯現。"},{"en":"Stories reveal hidden worth by showing that appearance is not the whole truth.","zh":"故事透過顯示外表不是全部真相，揭示隱藏價值。"},{"en":"This phrase teaches readers to look beyond surface judgement.","zh":"這個短語教讀者看穿表面判斷。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"Beauty and the Beast","meaning":"《美女與野獸》","examples":[{"en":"In Beauty and the Beast, Belle recognises humanity beneath anger.","zh":"在《美女與野獸》中，Belle 看見憤怒底下的人性。"},{"en":"Beauty and the Beast is a fairy tale about looking beyond frightening appearance.","zh":"《美女與野獸》是一個關於看穿可怕外表的童話。"},{"en":"The story teaches that love begins with understanding rather than beauty alone.","zh":"這個故事教導我們，愛始於理解，而不只是美貌。"},{"en":"Readers learn from Beauty and the Beast that anger may hide loneliness.","zh":"讀者從《美女與野獸》中學到，憤怒可能隱藏孤獨。"},{"en":"This title is often used to discuss hidden worth and compassion.","zh":"這個故事名常用來討論隱藏價值和同情心。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"Belle’s love begins when","meaning":"Belle 的愛始於","examples":[{"en":"Belle’s love begins when she recognises loneliness behind ugliness.","zh":"Belle 的愛始於她看見醜陋背後的孤獨。"},{"en":"Belle’s love begins when means her care starts at the moment she understands something deeper.","zh":"Belle 的愛始於……，是指她在理解更深層事情的一刻開始關心。"},{"en":"Belle’s love begins when she sees the Beast as wounded rather than simply frightening.","zh":"Belle 的愛始於她把野獸看成受傷的人，而不只是可怕的存在。"},{"en":"This phrase shows that love grows from recognition, not instant attraction.","zh":"這個短語顯示愛源於認出真相，而不是即時吸引。"},{"en":"It helps readers understand love as moral attention.","zh":"它幫助讀者把愛理解為道德上的關注。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"recognises loneliness behind ugliness","meaning":"看見醜陋背後的孤獨","examples":[{"en":"Belle recognises loneliness behind ugliness.","zh":"Belle 看見醜陋背後的孤獨。"},{"en":"Recognises loneliness behind ugliness means notices sadness hidden beneath an unattractive or frightening appearance.","zh":"看見醜陋背後的孤獨，是指注意到不吸引或可怕外表下隱藏的悲傷。"},{"en":"A classmate may recognise loneliness behind another student’s rude behaviour.","zh":"同學可能看見另一位學生粗魯行為背後的孤獨。"},{"en":"This recognition can change fear into compassion.","zh":"這種看見可以把恐懼變成同情。"},{"en":"This phrase teaches readers not to stop at appearance.","zh":"這個短語教讀者不要停留在外表。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"humanity beneath anger","meaning":"憤怒底下的人性","examples":[{"en":"Belle sees humanity beneath anger.","zh":"Belle 看見憤怒底下的人性。"},{"en":"Humanity beneath anger means the human feeling, pain, or goodness hidden under angry behaviour.","zh":"憤怒底下的人性，是指憤怒行為下隱藏的人類感受、痛苦或美善。"},{"en":"A teacher may see humanity beneath a student’s anger when she notices fear behind it.","zh":"老師注意到學生憤怒背後的恐懼時，可能看見憤怒底下的人性。"},{"en":"Seeing humanity beneath anger can make responses kinder and wiser.","zh":"看見憤怒底下的人性，可以令人回應得更善良和明智。"},{"en":"This phrase suggests that difficult people may still deserve understanding.","zh":"這個短語表示難相處的人仍可能值得理解。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"likewise","meaning":"同樣地","examples":[{"en":"Likewise, kindness is returned in tales where animals speak.","zh":"同樣地，在動物會說話的故事中，善意常得到回報。"},{"en":"Likewise means in the same way or similarly.","zh":"同樣地是指以相同方式或相似地。"},{"en":"Cinderella shows endurance; likewise, Hansel and Gretel show courage through cooperation.","zh":"灰姑娘顯示忍耐；同樣地，Hansel 和 Gretel 透過合作顯示勇氣。"},{"en":"Writers use likewise to connect two examples with a similar lesson.","zh":"作者使用「同樣地」來連接兩個有相似教訓的例子。"},{"en":"This word helps an essay move smoothly from one story to another.","zh":"這個詞幫助文章順暢地由一個故事轉到另一個故事。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"tales where animals speak","meaning":"動物會說話的故事","examples":[{"en":"In tales where animals speak, kindness is often returned.","zh":"在動物會說話的故事中，善意常得到回報。"},{"en":"Tales where animals speak are stories in which animals talk like people.","zh":"動物會說話的故事，是指動物像人一樣說話的故事。"},{"en":"In such tales, a small mouse may speak, think, and help a mighty lion.","zh":"在這類故事中，小老鼠可能會說話、思考，並幫助強大的獅子。"},{"en":"Speaking animals make moral lessons easier for children to understand.","zh":"會說話的動物令道德教訓更容易讓孩子理解。"},{"en":"This phrase points to fables that teach through imagined animal behaviour.","zh":"這個短語指透過想像中的動物行為教導人的寓言。"}],"source":"2023 Q5.pdf","sourcePage":4},{"front":"strangers offer help","meaning":"陌生人伸出援手","examples":[{"en":"Strangers offer help in many fairy tales.","zh":"在許多童話中，陌生人伸出援手。"},{"en":"Strangers offer help means unfamiliar people provide support, guidance, or kindness.","zh":"陌生人伸出援手，是指不熟悉的人提供支援、指引或善意。"},{"en":"In a story, an old woman on the road may offer help to a lost child.","zh":"在故事中，路上的老婦人可能向迷路孩子伸出援手。"},{"en":"Help from strangers can show that kindness may appear unexpectedly.","zh":"來自陌生人的幫助可以顯示善意可能意外出現。"},{"en":"This phrase teaches readers to value generosity beyond family or friends.","zh":"這個短語教讀者珍惜家人朋友以外的慷慨。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"kindness is returned","meaning":"善意得到回報","examples":[{"en":"Kindness is returned because it is given freely.","zh":"善意得到回報，因為它是不計算回報地付出。"},{"en":"Kindness is returned means kind actions often come back as help, gratitude, or trust.","zh":"善意得到回報，是指善意行動常以幫助、感激或信任的方式回到人身上。"},{"en":"A student who helps a classmate may later receive help during a difficult project.","zh":"幫助同學的學生，日後可能在困難專題中得到幫助。"},{"en":"Stories show kindness being returned to teach that generosity has value.","zh":"故事展示善意得到回報，是為了教導慷慨有價值。"},{"en":"This phrase does not mean kindness is a trade; it means kindness can create goodness.","zh":"這個短語不是指善意是交易，而是指善意能創造美善。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"given without calculation","meaning":"不計算回報地付出","examples":[{"en":"Kindness is powerful when it is given without calculation.","zh":"當善意是不計算回報地付出時，它就有力量。"},{"en":"Given without calculation means offered freely without counting reward or advantage.","zh":"不計算回報地付出，是指自由給予，而不計算獎賞或好處。"},{"en":"A student gives help without calculation when she explains homework to a classmate without expecting anything back.","zh":"學生不期待回報地向同學解釋功課，就是不計算回報地提供幫助。"},{"en":"Kindness given this way feels sincere and builds trust.","zh":"這樣付出的善意感覺真誠，並建立信任。"},{"en":"This phrase contrasts true generosity with selfish exchange.","zh":"這個短語對比真正慷慨與自私交換。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"shaped the way I treat people","meaning":"影響我待人的方式","examples":[{"en":"These stories have shaped the way I treat people at school.","zh":"這些故事影響我在學校待人的方式。"},{"en":"Shaped the way I treat people means influenced how I behave toward others.","zh":"影響我待人的方式，是指影響我如何對待別人。"},{"en":"A story about forgiveness may shape how a student responds after a quarrel.","zh":"關於寬恕的故事可能影響學生在爭吵後如何回應。"},{"en":"Stories shape behaviour when their lessons become part of daily choices.","zh":"當故事教訓成為日常選擇的一部分時，故事就會影響行為。"},{"en":"This phrase shows that reading can affect real relationships.","zh":"這個短語顯示閱讀可以影響真實關係。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"rather than unfriendly","meaning":"是害羞而不是不友善","examples":[{"en":"A quiet classmate may be shy rather than unfriendly.","zh":"安靜的同學可能是害羞，而不是不友善。"},{"en":"Rather than unfriendly means instead of being cold, rude, or unwilling to connect.","zh":"是害羞而不是不友善，是指不是冷漠、粗魯或不願連繫人。"},{"en":"A new student may stay silent because he is nervous rather than unfriendly.","zh":"新同學可能因緊張而沉默，而不是不友善。"},{"en":"This phrase helps prevent unfair judgement based on surface behaviour.","zh":"這個短語幫助防止基於表面行為的不公平判斷。"},{"en":"It teaches readers to consider kinder explanations.","zh":"它教讀者考慮更善意的解釋。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"difficult friend","meaning":"難相處的朋友","examples":[{"en":"A difficult friend may be hurt rather than cold.","zh":"難相處的朋友可能是受傷，而不是冷漠。"},{"en":"A difficult friend is a friend whose behaviour is hard to understand, accept, or deal with.","zh":"難相處的朋友是指行為難以理解、接受或處理的朋友。"},{"en":"A difficult friend may cancel plans often because they are unhappy, not because they do not care.","zh":"難相處的朋友可能常取消約定，是因為不快，而不是不在乎。"},{"en":"Understanding a difficult friend can reduce anger and open a kinder conversation.","zh":"理解難相處的朋友可以減少憤怒，並打開更善意的對話。"},{"en":"This phrase reminds us that difficult behaviour may hide pain.","zh":"這個短語提醒我們，難相處的行為可能隱藏痛苦。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"hurt rather than cold","meaning":"是受傷而不是冷漠","examples":[{"en":"A difficult friend may be hurt rather than cold.","zh":"難相處的朋友可能是受傷，而不是冷漠。"},{"en":"Hurt rather than cold means someone may be acting distant because of pain, not because they lack care.","zh":"是受傷而不是冷漠，是指某人表現疏離可能因痛苦，而不是因缺乏關心。"},{"en":"A classmate who stops talking may be hurt rather than cold after being excluded.","zh":"被排斥後停止說話的同學，可能是受傷而不是冷漠。"},{"en":"Seeing hurt behind coldness can make our response gentler.","zh":"看見冷漠背後的受傷，可以令我們回應得更溫柔。"},{"en":"This phrase teaches emotional understanding before judgement.","zh":"這個短語教人先作情感理解，再作判斷。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"look beyond the surface","meaning":"看穿表面","examples":[{"en":"The writer learned to look beyond the surface.","zh":"作者學會看穿表面。"},{"en":"To look beyond the surface means to see deeper reasons, feelings, or meanings behind appearances.","zh":"看穿表面，是指看見外表背後更深層的原因、感受或意思。"},{"en":"A teacher looks beyond the surface when she asks why a student is suddenly rude.","zh":"當老師詢問學生為何突然粗魯時，她就是在看穿表面。"},{"en":"Looking beyond the surface can turn judgement into understanding.","zh":"看穿表面可以把判斷變成理解。"},{"en":"This phrase is central to many fairy-tale lessons.","zh":"這個短語是許多童話教訓的核心。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"relationships became less like transactions","meaning":"關係變得不再像交易","examples":[{"en":"Relationships became less like transactions.","zh":"關係變得不再像交易。"},{"en":"Relationships became less like transactions means relationships felt less like exchanges of benefit or reward.","zh":"關係變得不再像交易，是指關係不再像利益或回報的交換。"},{"en":"A friendship becomes less like a transaction when help is given without counting favours.","zh":"當朋友幫忙時不計算人情，友誼就不再像交易。"},{"en":"This change makes relationships warmer and more sincere.","zh":"這種轉變令關係更溫暖和真誠。"},{"en":"This phrase criticises treating people as tools for personal gain.","zh":"這個短語批評把人當作個人利益工具的做法。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"more like bridges","meaning":"更像橋樑","examples":[{"en":"Relationships became more like bridges.","zh":"關係變得更像橋樑。"},{"en":"More like bridges means relationships became ways to connect, support, and understand people.","zh":"更像橋樑，是指關係變成連接、支援和理解別人的方式。"},{"en":"A kind conversation can become a bridge between two classmates who once misunderstood each other.","zh":"一次善意對話可以成為兩個曾經誤解彼此的同學之間的橋樑。"},{"en":"Bridges suggest connection rather than exchange or competition.","zh":"橋樑象徵連接，而不是交換或競爭。"},{"en":"This phrase presents relationships as paths toward care and understanding.","zh":"這個短語把關係呈現為通往關懷和理解的路。"}],"source":"2023 Q5.pdf","sourcePage":5},{"front":"not by chasing perfection","meaning":"不是靠追求完美","examples":[{"en":"Love is found not by chasing perfection.","zh":"愛不是靠追求完美而找到。"},{"en":"Not by chasing perfection means not through demanding flawless people or perfect situations.","zh":"不是靠追求完美，是指不是透過要求毫無缺點的人或完美情況。"},{"en":"A friendship grows not by chasing perfection but by accepting honest mistakes.","zh":"友誼不是靠追求完美而成長，而是透過接受真誠錯誤。"},{"en":"Chasing perfection can make people miss real kindness in imperfect people.","zh":"追求完美可能令人錯過不完美的人身上的真正善意。"},{"en":"This phrase rejects unrealistic standards in relationships.","zh":"這個短語否定關係中的不切實際標準。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"understanding imperfection","meaning":"理解不完美","examples":[{"en":"Love is found by understanding imperfection.","zh":"愛是透過理解不完美而找到。"},{"en":"Understanding imperfection means accepting that people have flaws, fears, and wounds.","zh":"理解不完美，是指接受人有缺點、恐懼和傷口。"},{"en":"A parent shows love by understanding a child’s imperfection while still guiding them.","zh":"父母理解孩子的不完美，同時仍引導孩子，就是表現愛。"},{"en":"Understanding imperfection makes forgiveness and patience possible.","zh":"理解不完美令寬恕和耐性成為可能。"},{"en":"This phrase presents love as realistic, gentle, and mature.","zh":"這個短語把愛呈現為實際、溫柔和成熟。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"survive family conflicts","meaning":"渡過家庭衝突","examples":[{"en":"Fairy tales have taught the writer how to survive family conflicts.","zh":"童話教會作者如何渡過家庭衝突。"},{"en":"To survive family conflicts means to get through arguments or tension at home without destroying relationships.","zh":"渡過家庭衝突，是指經歷家中的爭吵或緊張後，仍不摧毀關係。"},{"en":"A student survives family conflict by pausing before speaking during an argument over grades.","zh":"學生在因成績爭吵時說話前停一停，就是在渡過家庭衝突。"},{"en":"Families survive conflict when they choose forgiveness and keep talking.","zh":"當家人選擇寬恕並保持溝通時，就能渡過衝突。"},{"en":"This phrase shows that stories can guide real home life.","zh":"這個短語顯示故事可以引導真實家庭生活。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"without allowing bitterness to","meaning":"不讓怨恨……","examples":[{"en":"The writer wants to survive conflict without allowing bitterness to harden his heart.","zh":"作者想渡過衝突，而不讓怨恨令自己的心變硬。"},{"en":"Without allowing bitterness to means not letting resentment cause a harmful change.","zh":"不讓怨恨……，是指不讓怨氣造成有害改變。"},{"en":"A brother may forgive an argument without allowing bitterness to damage the relationship.","zh":"兄弟可以寬恕一次爭吵，而不讓怨恨傷害關係。"},{"en":"If bitterness is allowed to grow, small conflicts can become lasting distance.","zh":"如果怨恨被容許成長，小衝突可能變成長久距離。"},{"en":"This phrase warns against letting pain control the heart.","zh":"這個短語提醒人不要讓痛苦控制內心。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"bitterness","meaning":"怨恨","examples":[{"en":"Bitterness can harden a person’s heart.","zh":"怨恨可以令一個人的心變硬。"},{"en":"Bitterness means deep anger or resentment that stays after being hurt.","zh":"怨恨是受傷後留下的深層憤怒或怨氣。"},{"en":"A student may feel bitterness if they believe a friend betrayed them.","zh":"如果學生認為朋友背叛了自己，可能會感到怨恨。"},{"en":"Bitterness can make people cold, suspicious, and unwilling to forgive.","zh":"怨恨可以令人變得冷漠、多疑和不願寬恕。"},{"en":"This word shows what happens when pain is kept too long.","zh":"這個詞顯示痛苦被保存太久時會發生甚麼。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"harden my heart","meaning":"令我的心變硬","examples":[{"en":"Family conflicts should not harden my heart.","zh":"家庭衝突不應令我的心變硬。"},{"en":"To harden my heart means to make me less kind, forgiving, or open to others.","zh":"令我的心變硬，是指令我變得較不善良、不寬恕或不願向別人敞開。"},{"en":"Repeated arguments can harden a person’s heart if no one apologises or listens.","zh":"如果沒有人道歉或聆聽，反覆爭吵可能令人的心變硬。"},{"en":"Forgiveness keeps the heart from becoming closed and bitter.","zh":"寬恕能防止心變得封閉和怨恨。"},{"en":"This phrase describes emotional damage caused by unresolved hurt.","zh":"這個短語描述未解決傷痛造成的情感傷害。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"begin at home","meaning":"從家裏開始","examples":[{"en":"Many old stories begin at home.","zh":"許多古老故事從家裏開始。"},{"en":"Begin at home means start in a familiar family setting or ordinary domestic life.","zh":"從家裏開始，是指在熟悉的家庭背景或普通家居生活中開始。"},{"en":"A fairy tale may begin at home before the child enters a forest or palace.","zh":"童話可能先從家裏開始，然後孩子才進入森林或宮殿。"},{"en":"Beginning at home makes the story’s conflict feel close to everyday life.","zh":"從家裏開始，令故事衝突感覺貼近日常生活。"},{"en":"This phrase shows that adventure often grows from ordinary places.","zh":"這個短語顯示冒險常由普通地方展開。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"not in castles or battlefields","meaning":"不是在城堡或戰場","examples":[{"en":"Many old stories begin at home, not in castles or battlefields.","zh":"許多古老故事從家裏開始，不是在城堡或戰場。"},{"en":"Not in castles or battlefields means not in grand royal places or scenes of war.","zh":"不是在城堡或戰場，是指不是在宏大的皇室地方或戰爭場景。"},{"en":"A story may begin in a kitchen, not in castles or battlefields, to show ordinary pain.","zh":"故事可能從廚房開始，而不是在城堡或戰場，以顯示普通痛苦。"},{"en":"This contrast reminds readers that serious lessons can begin in simple homes.","zh":"這種對比提醒讀者，嚴肅教訓可以從簡單家庭開始。"},{"en":"The phrase rejects the idea that only grand settings matter.","zh":"這個短語否定只有宏大背景才重要的想法。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"castles","meaning":"城堡","examples":[{"en":"Fairy tales do not always begin in castles.","zh":"童話不一定從城堡開始。"},{"en":"Castles are large strong buildings where kings, queens, or nobles may live in stories.","zh":"城堡是故事中國王、王后或貴族可能居住的大型堅固建築。"},{"en":"A castle in a fairy tale can represent power, wealth, safety, or loneliness.","zh":"童話中的城堡可以代表權力、財富、安全或孤獨。"},{"en":"Some stories leave castles behind to focus on ordinary families and hardship.","zh":"有些故事不以城堡為中心，而是著重普通家庭和困難。"},{"en":"This word often creates a traditional fairy-tale atmosphere.","zh":"這個詞常營造傳統童話氣氛。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"battlefields","meaning":"戰場","examples":[{"en":"Many stories begin at home rather than on battlefields.","zh":"許多故事從家裏開始，而不是從戰場開始。"},{"en":"Battlefields are places where wars or violent struggles happen.","zh":"戰場是戰爭或暴力衝突發生的地方。"},{"en":"A battlefield may show public conflict, while a home may show private conflict.","zh":"戰場可能顯示公共衝突，而家庭可能顯示私人衝突。"},{"en":"Fairy tales do not need battlefields to teach courage or endurance.","zh":"童話不需要戰場也能教導勇氣或忍耐。"},{"en":"This word represents danger, violence, and large-scale struggle.","zh":"這個詞代表危險、暴力和大規模掙扎。"}],"source":"2023 Q5.pdf","sourcePage":6},{"front":"humiliated by","meaning":"被……羞辱","examples":[{"en":"Cinderella is humiliated by her stepfamily.","zh":"灰姑娘被她的繼親家庭羞辱。"},{"en":"Humiliated by someone means made to feel ashamed, small, or worthless by that person.","zh":"被某人羞辱，是指被那人令自己感到羞恥、渺小或沒有價值。"},{"en":"A student may feel humiliated by classmates who laugh at their clothes.","zh":"學生被同學取笑衣服時，可能感到被羞辱。"},{"en":"Being humiliated can hurt deeply, but stories may show how dignity survives.","zh":"被羞辱會深深傷人，但故事可能顯示尊嚴如何存活。"},{"en":"This phrase describes emotional cruelty done by others.","zh":"這個短語描述別人造成的情感殘酷。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"stepfamily","meaning":"繼親家庭","examples":[{"en":"Cinderella is treated badly by her stepfamily.","zh":"灰姑娘受到繼親家庭惡劣對待。"},{"en":"Stepfamily refers to family members connected through remarriage, such as a stepmother or stepsiblings.","zh":"繼親家庭是指透過再婚連繫的家庭成員，例如繼母或繼兄弟姊妹。"},{"en":"A stepfamily can be loving, but in Cinderella it becomes a source of cruelty.","zh":"繼親家庭可以有愛，但在《灰姑娘》中卻成為殘酷來源。"},{"en":"Stories about stepfamilies often explore belonging, jealousy, and fairness.","zh":"關於繼親家庭的故事常探討歸屬、嫉妒和公平。"},{"en":"This word names an important family relationship in many tales.","zh":"這個詞指出許多故事中的重要家庭關係。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"abandoned","meaning":"被遺棄","examples":[{"en":"Hansel and Gretel are abandoned.","zh":"Hansel 和 Gretel 被遺棄。"},{"en":"Abandoned means left alone without care, protection, or support.","zh":"被遺棄是指被留下，沒有照顧、保護或支援。"},{"en":"A child in a story may feel abandoned when adults disappear during danger.","zh":"當成年人在危險中消失時，故事中的孩子可能感到被遺棄。"},{"en":"Being abandoned creates fear because the person must survive without help.","zh":"被遺棄會帶來恐懼，因為人必須在沒有幫助下生存。"},{"en":"This word gives a story emotional seriousness and danger.","zh":"這個詞為故事帶來情感上的嚴肅和危險。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"the youngest child","meaning":"最年幼的孩子","examples":[{"en":"The youngest child in many tales is ignored or underestimated.","zh":"許多故事中的最年幼孩子被忽視或低估。"},{"en":"The youngest child is the child born last or the smallest among siblings.","zh":"最年幼的孩子是兄弟姊妹中最後出生或年紀最小的孩子。"},{"en":"In many stories, the youngest child is treated as weak but later proves wise.","zh":"在許多故事中，最年幼的孩子被視為弱小，但後來證明有智慧。"},{"en":"This character often teaches that value is not decided by age or size.","zh":"這個角色常教導我們，價值不是由年齡或身形決定。"},{"en":"This phrase appears often in tales about hidden strength.","zh":"這個短語常出現在關於隱藏力量的故事中。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"countless tales","meaning":"無數故事","examples":[{"en":"The youngest child is underestimated in countless tales.","zh":"在無數故事中，最年幼的孩子被低估。"},{"en":"Countless tales means very many stories, too many to count easily.","zh":"無數故事是指非常多、多到難以輕易數清的故事。"},{"en":"Countless tales show small or ignored characters becoming brave and wise.","zh":"無數故事展示細小或被忽視的角色變得勇敢和明智。"},{"en":"This phrase suggests that a pattern appears again and again in storytelling.","zh":"這個短語表示一種模式在故事中反覆出現。"},{"en":"It helps writers show that an idea is common and traditional.","zh":"它幫助作者顯示某個想法常見而傳統。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"ignored or underestimated","meaning":"被忽視或低估","examples":[{"en":"The youngest child is often ignored or underestimated.","zh":"最年幼的孩子常被忽視或低估。"},{"en":"Ignored or underestimated means not noticed properly or judged as less capable than one really is.","zh":"被忽視或低估，是指沒有被好好注意，或被評價為比實際能力低。"},{"en":"A quiet student may be ignored or underestimated until a group project reveals their ideas.","zh":"安靜學生可能被忽視或低估，直到小組習作展示出他的想法。"},{"en":"Being underestimated can hurt, but it may also become a chance to prove worth.","zh":"被低估會令人受傷，但也可能成為證明價值的機會。"},{"en":"This phrase shows unfair judgement based on appearance or position.","zh":"這個短語顯示基於外表或位置的不公平判斷。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"seem extreme","meaning":"看似極端","examples":[{"en":"These plots may seem extreme.","zh":"這些情節可能看似極端。"},{"en":"Seem extreme means appear unusually serious, dramatic, or far from normal life.","zh":"看似極端，是指顯得特別嚴重、戲劇化或遠離正常生活。"},{"en":"A story about children abandoned in a forest may seem extreme to modern readers.","zh":"關於孩子被遺棄在森林裏的故事，對現代讀者可能看似極端。"},{"en":"Extreme plots can still express familiar emotions such as fear and jealousy.","zh":"極端情節仍可以表達恐懼和嫉妒等熟悉情感。"},{"en":"This phrase admits that fairy-tale events may look unrealistic at first.","zh":"這個短語承認童話事件起初可能看起來不真實。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"emotions behind them","meaning":"背後的情感","examples":[{"en":"The emotions behind these plots are familiar.","zh":"這些情節背後的情感是熟悉的。"},{"en":"Emotions behind them means the feelings hidden beneath the dramatic events.","zh":"背後的情感，是指藏在戲劇化事件之下的感受。"},{"en":"Behind a story about abandonment may be the familiar fear of not being loved.","zh":"遺棄故事背後，可能是害怕不被愛的熟悉恐懼。"},{"en":"Understanding the emotions behind plots makes old tales feel relevant.","zh":"理解情節背後的情感，令古老故事感覺相關。"},{"en":"This phrase connects unrealistic events with real human feelings.","zh":"這個短語把不真實事件與真實人類感受連接起來。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"moments of jealousy","meaning":"嫉妒的時刻","examples":[{"en":"Every family has moments of jealousy and silence.","zh":"每個家庭都有嫉妒和沉默的時刻。"},{"en":"Moments of jealousy are times when people feel unhappy because someone else receives attention, love, or success.","zh":"嫉妒的時刻，是指人因別人得到關注、愛或成功而感到不快的時候。"},{"en":"Siblings may have moments of jealousy when one child receives more praise.","zh":"當一個孩子得到更多稱讚時，兄弟姊妹可能有嫉妒的時刻。"},{"en":"Jealousy becomes less harmful when families talk about it honestly.","zh":"當家庭誠實談論嫉妒時，它就較少造成傷害。"},{"en":"This phrase shows that ordinary family life contains difficult emotions.","zh":"這個短語顯示普通家庭生活包含困難情感。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"silence and misunderstanding","meaning":"沉默和誤解","examples":[{"en":"Families experience jealousy, silence and misunderstanding.","zh":"家庭會經歷嫉妒、沉默和誤解。"},{"en":"Silence and misunderstanding mean lack of communication and wrong ideas about each other.","zh":"沉默和誤解，是指缺乏溝通，以及對彼此產生錯誤想法。"},{"en":"A family argument may grow because of silence and misunderstanding after a small mistake.","zh":"小錯誤後出現沉默和誤解，可能令家庭爭吵擴大。"},{"en":"Talking honestly can turn silence and misunderstanding into clearer care.","zh":"誠實交談可以把沉默和誤解轉化為更清楚的關懷。"},{"en":"This phrase describes common causes of family conflict.","zh":"這個短語描述家庭衝突的常見原因。"}],"source":"2023 Q5.pdf","sourcePage":7},{"front":"what matters is not whether…, but how…","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not whether conflict appears, but how we respond.","zh":"重要的不是衝突是否出現，而是我們如何回應。"},{"en":"What matters is not whether A, but how B means the key issue is not if something happens, but the way we deal with it.","zh":"重要的不是A，而是如何B，是指關鍵不在於某事是否發生，而在於我們怎樣處理它。"},{"en":"What matters is not whether students make mistakes, but how they learn from them.","zh":"重要的不是學生是否犯錯，而是他們如何從錯誤中學習。"},{"en":"This structure shifts attention from fear of problems to responsible response.","zh":"這個句式把注意力由害怕問題轉向負責任回應。"},{"en":"It is useful for explaining maturity and judgement.","zh":"它適合解釋成熟和判斷力。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"conflict appears","meaning":"衝突出現","examples":[{"en":"Conflict appears in every family.","zh":"每個家庭都會有衝突出現。"},{"en":"Conflict appears means disagreement, tension, or argument begins to happen.","zh":"衝突出現是指分歧、緊張或爭吵開始發生。"},{"en":"Conflict may appear when siblings feel that rules are unfair.","zh":"當兄弟姊妹覺得規則不公平時，衝突可能出現。"},{"en":"When conflict appears, people can choose to shout or to listen.","zh":"當衝突出現時，人們可以選擇大叫或聆聽。"},{"en":"This phrase shows that conflict is normal, but response matters.","zh":"這個短語顯示衝突是正常的，但回應很重要。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"respond when it does","meaning":"當它出現時作出回應","examples":[{"en":"What matters is how we respond when conflict appears.","zh":"重要的是當衝突出現時，我們如何回應。"},{"en":"Respond when it does means choose what to say or do when the problem actually happens.","zh":"當它出現時作出回應，是指問題真正發生時選擇說甚麼或做甚麼。"},{"en":"A student responds well when conflict appears by asking for time to calm down.","zh":"當衝突出現時，學生請求時間冷靜下來，就是良好回應。"},{"en":"The way we respond can either repair or worsen a relationship.","zh":"我們的回應方式可以修補關係，也可以令關係惡化。"},{"en":"This phrase focuses on action after difficulty begins.","zh":"這個短語著重困難開始後的行動。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"gentleness","meaning":"溫柔","examples":[{"en":"Cinderella’s gentleness is sometimes mistaken for weakness.","zh":"灰姑娘的溫柔有時被誤認為軟弱。"},{"en":"Gentleness means a soft, kind, and careful way of treating others.","zh":"溫柔是指以柔和、善良和小心的方式對待別人。"},{"en":"A gentle person may speak calmly even when others are harsh.","zh":"溫柔的人即使面對嚴厲的人，也可能冷靜說話。"},{"en":"Gentleness is not weakness when it comes with courage and self-respect.","zh":"當溫柔伴隨勇氣和自尊時，它並不是軟弱。"},{"en":"This word shows quiet strength in difficult situations.","zh":"這個詞顯示困難情況中的安靜力量。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"mistaken for weakness","meaning":"被誤認為軟弱","examples":[{"en":"Cinderella’s gentleness is sometimes mistaken for weakness.","zh":"灰姑娘的溫柔有時被誤認為軟弱。"},{"en":"Mistaken for weakness means wrongly understood as lack of strength or courage.","zh":"被誤認為軟弱，是指被錯誤理解為缺乏力量或勇氣。"},{"en":"A student’s politeness may be mistaken for weakness by aggressive classmates.","zh":"學生的禮貌可能被具攻擊性的同學誤認為軟弱。"},{"en":"Kindness is sometimes mistaken for weakness, but it can require great self-control.","zh":"善良有時被誤認為軟弱，但它可能需要很大的自制力。"},{"en":"This phrase warns against judging gentle behaviour too quickly.","zh":"這個短語提醒人不要太快判斷溫柔行為。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"endurance","meaning":"忍耐；承受力","examples":[{"en":"Cinderella’s endurance prevents cruelty from changing her.","zh":"灰姑娘的忍耐防止殘酷改變她。"},{"en":"Endurance means the ability to continue through pain, difficulty, or unfairness.","zh":"忍耐是指在痛苦、困難或不公平中仍繼續下去的能力。"},{"en":"A student shows endurance when they keep studying after repeated disappointment.","zh":"學生在多次失望後仍繼續學習，就是顯示忍耐。"},{"en":"Endurance helps people survive hardship without losing their values.","zh":"忍耐幫助人渡過困難而不失去自己的價值。"},{"en":"This word suggests strength that lasts quietly over time.","zh":"這個詞表示隨時間持續的安靜力量。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"prevents cruelty from making her cruel","meaning":"防止殘酷令她也變得殘酷","examples":[{"en":"Her endurance prevents cruelty from making her cruel.","zh":"她的忍耐防止殘酷令她也變得殘酷。"},{"en":"This phrase means suffering unfair treatment does not turn her into someone equally unkind.","zh":"這個短語是指即使承受不公平對待，她也沒有變成同樣不善良的人。"},{"en":"A bullied student prevents cruelty from making him cruel when he refuses to bully others.","zh":"被欺凌的學生拒絕欺凌別人時，就是防止殘酷令自己也變得殘酷。"},{"en":"This kind of strength protects a person’s character under pressure.","zh":"這種力量在壓力下保護一個人的品格。"},{"en":"The phrase shows moral victory over harmful treatment.","zh":"這個短語顯示對有害對待的道德勝利。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"cooperate","meaning":"合作","examples":[{"en":"Hansel and Gretel survive because they cooperate.","zh":"Hansel 和 Gretel 因合作而生存下來。"},{"en":"To cooperate means to work together toward the same goal.","zh":"合作是指為同一目標一起工作。"},{"en":"Students cooperate when they divide work fairly in a group project.","zh":"學生在小組習作中公平分工時，就是合作。"},{"en":"Cooperation helps people solve problems that are too difficult alone.","zh":"合作幫助人解決獨自難以處理的問題。"},{"en":"This word shows that survival can depend on teamwork.","zh":"這個詞顯示生存可能取決於團隊合作。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"think clearly","meaning":"清晰思考","examples":[{"en":"They survive because they think clearly.","zh":"他們因清晰思考而生存下來。"},{"en":"To think clearly means to stay calm enough to understand a problem and choose wisely.","zh":"清晰思考是指保持足夠冷靜去理解問題並作出明智選擇。"},{"en":"A student thinks clearly when they break a difficult project into smaller tasks.","zh":"學生把困難專題拆成較小任務時，就是清晰思考。"},{"en":"Clear thinking helps people avoid panic during danger or conflict.","zh":"清晰思考幫助人在危險或衝突中避免恐慌。"},{"en":"This phrase presents intelligence as calm judgement.","zh":"這個短語把智慧呈現為冷靜判斷。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"protect each other","meaning":"保護彼此","examples":[{"en":"Hansel and Gretel protect each other when adults fail them.","zh":"當成年人辜負他們時，Hansel 和 Gretel 保護彼此。"},{"en":"To protect each other means to keep one another safe through care, warning, or support.","zh":"保護彼此是指透過關懷、提醒或支援令對方安全。"},{"en":"Friends protect each other when they stop harmful rumours from spreading.","zh":"朋友阻止有害謠言散播時，就是保護彼此。"},{"en":"Protecting each other becomes important when outside help is missing.","zh":"當外來幫助缺席時，保護彼此變得重要。"},{"en":"This phrase shows loyalty and shared responsibility.","zh":"這個短語顯示忠誠和共同責任。"}],"source":"2023 Q5.pdf","sourcePage":8},{"front":"when adults fail them","meaning":"當成年人辜負他們時","examples":[{"en":"They protect each other when adults fail them.","zh":"當成年人辜負他們時，他們保護彼此。"},{"en":"When adults fail them means when grown-ups do not provide the care, protection, or guidance children need.","zh":"當成年人辜負他們時，是指成年人沒有提供孩子需要的照顧、保護或指引。"},{"en":"Children may feel afraid when adults fail them during a crisis.","zh":"當成年人在危機中辜負孩子時，孩子可能感到害怕。"},{"en":"This phrase shows a painful situation where young people must become brave too early.","zh":"這個短語顯示年輕人被迫太早勇敢的痛苦情況。"},{"en":"It highlights the responsibility adults have toward children.","zh":"它突出成年人對孩子的責任。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"quarrel with","meaning":"與……爭吵","examples":[{"en":"The writer sometimes quarrels with his parents over grades.","zh":"作者有時因成績與父母爭吵。"},{"en":"To quarrel with someone means to argue with them, often emotionally.","zh":"與某人爭吵是指與他們爭辯，通常帶有情緒。"},{"en":"A student may quarrel with a sibling over shared computer time.","zh":"學生可能因共用電腦時間與兄弟姊妹爭吵。"},{"en":"Quarrelling can damage relationships if people speak without thinking.","zh":"如果人們不經思考便說話，爭吵可能傷害關係。"},{"en":"This phrase describes everyday conflict in family or friendship.","zh":"這個短語描述家庭或友誼中的日常衝突。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"over grades","meaning":"因成績","examples":[{"en":"The writer quarrels with his parents over grades.","zh":"作者因成績與父母爭吵。"},{"en":"Over grades means because of school marks or academic results.","zh":"因成績是指因學校分數或學業結果。"},{"en":"Many families argue over grades when parents worry about future choices.","zh":"當父母擔心未來選擇時，許多家庭會因成績爭吵。"},{"en":"Arguments over grades may hide deeper fears about pressure and expectations.","zh":"因成績而起的爭吵，可能隱藏對壓力和期望的更深恐懼。"},{"en":"This phrase shows one common source of family tension for students.","zh":"這個短語顯示學生家庭緊張的一個常見來源。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"trivial matters","meaning":"瑣碎事情","examples":[{"en":"The writer quarrels with his brother over trivial matters.","zh":"作者因瑣碎事情與弟弟爭吵。"},{"en":"Trivial matters are small issues that are not very important.","zh":"瑣碎事情是指不太重要的小問題。"},{"en":"Siblings may argue over trivial matters such as snacks, seats, or borrowed pencils.","zh":"兄弟姊妹可能因零食、座位或借鉛筆等瑣碎事情爭吵。"},{"en":"Trivial matters can become serious when tired people speak harshly.","zh":"當疲倦的人說話嚴厲時，瑣碎事情可能變得嚴重。"},{"en":"This phrase shows how small problems can create emotional conflict.","zh":"這個短語顯示小問題如何造成情感衝突。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"pause before speaking","meaning":"說話前停一停","examples":[{"en":"The writer tries to pause before speaking.","zh":"作者嘗試在說話前停一停。"},{"en":"To pause before speaking means to stop briefly and think before saying something.","zh":"說話前停一停，是指在開口前短暫停下來思考。"},{"en":"A student may pause before speaking during an argument to avoid hurtful words.","zh":"學生在爭吵中可能說話前停一停，以避免傷人的話。"},{"en":"Pausing can prevent anger from becoming regret.","zh":"停一停可以防止憤怒變成後悔。"},{"en":"This phrase shows self-control in communication.","zh":"這個短語顯示溝通中的自制力。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"words can become thorns","meaning":"說話可以變成刺","examples":[{"en":"Words can become thorns during family conflicts.","zh":"在家庭衝突中，說話可以變成刺。"},{"en":"Words can become thorns means speech can hurt sharply like something pointed.","zh":"說話可以變成刺，是指言語可以像尖銳東西一樣刺痛人。"},{"en":"A careless insult during an argument can become a thorn remembered for years.","zh":"爭吵中的一句粗心侮辱，可能變成多年後仍記得的一根刺。"},{"en":"This image reminds people to speak gently when emotions are strong.","zh":"這個意象提醒人在情緒強烈時也要溫柔說話。"},{"en":"The phrase shows that language can wound relationships.","zh":"這個短語顯示語言可以傷害關係。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"the absence of conflict","meaning":"沒有衝突","examples":[{"en":"Family love is not the absence of conflict.","zh":"家庭之愛並不是沒有衝突。"},{"en":"The absence of conflict means a complete lack of disagreement or tension.","zh":"沒有衝突是指完全沒有分歧或緊張。"},{"en":"A peaceful family is not one with the absence of conflict, but one that repairs conflict well.","zh":"和平的家庭不是沒有衝突，而是能好好修補衝突。"},{"en":"Expecting no conflict at all can make normal disagreements feel like failure.","zh":"期待完全沒有衝突，可能令正常分歧感覺像失敗。"},{"en":"This phrase helps define love realistically.","zh":"這個短語幫助我們實際地定義愛。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"the decision to keep a door open","meaning":"衝突後仍留下溝通空間的決定","examples":[{"en":"Family love is the decision to keep a door open after conflict.","zh":"家庭之愛是衝突後仍留下溝通空間的決定。"},{"en":"The decision to keep a door open means choosing to leave room for communication and repair.","zh":"衝突後仍留下溝通空間的決定，是指選擇保留溝通和修補關係的餘地。"},{"en":"A parent keeps a door open when they say, “We can talk again after dinner.”","zh":"當父母說「晚飯後我們可以再談」時，就是留下溝通空間。"},{"en":"Keeping a door open prevents one argument from ending the relationship.","zh":"留下溝通空間可以防止一次爭吵終結關係。"},{"en":"This phrase presents love as a choice made after pain.","zh":"這個短語把愛呈現為痛苦後作出的選擇。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"after conflict","meaning":"衝突過後","examples":[{"en":"A family should keep a door open after conflict.","zh":"家庭應在衝突過後保留溝通空間。"},{"en":"After conflict means after an argument, disagreement, or period of tension.","zh":"衝突過後，是指在爭吵、分歧或緊張時期之後。"},{"en":"After conflict, friends may need time before they can apologise.","zh":"衝突過後，朋友可能需要時間才可以道歉。"},{"en":"What people do after conflict often decides whether a relationship heals.","zh":"人們在衝突過後做甚麼，常決定關係能否修復。"},{"en":"This phrase focuses on the repair stage, not the fight itself.","zh":"這個短語著重修補階段，而不是爭吵本身。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"challenge power wisely","meaning":"明智地挑戰權力","examples":[{"en":"Fables have taught the writer to challenge power wisely.","zh":"寓言教會作者明智地挑戰權力。"},{"en":"To challenge power wisely means to question authority or unfair strength with judgement and care.","zh":"明智地挑戰權力，是指以判斷和小心態度質疑權威或不公平力量。"},{"en":"Students challenge power wisely when they present evidence calmly to a teacher or leader.","zh":"學生冷靜地向老師或領袖提出證據時，就是明智地挑戰權力。"},{"en":"Wise challenge avoids reckless anger and looks for effective action.","zh":"明智挑戰避免魯莽憤怒，並尋找有效行動。"},{"en":"This phrase shows courage guided by intelligence.","zh":"這個短語顯示由智慧引導的勇氣。"}],"source":"2023 Q5.pdf","sourcePage":9},{"front":"define victory morally","meaning":"以道德方式界定勝利","examples":[{"en":"Fables have taught the writer to define victory morally.","zh":"寓言教會作者以道德方式界定勝利。"},{"en":"To define victory morally means to judge success by what is right, not only by winning.","zh":"以道德方式界定勝利，是指用正確與否來判斷成功，而不只是看是否贏。"},{"en":"A student defines victory morally when they refuse to cheat even if cheating might bring a higher mark.","zh":"學生即使作弊可能取得更高分，仍拒絕作弊，就是以道德方式界定勝利。"},{"en":"Moral victory may involve patience, honesty, and kindness.","zh":"道德勝利可能包括耐性、誠實和善良。"},{"en":"This phrase shows that winning without goodness is not real success.","zh":"這個短語顯示沒有美善的勝利不是真正成功。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"in the real world","meaning":"在現實世界中","examples":[{"en":"In the real world, power is not always defeated by magic.","zh":"在現實世界中，權力不一定被魔法打敗。"},{"en":"In the real world means in actual life, not in fantasy or imagination.","zh":"在現實世界中，是指在真實生活裏，而不是幻想或想像中。"},{"en":"In the real world, unfairness is often challenged through evidence, rules, and persistence.","zh":"在現實世界中，不公平常透過證據、規則和堅持來挑戰。"},{"en":"This phrase contrasts fairy-tale magic with everyday reality.","zh":"這個短語對比童話魔法與日常現實。"},{"en":"It helps bring story lessons into practical life.","zh":"它幫助把故事教訓帶入實際生活。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"the rich and powerful","meaning":"富有而有權勢的人","examples":[{"en":"The rich and powerful are not always defeated by magic swords.","zh":"富有而有權勢的人不一定被魔法劍打敗。"},{"en":"The rich and powerful are people with money, influence, or authority.","zh":"富有而有權勢的人是擁有金錢、影響力或權威的人。"},{"en":"The rich and powerful may control decisions in business, politics, or communities.","zh":"富有而有權勢的人可能控制商業、政治或社區中的決定。"},{"en":"Stories sometimes imagine small characters challenging the rich and powerful.","zh":"故事有時想像小人物挑戰富有而有權勢的人。"},{"en":"This phrase identifies those with social advantage.","zh":"這個短語指出擁有社會優勢的人。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"defeated by","meaning":"被……打敗","examples":[{"en":"The powerful are not always defeated by magic swords.","zh":"有權勢的人不一定被魔法劍打敗。"},{"en":"Defeated by means beaten or overcome through a particular force, action, or person.","zh":"被……打敗，是指被某種力量、行動或人物擊敗或克服。"},{"en":"In real life, unfairness may be defeated by patience and evidence.","zh":"在現實生活中，不公平可能被耐性和證據打敗。"},{"en":"A bully is not always defeated by shouting back.","zh":"欺凌者不一定會被回罵打敗。"},{"en":"This phrase shows what causes someone or something to lose power.","zh":"這個短語顯示是甚麼令某人或某事失去力量。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"magic swords","meaning":"魔法劍","examples":[{"en":"The rich and powerful are not always defeated by magic swords.","zh":"富有而有權勢的人不一定被魔法劍打敗。"},{"en":"Magic swords are imaginary weapons with special power in fairy tales or legends.","zh":"魔法劍是童話或傳說中具有特殊力量的想像武器。"},{"en":"A magic sword may help a hero defeat a dragon in a story.","zh":"在故事中，魔法劍可能幫助英雄打敗惡龍。"},{"en":"In real life, problems are not solved by magic swords but by choices and effort.","zh":"在現實生活中，問題不是靠魔法劍解決，而是靠選擇和努力。"},{"en":"This phrase represents fantasy solutions to difficult problems.","zh":"這個短語代表對困難問題的幻想式解決方法。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"more often","meaning":"更常見的是","examples":[{"en":"More often, power is challenged by patience and integrity.","zh":"更常見的是，權力被耐性和正直挑戰。"},{"en":"More often means in many cases or more commonly.","zh":"更常見的是指在許多情況下或較普遍地。"},{"en":"More often, school conflicts are solved by calm discussion rather than anger.","zh":"更常見的是，校園衝突透過冷靜討論而不是憤怒來解決。"},{"en":"Writers use this phrase to show what usually happens instead of the dramatic version.","zh":"作者使用這個短語來顯示通常發生的是甚麼，而不是戲劇化版本。"},{"en":"It helps move an argument from fantasy to reality.","zh":"它幫助把論點由幻想帶到現實。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"challenged by","meaning":"被……挑戰","examples":[{"en":"Power is challenged by patience, intelligence and integrity.","zh":"權力被耐性、智慧和正直挑戰。"},{"en":"Challenged by means questioned, resisted, or tested through a particular quality or action.","zh":"被……挑戰，是指透過某種特質或行動被質疑、抵抗或考驗。"},{"en":"Unfair rules can be challenged by evidence and respectful discussion.","zh":"不公平規則可以被證據和尊重的討論挑戰。"},{"en":"Power challenged wisely may change without violence.","zh":"權力若被明智挑戰，可能不用暴力也會改變。"},{"en":"This phrase shows the method used to confront something strong.","zh":"這個短語顯示面對強大事物時使用的方法。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"patience, intelligence and integrity","meaning":"耐性、智慧和正直","examples":[{"en":"Power can be challenged by patience, intelligence and integrity.","zh":"權力可以被耐性、智慧和正直挑戰。"},{"en":"Patience, intelligence and integrity mean calm endurance, wise thinking, and moral honesty.","zh":"耐性、智慧和正直，是指冷靜忍耐、明智思考和道德誠實。"},{"en":"A student uses patience, intelligence and integrity when reporting unfair treatment with evidence.","zh":"學生用證據報告不公平對待時，就是運用耐性、智慧和正直。"},{"en":"These qualities can be stronger than anger because they build trust.","zh":"這些特質可以比憤怒更有力，因為它們建立信任。"},{"en":"This phrase presents moral strength as practical power.","zh":"這個短語把道德力量呈現為實際力量。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"the tortoise defeats the hare","meaning":"龜打敗兔子","examples":[{"en":"The tortoise defeats the hare because he stays focused.","zh":"龜打敗兔子，因為牠保持專注。"},{"en":"The tortoise defeats the hare means a slower but steady person beats a faster but careless one.","zh":"龜打敗兔子，是指較慢但穩定的人勝過較快但粗心的人。"},{"en":"A student like the tortoise may succeed by revising every day instead of rushing at the end.","zh":"像龜一樣的學生可能透過每天溫習，而不是最後匆忙準備而成功。"},{"en":"This fable teaches that discipline can defeat arrogance.","zh":"這則寓言教導我們，紀律可以打敗傲慢。"},{"en":"This phrase represents steady effort overcoming natural advantage.","zh":"這個短語代表穩定努力勝過天生優勢。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"refuses to be distracted by","meaning":"拒絕被……分散注意力","examples":[{"en":"The tortoise refuses to be distracted by arrogance.","zh":"龜拒絕被傲慢分散注意力。"},{"en":"Refuses to be distracted by means chooses not to let something take attention away from the goal.","zh":"拒絕被……分散注意力，是指選擇不讓某事把注意力從目標上移開。"},{"en":"A student refuses to be distracted by gossip when preparing for an exam.","zh":"學生準備考試時拒絕被閒言閒語分散注意力。"},{"en":"Staying focused helps people continue even when others boast or laugh.","zh":"保持專注幫助人即使面對別人吹噓或嘲笑也繼續前進。"},{"en":"This phrase shows discipline and self-control.","zh":"這個短語顯示紀律和自制力。"}],"source":"2023 Q5.pdf","sourcePage":10},{"front":"arrogance","meaning":"傲慢","examples":[{"en":"The hare is distracted by arrogance.","zh":"兔子被傲慢分散注意力。"},{"en":"Arrogance means too much pride and belief that one is better than others.","zh":"傲慢是指過度驕傲，並相信自己比別人優越。"},{"en":"A talented student shows arrogance if they refuse to practise because they think they cannot fail.","zh":"有天分的學生如果因自以為不會失敗而拒絕練習，就是表現傲慢。"},{"en":"Arrogance can make people careless and blind to risk.","zh":"傲慢可以令人粗心，並看不見風險。"},{"en":"This word warns that confidence without humility can become weakness.","zh":"這個詞提醒我們，沒有謙遜的信心可能變成弱點。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"the mouse helps the lion","meaning":"老鼠幫助獅子","examples":[{"en":"The mouse helps the lion despite being small.","zh":"老鼠雖然細小，卻幫助獅子。"},{"en":"The mouse helps the lion means a small or weak character saves a powerful one.","zh":"老鼠幫助獅子，是指細小或弱小角色拯救強大角色。"},{"en":"A junior student may help a senior by noticing a mistake others missed.","zh":"低年級學生可能透過注意到別人忽略的錯誤來幫助高年級學生。"},{"en":"This fable teaches that size does not decide usefulness.","zh":"這則寓言教導我們，大小不決定有用程度。"},{"en":"This phrase shows that humble kindness can matter greatly.","zh":"這個短語顯示謙卑善意可以非常重要。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"mighty","meaning":"強大的","examples":[{"en":"The mouse is not mighty, but he is kind.","zh":"老鼠並不強大，但牠善良。"},{"en":"Mighty means very strong, powerful, or impressive.","zh":"強大的是指非常有力量、有權勢或令人印象深刻。"},{"en":"A mighty leader may still need help from ordinary people.","zh":"強大的領袖仍可能需要普通人的幫助。"},{"en":"Being mighty does not guarantee wisdom, kindness, or freedom from trouble.","zh":"強大不保證有智慧、善良或不遇困難。"},{"en":"This word contrasts outward power with inner goodness.","zh":"這個詞對比外在力量與內在美善。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"small kindness","meaning":"細小的善意","examples":[{"en":"Small kindness can rescue great power.","zh":"細小的善意可以拯救強大的力量。"},{"en":"Small kindness means a simple act of care that may look minor.","zh":"細小的善意是指看似微小的簡單關懷行動。"},{"en":"A student’s small kindness, such as sharing notes, can help a struggling classmate.","zh":"學生分享筆記等細小善意，可以幫助正在掙扎的同學。"},{"en":"Small kindness matters because it can arrive exactly when someone needs help.","zh":"細小善意重要，因為它可能正好在某人需要時出現。"},{"en":"This phrase shows that goodness does not need to be grand to be powerful.","zh":"這個短語顯示善良不必宏大也可以有力量。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"rescue great power from","meaning":"把強大的力量從……中拯救出來","examples":[{"en":"Small kindness can rescue great power from its own limitations.","zh":"細小的善意可以把強大的力量從自身限制中拯救出來。"},{"en":"To rescue great power from something means to help a powerful person or system escape a weakness.","zh":"把強大的力量從某事中拯救出來，是指幫助有力量的人或制度逃離弱點。"},{"en":"A junior worker may rescue a manager from error by politely pointing out missing information.","zh":"初級員工禮貌指出遺漏資料時，可能把經理從錯誤中拯救出來。"},{"en":"This phrase shows that the strong sometimes need help from the small.","zh":"這個短語顯示強者有時也需要弱小者幫助。"},{"en":"It challenges the belief that power is always self-sufficient.","zh":"它挑戰權力總是自給自足的信念。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"its own limitations","meaning":"自身的限制","examples":[{"en":"Great power can be trapped by its own limitations.","zh":"強大的力量可能被自身的限制困住。"},{"en":"Its own limitations means the weaknesses or boundaries within something itself.","zh":"自身的限制，是指某物本身內在的弱點或界限。"},{"en":"A strong leader’s own limitations may include pride or unwillingness to listen.","zh":"強大領袖自身的限制可能包括驕傲或不願聆聽。"},{"en":"Recognising one’s own limitations makes cooperation possible.","zh":"承認自身限制令合作成為可能。"},{"en":"This phrase shows that power can fail because of inner weakness.","zh":"這個短語顯示權力可能因內在弱點而失敗。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"meanwhile","meaning":"同時；另一方面","examples":[{"en":"Jack’s adventure, meanwhile, warns the writer about courage.","zh":"同時，Jack 的冒險警告作者關於勇氣的道理。"},{"en":"Meanwhile introduces another related point happening in contrast or alongside the previous one.","zh":"同時或另一方面，用來引出與前一點相對或並列的另一個相關觀點。"},{"en":"The tortoise teaches patience; meanwhile, Jack’s story teaches judgement.","zh":"龜教導耐性；另一方面，Jack 的故事教導判斷力。"},{"en":"Writers use meanwhile to move to a different example while staying on the same topic.","zh":"作者使用 meanwhile 轉到不同例子，同時保持同一主題。"},{"en":"This word helps organise comparisons between stories.","zh":"這個詞幫助組織故事之間的比較。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"adventure up the beanstalk","meaning":"爬上豆莖的冒險","examples":[{"en":"Jack’s adventure up the beanstalk warns the writer about greed.","zh":"Jack 爬上豆莖的冒險警告作者關於貪婪的道理。"},{"en":"An adventure up the beanstalk refers to Jack’s journey into a strange world above the giant beanstalk.","zh":"爬上豆莖的冒險，是指 Jack 沿巨大豆莖進入上方奇異世界的旅程。"},{"en":"The climb up the beanstalk represents risk, courage, curiosity, and temptation.","zh":"爬上豆莖代表風險、勇氣、好奇心和誘惑。"},{"en":"This adventure teaches that bravery needs judgement.","zh":"這次冒險教導勇敢需要判斷力。"},{"en":"This phrase points to a famous fairy-tale journey full of danger and desire.","zh":"這個短語指向一段著名童話中充滿危險和慾望的旅程。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"warns me that","meaning":"警告我","examples":[{"en":"Jack’s adventure warns me that courage needs judgement.","zh":"Jack 的冒險警告我，勇氣需要判斷力。"},{"en":"Warns me that means teaches me to be careful about a danger or mistake.","zh":"警告我，是指教我小心某種危險或錯誤。"},{"en":"A failed project warns me that enthusiasm needs planning.","zh":"一次失敗專題警告我，熱情需要計劃。"},{"en":"Stories warn readers when they show the cost of careless choices.","zh":"當故事展示粗心選擇的代價時，它就是在警告讀者。"},{"en":"This phrase connects a story event with a personal lesson.","zh":"這個短語把故事事件與個人教訓連接起來。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"courage without judgement","meaning":"沒有判斷力的勇氣","examples":[{"en":"Courage without judgement can become greed.","zh":"沒有判斷力的勇氣可能變成貪婪。"},{"en":"Courage without judgement means bravery that lacks wisdom, care, or moral direction.","zh":"沒有判斷力的勇氣，是指缺乏智慧、小心或道德方向的勇敢。"},{"en":"A student shows courage without judgement if they confront a bully without thinking about safety.","zh":"如果學生不考慮安全就直接對抗欺凌者，就是表現沒有判斷力的勇氣。"},{"en":"Courage needs judgement so that action helps rather than harms.","zh":"勇氣需要判斷力，這樣行動才會幫助人而不是傷害人。"},{"en":"This phrase warns that bravery alone is not enough.","zh":"這個短語提醒我們，單靠勇敢並不足夠。"}],"source":"2023 Q5.pdf","sourcePage":11},{"front":"daring guided by necessity","meaning":"由需要引導的膽量","examples":[{"en":"Daring guided by necessity can break fear.","zh":"由需要引導的膽量可以打破恐懼。"},{"en":"Daring guided by necessity means brave action taken because it is truly needed.","zh":"由需要引導的膽量，是指因真正有需要而採取的勇敢行動。"},{"en":"A student may speak up with daring guided by necessity when a classmate is being treated unfairly.","zh":"當同學受到不公平對待時，學生可能憑由需要引導的膽量發聲。"},{"en":"Such daring is different from showing off because it serves a real purpose.","zh":"這種膽量不同於炫耀，因為它服務真正目的。"},{"en":"This phrase presents courage as purposeful and responsible.","zh":"這個短語把勇氣呈現為有目的和負責任。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"break fear","meaning":"打破恐懼","examples":[{"en":"Daring guided by necessity can break fear.","zh":"由需要引導的膽量可以打破恐懼。"},{"en":"To break fear means to weaken fear so it no longer controls action.","zh":"打破恐懼是指削弱恐懼，使它不再控制行動。"},{"en":"Speaking once in class can help a shy student begin to break fear.","zh":"在課堂上發言一次，可以幫助害羞學生開始打破恐懼。"},{"en":"Fear is broken gradually when people take careful steps through it.","zh":"當人們小心地一步一步穿越恐懼時，恐懼會逐漸被打破。"},{"en":"This phrase shows courage changing a person’s inner limits.","zh":"這個短語顯示勇氣改變一個人的內在限制。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"school life","meaning":"校園生活","examples":[{"en":"These stories are useful in school life.","zh":"這些故事在校園生活中很有用。"},{"en":"School life means the daily experiences students have in lessons, activities, friendships, and rules.","zh":"校園生活是學生在課堂、活動、友誼和規則中的日常經歷。"},{"en":"School life includes group projects, exams, clubs, and conflicts with classmates.","zh":"校園生活包括小組習作、考試、學會和同學衝突。"},{"en":"Fairy-tale lessons become practical when students use them in school life.","zh":"當學生把童話教訓用於校園生活時，它們就變得實用。"},{"en":"This phrase brings story wisdom into everyday student experience.","zh":"這個短語把故事智慧帶入學生的日常經驗。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"aggressive student","meaning":"具攻擊性的學生","examples":[{"en":"An aggressive student may dominate a group project.","zh":"具攻擊性的學生可能主導小組習作。"},{"en":"An aggressive student is a student who behaves forcefully, angrily, or in a controlling way.","zh":"具攻擊性的學生是以強硬、憤怒或控制方式行事的學生。"},{"en":"An aggressive student may interrupt others and refuse to listen.","zh":"具攻擊性的學生可能打斷別人並拒絕聆聽。"},{"en":"Dealing with an aggressive student requires calmness, evidence, and fair rules.","zh":"應付具攻擊性的學生需要冷靜、證據和公平規則。"},{"en":"This phrase describes a common challenge in group work.","zh":"這個短語描述小組工作中的常見挑戰。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"dominates a group project","meaning":"主導小組習作","examples":[{"en":"An aggressive student may dominate a group project.","zh":"具攻擊性的學生可能主導小組習作。"},{"en":"Dominates a group project means controls most decisions and gives others little space to contribute.","zh":"主導小組習作，是指控制大部分決定，令其他人很少有貢獻空間。"},{"en":"One student dominates a group project when they assign all duties without discussion.","zh":"當一名學生不經討論便分配所有職責時，就是主導小組習作。"},{"en":"Domination can make quieter members feel ignored and reduce teamwork.","zh":"主導行為可能令較安靜成員感到被忽視，並削弱團隊合作。"},{"en":"This phrase shows unfair control in a shared task.","zh":"這個短語顯示共享任務中的不公平控制。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"shouting back","meaning":"回罵","examples":[{"en":"Shouting back may only feed the giant.","zh":"回罵可能只會助長巨人的氣焰。"},{"en":"Shouting back means replying angrily and loudly when someone attacks or criticises you.","zh":"回罵是指當別人攻擊或批評你時，憤怒而大聲地回應。"},{"en":"A student shouting back at an aggressive classmate may make the conflict worse.","zh":"學生回罵具攻擊性的同學，可能令衝突惡化。"},{"en":"Shouting back can feel powerful for a moment but may not solve the problem.","zh":"回罵可能一時感覺有力量，但未必能解決問題。"},{"en":"This phrase shows an unwise reaction to unfair behaviour.","zh":"這個短語顯示對不公平行為的不明智反應。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"feed the giant","meaning":"只會助長對方氣焰","examples":[{"en":"Shouting back may only feed the giant.","zh":"回罵可能只會助長對方氣焰。"},{"en":"Feed the giant means give more power to the problem or aggressive person.","zh":"助長對方氣焰，是指給問題或具攻擊性的人更多力量。"},{"en":"Arguing loudly may feed the giant by making the aggressive student more excited.","zh":"大聲爭辯可能令具攻擊性的學生更興奮，從而助長其氣焰。"},{"en":"Calm evidence can starve the giant because it refuses to reward bad behaviour.","zh":"冷靜證據可以削弱對方氣焰，因為它拒絕獎賞壞行為。"},{"en":"This phrase uses a fairy-tale image to explain conflict management.","zh":"這個短語用童話意象解釋衝突管理。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"preparing evidence","meaning":"準備證據","examples":[{"en":"Preparing evidence is often more effective than shouting.","zh":"準備證據通常比大叫更有效。"},{"en":"Preparing evidence means collecting facts, examples, messages, or records before making a point.","zh":"準備證據是指在提出觀點前收集事實、例子、訊息或記錄。"},{"en":"Students prepare evidence when they write down who did each part of a group project.","zh":"學生寫下小組習作中誰負責哪部分時，就是準備證據。"},{"en":"Evidence helps solve conflict because it moves discussion away from emotion alone.","zh":"證據幫助解決衝突，因為它把討論從單靠情緒中移開。"},{"en":"This phrase shows a practical and calm response to unfairness.","zh":"這個短語顯示對不公平的實際而冷靜回應。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"dividing duties fairly","meaning":"公平分配職責","examples":[{"en":"Dividing duties fairly can help solve group conflict.","zh":"公平分配職責可以幫助解決小組衝突。"},{"en":"Dividing duties fairly means sharing tasks in a balanced and reasonable way.","zh":"公平分配職責，是指以平衡和合理方式分享任務。"},{"en":"A group divides duties fairly when each member receives work that matches time and ability.","zh":"當小組按時間和能力分配工作給每位成員時，就是公平分配職責。"},{"en":"Fair division prevents one person from controlling everything or doing everything.","zh":"公平分配防止一個人控制所有事或做所有事。"},{"en":"This phrase shows how justice can be practised in small daily tasks.","zh":"這個短語顯示公義如何在日常小任務中實踐。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"speaking calmly","meaning":"冷靜說話","examples":[{"en":"Speaking calmly is often more effective than shouting.","zh":"冷靜說話通常比大叫更有效。"},{"en":"Speaking calmly means expressing ideas in a steady and controlled voice.","zh":"冷靜說話是指以穩定而受控制的聲音表達想法。"},{"en":"A student speaks calmly when they explain a problem without insulting anyone.","zh":"學生不侮辱任何人而解釋問題時，就是冷靜說話。"},{"en":"Calm speech helps others listen instead of becoming defensive.","zh":"冷靜說話幫助別人聆聽，而不是變得防衛。"},{"en":"This phrase shows emotional control during conflict.","zh":"這個短語顯示衝突中的情緒控制。"}],"source":"2023 Q5.pdf","sourcePage":12},{"front":"more effective","meaning":"更有效","examples":[{"en":"Speaking calmly is often more effective.","zh":"冷靜說話通常更有效。"},{"en":"More effective means more successful in producing the result wanted.","zh":"更有效是指更能成功產生想要的結果。"},{"en":"A clear message may be more effective than a loud complaint.","zh":"清晰訊息可能比大聲投訴更有效。"},{"en":"In group work, fair discussion is often more effective than blame.","zh":"在小組工作中，公平討論通常比責備更有效。"},{"en":"This phrase compares methods by their real results.","zh":"這個短語按真實結果比較方法。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"defeat unfairness","meaning":"戰勝不公平","examples":[{"en":"We do not defeat unfairness by becoming cruel.","zh":"我們不是透過變得殘酷來戰勝不公平。"},{"en":"To defeat unfairness means to overcome unjust treatment or behaviour.","zh":"戰勝不公平是指克服不公正的對待或行為。"},{"en":"Students defeat unfairness when they use evidence and rules to correct a biased decision.","zh":"學生用證據和規則糾正偏頗決定時，就是戰勝不公平。"},{"en":"Unfairness is not truly defeated if we copy its cruelty.","zh":"如果我們複製不公平的殘酷，就沒有真正戰勝它。"},{"en":"This phrase connects justice with moral self-control.","zh":"這個短語把公義與道德自制連接起來。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"by becoming crueller than","meaning":"透過變得比……更殘酷","examples":[{"en":"We do not defeat unfairness by becoming crueller than the unfair.","zh":"我們不會透過變得比不公平者更殘酷來戰勝不公平。"},{"en":"By becoming crueller than means through acting even more harshly than the person or system being criticised.","zh":"透過變得比……更殘酷，是指用比被批評的人或制度更嚴厲的方式行事。"},{"en":"A student does not solve bullying by becoming crueller than the bully.","zh":"學生不會透過變得比欺凌者更殘酷來解決欺凌。"},{"en":"Becoming cruel may win a moment but lose moral ground.","zh":"變得殘酷可能贏得一刻，卻失去道德立場。"},{"en":"This phrase warns against fighting wrong with worse wrong.","zh":"這個短語提醒人不要以更錯的方式對抗錯誤。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"refuse to surrender","meaning":"拒絕放棄","examples":[{"en":"We defeat unfairness by refusing to surrender our judgement.","zh":"我們透過拒絕放棄判斷力來戰勝不公平。"},{"en":"To refuse to surrender means to choose not to give up something important.","zh":"拒絕放棄是指選擇不放下重要的東西。"},{"en":"A student refuses to surrender when they continue speaking truthfully despite pressure.","zh":"學生即使面對壓力仍繼續誠實說話，就是拒絕放棄。"},{"en":"Refusing to surrender does not require anger; it requires firmness and clarity.","zh":"拒絕放棄不需要憤怒，而需要堅定和清晰。"},{"en":"This phrase shows quiet resistance.","zh":"這個短語顯示安靜的抵抗。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"surrender our judgement","meaning":"放棄判斷力","examples":[{"en":"We should not surrender our judgement.","zh":"我們不應放棄判斷力。"},{"en":"To surrender our judgement means to give up our ability to think carefully and decide what is right.","zh":"放棄判斷力，是指放棄仔細思考和判斷甚麼是正確的能力。"},{"en":"A student surrenders judgement when they follow a cruel group without thinking.","zh":"學生不經思考地跟隨殘酷群體時，就是放棄判斷力。"},{"en":"Keeping judgement helps people resist pressure and unfairness.","zh":"保持判斷力幫助人抵抗壓力和不公平。"},{"en":"This phrase protects moral thinking during conflict.","zh":"這個短語保護衝突中的道德思考。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"understanding of","meaning":"對……的理解","examples":[{"en":"These stories have changed my understanding of happiness.","zh":"這些故事改變了我對幸福的理解。"},{"en":"Understanding of something means how a person thinks about or interprets it.","zh":"對某事的理解，是指一個人如何思考或詮釋它。"},{"en":"Reading fables can change a student’s understanding of success.","zh":"閱讀寓言可以改變學生對成功的理解。"},{"en":"A deeper understanding of happiness may come from stories about kindness and loss.","zh":"對幸福更深的理解，可能來自關於善良和失去的故事。"},{"en":"This phrase shows a change in thinking.","zh":"這個短語顯示思想上的改變。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"happily ever after","meaning":"從此幸福快樂","examples":[{"en":"Fairy tales changed the writer’s understanding of “happily ever after.”","zh":"童話改變了作者對「從此幸福快樂」的理解。"},{"en":"Happily ever after is a traditional ending meaning the characters live happily from then on.","zh":"從此幸福快樂是傳統結尾，意思是角色從那時起快樂地生活。"},{"en":"As children, readers may think happily ever after means no more problems.","zh":"小時候，讀者可能以為從此幸福快樂代表再沒有問題。"},{"en":"A mature reading may see happily ever after as peace earned through character.","zh":"成熟的閱讀可能把從此幸福快樂看作透過品格得到的平靜。"},{"en":"This phrase represents the fairy-tale idea of lasting happiness.","zh":"這個短語代表童話中持久幸福的想法。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"imagined it as","meaning":"把它想像成","examples":[{"en":"When he was young, the writer imagined happiness as a palace.","zh":"年幼時，作者把幸福想像成宮殿。"},{"en":"Imagined it as means pictured or understood something in a certain way.","zh":"把它想像成，是指以某種方式想像或理解某事。"},{"en":"A child may imagine success as a trophy or a rich prize.","zh":"孩子可能把成功想像成獎盃或豐厚獎品。"},{"en":"Later experience can change how people imagine happiness.","zh":"後來的經驗可以改變人們如何想像幸福。"},{"en":"This phrase shows an earlier mental picture or belief.","zh":"這個短語顯示較早期的心理圖像或信念。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"treasure chest","meaning":"寶箱","examples":[{"en":"He once imagined happiness as a treasure chest.","zh":"他曾經把幸福想像成寶箱。"},{"en":"A treasure chest is a box filled with valuable things such as gold or jewels in stories.","zh":"寶箱是故事中裝滿黃金或珠寶等貴重物品的箱子。"},{"en":"Children may imagine a treasure chest as the final reward after an adventure.","zh":"孩子可能把寶箱想像成冒險後的最終獎賞。"},{"en":"Seeing happiness as a treasure chest can make it seem like something to possess.","zh":"把幸福看成寶箱，可能令幸福看似可以擁有的東西。"},{"en":"This phrase represents material or fantasy reward.","zh":"這個短語代表物質或幻想式獎賞。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"see it as something quieter","meaning":"把它看成更平靜的東西","examples":[{"en":"Now the writer sees happiness as something quieter.","zh":"現在，作者把幸福看成更平靜的東西。"},{"en":"See it as something quieter means understand it as calmer and less dramatic than before.","zh":"把它看成更平靜的東西，是指把它理解為比以前更安靜和沒那麼戲劇化。"},{"en":"An adult may see success as something quieter, such as health, peace, and honest work.","zh":"成年人可能把成功看成更平靜的東西，例如健康、平安和誠實工作。"},{"en":"This change shows maturity because happiness no longer needs to look grand.","zh":"這種改變顯示成熟，因為幸福不再需要看起來宏大。"},{"en":"The phrase contrasts loud fantasy with inner peace.","zh":"這個短語對比喧鬧幻想與內在平靜。"}],"source":"2023 Q5.pdf","sourcePage":13},{"front":"the peace of knowing that","meaning":"知道……而得到的平靜","examples":[{"en":"Happiness is the peace of knowing that one has lived well.","zh":"幸福是知道自己活得好而得到的平靜。"},{"en":"The peace of knowing that means the calm feeling that comes from being sure of something meaningful.","zh":"知道……而得到的平靜，是指因確信某件有意義的事而產生的安寧感。"},{"en":"A student may feel the peace of knowing that they tried honestly, even if they did not win.","zh":"即使沒有勝出，學生知道自己誠實努力後，可能得到平靜。"},{"en":"This kind of peace depends on conscience, not applause.","zh":"這種平靜取決於良心，而不是掌聲。"},{"en":"This phrase defines happiness as inner calm.","zh":"這個短語把幸福定義為內在安寧。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"loved sincerely","meaning":"真誠地愛過","examples":[{"en":"Real happiness means knowing that one has loved sincerely.","zh":"真正的幸福是知道自己真誠地愛過。"},{"en":"Loved sincerely means cared for others honestly and without pretending.","zh":"真誠地愛過，是指誠實而不假裝地關心別人。"},{"en":"A person has loved sincerely when they listen, forgive, and help without calculation.","zh":"當一個人聆聽、寬恕和不計回報地幫助時，就是曾真誠地愛過。"},{"en":"Sincere love may not be perfect, but it is truthful and steady.","zh":"真誠的愛未必完美，但它真實而穩定。"},{"en":"This phrase connects happiness with genuine care.","zh":"這個短語把幸福與真正關懷連接起來。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"endured pain","meaning":"承受痛苦","examples":[{"en":"Real happiness means having endured pain without losing kindness.","zh":"真正的幸福是曾承受痛苦而沒有失去善良。"},{"en":"Endured pain means suffered difficulty or hurt and continued through it.","zh":"承受痛苦是指經歷困難或傷害，並繼續走下去。"},{"en":"A student endured pain when they recovered slowly after losing a friendship.","zh":"學生失去友誼後慢慢恢復，就是承受痛苦。"},{"en":"Enduring pain well means not allowing hurt to destroy one’s values.","zh":"好好承受痛苦，是指不讓傷害摧毀自己的價值。"},{"en":"This phrase shows strength through suffering.","zh":"這個短語顯示透過苦難而來的力量。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"without losing kindness","meaning":"沒有失去善良","examples":[{"en":"One can endure pain without losing kindness.","zh":"一個人可以承受痛苦而沒有失去善良。"},{"en":"Without losing kindness means remaining caring and gentle even after being hurt.","zh":"沒有失去善良，是指即使受傷後仍保持關懷和溫柔。"},{"en":"A person does this when they refuse to treat others cruelly after being treated badly.","zh":"當人被惡劣對待後仍拒絕殘酷對待別人時，就是沒有失去善良。"},{"en":"Keeping kindness after pain is difficult, so it shows deep strength.","zh":"痛苦後仍保持善良很困難，所以它顯示深層力量。"},{"en":"This phrase defines moral endurance.","zh":"這個短語定義道德上的忍耐。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"stood up to injustice","meaning":"挺身面對不公義","examples":[{"en":"Real happiness means having stood up to injustice.","zh":"真正的幸福是曾挺身面對不公義。"},{"en":"Stood up to injustice means resisted unfair treatment with courage.","zh":"挺身面對不公義，是指以勇氣抵抗不公平對待。"},{"en":"A student stands up to injustice when they report bullying instead of staying silent.","zh":"學生舉報欺凌而不是保持沉默時，就是挺身面對不公義。"},{"en":"Standing up to injustice can be frightening, but it protects dignity and fairness.","zh":"挺身面對不公義可能令人害怕，但它保護尊嚴和公平。"},{"en":"This phrase connects happiness with moral courage.","zh":"這個短語把幸福與道德勇氣連接起來。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"without selling one’s soul","meaning":"沒有出賣靈魂","examples":[{"en":"One can stand up to injustice without selling one’s soul.","zh":"一個人可以挺身面對不公義，而沒有出賣靈魂。"},{"en":"Without selling one’s soul means without giving up one’s values, honesty, or moral self.","zh":"沒有出賣靈魂，是指沒有放棄自己的價值、誠實或道德自我。"},{"en":"A student refuses to sell their soul when they reject cheating even under pressure.","zh":"學生即使有壓力仍拒絕作弊，就是沒有出賣靈魂。"},{"en":"Fighting unfairness should not require becoming dishonest or cruel.","zh":"對抗不公平不應要求人變得不誠實或殘酷。"},{"en":"This phrase shows that moral identity must be protected.","zh":"這個短語顯示道德身份必須受到保護。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"childish escapes from life","meaning":"逃避人生的幼稚幻想","examples":[{"en":"Fairy tales are not childish escapes from life.","zh":"童話不是逃避人生的幼稚幻想。"},{"en":"Childish escapes from life means immature ways of avoiding real problems.","zh":"逃避人生的幼稚幻想，是指不成熟地避開真實問題的方式。"},{"en":"Some people think stories are childish escapes from life, but stories can teach courage.","zh":"有些人以為故事是逃避人生的幼稚幻想，但故事可以教導勇氣。"},{"en":"Reading fairy tales may help people face life rather than run from it.","zh":"閱讀童話可能幫助人面對人生，而不是逃離人生。"},{"en":"This phrase rejects the idea that imagination is useless.","zh":"這個短語否定想像力沒有用的想法。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"maps drawn in bright colours","meaning":"用鮮明色彩繪成的地圖","examples":[{"en":"Fairy tales are maps drawn in bright colours.","zh":"童話是用鮮明色彩繪成的地圖。"},{"en":"Maps drawn in bright colours means guides that use vivid images to help people understand life.","zh":"用鮮明色彩繪成的地圖，是指用生動圖像幫助人理解人生的指引。"},{"en":"A fable can be like a map drawn in bright colours because it shows a moral path clearly.","zh":"寓言可以像用鮮明色彩繪成的地圖，因為它清楚顯示道德道路。"},{"en":"Bright colours make difficult lessons easier for young readers to remember.","zh":"鮮明色彩令困難教訓更容易被年輕讀者記住。"},{"en":"This phrase presents stories as beautiful guidance.","zh":"這個短語把故事呈現為美麗的指引。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"walk through dark forests","meaning":"走過黑暗森林","examples":[{"en":"These stories show us how to walk through dark forests.","zh":"這些故事教我們如何走過黑暗森林。"},{"en":"To walk through dark forests means to continue through frightening or confusing difficulties.","zh":"走過黑暗森林，是指繼續穿越令人害怕或困惑的困難。"},{"en":"A student walks through a dark forest when facing family conflict with patience and honesty.","zh":"學生以耐性和誠實面對家庭衝突時，就是走過黑暗森林。"},{"en":"Stories help readers move through fear by offering examples of courage.","zh":"故事透過提供勇氣例子，幫助讀者穿越恐懼。"},{"en":"This phrase uses a fairy-tale image for real-life struggle.","zh":"這個短語用童話意象描寫真實人生掙扎。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"belong to a magical world","meaning":"屬於魔法世界","examples":[{"en":"The children and animals may belong to a magical world.","zh":"小朋友和動物可能屬於魔法世界。"},{"en":"Belong to a magical world means exist in an imaginary place where unusual or impossible things can happen.","zh":"屬於魔法世界，是指存在於一個不尋常或不可能事情可以發生的想像地方。"},{"en":"Talking animals and enchanted forests belong to a magical world.","zh":"會說話的動物和被施法的森林屬於魔法世界。"},{"en":"Magical worlds can still teach lessons that matter in ordinary life.","zh":"魔法世界仍可以教導在平凡生活中重要的道理。"},{"en":"This phrase separates the story setting from real life while keeping its meaning useful.","zh":"這個短語把故事背景與現實生活分開，同時保留其有用意思。"}],"source":"2023 Q5.pdf","sourcePage":14},{"front":"the lessons are real","meaning":"教訓是真實的","examples":[{"en":"The magical world is imaginary, but the lessons are real.","zh":"魔法世界是想像的，但教訓是真實的。"},{"en":"The lessons are real means the meanings or teachings apply to actual life.","zh":"教訓是真實的，是指故事意思或教導適用於真實生活。"},{"en":"A talking animal is imaginary, but its lesson about kindness can be real.","zh":"會說話的動物是想像的，但它關於善良的教訓可以是真實的。"},{"en":"Real lessons make fantasy stories valuable beyond entertainment.","zh":"真實教訓令幻想故事在娛樂以外仍有價值。"},{"en":"This phrase explains why old tales still matter.","zh":"這個短語解釋為何古老故事至今仍重要。"}],"source":"2023 Q5.pdf","sourcePage":15},{"front":"carry them into","meaning":"把它們帶進","examples":[{"en":"We should carry these lessons into our ordinary lives.","zh":"我們應把這些教訓帶進平凡生活。"},{"en":"To carry them into something means to bring ideas or values from one place into another situation.","zh":"把它們帶進某處，是指把想法或價值由一個地方帶到另一個情況中。"},{"en":"Students can carry fairy-tale lessons into school life by treating quiet classmates kindly.","zh":"學生可以透過善待安靜同學，把童話教訓帶進校園生活。"},{"en":"Lessons matter more when people carry them into action.","zh":"當人們把教訓帶進行動時，教訓就更有意義。"},{"en":"This phrase connects reading with daily behaviour.","zh":"這個短語把閱讀與日常行為連接起來。"}],"source":"2023 Q5.pdf","sourcePage":15},{"front":"ordinary lives","meaning":"平凡生活","examples":[{"en":"The lessons can be carried into our ordinary lives.","zh":"這些教訓可以被帶進我們的平凡生活。"},{"en":"Ordinary lives means normal daily living, including school, family, friendships, and work.","zh":"平凡生活是指普通日常生活，包括學校、家庭、友誼和工作。"},{"en":"Fairy-tale lessons enter ordinary lives when people forgive, listen, and act bravely.","zh":"當人們寬恕、聆聽和勇敢行動時，童話教訓就進入平凡生活。"},{"en":"Ordinary life gives people many chances to practise old wisdom.","zh":"平凡生活給人許多機會實踐古老智慧。"},{"en":"This phrase brings magical stories back to familiar reality.","zh":"這個短語把魔法故事帶回熟悉現實。"}],"source":"2023 Q5.pdf","sourcePage":15},{"front":"live perfectly ever after","meaning":"從此完美地生活","examples":[{"en":"We may not live perfectly ever after.","zh":"我們未必能從此完美地生活。"},{"en":"Live perfectly ever after means live from now on without mistakes, pain, or problems.","zh":"從此完美地生活，是指從現在開始再沒有錯誤、痛苦或問題地生活。"},{"en":"No family lives perfectly ever after because conflict and misunderstanding still appear.","zh":"沒有家庭能從此完美地生活，因為衝突和誤解仍會出現。"},{"en":"The goal is not perfect life but wiser and kinder living.","zh":"目標不是完美人生，而是更有智慧和更善良地生活。"},{"en":"This phrase gently corrects the fantasy of a flawless ending.","zh":"這個短語溫和地修正對無瑕結局的幻想。"}],"source":"2023 Q5.pdf","sourcePage":15},{"front":"live more wisely","meaning":"活得更有智慧","examples":[{"en":"These stories can help us live more wisely.","zh":"這些故事可以幫助我們活得更有智慧。"},{"en":"To live more wisely means to make better choices with understanding, patience, and judgement.","zh":"活得更有智慧，是指以理解、耐性和判斷力作出更好的選擇。"},{"en":"A student lives more wisely when they pause before quarrelling and choose respectful words.","zh":"學生在爭吵前停一停並選擇尊重的說話，就是活得更有智慧。"},{"en":"Stories help us live wisely by showing the results of good and bad choices.","zh":"故事透過展示好壞選擇的結果，幫助我們有智慧地生活。"},{"en":"This phrase presents reading as preparation for life.","zh":"這個短語把閱讀呈現為人生準備。"}],"source":"2023 Q5.pdf","sourcePage":15},{"front":"more gently","meaning":"活得更溫柔","examples":[{"en":"Fairy tales can help us live more gently.","zh":"童話可以幫助我們活得更溫柔。"},{"en":"More gently means with greater kindness, care, and softness toward others.","zh":"活得更溫柔，是指以更多善意、關懷和柔和對待別人。"},{"en":"A student lives more gently when they try to understand a difficult friend before judging.","zh":"學生先嘗試理解難相處的朋友再作判斷時，就是活得更溫柔。"},{"en":"Gentle living does not mean weakness; it means choosing care over cruelty.","zh":"溫柔地生活不代表軟弱，而是選擇關懷而非殘酷。"},{"en":"This phrase shows the emotional lesson of many fairy tales.","zh":"這個短語顯示許多童話中的情感教訓。"}],"source":"2023 Q5.pdf","sourcePage":15},{"front":"more bravely","meaning":"活得更勇敢","examples":[{"en":"Fables can help us live more bravely.","zh":"寓言可以幫助我們活得更勇敢。"},{"en":"More bravely means with greater courage to face fear, unfairness, or difficulty.","zh":"活得更勇敢，是指以更大的勇氣面對恐懼、不公平或困難。"},{"en":"A student lives more bravely when they speak calmly against unfair treatment.","zh":"學生冷靜地反對不公平對待時，就是活得更勇敢。"},{"en":"Brave living may involve patience, evidence, and refusal to surrender judgement.","zh":"勇敢地生活可能包括耐性、證據和拒絕放棄判斷力。"},{"en":"This phrase shows that stories can teach courage for ordinary life.","zh":"這個短語顯示故事可以教導日常生活中的勇氣。"}],"source":"2023 Q5.pdf","sourcePage":15}],"dse/writing/part-b/2023/Q6":[{"front":"without a safety net","meaning":"沒有安全網；沒有後備保障","examples":[{"en":"For ten minutes, we performed without a safety net.","zh":"在十分鐘裏，我們在沒有安全網的情況下表演。"},{"en":"Without a safety net means without a prepared plan, backup, or protection if something goes wrong.","zh":"without a safety net 指沒有預先準備的計劃、後備方案或出錯時的保障。"},{"en":"Speaking in front of the class without notes can feel like performing without a safety net.","zh":"不看筆記在全班面前說話，可能感覺像沒有安全網地表演。"},{"en":"This phrase suggests risk because the speaker cannot depend on a ready answer.","zh":"這個短語暗示風險，因為說話者不能依賴現成答案。"},{"en":"Improvisation feels exciting because students must continue without a safety net.","zh":"即興表演令人興奮，因為學生必須在沒有後備保障下繼續。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"Dear Diary","meaning":"親愛的日記","examples":[{"en":"A diary entry can begin with “Dear Diary”.","zh":"日記可以以 “Dear Diary” 開始。"},{"en":"Dear Diary is a common opening used when writing privately to one’s diary.","zh":"Dear Diary 是寫私人日記時常用的開首。"},{"en":"A student may write “Dear Diary” before describing a frightening school performance.","zh":"學生在描述一次可怕的學校表演前，可能會寫 “Dear Diary”。"},{"en":"This phrase makes the writing feel personal, honest, and private.","zh":"這個短語令文字感覺個人、真誠和私密。"},{"en":"It helps readers understand that the writer is sharing thoughts rather than making a formal report.","zh":"它幫助讀者明白作者是在分享想法，而不是寫正式報告。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"used to think","meaning":"以前以為","examples":[{"en":"I used to think that tests were the most terrifying part of school.","zh":"我以前以為測驗是學校裏最可怕的部分。"},{"en":"Used to think means believed something in the past, but may not believe it now.","zh":"used to think 指過去相信某事，但現在可能不再這樣想。"},{"en":"I used to think speaking English was impossible, but practice made it easier.","zh":"我以前以為說英語是不可能的，但練習令它變得較容易。"},{"en":"This phrase often shows that the writer’s opinion has changed after an experience.","zh":"這個短語常顯示作者的想法在經歷後改變了。"},{"en":"The diary writer used to fear tests most, but improvisation changed that idea.","zh":"日記作者以前最怕測驗，但即興表演改變了這個想法。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"the most terrifying sentence","meaning":"最令人害怕的一句話","examples":[{"en":"I used to think the most terrifying sentence in school was about taking out paper.","zh":"我以前以為學校裏最令人害怕的一句話是關於拿出紙張。"},{"en":"The most terrifying sentence means the words that make someone feel the greatest fear.","zh":"the most terrifying sentence 指最令人感到恐懼的一句話。"},{"en":"For many students, “There will be a surprise test” is the most terrifying sentence.","zh":"對許多學生來說，「今天有突擊測驗」是最令人害怕的一句話。"},{"en":"This phrase exaggerates fear in a humorous way.","zh":"這個短語以幽默方式誇張地表達恐懼。"},{"en":"In the diary, a sentence about performing without preparation becomes even scarier than a test.","zh":"在日記中，一句關於沒有準備就要表演的話，比測驗更可怕。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"take out a piece of paper","meaning":"拿出一張紙","examples":[{"en":"The teacher asked us to take out a piece of paper.","zh":"老師叫我們拿出一張紙。"},{"en":"To take out a piece of paper means to get a sheet of paper ready for writing.","zh":"take out a piece of paper 指拿出一張紙準備書寫。"},{"en":"Students may take out a piece of paper when the teacher announces a dictation.","zh":"當老師宣布默書時，學生可能要拿出一張紙。"},{"en":"This action often makes students nervous because it may mean a test is coming.","zh":"這個動作常令學生緊張，因為它可能代表測驗即將開始。"},{"en":"In school stories, taking out paper can signal sudden pressure.","zh":"在校園故事中，拿出紙張可以象徵突然出現的壓力。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"discover a worse one","meaning":"發現更糟的一句","examples":[{"en":"Today I discovered a worse sentence.","zh":"今天我發現更糟的一句話。"},{"en":"To discover a worse one means to find something even more unpleasant or frightening than the first example.","zh":"discover a worse one 指發現比第一個例子更不愉快或更可怕的事情。"},{"en":"I thought homework was bad, but I discovered a worse one: a group presentation tomorrow.","zh":"我以為功課已經很糟，但我發現更糟的是：明天要小組匯報。"},{"en":"This phrase creates contrast between an old fear and a new, stronger fear.","zh":"這個短語在舊恐懼和新的更大恐懼之間製造對比。"},{"en":"The writer discovers that performing without preparation is worse than a surprise test.","zh":"作者發現，沒有準備就表演比突擊測驗更糟。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"perform a comedy sketch","meaning":"表演喜劇小品","examples":[{"en":"We had ten minutes to perform a comedy sketch.","zh":"我們有十分鐘表演喜劇小品。"},{"en":"To perform a comedy sketch means to act out a short funny scene for an audience.","zh":"perform a comedy sketch 指向觀眾演出一段短而有趣的場景。"},{"en":"Students may perform a comedy sketch during an English drama lesson.","zh":"學生可能在英文戲劇課中表演喜劇小品。"},{"en":"A comedy sketch needs timing, reactions, and clear character choices.","zh":"喜劇小品需要節奏、反應和清楚的角色選擇。"},{"en":"Performing a sketch without preparation can be frightening but also exciting.","zh":"沒有準備就表演小品可能令人害怕，但也令人興奮。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"no script, no preparation","meaning":"沒有劇本，沒有準備","examples":[{"en":"We had no script and no preparation.","zh":"我們沒有劇本，也沒有準備。"},{"en":"No script, no preparation means there were no written lines and no time to plan.","zh":"no script, no preparation 指沒有寫好的台詞，也沒有時間計劃。"},{"en":"A student asked to speak without notes has no script and no preparation.","zh":"被要求不看筆記說話的學生，就是沒有劇本、沒有準備。"},{"en":"This phrase shows why the task feels risky and frightening.","zh":"這個短語顯示任務為何感覺有風險和可怕。"},{"en":"Improvisation begins when performers must act without a ready plan.","zh":"即興表演在表演者必須沒有現成計劃下行動時開始。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"drama teacher","meaning":"戲劇老師","examples":[{"en":"Our drama teacher gave us an improvisation exercise.","zh":"我們的戲劇老師給了我們一個即興表演練習。"},{"en":"A drama teacher is a teacher who teaches acting, performance, movement, voice, and stage skills.","zh":"drama teacher 指教授演戲、表演、動作、聲音和舞台技巧的老師。"},{"en":"A drama teacher may ask students to act out emotions without using words.","zh":"戲劇老師可能要求學生不用說話演出情緒。"},{"en":"Drama teachers help students build confidence through performance and teamwork.","zh":"戲劇老師透過表演和合作幫助學生建立信心。"},{"en":"In the diary, the drama teacher creates a challenge that teaches trust.","zh":"在日記中，戲劇老師設計了一個教人信任的挑戰。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"be meant to","meaning":"旨在；目的是","examples":[{"en":"The exercise was meant to help us trust one another.","zh":"這個練習旨在幫助我們互相信任。"},{"en":"Be meant to means be intended or designed to do something.","zh":"be meant to 指某事被設計或安排來達到某目的。"},{"en":"The group task was meant to teach students how to listen carefully.","zh":"小組任務旨在教學生如何細心聆聽。"},{"en":"This phrase explains the purpose behind an activity.","zh":"這個短語解釋活動背後的目的。"},{"en":"Although the exercise felt terrifying, it was meant to build confidence and trust.","zh":"雖然練習感覺可怕，但它的目的是建立信心和信任。"}],"source":"2023 Q6.pdf","sourcePage":1},{"front":"trust one another","meaning":"互相信任","examples":[{"en":"The exercise helped us trust one another.","zh":"這個練習幫助我們互相信任。"},{"en":"To trust one another means to believe that others will support you and not let you down.","zh":"trust one another 指相信其他人會支持你，不會讓你失望。"},{"en":"Team members trust one another when they share work fairly.","zh":"當隊員公平分工時，他們就是互相信任。"},{"en":"Improvisation needs trust because no one knows what will happen next.","zh":"即興表演需要信任，因為沒有人知道接下來會發生甚麼。"},{"en":"The students learned to trust one another by rescuing mistakes on stage.","zh":"學生透過在舞台上補救錯誤，學會互相信任。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"react honestly","meaning":"真誠地反應","examples":[{"en":"Improvisation teaches students to react honestly.","zh":"即興表演教學生真誠地反應。"},{"en":"To react honestly means to respond with real feelings instead of pretending.","zh":"react honestly 指用真實感受回應，而不是假裝。"},{"en":"A student reacts honestly when they laugh naturally at a surprising line.","zh":"學生聽到意外台詞時自然發笑，就是真誠地反應。"},{"en":"Honest reactions make a performance feel alive because they are not forced.","zh":"真誠反應令演出有生命力，因為它們不是強迫出來的。"},{"en":"In improvisation, reacting honestly is often better than trying to sound clever.","zh":"在即興表演中，真誠反應常比努力顯得聰明更好。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"in the moment","meaning":"在當下","examples":[{"en":"Comedy can be discovered in the moment.","zh":"喜劇可以在當下被發現。"},{"en":"In the moment means while something is happening, without planning far ahead.","zh":"in the moment 指在事情發生時，而不是很早計劃好。"},{"en":"A funny reply may appear in the moment during a class discussion.","zh":"在課堂討論中，有趣回應可能在當下出現。"},{"en":"Improvisers work in the moment because they must respond to what is happening now.","zh":"即興表演者在當下工作，因為他們必須回應眼前發生的事。"},{"en":"This phrase shows that creativity can come from attention, not only preparation.","zh":"這個短語顯示創意可以來自專注，而不只是準備。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"first attempt at","meaning":"第一次嘗試","examples":[{"en":"It was my first attempt at improvisation.","zh":"那是我第一次嘗試即興表演。"},{"en":"A first attempt at something is the first time someone tries to do it.","zh":"first attempt at something 指某人第一次嘗試做某事。"},{"en":"My first attempt at public speaking was shaky but memorable.","zh":"我第一次嘗試公開演說時很不穩定，但很難忘。"},{"en":"First attempts often feel frightening because mistakes are likely.","zh":"第一次嘗試常令人害怕，因為很可能出錯。"},{"en":"The writer’s first attempt at improvisation teaches her more than a smooth performance would.","zh":"作者第一次嘗試即興表演，比一次順利演出教會她更多。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"improvisation","meaning":"即興表演","examples":[{"en":"Improvisation requires quick thinking and trust.","zh":"即興表演需要快速思考和信任。"},{"en":"Improvisation is performance created without a fixed script or full preparation.","zh":"improvisation 指沒有固定劇本或完整準備下創作出來的表演。"},{"en":"Actors use improvisation when they invent lines and actions during the scene.","zh":"演員在場景中即時創作台詞和動作時，就是使用即興表演。"},{"en":"Improvisation works best when performers listen carefully and accept one another’s ideas.","zh":"當表演者細心聆聽並接受彼此想法時，即興表演最有效。"},{"en":"It can feel risky because every response must be created in the moment.","zh":"它可能感覺有風險，因為每個回應都必須在當下創造。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"felt less like…than…","meaning":"與其說像……不如說像……","examples":[{"en":"The exercise felt less like drama training than a test of courage.","zh":"這個練習與其說像戲劇訓練，不如說像勇氣測試。"},{"en":"Felt less like one thing than another means it seemed more like the second thing than the first.","zh":"felt less like one thing than another 指它感覺不像第一樣事，而更像第二樣事。"},{"en":"The interview felt less like a test than a friendly conversation.","zh":"面試與其說像考試，不如說像友善對話。"},{"en":"This pattern compares expectation with real feeling.","zh":"這個句式比較預期和真實感受。"},{"en":"The writer expected drama training, but the activity felt more like facing fear.","zh":"作者原本以為是戲劇訓練，但活動更像面對恐懼。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"drama training","meaning":"戲劇訓練","examples":[{"en":"The activity was supposed to be drama training.","zh":"這項活動本應是戲劇訓練。"},{"en":"Drama training is practice that helps students improve acting, voice, movement, and stage confidence.","zh":"drama training 指幫助學生改善演技、聲音、動作和舞台信心的練習。"},{"en":"Drama training may include warm-ups, role play, and short performances.","zh":"戲劇訓練可以包括熱身、角色扮演和短演出。"},{"en":"It can teach students how to listen, react, and work with others.","zh":"它可以教學生如何聆聽、反應和與他人合作。"},{"en":"In the diary, drama training becomes a surprising lesson in courage.","zh":"在日記中，戲劇訓練變成一堂令人意外的勇氣課。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"be pushed towards a cliff","meaning":"被推向懸崖","examples":[{"en":"Improvisation felt like being pushed towards a cliff.","zh":"即興表演感覺像被推向懸崖。"},{"en":"Being pushed towards a cliff means feeling forced toward a frightening situation with no easy escape.","zh":"being pushed towards a cliff 指感覺被迫走向可怕情況，而且不易逃開。"},{"en":"Giving a speech without preparation may feel like being pushed towards a cliff.","zh":"沒有準備就演講，可能感覺像被推向懸崖。"},{"en":"This image exaggerates fear and shows how risky the exercise felt.","zh":"這個畫面誇張地表達恐懼，顯示練習感覺多有風險。"},{"en":"The writer uses the cliff image because improvisation felt dangerous and sudden.","zh":"作者使用懸崖意象，因為即興表演感覺危險又突然。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"in school uniform","meaning":"穿着校服","examples":[{"en":"I felt as if I had been pushed towards a cliff in school uniform.","zh":"我感覺自己像穿着校服被推向懸崖。"},{"en":"In school uniform means wearing the clothes required by the school.","zh":"in school uniform 指穿着學校要求的服裝。"},{"en":"Students in school uniform stood nervously before the drama exercise began.","zh":"穿着校服的學生在戲劇練習開始前緊張地站着。"},{"en":"Mentioning school uniform makes the frightening scene feel ordinary and comic at the same time.","zh":"提到校服，令可怕場景同時感覺日常又有喜劇感。"},{"en":"The phrase reminds readers that the performer is still just a student.","zh":"這個短語提醒讀者，表演者仍只是一名學生。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"at that instant","meaning":"在那一刻","examples":[{"en":"At that instant, I wanted to find an emergency exit.","zh":"在那一刻，我想找一個緊急出口。"},{"en":"At that instant means at that exact moment.","zh":"at that instant 指就在那個確切時刻。"},{"en":"At that instant, the student realised she had forgotten her first line.","zh":"在那一刻，學生意識到自己忘了第一句台詞。"},{"en":"This phrase highlights a sudden feeling or reaction.","zh":"這個短語突顯突然出現的感受或反應。"},{"en":"The writer’s fear appears immediately when she understands the task.","zh":"當作者明白任務時，恐懼立刻出現。"}],"source":"2023 Q6.pdf","sourcePage":2},{"front":"emergency exit","meaning":"緊急出口","examples":[{"en":"All I wanted to discover was an emergency exit.","zh":"我唯一想找到的是緊急出口。"},{"en":"An emergency exit is a way out used when people need to escape danger quickly.","zh":"emergency exit 指人們需要快速逃離危險時使用的出口。"},{"en":"The emergency exit must stay clear during school performances.","zh":"學校表演期間，緊急出口必須保持暢通。"},{"en":"In this diary, the phrase is used humorously to show the writer wanted to escape.","zh":"在這篇日記中，這個短語以幽默方式顯示作者想逃走。"},{"en":"Wanting an emergency exit shows how frightening the improvisation exercise felt.","zh":"想找緊急出口顯示即興練習令人多害怕。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"be cleared into","meaning":"被清理成","examples":[{"en":"The classroom had been cleared into a small performance space.","zh":"課室被清理成一個小表演空間。"},{"en":"Be cleared into means furniture or objects were moved away so a place became something else.","zh":"be cleared into 指家具或物件被移走，令地方變成另一種用途。"},{"en":"The hall was cleared into a rehearsal space before the play began.","zh":"話劇開始前，禮堂被清理成排練空間。"},{"en":"This phrase shows a physical change in the room’s purpose.","zh":"這個短語顯示房間用途上的實際改變。"},{"en":"Clearing the classroom into a performance space made the exercise feel real.","zh":"把課室清理成表演空間，令練習感覺更真實。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"performance space","meaning":"表演空間","examples":[{"en":"The classroom became a small performance space.","zh":"課室變成一個小表演空間。"},{"en":"A performance space is an area used for acting, speaking, dancing, or showing work to an audience.","zh":"performance space 指用來演戲、演說、跳舞或向觀眾展示作品的地方。"},{"en":"A school hall can become a performance space during drama club practice.","zh":"戲劇學會練習時，學校禮堂可以變成表演空間。"},{"en":"A performance space changes how students behave because others are watching.","zh":"表演空間會改變學生行為，因為有人正在觀看。"},{"en":"Even a classroom can feel like a stage when it becomes a performance space.","zh":"即使是課室，一旦變成表演空間，也會感覺像舞台。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"pushed against the walls","meaning":"被推到牆邊","examples":[{"en":"The chairs were pushed against the walls.","zh":"椅子被推到牆邊。"},{"en":"Pushed against the walls means moved to the sides of the room and placed near the walls.","zh":"pushed against the walls 指被移到房間兩旁，靠近牆壁放置。"},{"en":"Before the dance lesson, desks were pushed against the walls to make space.","zh":"舞蹈課前，書桌被推到牆邊騰出空間。"},{"en":"Moving furniture changes the room from a learning area into an activity space.","zh":"移動家具會把課室由學習區變成活動空間。"},{"en":"The chairs against the walls make the centre of the classroom feel like a stage.","zh":"椅子靠在牆邊，令課室中央感覺像舞台。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"smell of dust","meaning":"有塵埃味","examples":[{"en":"The floor smelled of dust.","zh":"地板有塵埃味。"},{"en":"Smell of dust means have the dry, old smell of dust in the air or on the surface.","zh":"smell of dust 指空氣或表面有乾燥、陳舊的塵埃氣味。"},{"en":"The store room smelled of dust after being closed for months.","zh":"儲物室關了幾個月後，有一股塵埃味。"},{"en":"This sensory detail makes the classroom feel real and slightly uncomfortable.","zh":"這個感官細節令課室感覺真實，也有點不舒服。"},{"en":"The dusty smell adds to the nervous atmosphere before the performance.","zh":"塵埃味加強了表演前緊張的氣氛。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"nervous students","meaning":"緊張的學生","examples":[{"en":"Twenty nervous students stood in a crooked circle.","zh":"二十名緊張的學生站成一個歪歪斜斜的圓圈。"},{"en":"Nervous students are students who feel worried, tense, or afraid.","zh":"nervous students 指感到擔心、緊繃或害怕的學生。"},{"en":"Nervous students may laugh too loudly before a performance begins.","zh":"緊張的學生可能在表演開始前笑得太大聲。"},{"en":"Nervousness is common when students must do something new in front of others.","zh":"當學生要在人前做新事情時，緊張很常見。"},{"en":"The phrase helps readers feel the group’s fear before the sketch starts.","zh":"這個短語幫助讀者在小品開始前感受到整組人的恐懼。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"crooked circle","meaning":"歪歪斜斜的圓圈","examples":[{"en":"The students stood in a crooked circle.","zh":"學生站成一個歪歪斜斜的圓圈。"},{"en":"A crooked circle is a circle that is uneven, bent, or not neatly shaped.","zh":"crooked circle 指不平均、彎曲或不整齊的圓形。"},{"en":"Young children may form a crooked circle when they sit down for a game.","zh":"小朋友坐下玩遊戲時，可能會圍成一個歪歪斜斜的圓圈。"},{"en":"The crooked shape suggests nervousness and lack of order.","zh":"歪斜的形狀暗示緊張和缺乏秩序。"},{"en":"This detail makes the scene feel realistic because the students are not perfectly arranged.","zh":"這個細節令場景更真實，因為學生不是完美排列的。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"laugh too loudly","meaning":"笑得太大聲","examples":[{"en":"The students laughed too loudly because silence felt worse.","zh":"學生笑得太大聲，因為沉默感覺更糟。"},{"en":"Laugh too loudly means laugh with more volume than feels natural or necessary.","zh":"laugh too loudly 指笑聲比自然或需要的音量更大。"},{"en":"Students may laugh too loudly when they are embarrassed and do not know what to say.","zh":"學生尷尬又不知道說甚麼時，可能笑得太大聲。"},{"en":"Loud laughter can hide nervousness because silence feels uncomfortable.","zh":"大聲笑可以掩飾緊張，因為沉默令人不舒服。"},{"en":"In the diary, laughter is both a sign of fear and a way to survive it.","zh":"在日記中，笑聲既是恐懼的表現，也是面對恐懼的方法。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"silence would have been worse","meaning":"沉默會更糟","examples":[{"en":"We laughed too loudly because silence would have been worse.","zh":"我們笑得太大聲，因為沉默會更糟。"},{"en":"Silence would have been worse means quietness would have felt more awkward or frightening than laughter.","zh":"silence would have been worse 指安靜比笑聲更尷尬或更可怕。"},{"en":"During a failed joke, silence would have been worse than nervous laughter.","zh":"笑話失敗時，沉默可能比緊張的笑聲更糟。"},{"en":"This phrase shows that people sometimes choose noise to escape discomfort.","zh":"這個短語顯示人們有時會選擇聲音來逃避不舒服。"},{"en":"For the students, loud laughter was safer than facing their fear in silence.","zh":"對學生來說，大聲笑比在沉默中面對恐懼更安全。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"draw the situation","meaning":"抽到情境","examples":[{"en":"My group drew the situation for our sketch.","zh":"我的小組抽到小品的情境。"},{"en":"To draw the situation means to randomly choose the scene or setting for a performance.","zh":"draw the situation 指隨機抽取表演的場景或設定。"},{"en":"Each group drew a situation from a box before starting the improvisation game.","zh":"每組在開始即興遊戲前，從盒子裏抽到一個情境。"},{"en":"Drawing the situation creates surprise because performers cannot choose what they get.","zh":"抽情境會製造驚喜，因為表演者不能選擇自己得到甚麼。"},{"en":"The chosen situation gives the group a starting point for the sketch.","zh":"被抽到的情境給小組一個小品起點。"}],"source":"2023 Q6.pdf","sourcePage":3},{"front":"a family dinner","meaning":"家庭晚餐","examples":[{"en":"We had to act out a family dinner where everyone was hiding something.","zh":"我們要演出一場每個人都在隱瞞事情的家庭晚餐。"},{"en":"A family dinner is a meal shared by family members, often at home.","zh":"family dinner 指家庭成員通常在家中一起吃的一餐。"},{"en":"A family dinner can become dramatic if everyone has a secret.","zh":"如果每個人都有秘密，家庭晚餐可以變得很有戲劇性。"},{"en":"This setting is familiar, so the audience can understand the scene quickly.","zh":"這個場景很熟悉，所以觀眾能很快理解。"},{"en":"Ordinary settings often work well in comedy because small problems can become ridiculous.","zh":"普通場景常很適合喜劇，因為小問題可以變得荒謬。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"hide something","meaning":"隱瞞某事","examples":[{"en":"Everyone in the family dinner was hiding something.","zh":"家庭晚餐中的每個人都在隱瞞某事。"},{"en":"To hide something means to keep it secret or stop others from seeing it.","zh":"hide something 指把某事保密，或不讓別人看見。"},{"en":"A student may hide a bad test result because they feel ashamed.","zh":"學生可能因感到羞愧而隱瞞差的測驗成績。"},{"en":"Hidden secrets create tension because the audience waits for the truth to appear.","zh":"被隱瞞的秘密會製造緊張感，因為觀眾等待真相出現。"},{"en":"In comedy, hiding something can lead to awkward and funny situations.","zh":"在喜劇中，隱瞞某事可以帶來尷尬又有趣的情況。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"simple enough","meaning":"似乎夠簡單","examples":[{"en":"The situation seemed simple enough at first.","zh":"起初，這個情境似乎夠簡單。"},{"en":"Simple enough means easy or clear enough to handle.","zh":"simple enough 指足夠容易或清楚，可以處理。"},{"en":"The game seemed simple enough until the teacher added a time limit.","zh":"這個遊戲似乎夠簡單，直到老師加上時間限制。"},{"en":"This phrase often prepares readers for a sudden difficulty.","zh":"這個短語常為讀者預告突然出現的困難。"},{"en":"The family dinner sounded easy, but improvisation made it unpredictable.","zh":"家庭晚餐聽起來容易，但即興表演令它變得難以預測。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"clap her hands","meaning":"拍手","examples":[{"en":"Ms Lee clapped her hands to start the exercise.","zh":"李老師拍手開始練習。"},{"en":"To clap her hands means to hit her hands together to make a sound.","zh":"clap her hands 指把雙手拍在一起發出聲音。"},{"en":"A teacher may clap her hands to get students’ attention.","zh":"老師可能拍手來吸引學生注意。"},{"en":"The clap works like a signal that the performance must begin.","zh":"拍手像一個信號，表示表演必須開始。"},{"en":"In the diary, one clap turns nervous waiting into real action.","zh":"在日記中，一下拍手把緊張等待變成真正行動。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"become impossible","meaning":"變得不可能","examples":[{"en":"Suddenly, the simple situation became impossible.","zh":"突然，簡單的情境變得不可能。"},{"en":"Become impossible means change from manageable to extremely difficult or unable to be done.","zh":"become impossible 指由可處理變成極其困難或無法完成。"},{"en":"The worksheet became impossible when the student realised half the instructions were missing.","zh":"當學生發現一半指示不見了，工作紙變得不可能完成。"},{"en":"This phrase shows how fear can make even a simple task feel too hard.","zh":"這個短語顯示恐懼如何令簡單任務也變得太難。"},{"en":"Improvisation became impossible for the writer because there was no time to plan.","zh":"對作者來說，即興表演變得不可能，因為沒有時間計劃。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"walk onto the imaginary stage","meaning":"走上想像中的舞台","examples":[{"en":"I walked onto the imaginary stage as the mother.","zh":"我以母親的角色走上想像中的舞台。"},{"en":"To walk onto the imaginary stage means to enter the acting area even though there is no real stage.","zh":"walk onto the imaginary stage 指走進表演區，即使那裏沒有真正舞台。"},{"en":"A student may walk onto the imaginary stage in the classroom and pretend to be a king.","zh":"學生可能走上課室裏想像中的舞台，假裝自己是國王。"},{"en":"This phrase shows how imagination turns an ordinary floor into a performance area.","zh":"這個短語顯示想像力如何把普通地板變成表演區。"},{"en":"The writer steps into the role before knowing what will happen.","zh":"作者在不知道接下來會發生甚麼前，先走進角色。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"imaginary stage","meaning":"想像中的舞台","examples":[{"en":"The classroom floor became our imaginary stage.","zh":"課室地板變成我們想像中的舞台。"},{"en":"An imaginary stage is a performance space created in people’s minds rather than built physically.","zh":"imaginary stage 指在人們腦海中創造，而不是實際建造的表演空間。"},{"en":"During drama class, a corner of the room can become an imaginary stage.","zh":"戲劇課中，房間一角可以成為想像中的舞台。"},{"en":"Imaginary stages help students practise performance without needing special equipment.","zh":"想像中的舞台幫助學生在沒有特別設備下練習表演。"},{"en":"The phrase shows that theatre can happen wherever people agree to imagine it.","zh":"這個短語顯示只要人們同意想像，劇場就可以在任何地方發生。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"invisible chair","meaning":"隱形椅子","examples":[{"en":"Jason sat on an invisible chair.","zh":"Jason 坐在一張隱形椅子上。"},{"en":"An invisible chair is an imagined chair that the actor pretends to use.","zh":"invisible chair 指演員假裝使用的想像椅子。"},{"en":"In drama class, students may sit on an invisible chair to practise physical control.","zh":"在戲劇課中，學生可能坐在隱形椅子上練習身體控制。"},{"en":"Invisible objects require clear acting so the audience understands what is happening.","zh":"隱形物件需要清楚演技，讓觀眾明白正在發生甚麼。"},{"en":"Jason’s invisible chair makes the scene funny because he treats it as real.","zh":"Jason 的隱形椅子令場面有趣，因為他把它當成真的。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"invisible soup","meaning":"隱形湯","examples":[{"en":"Jason began eating invisible soup seriously.","zh":"Jason 開始認真地喝隱形湯。"},{"en":"Invisible soup is imagined soup that an actor pretends to eat.","zh":"invisible soup 指演員假裝正在喝的想像湯。"},{"en":"A performer can make invisible soup believable by holding an imaginary bowl and spoon.","zh":"表演者可以透過拿着想像中的碗和湯匙，令隱形湯變得可信。"},{"en":"Pretending carefully can turn nothing into something the audience accepts.","zh":"細心假裝可以把沒有的東西變成觀眾接受的東西。"},{"en":"Jason’s invisible soup becomes funny because he eats it with complete seriousness.","zh":"Jason 的隱形湯變得好笑，因為他非常認真地喝。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"with such seriousness that","meaning":"如此認真，以致","examples":[{"en":"Jason ate the invisible soup with such seriousness that the class started giggling.","zh":"Jason 如此認真地喝隱形湯，以致全班開始咯咯笑。"},{"en":"With such seriousness that means in such a serious way that it caused a result.","zh":"with such seriousness that 指以非常認真的方式做某事，並造成某結果。"},{"en":"The student read the silly poem with such seriousness that everyone laughed.","zh":"那名學生如此認真地朗讀荒謬詩歌，以致大家都笑了。"},{"en":"This pattern connects the strength of an action with its effect.","zh":"這個句式把行動的強度與其效果連接起來。"},{"en":"Jason’s serious acting made the ridiculous situation even funnier.","zh":"Jason 認真的演技令荒謬情況變得更有趣。"}],"source":"2023 Q6.pdf","sourcePage":4},{"front":"start giggling","meaning":"開始咯咯笑","examples":[{"en":"The class started giggling at Jason’s acting.","zh":"全班因 Jason 的演技開始咯咯笑。"},{"en":"To start giggling means to begin laughing quietly or nervously.","zh":"start giggling 指開始輕聲或緊張地笑。"},{"en":"Students may start giggling when a serious performance becomes unexpectedly silly.","zh":"當嚴肅表演突然變得荒謬時，學生可能開始咯咯笑。"},{"en":"Giggling can show amusement, nervousness, or both at the same time.","zh":"咯咯笑可以同時顯示好笑、緊張，或兩者都有。"},{"en":"The class’s giggling tells the performers that the comedy is beginning to work.","zh":"全班的笑聲告訴表演者，喜劇開始奏效。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"something was working","meaning":"有些東西開始奏效","examples":[{"en":"I told myself that something was working.","zh":"我告訴自己，有些東西開始奏效。"},{"en":"Something was working means part of the plan or performance was beginning to succeed.","zh":"something was working 指計劃或表演中的某部分開始成功。"},{"en":"When the audience laughed, the nervous speaker realised something was working.","zh":"當觀眾笑了，緊張的講者意識到有些東西開始奏效。"},{"en":"This phrase gives the performer a small sign of hope.","zh":"這個短語給表演者一個小小希望信號。"},{"en":"In improvisation, even one laugh can show that the scene has life.","zh":"在即興表演中，即使只是一聲笑，也能顯示場面有生命力。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"burst in","meaning":"突然闖進來","examples":[{"en":"Mandy burst in with a strange announcement.","zh":"Mandy 突然闖進來，宣布了一件奇怪的事。"},{"en":"To burst in means to enter suddenly and energetically.","zh":"burst in 指突然並充滿能量地進入。"},{"en":"A student burst in late and shouted that the rehearsal had moved rooms.","zh":"一名學生遲到闖進來，大叫排練改了房間。"},{"en":"Bursting in can change a scene quickly because it brings surprise and energy.","zh":"突然闖入可以迅速改變場面，因為它帶來驚喜和能量。"},{"en":"Mandy’s sudden entrance pushes the sketch into complete absurdity.","zh":"Mandy 的突然出現把小品推向完全荒謬。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"adopt a crocodile","meaning":"收養一條鱷魚","examples":[{"en":"Mandy announced that she had adopted a very small crocodile.","zh":"Mandy 宣布她收養了一條很小的鱷魚。"},{"en":"To adopt a crocodile means to take a crocodile into one’s care, usually in an absurd or impossible context here.","zh":"adopt a crocodile 指把鱷魚帶入自己的照顧中，在這裏通常是荒謬或不可能的情境。"},{"en":"In a comedy sketch, a child might claim to adopt a crocodile as a family pet.","zh":"在喜劇小品中，孩子可能聲稱收養了一條鱷魚作家庭寵物。"},{"en":"The idea is funny because crocodiles are dangerous and unsuitable for homes.","zh":"這個想法好笑，因為鱷魚危險，而且不適合家居。"},{"en":"This ridiculous announcement gives the group something surprising to build on.","zh":"這個荒謬宣布給小組一個意外元素去發展。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"keep it in her school bag","meaning":"把它放在書包裏","examples":[{"en":"She said she was keeping the crocodile in her school bag.","zh":"她說她把那條鱷魚放在書包裏。"},{"en":"To keep it in her school bag means to store the animal inside the bag she takes to school.","zh":"keep it in her school bag 指把那隻動物放在她帶回學校的書包內。"},{"en":"A student might keep a secret note in her school bag, but not a crocodile.","zh":"學生可能把秘密字條放在書包裏，但不會把鱷魚放進去。"},{"en":"The image is funny because the bag is far too ordinary for such a dangerous animal.","zh":"這個畫面好笑，因為書包對這麼危險的動物來說太普通。"},{"en":"This detail makes the sketch more ridiculous and memorable.","zh":"這個細節令小品更荒謬和難忘。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"my mind went blank","meaning":"腦袋一片空白","examples":[{"en":"When I heard about the crocodile, my mind went blank.","zh":"當我聽到那條鱷魚時，我腦袋一片空白。"},{"en":"My mind went blank means I suddenly could not think of anything to say or do.","zh":"my mind went blank 指我突然想不到任何可說或可做的事。"},{"en":"During the oral exam, my mind went blank when the teacher asked a difficult question.","zh":"口試時，老師問了一條困難問題，我腦袋一片空白。"},{"en":"This often happens when people feel shocked, nervous, or under pressure.","zh":"當人感到震驚、緊張或受壓時，這種情況常會發生。"},{"en":"In improvisation, a blank mind is frightening because the scene must continue.","zh":"在即興表演中，腦袋空白很可怕，因為場面必須繼續。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"for one horrible second","meaning":"可怕的一秒間","examples":[{"en":"For one horrible second, I did not know what to say.","zh":"在可怕的一秒間，我不知道該說甚麼。"},{"en":"For one horrible second means during one very short but frightening moment.","zh":"for one horrible second 指在一個非常短但可怕的時刻裏。"},{"en":"For one horrible second, the speaker forgot the next line of the speech.","zh":"在可怕的一秒間，講者忘記了演講下一句。"},{"en":"This phrase stretches a tiny moment because fear makes it feel longer.","zh":"這個短語拉長一個小時刻，因為恐懼令它感覺更久。"},{"en":"The writer uses it to show how panic can appear suddenly.","zh":"作者用它顯示恐慌如何突然出現。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"as if someone had switched off the lights inside my head","meaning":"彷彿有人關掉我腦內的燈","examples":[{"en":"I felt as if someone had switched off the lights inside my head.","zh":"我感覺彷彿有人關掉我腦內的燈。"},{"en":"This phrase means the writer suddenly could not think clearly, as though her thoughts had gone dark.","zh":"這個短語指作者突然不能清楚思考，好像思想變得一片黑暗。"},{"en":"During the debate, he felt as if someone had switched off the lights inside his head.","zh":"辯論時，他感覺彷彿有人關掉他腦內的燈。"},{"en":"The image makes mental panic feel visual and easy to imagine.","zh":"這個畫面令心理恐慌變得視覺化，容易想像。"},{"en":"It shows that fear can stop thoughts as quickly as turning off a light.","zh":"它顯示恐懼可以像關燈一樣迅速停止思考。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"switch off the lights","meaning":"關燈","examples":[{"en":"It felt as if someone had switched off the lights inside my head.","zh":"那感覺像有人關掉我腦內的燈。"},{"en":"To switch off the lights means to turn the lights off.","zh":"switch off the lights 指把燈關掉。"},{"en":"The teacher switched off the lights before showing a video.","zh":"老師播放影片前關燈。"},{"en":"In the diary, the phrase is used metaphorically to show the mind going blank.","zh":"在日記中，這個短語以比喻方式顯示腦袋一片空白。"},{"en":"Turning off lights suggests sudden darkness, just like sudden panic.","zh":"關燈暗示突然的黑暗，就像突然的恐慌。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"soon realised","meaning":"很快意識到","examples":[{"en":"I soon realised that improvisation is not about perfect ideas.","zh":"我很快意識到即興表演不是關於完美想法。"},{"en":"Soon realised means understood something after a short time.","zh":"soon realised 指在短時間後明白某事。"},{"en":"I soon realised that the audience was kinder than I had expected.","zh":"我很快意識到觀眾比我預期中友善。"},{"en":"This phrase shows a quick change in understanding.","zh":"這個短語顯示理解上的快速轉變。"},{"en":"The writer soon realises that listening matters more than having clever ideas.","zh":"作者很快意識到，聆聽比擁有聰明想法更重要。"}],"source":"2023 Q6.pdf","sourcePage":5},{"front":"not about waiting for","meaning":"不是等待","examples":[{"en":"Improvisation is not about waiting for the perfect idea.","zh":"即興表演不是等待完美想法。"},{"en":"Not about waiting for means the main point is not to delay until something ideal appears.","zh":"not about waiting for 指重點不是拖延到理想事物出現。"},{"en":"Learning English is not about waiting for confidence before speaking.","zh":"學英語不是等待有信心才開口。"},{"en":"This phrase rejects a passive approach and encourages action.","zh":"這個短語否定被動做法，並鼓勵行動。"},{"en":"In improvisation, waiting too long can kill the energy of the scene.","zh":"在即興表演中，等待太久會殺死場面的能量。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"the perfect idea","meaning":"完美想法","examples":[{"en":"I stopped waiting for the perfect idea.","zh":"我停止等待完美想法。"},{"en":"The perfect idea means an ideal answer or plan that feels completely right.","zh":"the perfect idea 指感覺完全正確的理想答案或計劃。"},{"en":"A writer may waste time waiting for the perfect idea before starting an essay.","zh":"作者可能在開始文章前浪費時間等待完美想法。"},{"en":"Waiting for perfection can stop people from trying anything at all.","zh":"等待完美可能會阻止人嘗試任何事情。"},{"en":"Improvisation teaches that a usable idea is often better than a perfect idea.","zh":"即興表演教人，可用的想法常比完美想法更好。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"accept the ridiculous gift","meaning":"接受荒謬的禮物","examples":[{"en":"Improvisation means accepting the ridiculous gift thrown at you.","zh":"即興表演意味着接受拋給你的荒謬禮物。"},{"en":"Accept the ridiculous gift means take a strange idea from another performer and use it instead of rejecting it.","zh":"accept the ridiculous gift 指接受另一位表演者提出的奇怪想法，並使用它而不是拒絕它。"},{"en":"If someone says the classroom is a spaceship, a good improviser accepts the ridiculous gift.","zh":"如果有人說課室是一艘太空船，好的即興表演者會接受這份荒謬禮物。"},{"en":"Accepting strange ideas keeps the scene alive because performers build together.","zh":"接受奇怪想法令場面保持生命力，因為表演者一起建立故事。"},{"en":"The crocodile idea becomes useful only when the narrator accepts it.","zh":"鱷魚這個想法只有在敘述者接受後才變得有用。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"thrown at you","meaning":"拋給你的","examples":[{"en":"A ridiculous idea may be thrown at you during improvisation.","zh":"在即興表演中，一個荒謬想法可能會被拋給你。"},{"en":"Thrown at you means given to you suddenly, often without warning.","zh":"thrown at you 指突然給你，通常沒有預警。"},{"en":"In a group discussion, a difficult question may be thrown at you unexpectedly.","zh":"在小組討論中，一條困難問題可能會意外地被拋給你。"},{"en":"This phrase suggests pressure because you must respond quickly.","zh":"這個短語暗示壓力，因為你必須快速回應。"},{"en":"Improvisers learn to use whatever idea is thrown at them.","zh":"即興表演者學會使用任何被拋給他們的想法。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"turn it into something usable","meaning":"把它變成可用的東西","examples":[{"en":"A good improviser turns a strange idea into something usable.","zh":"好的即興表演者會把奇怪想法變成可用的東西。"},{"en":"To turn it into something usable means to change a difficult or strange idea into something that helps the scene.","zh":"turn it into something usable 指把困難或奇怪的想法變成有助場面的東西。"},{"en":"A performer can turn an accidental mistake into something usable by treating it as part of the story.","zh":"表演者可以把意外錯誤視為故事一部分，從而把它變成可用的東西。"},{"en":"This skill matters because improvisation depends on quick adaptation.","zh":"這種技能很重要，因為即興表演依賴快速適應。"},{"en":"The narrator turns the crocodile idea into comedy by accepting it seriously.","zh":"敘述者透過認真接受鱷魚想法，把它變成喜劇。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"put one hand on my chest","meaning":"把一隻手放在胸口","examples":[{"en":"I gasped and put one hand on my chest.","zh":"我倒抽一口氣，把一隻手放在胸口。"},{"en":"To put one hand on my chest means to place one hand over the front of the body, often to show shock.","zh":"put one hand on my chest 指把一隻手放在身體前方胸口位置，常用來表示震驚。"},{"en":"An actor may put one hand on the chest after hearing surprising news.","zh":"演員聽到驚人消息後，可能把一隻手放在胸口。"},{"en":"This gesture makes emotion visible to the audience.","zh":"這個動作令情緒對觀眾可見。"},{"en":"The narrator uses the gesture to turn panic into performance.","zh":"敘述者用這個動作把恐慌轉化為表演。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"not again","meaning":"不會又來吧","examples":[{"en":"I shouted, “Not again!” when Mandy mentioned the crocodile.","zh":"Mandy 提到鱷魚時，我大叫：「不會又來吧！」"},{"en":"Not again means something unwanted or ridiculous has happened before and is happening another time.","zh":"not again 指不想要或荒謬的事情以前發生過，現在又再次發生。"},{"en":"When the projector failed for the third time, the teacher sighed, “Not again!”","zh":"投影機第三次壞掉時，老師嘆氣說：「不會又來吧！」"},{"en":"This phrase can be funny because it suggests a strange problem is already familiar.","zh":"這個短語可以很好笑，因為它暗示奇怪問題早已熟悉。"},{"en":"Saying “Not again!” made the crocodile sound like an old family problem.","zh":"說「不會又來吧！」令鱷魚聽起來像舊有家庭問題。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"no reptiles at dinner","meaning":"晚餐時不准有爬蟲類動物","examples":[{"en":"We had agreed that there would be no reptiles at dinner.","zh":"我們已經同意晚餐時不准有爬蟲類動物。"},{"en":"No reptiles at dinner means animals such as crocodiles, snakes, or lizards are not allowed during the meal.","zh":"no reptiles at dinner 指晚餐期間不准有鱷魚、蛇或蜥蜴等爬蟲類動物。"},{"en":"In a comedy scene, a parent may announce, “No reptiles at dinner.”","zh":"在喜劇場景中，家長可能宣布：「晚餐時不准有爬蟲類動物。」"},{"en":"The sentence is funny because it treats an absurd rule as if it were normal.","zh":"這句好笑，因為它把荒謬規則當成正常事情處理。"},{"en":"This line helps the group build a family history inside the sketch.","zh":"這句台詞幫助小組在小品中建立家庭歷史。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"the room exploded","meaning":"全場爆笑","examples":[{"en":"The room exploded with laughter.","zh":"全場爆笑。"},{"en":"The room exploded means everyone suddenly reacted loudly and strongly.","zh":"the room exploded 指所有人突然大聲而強烈地作出反應。"},{"en":"The classroom exploded with laughter when the teacher’s joke landed.","zh":"老師的笑話奏效時，課室全場爆笑。"},{"en":"This phrase makes laughter sound powerful, sudden, and shared.","zh":"這個短語令笑聲聽起來強烈、突然而共同。"},{"en":"The room’s reaction gave the performer confidence to continue.","zh":"全場的反應給表演者信心繼續下去。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"save me","meaning":"救了我","examples":[{"en":"That laugh saved me.","zh":"那陣笑聲救了我。"},{"en":"Save me means rescue me from fear, failure, embarrassment, or danger.","zh":"save me 指把我從恐懼、失敗、尷尬或危險中救出來。"},{"en":"A friend’s encouraging smile saved me when I forgot my speech.","zh":"當我忘記演講時，朋友鼓勵的微笑救了我。"},{"en":"In performance, one laugh can save a nervous actor by showing the audience is supportive.","zh":"在表演中，一聲笑可以透過顯示觀眾支持來救回緊張演員。"},{"en":"The laugh saved the narrator because it turned panic into courage.","zh":"那陣笑聲救了敘述者，因為它把恐慌變成勇氣。"}],"source":"2023 Q6.pdf","sourcePage":6},{"front":"not just noise","meaning":"不只是聲音","examples":[{"en":"The laugh was not just noise.","zh":"那陣笑聲不只是聲音。"},{"en":"Not just noise means the sound had deeper meaning, not only volume.","zh":"not just noise 指那聲音有更深意義，而不只是音量。"},{"en":"Applause after a nervous speech is not just noise; it can be encouragement.","zh":"緊張演講後的掌聲不只是聲音；它可以是鼓勵。"},{"en":"This phrase helps show that a simple sound can carry emotional support.","zh":"這個短語幫助顯示簡單聲音可以承載情感支持。"},{"en":"The class’s laughter meant permission, acceptance, and trust.","zh":"全班的笑聲代表允許、接納和信任。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"permission to be foolish","meaning":"容許自己變得愚蠢","examples":[{"en":"The laugh gave me permission to be foolish.","zh":"那陣笑聲容許我變得愚蠢。"},{"en":"Permission to be foolish means feeling allowed to act silly without shame.","zh":"permission to be foolish 指感覺自己可以做傻事而不必羞愧。"},{"en":"A friendly audience gives performers permission to be foolish and playful.","zh":"友善觀眾會容許表演者變得愚蠢和好玩。"},{"en":"Comedy needs this permission because fear of embarrassment kills creativity.","zh":"喜劇需要這種允許，因為害怕尷尬會殺死創意。"},{"en":"Once the narrator felt allowed to be foolish, she became braver.","zh":"一旦敘述者感到可以愚蠢，她就變得更勇敢。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"be bold","meaning":"大膽","examples":[{"en":"The laugh gave me permission to be bold.","zh":"那陣笑聲容許我變得大膽。"},{"en":"To be bold means to act bravely, confidently, or without too much fear.","zh":"be bold 指勇敢、自信，或沒有太多恐懼地行動。"},{"en":"A student must be bold to try a strange idea in front of the class.","zh":"學生要大膽，才敢在全班面前嘗試奇怪想法。"},{"en":"Being bold does not mean being perfect; it means being willing to risk embarrassment.","zh":"大膽不代表完美；而是願意冒尷尬的風險。"},{"en":"Improvisation rewards bold choices because they give others something to build on.","zh":"即興表演會回報大膽選擇，因為它們給其他人可發展的材料。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"fail and continue anyway","meaning":"即使失敗也繼續下去","examples":[{"en":"Improvisation allows us to fail and continue anyway.","zh":"即興表演容許我們即使失敗也繼續下去。"},{"en":"To fail and continue anyway means to make a mistake but keep going.","zh":"fail and continue anyway 指出錯後仍然繼續。"},{"en":"During a speech, a student may forget a word, smile, and continue anyway.","zh":"演講時，學生可能忘記一個字，微笑後仍繼續下去。"},{"en":"This ability matters because stopping can make a small mistake feel larger.","zh":"這種能力很重要，因為停下來會令小錯誤顯得更大。"},{"en":"Improvisation teaches that mistakes can become part of the performance.","zh":"即興表演教人，錯誤可以成為演出的一部分。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"cheerful disaster","meaning":"開心混亂的災難","examples":[{"en":"After that, the sketch became a cheerful disaster.","zh":"之後，小品變成一場開心混亂的災難。"},{"en":"A cheerful disaster is something messy and imperfect but still enjoyable.","zh":"cheerful disaster 指凌亂、不完美，但仍令人享受的事情。"},{"en":"The class party became a cheerful disaster when the games went wrong but everyone laughed.","zh":"遊戲出錯但大家都笑時，班會變成開心混亂的災難。"},{"en":"This phrase combines failure with happiness.","zh":"這個短語把失敗與快樂結合起來。"},{"en":"The sketch was chaotic, but the shared laughter made it successful in its own way.","zh":"小品很混亂，但共同笑聲令它以自己的方式成功。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"crawl under the table","meaning":"爬到桌下","examples":[{"en":"Alvin crawled under the imaginary table.","zh":"Alvin 爬到想像中的桌下。"},{"en":"To crawl under the table means to move on hands and knees beneath a table.","zh":"crawl under the table 指用手和膝蓋在桌下移動。"},{"en":"A child may crawl under the table during a game of hide-and-seek.","zh":"孩子玩捉迷藏時可能爬到桌下。"},{"en":"In performance, crawling under an imaginary table requires clear body movement.","zh":"在表演中，爬到想像中的桌下需要清楚身體動作。"},{"en":"Alvin’s action made the invisible family dinner feel more physical and funny.","zh":"Alvin 的動作令隱形家庭晚餐感覺更具體、更有趣。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"claim to be","meaning":"聲稱自己是","examples":[{"en":"Alvin claimed to be the crocodile’s lawyer.","zh":"Alvin 聲稱自己是那條鱷魚的律師。"},{"en":"To claim to be something means to say that one is that thing, whether or not it is believable.","zh":"claim to be something 指聲稱自己是某個身份，不論是否可信。"},{"en":"In a comedy sketch, a student may claim to be a famous detective.","zh":"在喜劇小品中，學生可能聲稱自己是著名偵探。"},{"en":"This phrase can create humour when the claim is surprising or ridiculous.","zh":"當聲稱內容令人意外或荒謬時，這個短語可以製造幽默。"},{"en":"Alvin’s claim makes the crocodile story even more absurd.","zh":"Alvin 的聲稱令鱷魚故事更加荒謬。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"discipline the school bag","meaning":"管教那個書包","examples":[{"en":"Jason tried to discipline the school bag with a soup spoon.","zh":"Jason 嘗試用湯匙管教那個書包。"},{"en":"To discipline the school bag means to treat the bag as if it were a misbehaving child or animal.","zh":"discipline the school bag 指把書包當成行為不當的孩子或動物來管教。"},{"en":"In a silly sketch, a teacher might try to discipline a noisy pencil case.","zh":"在荒謬小品中，老師可能嘗試管教一個吵鬧的筆袋。"},{"en":"The humour comes from giving a school bag human-like behaviour.","zh":"幽默來自把人的行為賦予書包。"},{"en":"This action accepts the crocodile idea and turns it into physical comedy.","zh":"這個動作接受了鱷魚想法，並把它變成肢體喜劇。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"with a soup spoon","meaning":"用湯匙","examples":[{"en":"Jason used a soup spoon to discipline the school bag.","zh":"Jason 用湯匙管教那個書包。"},{"en":"With a soup spoon means using a spoon for soup as the tool.","zh":"with a soup spoon 指使用喝湯用的湯匙作工具。"},{"en":"A child may stir noodles with a soup spoon during dinner.","zh":"孩子吃晚飯時可能用湯匙攪拌麵條。"},{"en":"Using a soup spoon as a serious object in a ridiculous scene creates comedy.","zh":"在荒謬場景中把湯匙當成嚴肅工具使用，會製造喜劇。"},{"en":"The ordinary spoon makes the imaginary crocodile situation even funnier.","zh":"普通湯匙令想像中的鱷魚情境更加好笑。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"apparently","meaning":"看來；顯然","examples":[{"en":"Apparently, I had become the exhausted mother of three humans and one reptile.","zh":"看來，我已成為三個人類和一隻爬蟲類動物的筋疲力盡母親。"},{"en":"Apparently means it seems that something is true, often in a slightly surprised tone.","zh":"apparently 指某事似乎是真的，常帶有一點驚訝語氣。"},{"en":"Apparently, our group had turned a simple dinner into a crocodile trial.","zh":"看來，我們小組把一場簡單晚餐變成了鱷魚審訊。"},{"en":"This word is useful when the speaker is discovering the situation at the same time as the audience.","zh":"當說話者和觀眾同時發現情況時，這個詞很有用。"},{"en":"It adds humour because the narrator sounds surprised by her own role.","zh":"它增添幽默，因為敘述者似乎也對自己的角色感到驚訝。"}],"source":"2023 Q6.pdf","sourcePage":7},{"front":"exhausted mother","meaning":"筋疲力盡的母親","examples":[{"en":"I played an exhausted mother in the sketch.","zh":"我在小品中扮演一位筋疲力盡的母親。"},{"en":"An exhausted mother is a mother who feels extremely tired from caring for others or managing problems.","zh":"exhausted mother 指因照顧他人或處理問題而非常疲倦的母親。"},{"en":"An exhausted mother may sit down quietly after a long day of work and housework.","zh":"筋疲力盡的母親可能在工作和家務後安靜坐下。"},{"en":"In comedy, an exhausted character can react dramatically to small problems.","zh":"在喜劇中，疲倦角色可以對小問題作出誇張反應。"},{"en":"The writer’s exhausted mother role made the crocodile family dinner funnier.","zh":"作者的筋疲力盡母親角色令鱷魚家庭晚餐更好笑。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"academically ambitious reptile","meaning":"有學業抱負的爬蟲類動物","examples":[{"en":"The crocodile became an academically ambitious reptile.","zh":"那條鱷魚變成一隻有學業抱負的爬蟲類動物。"},{"en":"An academically ambitious reptile is a humorous description of a reptile imagined as caring about school success.","zh":"academically ambitious reptile 是幽默說法，指把爬蟲類動物想像成關心學業成功。"},{"en":"A lizard wanting top exam marks would be an academically ambitious reptile.","zh":"一隻想在考試中取得高分的蜥蜴，就是有學業抱負的爬蟲類動物。"},{"en":"The phrase is funny because reptiles do not normally have school goals.","zh":"這個短語好笑，因為爬蟲類動物通常沒有學業目標。"},{"en":"It turns the crocodile from a dangerous animal into a ridiculous student.","zh":"它把鱷魚由危險動物變成荒謬學生。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"had better get","meaning":"最好取得","examples":[{"en":"The crocodile had better get at least Level 5 in Biology.","zh":"那條鱷魚最好在生物科取得至少第五級。"},{"en":"Had better get means should get, often with a warning or strong expectation.","zh":"had better get 指最好取得，常帶有警告或強烈期望。"},{"en":"You had better get enough sleep before the competition tomorrow.","zh":"你明天比賽前最好有充足睡眠。"},{"en":"This phrase can sound serious, which makes it funny in a ridiculous situation.","zh":"這個短語可以聽起來嚴肅，因此在荒謬情況中變得好笑。"},{"en":"Saying a crocodile had better get a good Biology grade creates comic absurdity.","zh":"說鱷魚最好取得好生物成績，創造喜劇荒謬感。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"at least","meaning":"至少","examples":[{"en":"The crocodile had better get at least Level 5 in Biology.","zh":"那條鱷魚最好在生物科取得至少第五級。"},{"en":"At least means not less than a certain amount, level, or standard.","zh":"at least 指不少於某個數量、水平或標準。"},{"en":"Students should read at least one paragraph before using their phones.","zh":"學生使用電話前應至少閱讀一段。"},{"en":"This phrase sets a minimum expectation.","zh":"這個短語設定最低期望。"},{"en":"In the sketch, asking for at least Level 5 makes the imaginary crocodile sound like a serious student.","zh":"在小品中，要求至少第五級令想像中的鱷魚聽起來像認真學生。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"Level 5 in Biology","meaning":"生物科第五級","examples":[{"en":"I said the crocodile should get Level 5 in Biology.","zh":"我說那條鱷魚應該在生物科取得第五級。"},{"en":"Level 5 in Biology means a high grade in the Biology subject.","zh":"Level 5 in Biology 指在生物科取得較高等級。"},{"en":"A student aiming for Level 5 in Biology may revise past papers and laboratory notes.","zh":"目標為生物科第五級的學生，可能會溫習歷屆試題和實驗筆記。"},{"en":"The phrase is funny because a crocodile belongs in Biology, but not as an exam candidate.","zh":"這個短語好笑，因為鱷魚與生物科有關，但不是考生。"},{"en":"This joke connects school pressure with the absurd crocodile story.","zh":"這個笑話把學業壓力與荒謬鱷魚故事連接起來。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"make sense","meaning":"說得通；有道理","examples":[{"en":"None of it made sense, but everyone understood the joke.","zh":"這一切都不太說得通，但大家都明白笑點。"},{"en":"Make sense means be logical, clear, or understandable.","zh":"make sense 指合邏輯、清楚或容易理解。"},{"en":"The instructions did not make sense until the teacher showed an example.","zh":"指示在老師展示例子前並不太說得通。"},{"en":"Comedy does not always need to make perfect sense if the audience understands the pattern.","zh":"如果觀眾理解模式，喜劇不一定需要完全合邏輯。"},{"en":"The sketch made emotional sense even though the story was ridiculous.","zh":"這個小品雖然故事荒謬，但情感上說得通。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"somehow","meaning":"不知怎的","examples":[{"en":"Somehow, all of the nonsense worked.","zh":"不知怎的，所有胡鬧都奏效了。"},{"en":"Somehow means in a way that is surprising or not clearly understood.","zh":"somehow 指以令人意外或不完全明白的方式。"},{"en":"Somehow, the messy group project became a successful presentation.","zh":"不知怎的，混亂的小組專題變成了一次成功匯報。"},{"en":"This word suggests that the result is unexpected but real.","zh":"這個詞暗示結果出乎意料但確實存在。"},{"en":"The sketch worked somehow because the performers trusted one another.","zh":"小品不知怎地成功，因為表演者互相信任。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"interrupt one another","meaning":"互相打斷","examples":[{"en":"We interrupted one another during the sketch.","zh":"我們在小品中互相打斷。"},{"en":"To interrupt one another means to speak or act before another person has finished.","zh":"interrupt one another 指在對方完成前說話或行動。"},{"en":"Students may interrupt one another during an excited group discussion.","zh":"學生在興奮的小組討論中可能互相打斷。"},{"en":"In ordinary conversation, interrupting can be rude, but in comedy it can create energy.","zh":"在日常對話中，打斷可能無禮；但在喜劇中，它可以製造能量。"},{"en":"The group’s interruptions showed nervousness but also quick teamwork.","zh":"小組的互相打斷顯示緊張，也顯示快速合作。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"rescue one another","meaning":"互相補救","examples":[{"en":"We rescued one another when someone made a mistake.","zh":"當有人出錯時，我們互相補救。"},{"en":"To rescue one another means to help each other recover from trouble or embarrassment.","zh":"rescue one another 指互相幫助對方從麻煩或尷尬中恢復。"},{"en":"During a group presentation, classmates rescue one another by adding missing information.","zh":"在小組匯報中，同學可以透過補充遺漏資料互相補救。"},{"en":"Improvisers rescue one another by accepting mistakes and turning them into the story.","zh":"即興表演者透過接受錯誤並把它變成故事來互相補救。"},{"en":"This support allows performers to take risks without feeling alone.","zh":"這種支持讓表演者敢於冒險，而不感到孤單。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"contradict one another","meaning":"互相矛盾","examples":[{"en":"We contradicted one another and built the story together.","zh":"我們互相矛盾，並一起建立故事。"},{"en":"To contradict one another means to say or do things that disagree with each other.","zh":"contradict one another 指說出或做出彼此不一致的事情。"},{"en":"Two performers may contradict one another by giving different names for the same character.","zh":"兩名表演者可能為同一角色取不同名字，從而互相矛盾。"},{"en":"Contradictions can confuse a scene, but they can also become jokes if accepted.","zh":"矛盾可以令場面混亂，但如果被接受，也可以變成笑話。"},{"en":"In improvisation, even contradictions can help build a strange shared world.","zh":"在即興表演中，即使互相矛盾也能幫助建立奇怪的共同世界。"}],"source":"2023 Q6.pdf","sourcePage":8},{"front":"build a tiny universe out of nonsense","meaning":"用胡鬧建立一個小小世界","examples":[{"en":"We built a tiny universe out of nonsense.","zh":"我們用胡鬧建立了一個小小世界。"},{"en":"To build a tiny universe out of nonsense means to create a complete little world from silly, illogical ideas.","zh":"build a tiny universe out of nonsense 指用愚蠢、不合邏輯的想法創造一個完整的小世界。"},{"en":"Children can build a tiny universe out of nonsense when they invent rules for a playground game.","zh":"孩子為遊樂場遊戲發明規則時，可以用胡鬧建立一個小小世界。"},{"en":"Comedy often works by making absurd ideas feel real for a short time.","zh":"喜劇常透過令荒謬想法在短時間內感覺真實而成功。"},{"en":"The group’s crocodile dinner became its own tiny universe.","zh":"小組的鱷魚晚餐變成了自己的小小世界。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"the more…, the funnier…","meaning":"越……就越有趣","examples":[{"en":"The more we listened, the funnier we became.","zh":"我們越聆聽，就變得越有趣。"},{"en":"The more…, the funnier… shows that one increase makes something more humorous.","zh":"the more…, the funnier… 顯示一件事增加時，某事變得更有趣。"},{"en":"The more carefully the actors listened, the funnier their replies became.","zh":"演員越細心聆聽，他們的回應就越有趣。"},{"en":"This pattern links effort with a growing result.","zh":"這個句式把努力與逐漸增長的結果連接起來。"},{"en":"In improvisation, humour grows when performers build on one another’s ideas.","zh":"在即興表演中，當表演者建立在彼此想法上，幽默就會增長。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"the braver…, the more…","meaning":"越勇敢，就越……","examples":[{"en":"The braver we became, the more the audience trusted us.","zh":"我們越勇敢，觀眾就越信任我們。"},{"en":"The braver…, the more… means as courage increases, another result also increases.","zh":"the braver…, the more… 指勇氣增加時，另一個結果也增加。"},{"en":"The braver a speaker becomes, the more clearly the audience hears their message.","zh":"講者越勇敢，觀眾就越清楚聽到他的訊息。"},{"en":"This pattern shows a relationship between confidence and response.","zh":"這個句式顯示信心與反應之間的關係。"},{"en":"In the sketch, bravery made the audience feel safer laughing with the performers.","zh":"在小品中，勇氣令觀眾更放心與表演者一起笑。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"trust us","meaning":"信任我們","examples":[{"en":"The audience trusted us more as we became braver.","zh":"隨着我們變得更勇敢，觀眾更信任我們。"},{"en":"Trust us means believe that we know what we are doing or will guide them safely through the performance.","zh":"trust us 指相信我們知道自己在做甚麼，或能安全帶領他們看完整個表演。"},{"en":"An audience trusts performers when they commit fully to their roles.","zh":"當表演者完全投入角色時，觀眾會信任他們。"},{"en":"Trust grows when actors do not panic after a mistake.","zh":"當演員出錯後沒有慌張時，信任會增加。"},{"en":"The class trusted the group because they kept the scene alive together.","zh":"全班信任這個小組，因為他們一起令場面繼續下去。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"not every moment was smooth","meaning":"不是每一刻都順利","examples":[{"en":"Of course, not every moment was smooth.","zh":"當然，不是每一刻都順利。"},{"en":"Not every moment was smooth means some parts were awkward, difficult, or imperfect.","zh":"not every moment was smooth 指有些部分尷尬、困難或不完美。"},{"en":"Not every moment of the presentation was smooth, but the group finished confidently.","zh":"匯報不是每一刻都順利，但小組仍有信心地完成。"},{"en":"This phrase admits problems while keeping the overall judgment positive.","zh":"這個短語承認問題，同時保持整體評價正面。"},{"en":"It helps the diary sound honest instead of pretending everything was perfect.","zh":"它令日記聽起來真實，而不是假裝一切完美。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"halfway through","meaning":"進行到一半時","examples":[{"en":"Halfway through, I forgot Jason’s character name.","zh":"進行到一半時，我忘記了 Jason 的角色名字。"},{"en":"Halfway through means in the middle of an activity or process.","zh":"halfway through 指在活動或過程中間。"},{"en":"Halfway through the song, the singer forgot the next line.","zh":"歌曲唱到一半時，歌手忘記了下一句。"},{"en":"This phrase shows when a problem happened during the performance.","zh":"這個短語顯示問題在表演中何時發生。"},{"en":"A mistake halfway through is frightening because the scene is not over yet.","zh":"進行到一半時出錯令人害怕，因為場面還未結束。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"character name","meaning":"角色名字","examples":[{"en":"I forgot Jason’s character name during the sketch.","zh":"我在小品中忘記了 Jason 的角色名字。"},{"en":"A character name is the name of a person or role in a story or performance.","zh":"character name 指故事或表演中人物或角色的名字。"},{"en":"Actors must remember character names so dialogue stays clear.","zh":"演員必須記住角色名字，讓對白保持清楚。"},{"en":"Forgetting a character name can break the scene unless others respond creatively.","zh":"忘記角色名字可能破壞場面，除非其他人創意地回應。"},{"en":"In improvisation, even a wrong character name can become a joke.","zh":"在即興表演中，即使錯誤的角色名字也可以變成笑話。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"for the wrong reason","meaning":"因錯誤原因","examples":[{"en":"Everyone laughed for the wrong reason.","zh":"大家因錯誤原因而笑。"},{"en":"For the wrong reason means because of something unintended or not planned.","zh":"for the wrong reason 指因為不是原本打算或預期的事情。"},{"en":"The class laughed for the wrong reason when the speaker dropped her notes.","zh":"當講者掉下筆記時，全班因錯誤原因而笑。"},{"en":"This phrase often suggests embarrassment because the laughter was not caused by the intended joke.","zh":"這個短語常暗示尷尬，因為笑聲不是由原本設計的笑話引起。"},{"en":"The writer felt ashamed because the audience laughed at a mistake, not a clever line.","zh":"作者感到羞愧，因為觀眾笑的是錯誤，而不是聰明台詞。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"my face burned","meaning":"我尷尬得臉紅","examples":[{"en":"My face burned when I made the mistake.","zh":"我犯錯時，尷尬得臉紅。"},{"en":"My face burned means I felt embarrassed and my face became hot or red.","zh":"my face burned 指我感到尷尬，臉變熱或變紅。"},{"en":"My face burned when I gave the wrong answer in front of the class.","zh":"我在全班面前答錯問題時，尷尬得臉紅。"},{"en":"This phrase shows shame through a physical feeling.","zh":"這個短語透過身體感覺展示羞愧。"},{"en":"The writer’s face burned because she thought the mistake had exposed her fear.","zh":"作者臉紅，因為她覺得錯誤暴露了自己的恐懼。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"still","meaning":"然而","examples":[{"en":"Still, nobody stopped performing.","zh":"然而，沒有人停止表演。"},{"en":"Still means however, or despite what has just happened.","zh":"still 指然而，或儘管剛發生了某事。"},{"en":"The microphone failed; still, the speaker continued loudly.","zh":"麥克風壞了；然而，講者仍大聲繼續。"},{"en":"This word introduces resilience after a problem.","zh":"這個詞在問題後引入堅持。"},{"en":"In the sketch, the mistake happened, but the group kept going anyway.","zh":"在小品中，錯誤發生了，但小組仍繼續下去。"}],"source":"2023 Q6.pdf","sourcePage":9},{"front":"as if it were","meaning":"彷彿它是","examples":[{"en":"Mandy repeated “Uncle Father” as if it were a respectable family title.","zh":"Mandy 重複說 “Uncle Father”，彷彿它是一個體面的家庭稱謂。"},{"en":"As if it were means treating something as though it were true or real.","zh":"as if it were 指把某事當作真的或真實存在般對待。"},{"en":"The actor held an invisible crown as if it were made of gold.","zh":"演員拿着隱形皇冠，彷彿它是金造的。"},{"en":"This phrase can make a ridiculous idea funnier by treating it seriously.","zh":"這個短語可以透過認真對待荒謬想法，令它更好笑。"},{"en":"Mandy saves the mistake by pretending the strange title is completely normal.","zh":"Mandy 透過假裝奇怪稱謂完全正常，救回了錯誤。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"respectable family title","meaning":"體面的家庭稱謂","examples":[{"en":"“Uncle Father” became a respectable family title in the sketch.","zh":"“Uncle Father” 在小品中變成一個體面的家庭稱謂。"},{"en":"A respectable family title is a proper-sounding name for someone’s role in a family.","zh":"respectable family title 指聽起來正式得體的家庭角色稱呼。"},{"en":"“Grandfather” and “Auntie” are respectable family titles in ordinary life.","zh":"「祖父」和「姨姨」在日常生活中都是體面的家庭稱謂。"},{"en":"“Uncle Father” sounds ridiculous because it mixes two different family roles.","zh":"“Uncle Father” 聽起來荒謬，因為它混合了兩種不同家庭角色。"},{"en":"Treating it as respectable turns a mistake into comedy.","zh":"把它當成體面稱謂，令錯誤變成喜劇。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"become part of the story","meaning":"成為故事的一部分","examples":[{"en":"My mistake suddenly became part of the story.","zh":"我的錯誤突然成為故事的一部分。"},{"en":"Become part of the story means be accepted and included in what is happening.","zh":"become part of the story 指被接受並納入正在發生的事情中。"},{"en":"A dropped prop can become part of the story if an actor uses it creatively.","zh":"如果演員創意地使用掉下的道具，它可以成為故事的一部分。"},{"en":"This phrase shows how improvisation can turn failure into material.","zh":"這個短語顯示即興表演如何把失敗變成材料。"},{"en":"The mistake stopped being embarrassing once the group built on it.","zh":"當小組把錯誤發展下去時，它就不再只是尷尬。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"the strangest lesson of the day","meaning":"當天最奇怪的一課","examples":[{"en":"That was the strangest lesson of the day.","zh":"那是當天最奇怪的一課。"},{"en":"The strangest lesson of the day means the most unusual thing learned that day.","zh":"the strangest lesson of the day 指當天學到的最不尋常事情。"},{"en":"The strangest lesson of the day was that a mistake could make a speech better.","zh":"當天最奇怪的一課是，錯誤也可以令演講變得更好。"},{"en":"This phrase shows that learning can come from unexpected moments.","zh":"這個短語顯示學習可以來自意想不到的時刻。"},{"en":"The writer learns that errors can open new paths in performance.","zh":"作者學到錯誤可以在表演中打開新路。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"in ordinary life","meaning":"在日常生活中","examples":[{"en":"In ordinary life, we try to hide mistakes.","zh":"在日常生活中，我們嘗試掩飾錯誤。"},{"en":"In ordinary life means in normal daily situations outside special performance or drama settings.","zh":"in ordinary life 指在特別表演或戲劇情境以外的正常日常情況中。"},{"en":"In ordinary life, students may feel embarrassed when they answer wrongly.","zh":"在日常生活中，學生答錯時可能感到尷尬。"},{"en":"This phrase contrasts daily behaviour with what happens on stage.","zh":"這個短語對比日常行為與舞台上發生的事。"},{"en":"The writer realises that ordinary life teaches hiding, while improvisation teaches using mistakes.","zh":"作者意識到日常生活教人掩飾，而即興表演教人使用錯誤。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"hide mistakes","meaning":"掩飾錯誤","examples":[{"en":"People often try to hide mistakes.","zh":"人們常嘗試掩飾錯誤。"},{"en":"To hide mistakes means to cover them up or stop others from noticing them.","zh":"hide mistakes 指遮掩錯誤，或阻止別人注意到它們。"},{"en":"A student may hide mistakes in homework because they fear criticism.","zh":"學生可能因害怕批評而掩飾功課中的錯誤。"},{"en":"Hiding mistakes can make people more nervous because they fear being discovered.","zh":"掩飾錯誤會令人更緊張，因為他們害怕被發現。"},{"en":"Improvisation offers a different lesson: mistakes can be accepted and developed.","zh":"即興表演提供不同一課：錯誤可以被接受和發展。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"on stage","meaning":"在舞台上","examples":[{"en":"On stage, a mistake can become a doorway.","zh":"在舞台上，錯誤可以成為一道門。"},{"en":"On stage means in a performance space where people are acting or presenting to an audience.","zh":"on stage 指在向觀眾演出或展示的表演空間中。"},{"en":"On stage, even a pause can feel meaningful if the actor uses it well.","zh":"在舞台上，如果演員運用得好，即使停頓也可以有意義。"},{"en":"Actions on stage are seen by others, so mistakes cannot always be hidden.","zh":"舞台上的行動會被別人看見，所以錯誤不能總是被隱藏。"},{"en":"The stage changes mistakes into chances for new choices.","zh":"舞台把錯誤變成作出新選擇的機會。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"become a doorway","meaning":"成為一道門；成為契機","examples":[{"en":"A mistake can become a doorway during improvisation.","zh":"在即興表演中，錯誤可以成為一道門。"},{"en":"Become a doorway means become an opening or chance that leads to something new.","zh":"become a doorway 指成為通向新事物的開口或機會。"},{"en":"A wrong answer can become a doorway to a useful class discussion.","zh":"錯誤答案可以成為有用課堂討論的契機。"},{"en":"This phrase suggests that failure does not have to close the scene.","zh":"這個短語暗示失敗不一定會關閉場面。"},{"en":"In improvisation, mistakes become doorways when performers accept them.","zh":"在即興表演中，當表演者接受錯誤，錯誤就會成為契機。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"it was not because…, but because…","meaning":"不是因為……，而是因為……","examples":[{"en":"It was not because we were talented, but because we supported one another.","zh":"這不是因為我們有天分，而是因為我們互相支持。"},{"en":"It was not because…, but because… corrects one possible reason and gives the true reason.","zh":"it was not because…, but because… 用來修正一個可能原因，並指出真正原因。"},{"en":"The group succeeded not because they were perfect, but because they kept helping each other.","zh":"小組成功不是因為他們完美，而是因為他們一直互相幫助。"},{"en":"This pattern helps explain the real cause behind an outcome.","zh":"這個句式有助解釋結果背後的真正原因。"},{"en":"The diary writer uses it to show that teamwork mattered more than talent.","zh":"日記作者用它顯示團隊合作比天分更重要。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"scene survived","meaning":"場面得以維持下去","examples":[{"en":"The scene survived because we refused to abandon one another.","zh":"場面得以維持下去，因為我們拒絕拋下彼此。"},{"en":"Scene survived means the performance continued successfully despite mistakes or problems.","zh":"scene survived 指表演雖然有錯誤或問題，仍成功繼續。"},{"en":"The scene survived after one actor forgot a line because another actor created a new reply.","zh":"一名演員忘詞後，另一名演員創作新回應，所以場面得以維持。"},{"en":"This phrase treats the scene like a living thing that can almost fail or continue.","zh":"這個短語把場面當成有生命的東西，可能失敗也可能繼續。"},{"en":"The scene survived because the group chose support over panic.","zh":"場面得以維持，是因為小組選擇支持而不是恐慌。"}],"source":"2023 Q6.pdf","sourcePage":10},{"front":"refuse to abandon one another","meaning":"拒絕拋下彼此","examples":[{"en":"We refused to abandon one another on stage.","zh":"我們在舞台上拒絕拋下彼此。"},{"en":"To refuse to abandon one another means to choose not to leave teammates unsupported.","zh":"refuse to abandon one another 指選擇不讓隊友失去支援。"},{"en":"A debate team refuses to abandon one another when members help answer difficult questions.","zh":"辯論隊成員協助回答困難問題時，就是拒絕拋下彼此。"},{"en":"This attitude is important because performance depends on shared trust.","zh":"這種態度很重要，因為表演依賴共同信任。"},{"en":"The students kept the sketch alive by staying with each other’s ideas.","zh":"學生透過跟隨彼此想法，令小品保持生命力。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"the ten minutes ended","meaning":"十分鐘結束時","examples":[{"en":"When the ten minutes ended, Ms Lee clapped first.","zh":"十分鐘結束時，李老師率先拍手。"},{"en":"The ten minutes ended means the fixed performance time was over.","zh":"the ten minutes ended 指固定的表演時間完結。"},{"en":"When the ten minutes ended, the group finally realised they had survived the task.","zh":"十分鐘結束時，小組終於意識到自己撐過了任務。"},{"en":"Time limits make improvisation intense because performers must keep going until the end.","zh":"時間限制令即興表演更緊張，因為表演者必須撐到最後。"},{"en":"The ending brings relief after a risky and chaotic performance.","zh":"結束帶來鬆一口氣的感覺，因為表演既冒險又混亂。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"the whole class joined in","meaning":"全班也跟着加入","examples":[{"en":"Ms Lee clapped first, and the whole class joined in.","zh":"李老師率先拍手，全班也跟着加入。"},{"en":"The whole class joined in means all the students began doing the same action together.","zh":"the whole class joined in 指全班學生開始一起做同一個動作。"},{"en":"When one student started cheering, the whole class joined in.","zh":"當一名學生開始歡呼時，全班也跟着加入。"},{"en":"This phrase shows shared support and group response.","zh":"這個短語顯示共同支持和群體反應。"},{"en":"The class joining in makes the applause feel warm and communal.","zh":"全班加入令掌聲感覺溫暖而有社群感。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"bow awkwardly","meaning":"笨拙地鞠躬","examples":[{"en":"I bowed awkwardly after the sketch.","zh":"小品結束後，我笨拙地鞠躬。"},{"en":"To bow awkwardly means to bend forward in a shy, clumsy, or embarrassed way after performing.","zh":"bow awkwardly 指表演後害羞、笨拙或尷尬地向前鞠躬。"},{"en":"A nervous student may bow awkwardly after finishing a speech.","zh":"緊張學生完成演講後可能笨拙地鞠躬。"},{"en":"This action shows both politeness and discomfort.","zh":"這個動作同時顯示禮貌和不自在。"},{"en":"The awkward bow makes the diary ending feel honest and human.","zh":"笨拙的鞠躬令日記結尾感覺真實而有人味。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"still breathless","meaning":"仍然氣喘","examples":[{"en":"I was still breathless after the performance.","zh":"表演後，我仍然氣喘。"},{"en":"Still breathless means still breathing quickly because of excitement, fear, or physical effort.","zh":"still breathless 指仍因興奮、恐懼或身體努力而呼吸急促。"},{"en":"After running up the stairs, the student was still breathless when class began.","zh":"跑上樓梯後，學生上課開始時仍然氣喘。"},{"en":"Breathlessness shows that the body has been under pressure.","zh":"氣喘顯示身體承受了壓力。"},{"en":"The writer’s breathlessness proves the performance felt as intense as exercise.","zh":"作者仍然氣喘，證明表演感覺像運動一樣強烈。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"hair sticking to my forehead","meaning":"頭髮黏在額頭上","examples":[{"en":"My hair was sticking to my forehead after the sketch.","zh":"小品後，我的頭髮黏在額頭上。"},{"en":"Hair sticking to my forehead means hair was pressed against the front of the head because of sweat or heat.","zh":"hair sticking to my forehead 指頭髮因汗水或熱力貼在額頭上。"},{"en":"After PE class, her hair was sticking to her forehead.","zh":"體育課後，她的頭髮黏在額頭上。"},{"en":"This detail shows physical effort and nervous sweat.","zh":"這個細節顯示身體努力和緊張汗水。"},{"en":"It makes the performance feel real because the writer’s body shows what she went through.","zh":"它令表演感覺真實，因為作者的身體顯示她經歷了甚麼。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"heart thundering","meaning":"心跳如雷","examples":[{"en":"My heart was thundering after the performance.","zh":"表演後，我心跳如雷。"},{"en":"Heart thundering means the heart was beating very loudly or strongly because of fear or excitement.","zh":"heart thundering 指心臟因恐懼或興奮而跳得很響或很強。"},{"en":"My heart was thundering before I walked onto the stage.","zh":"我走上舞台前心跳如雷。"},{"en":"This phrase compares heartbeat to thunder to show intensity.","zh":"這個短語把心跳比作雷聲，以顯示強烈程度。"},{"en":"The writer’s heart thundering shows that the performance was emotionally powerful.","zh":"作者心跳如雷，顯示表演在情感上非常強烈。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"as though","meaning":"好像","examples":[{"en":"My heart was thundering as though I had just sprinted around the playground.","zh":"我心跳如雷，好像剛剛繞操場衝刺了一圈。"},{"en":"As though means as if, used to compare a feeling with an imagined situation.","zh":"as though 指好像，用來把感覺與想像情況作比較。"},{"en":"She looked at the test paper as though it were written in another language.","zh":"她看着試卷，好像它是用另一種語言寫成的。"},{"en":"This phrase helps readers understand a feeling through comparison.","zh":"這個短語透過比較幫助讀者理解感受。"},{"en":"The writer compares performing to sprinting because both leave her breathless and shaken.","zh":"作者把表演比作衝刺，因為兩者都令她氣喘和震動。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"sprint around the playground","meaning":"繞操場衝刺","examples":[{"en":"I felt as though I had just sprinted around the playground.","zh":"我感覺好像剛繞操場衝刺了一圈。"},{"en":"To sprint around the playground means to run very fast around the school playground.","zh":"sprint around the playground 指圍着學校操場快速奔跑。"},{"en":"Students may sprint around the playground during PE warm-ups.","zh":"學生可能在體育熱身時繞操場衝刺。"},{"en":"Sprinting makes the heart beat quickly and the body feel tired.","zh":"衝刺會令心跳加快，身體感到疲倦。"},{"en":"The comparison shows that improvisation exhausted the writer like physical exercise.","zh":"這個比較顯示即興表演像身體運動一樣令作者疲累。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"thunderous applause","meaning":"雷鳴般的掌聲","examples":[{"en":"The applause was not thunderous, but it was warm and real.","zh":"掌聲不是雷鳴般的，但它溫暖而真實。"},{"en":"Thunderous applause means extremely loud and powerful clapping.","zh":"thunderous applause 指非常響亮而有力的掌聲。"},{"en":"A famous singer may receive thunderous applause after a concert.","zh":"著名歌手演唱會後可能獲得雷鳴般的掌聲。"},{"en":"The diary says the applause was not thunderous to show it was modest, not dramatic.","zh":"日記說掌聲不是雷鳴般的，是為了顯示它樸素而不誇張。"},{"en":"Warm applause can matter more than loud applause when it feels sincere.","zh":"當掌聲感覺真誠時，溫暖掌聲可能比響亮掌聲更重要。"}],"source":"2023 Q6.pdf","sourcePage":11},{"front":"warm, generous and real","meaning":"溫暖、慷慨而真實","examples":[{"en":"The applause felt warm, generous and real.","zh":"掌聲感覺溫暖、慷慨而真實。"},{"en":"Warm, generous and real means kind, supportive, and sincere.","zh":"warm, generous and real 指友善、支持和真誠。"},{"en":"A teacher’s feedback can feel warm, generous and real when it notices effort.","zh":"當老師的回饋注意到努力時，它可以感覺溫暖、慷慨而真實。"},{"en":"This phrase shows that the applause gave emotional support, not just praise.","zh":"這個短語顯示掌聲給予的是情感支持，而不只是讚美。"},{"en":"The writer remembers the applause because it felt honest and caring.","zh":"作者記得這陣掌聲，因為它感覺誠實而關懷。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"polished answers","meaning":"經修飾的答案","examples":[{"en":"I usually prefer polished answers and neat plans.","zh":"我通常較喜歡經修飾的答案和井井有條的計劃。"},{"en":"Polished answers are carefully prepared answers that sound smooth and correct.","zh":"polished answers 指經仔細準備、聽起來流暢正確的答案。"},{"en":"Students often prefer polished answers during oral exams because they feel safer.","zh":"學生在口試中常較喜歡經修飾的答案，因為它們感覺較安全。"},{"en":"Polished answers can be impressive, but they may leave little room for surprise.","zh":"經修飾的答案可以令人印象深刻，但可能沒有太多驚喜空間。"},{"en":"The writer learns that unpolished moments can also create real confidence.","zh":"作者學會，未經修飾的時刻也能創造真正信心。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"neat plans","meaning":"井井有條的計劃","examples":[{"en":"I usually feel safer with neat plans.","zh":"我通常有井井有條的計劃時會感到更安全。"},{"en":"Neat plans are clear, orderly plans with little mess or uncertainty.","zh":"neat plans 指清楚、有秩序，而且少混亂或不確定性的計劃。"},{"en":"A student may feel calmer when a presentation has a neat plan.","zh":"當匯報有井井有條的計劃時，學生可能較平靜。"},{"en":"Neat plans are useful, but they cannot prepare us for every surprise.","zh":"井井有條的計劃有用，但不能讓我們準備好面對每個驚喜。"},{"en":"Improvisation forces the writer to act when no neat plan exists.","zh":"即興表演迫使作者在沒有井井有條計劃時行動。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"a small revolution","meaning":"小小的革命","examples":[{"en":"For me, the applause felt like a small revolution.","zh":"對我來說，那陣掌聲感覺像一場小小的革命。"},{"en":"A small revolution means a quiet but important change in how someone thinks or feels.","zh":"small revolution 指某人想法或感受上安靜但重要的改變。"},{"en":"Speaking once in class may feel like a small revolution for a shy student.","zh":"對害羞學生來說，在課堂上發言一次可能像小小的革命。"},{"en":"This phrase shows that the moment changed the writer’s inner world.","zh":"這個短語顯示那一刻改變了作者的內心世界。"},{"en":"The applause made her rethink confidence, mistakes, and courage.","zh":"掌聲令她重新思考自信、錯誤和勇氣。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"sitting at my desk","meaning":"坐在書桌前","examples":[{"en":"Sitting at my desk, I kept replaying the moment.","zh":"坐在書桌前，我不斷回想那一刻。"},{"en":"Sitting at my desk means being seated at the table where one studies or writes.","zh":"sitting at my desk 指坐在自己學習或寫作的桌子前。"},{"en":"Sitting at my desk after school, I thought about what had happened in class.","zh":"放學後坐在書桌前，我思考課堂上發生的事。"},{"en":"This phrase creates a quiet scene after the excitement of performance.","zh":"這個短語在表演的興奮後創造安靜場景。"},{"en":"It shows the writer reflecting privately in her diary.","zh":"它顯示作者在日記中私下反思。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"keep replaying","meaning":"不斷回想","examples":[{"en":"I kept replaying the moment when my mind went blank.","zh":"我不斷回想腦袋一片空白的那一刻。"},{"en":"To keep replaying means to think about something again and again, like watching it in the mind.","zh":"keep replaying 指一次又一次思考某事，像在腦海中重播。"},{"en":"After the speech, she kept replaying the moment when everyone laughed.","zh":"演講後，她不斷回想大家笑起來的那一刻。"},{"en":"People replay moments when they are important, embarrassing, or surprising.","zh":"當某些時刻重要、尷尬或令人意外時，人們會不斷回想。"},{"en":"The writer keeps replaying the moment because it changed how she understood fear.","zh":"作者不斷回想那一刻，因為它改變了她對恐懼的理解。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"bring something back to life","meaning":"令……重現生機","examples":[{"en":"Laughter brought my confidence back to life.","zh":"笑聲令我的信心重現生機。"},{"en":"To bring something back to life means to make something feel alive, active, or strong again.","zh":"bring something back to life 指令某事重新有生命力、活力或力量。"},{"en":"A kind comment can bring a nervous student’s confidence back to life.","zh":"一句友善評語可以令緊張學生的信心重現生機。"},{"en":"This phrase suggests that confidence had almost disappeared but returned.","zh":"這個短語暗示信心幾乎消失，但又回來了。"},{"en":"The class’s laughter revived the writer’s courage in the middle of panic.","zh":"全班的笑聲在恐慌中重新喚醒作者的勇氣。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"before today","meaning":"在今天之前","examples":[{"en":"Before today, I thought confidence meant being prepared.","zh":"在今天之前，我以為自信代表已有準備。"},{"en":"Before today means earlier than this day or before today’s experience changed the writer’s view.","zh":"before today 指早於今天，或在今天的經歷改變作者看法之前。"},{"en":"Before today, I believed mistakes always ruined performances.","zh":"在今天之前，我相信錯誤總會破壞表演。"},{"en":"This phrase marks a clear change between old belief and new understanding.","zh":"這個短語清楚標示舊信念與新理解之間的改變。"},{"en":"The diary writer uses it to show that the drama lesson changed her idea of confidence.","zh":"日記作者用它顯示戲劇課改變了她對自信的想法。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"confidence meant being prepared","meaning":"自信代表已有準備","examples":[{"en":"I used to think confidence meant being prepared.","zh":"我以前以為自信代表已有準備。"},{"en":"Confidence meant being prepared means the writer believed confidence came only from planning and practice.","zh":"confidence meant being prepared 指作者相信自信只來自計劃和練習。"},{"en":"A student may think confidence means memorising every line before a speech.","zh":"學生可能以為自信就是在演講前背熟每一句台詞。"},{"en":"This belief feels safe, but it may fail when something unexpected happens.","zh":"這種信念感覺安全，但當意外發生時可能失效。"},{"en":"The performance teaches that confidence can also mean continuing without preparation.","zh":"這次表演教她，自信也可以代表在沒有準備下繼續。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"staying present","meaning":"保持投入當下","examples":[{"en":"Confidence also means staying present when preparation disappears.","zh":"當準備消失時，自信也代表保持投入當下。"},{"en":"Staying present means keeping attention on what is happening now instead of panicking about the past or future.","zh":"staying present 指把注意力放在眼前發生的事，而不是為過去或未來慌張。"},{"en":"An actor stays present by listening to the other performer’s next line.","zh":"演員透過聆聽另一位表演者下一句台詞來保持投入當下。"},{"en":"Staying present helps people respond clearly when plans fail.","zh":"當計劃失效時，保持投入當下幫助人清楚回應。"},{"en":"In improvisation, confidence comes from attention to the moment.","zh":"在即興表演中，自信來自對當下的專注。"}],"source":"2023 Q6.pdf","sourcePage":12},{"front":"preparation disappears","meaning":"準備消失","examples":[{"en":"Improvisation begins when preparation disappears.","zh":"當準備消失時，即興表演便開始。"},{"en":"Preparation disappears means the planned support, notes, or expected structure is no longer available.","zh":"preparation disappears 指計劃好的支援、筆記或預期結構不再存在。"},{"en":"During a sudden question, preparation disappears and the student must think quickly.","zh":"面對突如其來的問題時，準備會消失，學生必須快速思考。"},{"en":"This phrase shows the moment when people must rely on attention and trust.","zh":"這個短語顯示人們必須依賴專注和信任的時刻。"},{"en":"Improvisation teaches students how to act when no plan remains.","zh":"即興表演教學生在沒有計劃時如何行動。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"naturally funny","meaning":"天生風趣","examples":[{"en":"Improvisation did not teach me how to be naturally funny.","zh":"即興表演沒有教會我如何變得天生風趣。"},{"en":"Naturally funny means able to make people laugh easily without much effort or planning.","zh":"naturally funny 指不用太多努力或計劃就能輕易令人發笑。"},{"en":"Some students seem naturally funny because their timing and reactions are quick.","zh":"有些學生看似天生風趣，因為他們的節奏和反應很快。"},{"en":"The writer learns that comedy is not only about natural talent.","zh":"作者學會喜劇不只關於天生才能。"},{"en":"Listening and trusting can make a scene funny even if no one feels naturally funny.","zh":"即使沒有人覺得自己天生風趣，聆聽和信任也能令場面好笑。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"teach me how to listen, trust and leap","meaning":"教會我聆聽、信任和躍出一步","examples":[{"en":"Improvisation taught me how to listen, trust and leap.","zh":"即興表演教會我聆聽、信任和躍出一步。"},{"en":"To listen, trust and leap means to pay attention, believe in others, and take a brave step without full certainty.","zh":"listen, trust and leap 指專心聆聽、相信他人，並在不完全確定下勇敢踏出一步。"},{"en":"A performer must listen to the scene, trust teammates, and leap into the next line.","zh":"表演者必須聆聽場面、信任隊友，並躍進下一句台詞。"},{"en":"This phrase summarises the emotional lesson of improvisation.","zh":"這個短語總結即興表演帶來的情感課堂。"},{"en":"It shows that courage comes from action with others, not from perfect preparation.","zh":"它顯示勇氣來自與他人一起行動，而不是來自完美準備。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"no rehearsal","meaning":"沒有綵排","examples":[{"en":"We had no script, no rehearsal and no safety net.","zh":"我們沒有劇本、沒有綵排，也沒有安全網。"},{"en":"No rehearsal means there was no practice before the actual performance.","zh":"no rehearsal 指正式表演前沒有練習。"},{"en":"A group asked to perform immediately has no rehearsal time.","zh":"被要求立即表演的小組沒有綵排時間。"},{"en":"Without rehearsal, performers must depend on listening, reaction, and trust.","zh":"沒有綵排時，表演者必須依賴聆聽、反應和信任。"},{"en":"The lack of rehearsal makes the success of the sketch feel more surprising.","zh":"沒有綵排令小品的成功更令人意外。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"no safety net","meaning":"沒有安全網","examples":[{"en":"We had no safety net during the sketch.","zh":"我們在小品中沒有安全網。"},{"en":"No safety net means no backup plan, script, or protection from failure.","zh":"no safety net 指沒有後備計劃、劇本或避免失敗的保障。"},{"en":"Answering an unexpected question on stage can feel like having no safety net.","zh":"在舞台上回答意外問題，可能感覺像沒有安全網。"},{"en":"A safety net makes people feel secure, so losing it can be frightening.","zh":"安全網令人感到安心，因此失去它會令人害怕。"},{"en":"Improvisation teaches students how to continue even with no safety net.","zh":"即興表演教學生即使沒有安全網也繼續下去。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"chaotic minutes","meaning":"混亂的十分鐘","examples":[{"en":"For ten chaotic minutes, we performed without a script.","zh":"在混亂的十分鐘裏，我們沒有劇本地表演。"},{"en":"Chaotic minutes are minutes filled with confusion, movement, noise, and unexpected events.","zh":"chaotic minutes 指充滿混亂、動作、聲音和意外事件的時間。"},{"en":"The last five minutes before the school show were chaotic minutes for the backstage team.","zh":"學校表演前最後五分鐘，對後台團隊來說是混亂的幾分鐘。"},{"en":"Chaos can be stressful, but it can also create energy in improvisation.","zh":"混亂可以令人有壓力，但也可以在即興表演中創造能量。"},{"en":"The ten chaotic minutes became meaningful because the group survived them together.","zh":"這混亂的十分鐘變得有意義，因為小組一起撐過它。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"we flew","meaning":"我們飛起來了；我們自由發揮了","examples":[{"en":"For ten chaotic minutes, we flew.","zh":"在混亂的十分鐘裏，我們飛起來了。"},{"en":"We flew means we felt free, brave, and alive during the performance.","zh":"we flew 指我們在表演中感到自由、勇敢和充滿生命力。"},{"en":"A nervous student may feel as if they flew after speaking confidently for the first time.","zh":"緊張學生第一次有信心地發言後，可能感覺自己像飛起來了。"},{"en":"This phrase is not literal; it describes emotional freedom and sudden confidence.","zh":"這個短語不是字面意思；它描述情感上的自由和突然出現的信心。"},{"en":"The students flew because they stopped hiding and began trusting one another.","zh":"學生之所以飛起來，是因為他們停止掩飾，開始互相信任。"}],"source":"2023 Q6.pdf","sourcePage":13},{"front":"Good night","meaning":"晚安","examples":[{"en":"A diary entry may end with “Good night”.","zh":"日記可以以 “Good night” 作結。"},{"en":"Good night is a simple closing used before sleep or at the end of a personal diary entry.","zh":"Good night 是睡前或私人日記結尾常用的簡單結語。"},{"en":"After writing about a long and emotional day, a student may end with “Good night”.","zh":"學生寫完漫長又充滿情緒的一天後，可能以 “Good night” 作結。"},{"en":"This phrase gives the diary a quiet and personal ending.","zh":"這個短語給日記一個安靜而個人的結尾。"},{"en":"It suggests the writer is closing the day after reflecting on what happened.","zh":"它暗示作者在反思當天發生的事後，正在結束這一天。"}],"source":"2023 Q6.pdf","sourcePage":13}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2023_SEED);
